window.__Q=window.__Q||{};window.__Q["clin/2/A1"]=[{"q":"接受肝淋巴管的淋巴结的是","o":["肠系膜上淋巴结","腰淋巴结","腹腔淋巴结","膈上淋巴结","幽门淋巴结"],"a":2,"e":"肝的深淋巴管沿肝门静脉出肝注入肝淋巴结，其输出管再入腹腔干周围的腹腔淋巴结，肝浅淋巴管亦部分注入腹腔淋巴结和膈上淋巴结。腰淋巴结收纳腹腔成对器官及盆壁的淋巴，肠系膜上淋巴结引流空回肠与右半结肠，均不接纳肝的淋巴；膈上淋巴结只收纳肝膈面浅淋巴及膈的淋巴"},{"q":"疑核属于","o":["一般躯体运动核","一般躯体感觉核","特殊内脏感觉核","特殊躯体感觉核","特殊内脏运动核"],"a":4,"e":"疑核位于延髓橄榄上部网状结构中，发出特殊内脏运动纤维加入舌咽、迷走和副神经，支配由鳃弓衍化的咽、喉、软腭肌。一般躯体运动核为动眼、滑车、展和舌下神经核，支配眼外肌与舌肌；一般躯体感觉核接受三叉神经传入，特殊躯体感觉核为前庭蜗核，均不属疑核"},{"q":"眼动脉的分支包括","o":["视网膜中央动脉","面动脉","上颌动脉","内眦动脉","下颌动脉"],"a":0,"e":"眼动脉起自颈内动脉，穿视神经管入眶，分支有视网膜中央动脉、睫后短动脉、睫前动脉、泪腺动脉及筛前筛后动脉，视网膜中央动脉是供应视网膜内层的唯一动脉。上颌动脉为颈外动脉终支，面动脉属颈外动脉，其终支内眦动脉与眼动脉吻合，三者均非眼动脉分支"},{"q":"通过圆孔的结构是","o":["眶上神经","眼神经","上颌神经","上颌动脉","脑膜中动脉"],"a":2,"e":"上颌神经含一般躯体感觉纤维，经海绵窦外侧壁后穿圆孔出颅入翼腭窝，再经眶下裂入眶续为眶下神经。眶上神经是眼神经的分支，经眶上裂、眶上孔出眶；脑膜中动脉穿棘孔入颅，上颌动脉经翼上颌裂进入翼腭窝，均不通过圆孔"},{"q":"接受来自下丘臂的听觉传导纤维的核团是","o":["腹前核","内侧膝状体","腹后内侧核","腹外侧核","外侧膝状体"],"a":1,"e":"下丘臂自下丘连于内侧膝状体，传导听觉冲动，内侧膝状体是听觉通路在丘脑的中继站，发出听辐射投射至颞叶听区。外侧膝状体经上丘臂接受视束纤维，为视觉中继站；腹后内侧核接受三叉丘系和味觉纤维，腹后外侧核接受内侧丘系与脊髓丘系"},{"q":"关于十二指肠的描述，正确的是","o":["全长约20cm","属于腹膜内位器官","肝胰壶腹开口于十二指肠水平部","分为上部、降部、水平部三部分","紧贴腹后壁"],"a":4,"e":"十二指肠除始末两端外均被腹膜覆盖并固定于腹后壁，属腹膜外位器官，位置深而固定，这是其区别于空回肠的要点。其全长20～25cm，分上部、降部、水平部和升部，肝胰壶腹开口于降部后内侧壁的十二指肠大乳头；腹膜内位为胃、空肠等特点，分三部的说法遗漏升部"},{"q":"以下关于甲状腺鞘的描述，正确的是","o":["又称纤维囊","也称真被膜","由气管前筋膜形成","属于甲状腺被膜的内层","为甲状腺的外膜"],"a":2,"e":"甲状腺鞘即假被膜，由颈深筋膜的气管前筋膜包裹甲状腺形成，与甲状腺外膜即真被膜（纤维囊）之间为囊鞘间隙，内有甲状旁腺、血管和神经。纤维囊紧贴腺实质，属被膜内层；气管前筋膜为颈深筋膜中层，不能称为甲状腺外膜"},{"q":"关于心尖的描述，正确的是","o":["朝向右前下方","由右心室构成","平对左侧第5肋间隙","前室间支与后室间支吻合处","活体不易触摸到其搏动"],"a":2,"e":"心尖圆钝游离，由左心室构成，朝向左前下方，在左侧第5肋间隙锁骨中线内侧1～2cm处可触及搏动。心底朝右后上方，由左心房和部分右心房构成；前、后室间支的吻合处在心尖切迹附近，并非心尖本体；心尖搏动在活体最易扪及"},{"q":"薄束核和楔束核发出的纤维构成","o":["薄束和楔束","脊髓丘脑束","三叉丘系","内侧丘系","外侧丘系"],"a":3,"e":"薄束核与楔束核发出二级纤维绕中央灰质腹侧行向中线，交叉形成内侧丘系交叉，交叉后上行构成内侧丘系，终于丘脑腹后外侧核。脊髓丘脑束起自对侧后角，三叉丘系起自三叉神经脊束核和脑桥核，外侧丘系由蜗核纤维组成，三者均不起自薄、楔束核"},{"q":"可作为划分上、下纵隔的标志是","o":["第4胸椎体下缘","胸骨体","胸骨柄","心包","肺门"],"a":0,"e":"纵隔以胸骨角至第4胸椎体下缘的平面分为上、下纵隔，该平面相当于胸骨角平面，也是主动脉弓下缘和气管杈所在高度。胸骨柄与胸骨体是构成胸骨角的两部分，属体表定位标志而非分界本身；肺门位于中纵隔内，心包居下纵隔中份"},{"q":"下列有关肝下间隙，描述正确的是","o":["借镰状韧带分为左、右肝下间隙","右肝下间隙借小网膜分为右肝下前间隙和右肝下后间隙","左肝下前间隙即小腹膜腔","右肝下后间隙即肝肾隐窝","属于结肠下区"],"a":0,"e":"肝下间隙指肝脏面腹膜与横结肠及其系膜之间的间隙，借镰状韧带和肝圆韧带分为左、右肝下间隙。左肝下间隙再借小网膜分为前、后两部，左肝下后间隙即网膜囊；右肝下间隙本身即肝肾隐窝，不存在“右肝下后间隙”之称。该间隙位于结肠上区"},{"q":"在锁骨中线处胸膜下界相交于","o":["第6肋","第7肋","第8肋","第9肋","第10肋"],"a":2,"e":"胸膜下界在锁骨中线与第8肋相交，腋中线与第10肋相交，肩胛线与第11肋相交，后端止于第12胸椎高度。肺下界较胸膜下界高出约两个肋，锁骨中线处平第6肋，故第6肋是肺下缘位置；第10肋为腋中线处的胸膜下界"},{"q":"颈内静脉伴行的血管是哪一条","o":["颈外静脉","上颌静脉","颈外动脉","下颌后静脉","颈总动脉"],"a":4,"e":"颈内静脉在颈动脉鞘内沿颈内动脉和颈总动脉的外侧下行，至胸锁关节后方与锁骨下静脉合成头臂静脉。颈外静脉走行于胸锁乳突肌表面，属浅静脉；下颌后静脉由颞浅静脉与上颌静脉合成，上颌静脉为其属支，两者均不与颈内静脉全程伴行"},{"q":"参加肩关节旋外的肌是","o":["胸大肌","小圆肌","背阔肌","大圆肌","肩胛下肌"],"a":1,"e":"小圆肌起自肩胛骨外侧缘背面，经肩关节囊后方止于肱骨大结节下部，由腋神经支配，收缩使肩关节旋外，与冈下肌同为旋外肌。肩胛下肌、大圆肌、胸大肌、背阔肌均使肩关节旋内，其中大圆肌兼后伸内收，背阔肌使肩关节后伸、内收和旋内"},{"q":"关于指浅屈肌的叙述，错误的是","o":["为前臂后群浅层肌","肌束向下移行为4条肌腱","肌腱经腕管入手掌","止于内侧2～5指中节指骨体两侧","可屈腕关节和肘关节"],"a":0,"e":"指浅屈肌位于前臂前群浅层第二层，起自肱骨内上髁及尺、桡骨前面，肌束下行分为4条腱经腕管入手掌，止于第2～5指中节指骨体两侧，可屈近侧指间关节、掌指关节和腕关节。前臂后群浅层为桡侧腕长伸肌、指伸肌、小指伸肌和尺侧腕伸肌，属伸肌群"},{"q":"关于交感神经和副交感神经的区别，错误的是","o":["低级中枢的部位不同","都是管理内脏运动","周围部神经节的位置不同","节前神经元与节后神经元的比例不同","副交感分布范围更广"],"a":4,"e":"交感神经低级中枢位于脊髓胸腰部中间带外侧核，节前纤维在椎旁或椎前神经节换元，一个节前神经元联系多个节后神经元，故作用范围广；副交感中枢在脑干副交感核和骶髓，节后神经元位于器官旁或器官壁内，分布局限。两者同属内脏运动神经，均管理内脏活动"},{"q":"竖脊肌的形态结构特征包括","o":["是背部强大的屈肌","位于背部的浅层","收缩时使脊柱后伸和仰头","为全身最大的阔肌","仅连于相邻椎骨之间"],"a":2,"e":"竖脊肌纵列于棘突两侧沟内，起自骶骨背面和髂嵴，分为髂肋肌、最长肌和棘肌，止于肋骨、椎骨及颞骨乳突，一侧收缩使脊柱侧屈，两侧收缩使脊柱后伸并仰头。背浅层的斜方肌、背阔肌止于上肢带骨或肱骨；全身最大的阔肌是背阔肌"},{"q":"不穿经梨状肌下孔的神经","o":["坐骨神经","阴部神经","臀下神经","股后皮神经","闭孔神经"],"a":4,"e":"穿梨状肌下孔的结构自外侧向内侧依次为坐骨神经、股后皮神经、臀下神经及臀下血管、阴部神经及阴部内血管，坐骨神经为其中最粗大者。闭孔神经经闭膜管至股内侧区，不穿梨状肌下孔；穿梨状肌上孔者为臀上神经和臀上血管"},{"q":"关于闭孔神经的叙述，错误的是","o":["自腰丛发出","沿盆腔侧壁前行穿闭孔","肌支支配股内侧肌群","皮支分布于大腿内侧面皮肤","没有分支到髋关节"],"a":4,"e":"闭孔神经自腰丛发出，沿盆侧壁前行穿闭膜管至股内侧区，肌支支配闭孔外肌和股内侧群，皮支分布于大腿内侧面皮肤，另有细支分布于髋关节和膝关节。故“无分支到髋关节”与解剖事实相反，其余各项均符合其行程与分布"},{"q":"远侧列的腕骨包括","o":["手舟骨","月骨","三角骨","大多角骨","豌豆骨"],"a":3,"e":"腕骨远侧列自桡侧向尺侧为大多角骨、小多角骨、头状骨和钩骨，近侧列为手舟骨、月骨、三角骨和豌豆骨。豌豆骨位于近侧列尺侧，覆于三角骨掌面；大多角骨与第1掌骨底构成拇指腕掌关节，属鞍状关节"},{"q":"属于内生殖器的结构","o":["阴阜","前庭球","前庭大腺","小阴唇","阴蒂"],"a":2,"e":"女性内生殖器由卵巢、输卵管、子宫、阴道和前庭大腺组成，前庭大腺位于大阴唇后部、前庭球后端深面，导管开口于阴道前庭，分泌黏液润滑阴道。阴阜、小阴唇、阴蒂及前庭球均属女阴，即外生殖器结构"},{"q":"接受内侧丘系纤维的丘脑神经核是","o":["腹后内侧核","腹后外侧核","腹外侧核","腹前核","内侧膝状体"],"a":1,"e":"腹后外侧核接受内侧丘系和脊髓丘系的纤维，发出丘脑中央辐射经内囊后肢投射至中央后回中、上部及中央旁小叶后部。腹后内侧核接受三叉丘系和味觉纤维；腹前核、腹外侧核属锥体外系中继核；内侧膝状体为听觉通路中继站"},{"q":"肋的形态结构特征是","o":["第1～8肋前端连于胸骨称为真肋","第9～10肋软骨连成肋弓","外面近下缘处有肋沟","分为真肋和假肋","肋属扁骨"],"a":4,"e":"肋骨属扁骨，分体及前、后两端，后端肋头有关节面与胸椎肋凹相关节，肋体下缘内面有肋沟，容纳肋间血管和神经。第1～7肋为真肋，第8～10肋借肋软骨连成肋弓，第11～12肋为浮肋；肋沟在内面而不在外面，真肋数目与成弓范围均与所述不符"},{"q":"对副神经的叙述错误的是","o":["在橄榄后沟下部连于延髓","经颈静脉孔出颅","脑根加入迷走神经","脊髓根支配斜方肌和胸锁乳突肌","为躯体运动神经"],"a":4,"e":"副神经由延髓根和脊髓根合成，脊髓根经枕骨大孔入颅与延髓根合并，再穿颈静脉孔出颅，支配胸锁乳突肌和斜方肌，延髓根在出颅前加入迷走神经。两肌由鳃弓衍化，故副神经属特殊内脏运动神经，笼统称为躯体运动神经不准确"},{"q":"胸核发出的纤维组成","o":["同侧的脊髓小脑前束","对侧的脊髓小脑前束","同侧的脊髓小脑后束","对侧的脊髓小脑后束","对侧的小脑下脚"],"a":2,"e":"胸核位于C8～L2节段后角基底部内侧，发出二级纤维在同侧侧索后部组成脊髓小脑后束，经小脑下脚入旧小脑皮质，此束仅见于L2以上节段。脊髓小脑前束主要起自腰骶膨大Ⅴ～Ⅶ层，大部交叉至对侧，经小脑上脚入小脑；小脑下脚内还有前庭小脑和橄榄小脑纤维"},{"q":"两侧胸膜腔","o":["借呼吸道相通","向内侧与心包横窦相通","向下和腹膜腔相通","开口于肺门","各自形成密闭间隙"],"a":4,"e":"胸膜腔是脏、壁胸膜在肺根处相互移行形成的密闭潜在腔隙，左右各一，互不相通，腔内为负压，仅含少量浆液以减少摩擦。两侧胸膜腔不与呼吸道、腹膜腔或心包横窦相通，肺根下方两层胸膜愈合并向下延伸为肺韧带"},{"q":"在足骨，跟骨前方的跗骨是","o":["足舟骨","骰骨","外侧楔骨","内侧楔骨","中间楔骨"],"a":1,"e":"跟骨前方为骰骨，二者以跟骰关节相连，骰骨前方与第4、5跖骨底相接，参与构成跗跖关节的外侧部。足舟骨位于距骨前方，内侧、中间、外侧三块楔骨位于足舟骨前方，均不直接与跟骨相接；跟骨后端隆凸为跟骨结节，是跟腱附着处"},{"q":"眼球屈光装置的主要结构","o":["角膜","房水","晶状体","玻璃体","视网膜"],"a":2,"e":"晶状体是眼屈光装置的主要结构，双凸透明，借睫状小带连于睫状体，视近物时睫状肌收缩、小带松弛，晶状体凸度增大，屈光力增强。角膜、房水、玻璃体同属屈光装置，其中角膜折光力最强；视网膜属感光装置，不含屈光结构"},{"q":"动眼神经穿经","o":["视神经管","眶上裂","眶下裂","眶上孔","眶下孔"],"a":1,"e":"动眼神经自中脑脚间窝出脑，经海绵窦外侧壁上部、眶上裂入眶，分支支配上直肌、上睑提肌、下直肌、内直肌和下斜肌，副交感纤维在睫状神经节换元后支配瞳孔括约肌和睫状肌。视神经经视神经管入眶，上颌神经经圆孔、眶下裂入眶，均不经眶上裂"},{"q":"下列哪项属于实质性的内脏器官","o":["甲状腺","脾","肾上腺","肝","子宫"],"a":3,"e":"内脏学把内部无特定空腔、由腺组织构成并被结缔组织分隔成小叶的器官称实质性器官，肝、胰、肾和生殖腺属此类，肝以肝门为血管、胆管出入处。甲状腺、肾上腺属内分泌器官，脾属淋巴器官，子宫为有腔的肌性器官，均不列为内脏学意义上的实质性器官"},{"q":"下消化道不包括","o":["十二指肠","空肠","回肠","直肠","盲肠"],"a":0,"e":"临床上以十二指肠为界，口腔至十二指肠称上消化道，空肠以下至肛管称下消化道，故空肠、回肠、盲肠、直肠均属下消化道。十二指肠虽属小肠，但其黏膜接受胃酸、胆汁和胰液，归入上消化道；空肠与回肠以近侧2/5与远侧3/5为界，亦属下消化道"},{"q":"关于腓总神经及其分支的叙述，错误的是","o":["腓深神经支配小腿前群肌","腓深神经支配小腿外侧群肌","腓浅神经分布于小腿外侧","腓骨颈处的骨折易导致腓总神经损伤","腓深神经终支分布于足背内侧区"],"a":1,"e":"腓总神经绕腓骨颈后分为腓浅、腓深神经，腓浅神经支配腓骨长、短肌即小腿外侧群，司足外翻；腓深神经支配小腿前群肌和足背肌，终支分布于第1、2趾相对缘皮肤。腓骨颈骨折易伤及腓总神经，出现足下垂并内翻"},{"q":"关于副神经的叙述，错误的是","o":["由颅根和脊髓根合成","经枕骨大孔出颅","颅根加入迷走神经","脊髓根支配胸锁乳突肌和斜方肌","为运动性脑神经"],"a":1,"e":"副神经由延髓根和脊髓根合成，其脊髓根经枕骨大孔入颅与延髓根合并，再经颈静脉孔出颅，支配胸锁乳突肌和斜方肌。枕骨大孔是脊髓根的入颅途径而非出颅部位；延髓根在出颅前加入迷走神经，副神经整体属运动性脑神经"},{"q":"分上、下面和内、外缘的肋骨是","o":["第1肋骨","第2肋骨","第8肋骨","第11肋骨","第12肋骨"],"a":0,"e":"第1肋扁宽而短，分上、下面和内、外缘，无肋角和肋沟，内缘前份有前斜角肌结节，其前、后方各有锁骨下静脉和锁骨下动脉经过的压迹。第2～12肋均有肋角和肋沟，第11、12肋前端游离于腹壁肌层中，称浮肋"},{"q":"可内收、内旋和前屈肩关节的肌是","o":["胸大肌","背阔肌","冈上肌","小圆肌","三角肌"],"a":0,"e":"胸大肌起自锁骨内侧半、胸骨和第1～6肋软骨，止于肱骨大结节嵴，使肩关节内收、旋内和前屈。背阔肌起自下位胸椎棘突等处，止于小结节嵴，使肩关节后伸、内收和旋内；三角肌与冈上肌主司外展，小圆肌司旋外"},{"q":"颈动脉窦的描述，何者正确","o":["可感受血液中氧分压的变化","位于颈外动脉的起始处","为化学感受器","为压力感受器","可感受血液中二氧化碳分压的变化"],"a":3,"e":"颈动脉窦是颈总动脉末端与颈内动脉起始处的膨大，窦壁外膜内含丰富游离神经末梢，属压力感受器，血压升高时窦壁扩张，反射性引起心率减慢、末梢血管扩张、血压下降。颈动脉小球为化学感受器，感受血氧、二氧化碳分压和氢离子浓度变化，二者常被互换设错"},{"q":"阴道前庭","o":["两侧大阴唇之间的裂隙","又称为阴道穹","两侧小阴唇之间的裂隙","尿道外口在后方，阴道口在前方","前庭球位于阴道前庭内"],"a":2,"e":"阴道前庭是两侧小阴唇之间的菱形区，前部有尿道外口，后部有阴道口，前庭大腺导管开口于阴道口两侧。两侧大阴唇之间的裂隙为阴裂；阴道穹是阴道上端与子宫颈阴道部之间的环形间隙；前庭球位于大阴唇皮下，不属前庭内结构"},{"q":"穿经四边孔的动脉是","o":["胸肩峰动脉","旋肩胛动脉","肩胛下动脉","旋肱前动脉","旋肱后动脉"],"a":4,"e":"旋肱后动脉起自腋动脉，与腋神经伴行穿四边孔，绕肱骨外科颈至三角肌和肩关节。旋肩胛动脉穿三边孔至冈下窝；胸肩峰动脉穿锁胸筋膜分布于胸肌和三角肌；肩胛下动脉分为胸背动脉与旋肩胛动脉，三者均不经四边孔"},{"q":"对舌下神经描述正确的是","o":["伴同名动静脉经舌下神经管出颅","来自对侧的舌下神经核","支配舌肌","经延髓脑桥沟出脑","为舌的感觉神经"],"a":2,"e":"舌下神经由延髓舌下神经核发出，经锥体与橄榄之间的前外侧沟出脑，穿舌下神经管出颅，支配舌内肌和大部分舌外肌。该核只接受对侧皮质核束，故核上性损伤时伸舌偏向病灶对侧；舌的感觉由舌神经和舌咽神经管理"},{"q":"属于颈外动脉分支的是","o":["甲状腺上动脉","椎动脉","脑膜中动脉","胸廓内动脉","甲状腺下动脉"],"a":0,"e":"颈外动脉在甲状软骨上缘平面由颈总动脉分出，分支有甲状腺上动脉、舌动脉、面动脉、枕动脉、耳后动脉、咽升动脉、颞浅动脉和上颌动脉。甲状腺下动脉起自甲状颈干，椎动脉与胸廓内动脉为锁骨下动脉分支，脑膜中动脉属上颌动脉分支"},{"q":"参与视觉、听觉姿势反射活动的纤维束","o":["网状脊髓束","顶盖脊髓束","内侧纵束","前庭脊髓束","红核脊髓束"],"a":1,"e":"上丘深层发出纤维经被盖背侧交叉越中线，下行组成顶盖脊髓束，止于颈髓中间带和前角内侧核，完成头颈部对声、光刺激的姿势反射。内侧纵束协调眼球与头颈运动，前庭脊髓束调节伸肌张力，红核脊髓束影响屈肌张力，网状脊髓束调节肌张力"},{"q":"经过内囊膝的纤维束是","o":["丘脑中央辐射","视辐射","皮质脊髓前束","皮质脊髓侧束","皮质核束"],"a":4,"e":"内囊膝位于尾状核头与豆状核之间，内有皮质核束通过，该束起自中央前回下1/3，下行至脑干躯体运动核和特殊内脏运动核。内囊后肢含皮质脊髓束、丘脑中央辐射和视辐射；皮质脊髓前束与侧束均在延髓交叉后行于脊髓，不穿内囊膝"},{"q":"关于听觉性语言中枢的叙述，错误的是","o":["位于角回","损伤后患者不理解别人讲话的意思","损伤后患者不理解自己讲的话","损伤后患者不能正确回答问题和正常说话","损伤后患者能听到别人讲的话"],"a":0,"e":"听觉性语言中枢位于颞上回后部，属Wernicke区，损伤后能听到声音但不理解语意，自己说话杂乱，不能正确回答问题，称感觉性失语。角回为视觉性语言区即阅读中枢，损伤致失读症；书写中枢位于额中回后部，损伤致失写症"},{"q":"注入右淋巴导管的淋巴干是","o":["肠干","右腰干","左支气管纵隔干","左颈干","右锁骨下干"],"a":4,"e":"右淋巴导管由右颈干、右锁骨下干和右支气管纵隔干汇合而成，注入右静脉角，引流右上肢、右半头颈和右半胸的淋巴。左颈干、左支气管纵隔干及肠干汇入胸导管；腰干汇入乳糜池，亦属胸导管系，左右腰干均不注入右淋巴导管"},{"q":"腓浅神经损伤的表现为","o":["足外翻","足内翻","足背屈","足下垂","钩状足"],"a":1,"e":"腓浅神经在小腿外侧群内下行，支配腓骨长、短肌，司足外翻，皮支分布于小腿外侧和足背。损伤后外翻肌瘫痪，胫骨后肌等内翻肌失去拮抗，出现足内翻并伴足背感觉障碍。足下垂见于腓深神经或腓总神经损伤，钩状足见于胫神经损伤"},{"q":"关于形成静脉角的两条静脉是","o":["左、右头臂静脉","颈内静脉和颈外静脉","颈外静脉和锁骨下静脉","锁骨下静脉和颈内静脉","头臂静脉和锁骨下静脉"],"a":3,"e":"静脉角是颈内静脉与锁骨下静脉在胸锁关节后方汇合处形成的夹角，左右各一，分别有胸导管和右淋巴导管注入。颈外静脉注入锁骨下静脉，头臂静脉由颈内静脉与锁骨下静脉合成，两侧头臂静脉再汇成上腔静脉"},{"q":"一侧舌下神经损伤可导致","o":["伸舌时舌尖偏向健侧","舌不能前伸","舌的感觉丧失","无舌肌萎缩","伸舌时舌尖偏向患侧"],"a":4,"e":"一侧舌下神经损伤使同侧舌内、外肌瘫痪并萎缩，伸舌时健侧颏舌肌将舌尖推向患侧。舌的感觉由舌神经和舌咽神经管理，故感觉无障碍；因仅一侧瘫痪，舌仍可前伸。核上性损伤只致对侧舌肌核上瘫，无肌萎缩"},{"q":"关于腋神经正确的是","o":["从臂丛后束发出，穿过三边孔到达肩胛区","从臂丛外侧束发出，穿过四边孔到达肩胛区","从臂丛后束发出，穿过四边孔到达肩胛区","不发出分支到小圆肌","支配三角肌和大圆肌"],"a":2,"e":"腋神经发自臂丛后束，与旋肱后血管伴行穿四边孔，绕肱骨外科颈至三角肌深面，支配三角肌和小圆肌，皮支为臂外侧上皮神经。穿三边孔者为旋肩胛动脉；大圆肌由肩胛下神经支配；四边孔并非外侧束分支的通道"},{"q":"分布于结肠左曲以上的消化管的副交感神经是","o":["内脏大神经","迷走神经","内脏小神经","盆内脏神经","腰内脏神经"],"a":1,"e":"迷走神经的副交感节前纤维起自迷走神经背核，随腹腔支和肠系膜上动脉周围丛分布于胃、肝、胰、脾、肾及结肠左曲以上的消化管。结肠左曲以下的消化管和盆腔脏器由骶副交感核发出的盆内脏神经支配；内脏大、小神经和腰内脏神经属交感神经"},{"q":"脊柱的组成不包括","o":["24块椎骨","骶骨","尾骨","椎间盘","骶髂关节"],"a":4,"e":"脊柱由24块椎骨、1块骶骨、1块尾骨借椎间盘、韧带和关节连结而成，形成颈、胸、腰、骶四个生理弯曲，椎间盘约占脊柱全长1/4。骶髂关节由骶骨与髂骨耳状面构成，属下肢带骨连结，参与骨盆构成，不属于脊柱的组成"},{"q":"腹壁上动脉起自下列哪条动脉","o":["胸廓内动脉","肩胛下动脉","肋颈干","甲状颈干","锁骨下动脉"],"a":0,"e":"腹壁上动脉是胸廓内动脉的直接延续，在胸廓内动脉行至第6肋间隙处发出，穿膈进入腹直肌鞘深面下行，至脐附近与腹壁下动脉吻合。肩胛下动脉为腋动脉分支，肋颈干与甲状颈干为锁骨下动脉分支，均与腹壁上动脉起源无关"},{"q":"下列哪些动脉为锁骨下动脉的直接分支","o":["椎动脉、胸外侧动脉、胸廓内动脉、甲状颈干","甲状颈干、胸廓内动脉、甲状腺下动脉","椎动脉、甲状颈干、肋颈干、胸廓内动脉","甲状颈干、肋颈干、椎动脉、肩胛下动脉","胸廓内动脉、甲状颈干、上颌动脉、椎动脉"],"a":2,"e":"锁骨下动脉的直接分支为椎动脉、胸廓内动脉、甲状颈干和肋颈干，甲状颈干再分出甲状腺下动脉、肩胛上动脉等。胸外侧动脉和肩胛下动脉属腋动脉分支，上颌动脉为颈外动脉终支，甲状腺下动脉是甲状颈干的二级分支"},{"q":"肾蒂内各结构的排列，自上而下依次是","o":["肾静脉、肾动脉、肾盂","肾静脉、肾盂、肾动脉","肾盂、肾静脉、肾动脉","肾盂、肾动脉、肾静脉","肾动脉、肾静脉、肾盂"],"a":4,"e":"肾蒂内结构自前向后为肾静脉、肾动脉、肾盂末端，自上而下为肾动脉、肾静脉、肾盂。右肾靠近下腔静脉，故右肾蒂较左侧短。前、后排列常被误作上、下顺序，把肾盂置于最上方或把肾静脉置于最上方均与事实不符"},{"q":"齿状线在临床上的实用意义是","o":["齿状线上有神经反射弧","齿状线上、下血液供应、神经及淋巴引流各异","齿状线上直肠易受感染","齿状线下肛管狭窄易受感染","齿状线下是肛门外括约肌所在部位"],"a":1,"e":"齿状线是直肠黏膜与肛管皮肤的交界，以上为单层柱状上皮，以下为复层扁平上皮；上下方的动脉来源、静脉回流、淋巴引流和神经分布均不同，故齿状线是肛管疾病定位和术式选择的重要标志。齿状线以上受内脏神经支配、痛觉迟钝，以下受躯体神经支配、痛觉敏锐"},{"q":"关于心纤维性支架正确的是","o":["由疏松结缔组织构成","仅由4个瓣膜环组成","心肌纤维和心瓣膜的附着处","左纤维三角又称为中心纤维体","内有左、右束支通过"],"a":2,"e":"心纤维性支架由致密结缔组织构成，包括四个瓣膜环、左纤维三角、右纤维三角和室间隔膜部，为心肌纤维与心瓣膜提供附着，并被房室束穿过。右纤维三角又称中心纤维体，与左纤维三角并非同一结构；左、右束支发自房室束，不行于心纤维支架内"},{"q":"抗利尿激素和催产素是由以下哪个结构产生的","o":["腺垂体","神经垂体","垂体前叶","视上核和室旁核","垂体后叶"],"a":3,"e":"抗利尿激素和缩宫素由下丘脑视上核、室旁核的神经内分泌细胞合成，经视上垂体束运至神经垂体贮存并释放入血，神经垂体只贮存不合成。腺垂体合成生长激素和各类促激素；垂体后叶为神经部与中间部的合称，属贮存和释放部位"},{"q":"关于松果体的叙述，错误的是","o":["位于背侧丘脑的后上方","呈淡红色的椭圆形小体","儿童期较发达","促进性成熟","成年后钙化"],"a":4,"e":"官方答案为【成年后钙化】，但依据教材，正确答案为【促进性成熟】。松果体位于背侧丘脑后上方，呈淡红色椭圆形小体，儿童期较发达，16岁以后逐渐钙化，故“成年后钙化”符合事实。松果体分泌褪黑素抑制性腺发育，幼年受损可致性早熟，“促进性成熟”与其作用相反"},{"q":"上丘脑不包括","o":["缰三角","缰连合","丘脑髓纹","前连合","后连合"],"a":3,"e":"上丘脑位于第三脑室顶后部，包括松果体、缰三角、缰连合、丘脑髓纹和后连合。前连合是横过终板上方、连接两侧颞叶的连合纤维，属大脑连合系；丘脑髓纹自缰三角投射至缰核，后连合位于中脑与间脑交界处"},{"q":"与尺骨滑车切迹组成肱尺关节的结构是","o":["肱骨滑车","桡骨头关节凹","尺骨桡切迹","桡骨尺切迹","桡骨环状关节面"],"a":0,"e":"肱尺关节由肱骨滑车与尺骨滑车切迹构成，是肘关节三个关节之一，以屈伸运动为主。肱桡关节由肱骨小头与桡骨头关节凹构成；桡尺近侧关节由桡骨环状关节面与尺骨桡切迹构成，三者共包于一个关节囊内"},{"q":"属于下丘脑的结构是","o":["丘脑枕","松果体","髓纹","灰结节","内、外侧膝状体"],"a":3,"e":"下丘脑位于下丘脑沟以下，构成第三脑室侧壁下部和底，自前向后分视前区、视上区、结节区和乳头区，灰结节属结节区表面结构。丘脑枕属背侧丘脑，内、外侧膝状体属后丘脑，松果体、缰三角和缰连合属上丘脑"},{"q":"分布于腹腔脏器的交感神经节后纤维发自","o":["胸5～12交感干神经节","腰交感干神经节","腰、骶交感干神经节","椎前神经节","胸1～5交感干神经节"],"a":3,"e":"腹腔脏器的交感节后纤维主要起自椎前神经节，包括腹腔神经节、主动脉肾神经节、肠系膜上神经节和肠系膜下神经节，其节前纤维来自胸腰部中间带外侧核。椎旁神经节的节后纤维经灰交通支返回脊神经，分布于躯干四肢血管、汗腺和竖毛肌"},{"q":"直接注入右心房的静脉是","o":["心大静脉","心中静脉","心小静脉","心最小静脉","心前静脉"],"a":4,"e":"心前静脉起于右心室前壁，可有1～4支，越过冠状沟直接注入右心房。心大静脉、心中静脉和心小静脉均汇入冠状窦，再经冠状窦口入右心房；心最小静脉直接开口于心房或心室腔。故除心前静脉外，其余各静脉均先入冠状窦"},{"q":"下述关于胸骨旁淋巴结的描述，正确的是","o":["沿胸廓内血管排列","输出淋巴管注入锁骨下干","引流乳房上部的淋巴","位于胸膜腔内","与胸肌淋巴结联系密切"],"a":0,"e":"胸骨旁淋巴结沿胸廓内血管排列，位于胸骨两侧、壁胸膜外，引流胸腹前壁和乳房内侧部的淋巴，输出管参与合成支气管纵隔干。乳房上部的淋巴注入尖淋巴结，乳房外侧部注入胸肌淋巴结；该群淋巴结不在胸膜腔内"},{"q":"在肩关节外展中最重要的一对肌是","o":["三角肌和肩胛下肌","三角肌和冈上肌","冈上肌和肩胛下肌","大圆肌和肩胛下肌","三角肌和大圆肌"],"a":1,"e":"肩关节外展由三角肌中部纤维与冈上肌协同完成，冈上肌启动外展并稳定肱骨头，三角肌为外展主力，二者分别由肩胛上神经和腋神经支配。肩胛下肌、大圆肌使肩关节内收、旋内，冈下肌和小圆肌司旋外，均非外展肌"},{"q":"一侧视神经受损，光照健侧瞳孔时，会出现","o":["患侧瞳孔直接对光反射消失，间接对光反射存在","患侧瞳孔直接和间接对光反射均消失","两眼瞳孔对光反射均消失","健侧瞳孔直接对光反射存在，间接对光反射消失","健侧瞳孔间接对光反射存在，直接对光反射消失"],"a":0,"e":"一侧视神经受损后患眼传入中断，光照患眼时两侧瞳孔均无反应；光照健侧眼，冲动经健侧视神经、视交叉和双侧视束至顶盖前区，两侧动眼神经副核同时兴奋，故患侧间接对光反射存在、直接反射消失。动眼神经损伤则患侧直接与间接反射均消失"},{"q":"发出分支分布于眼球角膜的神经","o":["视神经","动眼神经","展神经","眼神经","鼻睫神经"],"a":3,"e":"角膜的感觉由眼神经传导，眼神经经眶上裂入眶后发出鼻睫神经，其睫状长神经穿巩膜入眼球，分布于角膜、虹膜和睫状体。视神经传导视觉冲动，动眼神经和展神经为运动神经，上颌神经分布于下睑、鼻翼和上唇，均不管理角膜感觉"},{"q":"集合淋巴滤泡多存在于","o":["空肠","回肠","结肠","盲肠","直肠"],"a":1,"e":"集合淋巴滤泡又称Peyer斑，由20～30个淋巴滤泡聚集而成，多位于回肠下部对肠系膜缘的黏膜内，长轴与肠管一致，是肠伤寒病变及并发肠穿孔、肠出血的部位。孤立淋巴滤泡散在于空肠和回肠，结肠与盲肠的淋巴组织以孤立滤泡为主"},{"q":"有关心脏正确的说法是","o":["心前面两心耳之间为主动脉根","右心房构成心右缘","居于胸腔的正中","位于两侧肺之间的前纵隔内","冠状沟将心脏分为左、右半"],"a":1,"e":"右缘由右心房构成，左缘绝大部分由左心室构成，心前面两心耳之间为动脉圆锥即右心室流出道，冠状沟分隔心房与心室而非左右半心。心位于中纵隔内，约2/3在正中线左侧，长轴与正中矢状面约成45°角，并不居于胸腔正中"},{"q":"左侧精索静脉曲张的原因之一是","o":["左侧睾丸静脉以直角注入左髂外静脉","左侧睾丸静脉以直角注入左髂内静脉","左侧睾丸静脉以直角注入左髂总静脉","左侧睾丸静脉以直角注入下腔静脉","左侧睾丸静脉以直角注入左肾静脉"],"a":4,"e":"左侧睾丸静脉呈直角注入左肾静脉，行程长且静脉瓣缺乏；右睾丸静脉以锐角直接注入下腔静脉，故精索静脉曲张多见于左侧。左睾丸静脉不注入髂外静脉、髂内静脉或髂总静脉，其回流受阻是左侧发病的解剖学基础"},{"q":"支配腮腺的副交感纤维来自","o":["耳神经节","迷走神经","面神经","上泌涎核","鼓索"],"a":0,"e":"腮腺的副交感纤维起自延髓下泌涎核，经舌咽神经鼓室神经、岩小神经至耳神经节换元，节后纤维经耳颞神经入腮腺。上泌涎核发出的纤维随面神经鼓索至下颌下神经节，支配舌下腺和下颌下腺；迷走神经不管理唾液腺分泌"},{"q":"红核位于","o":["间脑","中脑","脑桥","延髓","小脑"],"a":1,"e":"红核位于中脑上丘水平的被盖中央，横断面呈圆形，接受小脑齿状核和大脑皮质纤维，发出红核脊髓束经被盖腹侧交叉下行，调节屈肌张力。黑质位于大脑脚底与被盖之间，同属中脑；脑桥、延髓和小脑内无红核"},{"q":"具有神经内分泌功能的下丘脑核团是","o":["乳头体核","视上核","下丘脑后核","腹内侧核","背内侧核"],"a":1,"e":"视上核和室旁核的神经内分泌细胞合成抗利尿激素和缩宫素，经视上垂体束输送至神经垂体贮存并释放入血。乳头体核、下丘脑后核、腹内侧核和背内侧核属一般中继或调节核团，参与摄食、体温和内脏活动调节，不具神经内分泌功能"},{"q":"关于上矢状窦的说法错误的是","o":["位于大脑镰的上缘","前方止于盲孔","后方注入窦汇","蛛网膜粒突入此窦","不属于硬脑膜窦"],"a":4,"e":"上矢状窦位于大脑镰上缘，前起盲孔，向后注入窦汇，窦壁内面的蛛网膜粒突入窦腔，是脑脊液回流入血的部位，两侧接受大脑上静脉。上矢状窦属硬脑膜窦，窦壁无平滑肌、无瓣膜，损伤后出血不易自止，也不能收缩止血"},{"q":"患者，头痛、恶心、呕吐，以及视力一过性朦胧。检眼镜观察发现视神经盘充血、扩大、隆起明显（≥3D），边缘模糊，甚至累及附近视网膜，条状出血和渗出物，视网膜静脉怒张弯曲，黄斑部可见不完全性的星芒状渗出物。头颅CT检查患者颅内脑脊液增多，诊断为颅内高压。其视力及视神经盘症状应该是颅内高压引起的","o":["视神经损伤","眼外肌受损","动眼神经损伤","滑车神经损伤","视神经盘水肿"],"a":4,"e":"视神经由脑向前突出形成，三层脑膜及蛛网膜下隙随之延伸至视神经周围，颅内压增高时压力经蛛网膜下隙传至视神经鞘，压迫视网膜中央静脉，引起视神经盘充血、隆起、边缘模糊及条状出血，即视神经盘水肿。视神经损伤表现为视力下降和视野缺损，眼外肌受损则眼球运动障碍"},{"q":"骨间掌侧肌的作用是","o":["内收第2、3、4指","内收第2、4、5指","外展第2、3、4指","外展第2、4、5指","外展第3、4、5指"],"a":1,"e":"骨间掌侧肌起自第2掌骨内侧面及第4、5掌骨外侧面，止于第2、4、5指指背腱膜，收缩时使第2、4、5指内收并向中指靠拢，兼屈掌指关节、伸指间关节。骨间背侧肌固定第3指并外展第2、4指，外展拇指者为拇短展肌"},{"q":"连于甲状软骨上缘与舌骨之间的结构称为","o":["环甲正中韧带","前庭韧带","方形膜","环状软骨气管韧带","甲状舌骨膜"],"a":4,"e":"甲状舌骨膜位于甲状软骨上缘与舌骨之间，中部增厚为甲状舌骨正中韧带，两侧为甲状舌骨外侧韧带，内含麦粒软骨。环甲正中韧带连于甲状软骨下缘与环状软骨弓之间，方形膜连于会厌软骨与杓状软骨，环状软骨气管韧带连于环状软骨与第1气管软骨环"},{"q":"在骨连结，纤维软骨结合包括","o":["耻骨连合","前臂骨间膜","骺软骨","骶椎合成骶骨","髂骨、坐骨和耻骨合成髋骨"],"a":0,"e":"耻骨联合由两侧耻骨联合面借耻骨间盘即纤维软骨相连，属纤维软骨结合，可有轻微活动，妊娠期活动度增大。前臂骨间膜属纤维连结，骺软骨为透明软骨结合，骶椎融合成骶骨、髂骨坐骨耻骨合成髋骨均属骨性结合"},{"q":"关于附睾的描述，不正确的是","o":["附着在睾丸的上端及后缘","可分为头、体、尾三部","附睾管也可产生精子","可分泌液体促进精子成熟","形态为新月形"],"a":2,"e":"附睾呈新月形，紧贴睾丸上端和后缘，分头、体、尾三部，由睾丸输出小管和附睾管构成，分泌附睾液营养精子并促进其成熟，精子在此暂时贮存。精子由睾丸生精小管产生，附睾管只输送和储存精子，不具生精功能"},{"q":"甲状腺次全切除手术后出现手足搐搦，可能是","o":["甲状腺素分泌不足","甲状旁腺功能亢进","切除了甲状旁腺","甲状腺功能低下","损伤甲状腺神经"],"a":2,"e":"甲状旁腺多位于甲状腺侧叶后缘与纤维囊之间，血供来自甲状腺下动脉，甲状腺次全切除时易被误切或损伤。甲状旁腺激素调节钙磷代谢，分泌不足使血钙降低、神经肌肉兴奋性增高，出现手足搐搦。甲状腺功能低下表现为代谢率降低和黏液性水肿"},{"q":"肾上腺的描述中，正确的是","o":["腹膜内位器官","腹膜间位器官","腹膜后位器官","不是内分泌腺","是混合腺，既是内分泌腺又是外分泌腺"],"a":2,"e":"肾上腺位于肾的上内方，仅前面被腹膜覆盖，属腹膜外位即腹膜后位器官，与肾同被肾筋膜包绕，其间有疏松结缔组织分隔。肾上腺为内分泌腺，分泌糖皮质激素、盐皮质激素和肾上腺素，无外分泌部，不属混合腺"},{"q":"既可以屈髋关节又可以屈膝关节，并使膝关节旋内的肌是","o":["缝匠肌","股四头肌","大收肌","阔筋膜张肌","股薄肌"],"a":0,"e":"缝匠肌为全身最长的肌，起自髂前上棘，止于胫骨上端内侧面，可屈髋、屈膝并使已屈的膝关节旋内，由股神经支配。股四头肌屈髋伸膝；股薄肌、大收肌属内侧群，主要内收髋关节；阔筋膜张肌紧张阔筋膜并屈髋，均不能屈膝"},{"q":"躯干骨不包括","o":["椎骨","肋","尾骨","骶骨","肩胛骨"],"a":4,"e":"躯干骨包括24块椎骨、1块骶骨、1块尾骨、1块胸骨和12对肋，参与构成脊柱、胸廓和骨盆后壁。肩胛骨属上肢带骨，与锁骨共同构成上肢带，位于胸廓后外侧，不列入躯干骨；肋虽参与胸廓构成，仍属躯干骨"},{"q":"动眼神经损伤可使患者出现","o":["患侧眼内斜视","患侧眼内斜视和瞳孔缩小","对侧眼外斜视","患侧眼外斜视和瞳孔散大","对侧偏盲"],"a":3,"e":"动眼神经支配除外直肌和上斜肌以外的全部眼外肌及上睑提肌，损伤后内直肌瘫痪，外直肌牵拉使患眼外斜视并上睑下垂；副交感纤维中断致瞳孔括约肌麻痹，瞳孔散大、对光反射消失。内斜视为展神经损伤，对侧偏盲为视交叉以上视路损伤"},{"q":"属于头颈部深静脉的是","o":["颈外静脉","颈前静脉","颈内静脉","面静脉","颞浅静脉"],"a":2,"e":"头颈部静脉分浅、深两组，深静脉包括颈内静脉、锁骨下静脉和颅内静脉，颈内静脉于颈静脉孔处续于乙状窦，是颈部最粗大的静脉，管腔常处于开放状态。面静脉、颞浅静脉、颈前静脉和颈外静脉均属浅静脉"},{"q":"关于直肠的描述正确的是","o":["有结肠带","穿盆膈接续肛管","上段为腹膜内位","中段为腹膜间位","没有弯曲"],"a":1,"e":"直肠在第3骶椎前方起自乙状结肠，沿骶、尾骨前面下行，穿盆膈移行于肛管，矢状面上有骶曲和会阴曲。直肠上段前面和两侧有腹膜覆盖，属腹膜间位；中段仅前面覆以腹膜，为腹膜外位；直肠无结肠带、结肠袋和肠脂垂"},{"q":"管理角膜感觉的神经","o":["视神经","面神经","眼神经","动眼神经","上颌神经"],"a":2,"e":"角膜的一般躯体感觉由眼神经传导，眼神经发出鼻睫神经，其睫状长神经穿巩膜入眼球，分布于角膜、虹膜和睫状体。动眼神经含躯体运动和副交感纤维，面神经管理泪腺分泌和眼轮匝肌，上颌神经分布于下睑、鼻翼及上唇皮肤"},{"q":"防止子宫脱垂的韧带","o":["子宫骶韧带","子宫圆韧带","子宫主韧带","子宫阔韧带","骨盆漏斗韧带"],"a":2,"e":"子宫主韧带位于阔韧带基部，由结缔组织和平滑肌构成，自子宫颈两侧连至盆侧壁，固定子宫颈、防止子宫脱垂。子宫圆韧带维持子宫前倾，子宫骶韧带向后上牵引子宫颈协同维持前倾前屈，阔韧带限制子宫向两侧移动"},{"q":"阻塞后引起左心室侧壁梗死","o":["前室间支","后室间支","左心室后支","旋支","动脉圆锥支"],"a":3,"e":"旋支为左冠状动脉的终支之一，分布于左心房、左心室侧壁及后壁的一部分，并发出左缘支供应心左缘，阻塞时致左心室侧壁梗死。前室间支供应左心室前壁和室间隔前2/3，后室间支供应下壁和室间隔后1/3，左心室后支为右冠状动脉分支"},{"q":"关于膀胱的叙述，错误的是","o":["膀胱三角是结核、肿瘤和炎症的好发部位","分为尖、体、底和颈四部分","膀胱三角位于尿道内口与输尿管口之间","正常成年人膀胱容量为200～400ml","膀胱的最下部为膀胱颈"],"a":3,"e":"成年人膀胱容量平均350～500ml，超过500ml时因壁张力过大而疼痛，新生儿约为成人的1/10。膀胱空虚时呈三棱锥体形，分尖、体、底和颈四部，膀胱三角位于两输尿管口与尿道内口之间，是结核、肿瘤和炎症的好发部位"},{"q":"降肋助呼气的肌是","o":["前、中、后斜角肌","肋间内肌","肋间外肌","前锯肌","胸小肌"],"a":1,"e":"肋间内肌起自下位肋骨上缘，肌束斜向前上，止于上位肋骨下缘，收缩时降肋、缩小胸廓，助呼气。肋间外肌肌束斜向前下，提肋助吸气；前斜角肌和胸小肌可上提肋助吸气，前锯肌主要拉肩胛骨向前并紧贴胸廓"},{"q":"关于心包的叙述，错误的是","o":["分为纤维性心包和浆膜性心包","纤维性心包与浆膜性心包相移行为心包腔","浆膜性心包贴于纤维性心包内面","浆膜性心包覆盖于心表面","心包位于纵隔内"],"a":1,"e":"浆膜心包的脏层贴于心表面构成心外膜，壁层衬于纤维心包内面，脏、壁两层在出入心的大血管根部互相移行，两层之间的潜在腔隙才是心包腔。纤维心包与浆膜心包壁层紧密相贴，不移行成腔；心包位于中纵隔内，包裹心和大血管根部"},{"q":"一患者左侧大脑Broca区损伤，可能会发生","o":["无法阅读原先认识的字，不理解文字符号的意义，因Broca区是视觉性语言区","虽能发音，无法说出有意义的语言，因Broca区是运动性语言区","手的运动存在，但无法完成写字、绘图等精细动作，因Broca区是书写区","尽管视觉正常，对原先认识的字不能阅读，因Broca区是视觉性语言区","能听见别人讲话，但不理解讲话的内容，因Broca区是听觉语言区"],"a":1,"e":"Broca区即运动性语言中枢，位于优势半球额下回后1/3，损伤后虽能发音，但不能说出有意义的语言，称运动性失语。角回为视觉性语言区，损伤致失读；额中回后部为书写中枢，损伤致失写；颞上回后部损伤致感觉性失语"},{"q":"胃的供血动脉中起自肝固有动脉的是","o":["胃左动脉","胃右动脉","胃后动脉","胃短动脉","胃网膜右动脉"],"a":1,"e":"胃右动脉起自肝固有动脉，沿胃小弯向左与胃左动脉吻合，分布于胃小弯侧胃壁。胃左动脉直接起自腹腔干，胃网膜右动脉起自胃十二指肠动脉，胃网膜左动脉和胃短动脉起自脾动脉，胃后动脉多起自脾动脉"},{"q":"子宫峡位于","o":["子宫与输卵管之间","子宫体与子宫颈之间","子宫颈阴道上部与子宫颈阴道部之间","子宫颈与阴道之间","子宫体与子宫颈阴道部之间"],"a":1,"e":"子宫峡位于子宫体与子宫颈相接处，非孕时长约1cm，妊娠末期伸展变薄形成子宫下段，是剖宫取胎的切开部位。子宫颈分阴道部和阴道上部，二者以阴道附着处为界，与子宫峡不在同一平面；子宫与输卵管之间为输卵管子宫口所在"},{"q":"锥体交叉","o":["位于脑桥腹侧","位于中脑的大脚底","感觉传导束的交叉处","皮质脊髓束的交叉纤维","锥体外系纤维的交叉处"],"a":3,"e":"锥体交叉位于延髓锥体下端，是皮质脊髓束75%～90%纤维越中线交叉之处，交叉后形成皮质脊髓侧束。内侧丘系交叉位于其上方，由薄、楔束核发出的感觉纤维交叉形成，两者不在同一平面；锥体外系经红核脊髓束、网状脊髓束下行，无锥体交叉"},{"q":"关于阴茎的描述何者正确","o":["分为头、体、颈三部","分为头、体、颈、根四部","分为头、体、根三部","由一个阴茎海绵体构成","由两个尿道海绵体构成"],"a":2,"e":"阴茎分头、体、根三部分，由两条阴茎海绵体和一条尿道海绵体构成，尿道海绵体前端膨大为阴茎头，末端有尿道外口，两条阴茎海绵体并列于背侧。阴茎无颈部；尿道海绵体只有一条，位于腹侧并包绕尿道"},{"q":"穿过茎乳孔的脑神经","o":["动眼神经","面神经","展神经","舌下神经","副神经"],"a":1,"e":"面神经连于脑桥延髓沟外侧部，经内耳门、内耳道入面神经管，最后穿茎乳孔出颅，出孔后进入腮腺，分颞、颧、颊、下颌缘和颈五支。动眼神经、展神经经眶上裂，舌下神经经舌下神经管，副神经经颈静脉孔"},{"q":"在腕骨，从桡侧至尺侧，远侧列的腕骨是","o":["钩骨、小多角骨、头状骨、大多角骨","头状骨、小多角骨、大多角骨、钩骨","小多角骨、大多角骨、头状骨、钩骨","大多角骨、小多角骨、头状骨、钩骨","大多角骨、小多角骨、三角骨、钩骨"],"a":3,"e":"腕骨远侧列自桡侧向尺侧依次为大多角骨、小多角骨、头状骨和钩骨，近侧列为手舟骨、月骨、三角骨和豌豆骨。大多角骨与第1掌骨底构成拇指腕掌关节，钩骨与第4、5掌骨底相关节；三角骨与豌豆骨属近侧列"},{"q":"有关脾的功能正确的是","o":["是人体最大的淋巴结","不具有造血功能","清除衰老的红细胞","不能参加免疫应答反应","不具有内分泌功能"],"a":2,"e":"脾是人体最大的淋巴器官，具有储血、造血、清除衰老红细胞和参与免疫应答的功能，胚胎期可造红细胞和粒细胞。淋巴结遍布全身但体积小，不能称最大的淋巴结；脾无外分泌部，不是混合腺，被膜内平滑肌收缩可调节储血"},{"q":"下丘脑的功能不包括","o":["神经内分泌的调节","自主神经的调节","视觉的中继站","体温的调节","摄食行为的调节"],"a":2,"e":"下丘脑是神经内分泌和自主神经的高级中枢，调节体温、摄食、水平衡、情绪和昼夜节律，并控制垂体前、后叶的分泌。视觉的中继站是后丘脑的外侧膝状体，听觉中继站为内侧膝状体，两者均属下丘脑以外的结构"},{"q":"在头面部的痛温觉传导通路中，第1级神经元胞体位于","o":["脊神经节","睫状神经节","三叉神经脊束核","三叉神经脑桥核","三叉神经节"],"a":4,"e":"头面部痛温觉传导的第1级神经元胞体位于三叉神经节，属假单极神经元，周围突经三叉神经分支分布于面部皮肤和口鼻黏膜，中枢突入脑桥后主要止于三叉神经脊束核。三叉神经脊束核为第2级神经元所在，睫状神经节为副交感神经节"},{"q":"肾门位于","o":["肾的外侧缘","肾的内侧缘","肾的上端","肾的下端","肾的前面"],"a":1,"e":"肾门位于肾内侧缘中部凹陷处，是肾静脉、肾动脉、肾盂、神经和淋巴管出入的部位，肾门向肾内续为肾窦，容纳肾小盏、肾大盏和脂肪。肾外侧缘隆凸，上、下端钝圆，前面凸起贴腹膜，后面平坦紧贴腹后壁"},{"q":"上颌窦的开口位于","o":["下鼻道","上鼻道","中鼻道","后鼻道","前鼻道"],"a":2,"e":"上颌窦开口于中鼻道半月裂孔，窦口高于窦底，直立位积液不易引流，是鼻窦炎的好发部位。额窦、前筛窦和中筛窦也开口于中鼻道，后筛窦开口于上鼻道，蝶窦开口于蝶筛隐窝，鼻泪管开口于下鼻道，均不属上颌窦开口"},{"q":"心脏瓣膜复合体不包括哪个结构","o":["二、三尖瓣瓣环","瓣尖","腱索","乳头肌","肉柱"],"a":4,"e":"心脏瓣膜复合体由瓣环、瓣叶即瓣尖、腱索和乳头肌构成，四者协同保证血液单向流动，任一结构损伤即引起血流动力学改变。肉柱是心室壁的肌性隆起，见于右心室流入道，与瓣膜启闭无关；隔缘肉柱内含右束支，属心室壁结构"},{"q":"损伤视交叉中央处，两眼视野表现为","o":["双眼右侧偏盲","左眼鼻侧偏盲","双眼颞侧偏盲","右眼鼻侧偏盲","双眼全盲"],"a":2,"e":"视交叉中来自两眼视网膜鼻侧半的纤维交叉至对侧，来自颞侧半的纤维不交叉，故中央部交叉纤维损伤时双眼颞侧视野缺损，称双眼颞侧偏盲。一侧视神经损伤致该眼全盲，视束及以后视路损伤致双眼对侧同向性偏盲"},{"q":"掌深弓的组成","o":["由桡动脉的末端和尺动脉的掌深支组成","常由尺动脉的末端单独组成","常由桡动脉单独组成","由桡动脉的末端和尺动脉的末端组成","与掌浅弓没有吻合"],"a":0,"e":"掌深弓由桡动脉末端与尺动脉掌深支吻合而成，位于指深屈肌腱深面，弓的凸侧约平腕掌关节，发出3支掌心动脉注入指掌侧总动脉。掌浅弓由尺动脉末端与桡动脉掌浅支吻合而成，两弓之间有多处吻合支相通"},{"q":"关于脾切迹的描述正确的是","o":["脾前缘下部有2～3个切迹","后缘有2～3个切迹","正常情况下在肋弓下可触及","上端锐利","脾大时是触诊脾的标志"],"a":4,"e":"脾切迹位于脾上缘前部，有2～3个，脾大时可在肋弓下触及，是触诊辨认脾的标志。脾下缘较钝，上缘较锐；正常脾位于左季肋区第9～11肋深面，肋弓下不能触及；后端钝圆朝向后内方，前端较宽达腋中线"},{"q":"关于肺的淋巴管注入的淋巴结是","o":["胸骨旁淋巴结","肋间后淋巴结","气管旁淋巴结","支气管肺淋巴结","纵隔后淋巴结"],"a":3,"e":"肺的淋巴管注入肺淋巴结和支气管肺门淋巴结，再经气管支气管淋巴结、气管旁淋巴结引流至右淋巴导管或胸导管。胸骨旁淋巴结引流乳房内侧部和胸腹前壁，肋间后淋巴结收纳胸壁，纵隔后淋巴结接纳食管和心包的淋巴"},{"q":"第7颈椎的形态结构特征不包括","o":["又名隆椎","棘突长而不分叉","活体易于触及","常作为计数椎骨序数的标志","横突孔有椎动脉经过"],"a":4,"e":"第7颈椎棘突长而不分叉，末端隆起，活体易触及，称隆椎，是计数椎骨序数的标志，其棘突也常作为针刺取穴的定位点。椎动脉穿经第6至第1颈椎的横突孔，第7颈椎横突孔无椎动脉通过，故该项不属隆椎特征"},{"q":"参与协调眼球运动和头部姿势的纤维束","o":["网状脊髓束","顶盖脊髓束","内侧纵束","前庭脊髓束","红核脊髓束"],"a":2,"e":"内侧纵束位于前索和脑干中线两侧，上起中脑、下至颈髓，联系前庭神经核与动眼、滑车、展神经核及副神经脊髓核、颈髓前角，协调眼外肌运动和头颈姿势。顶盖脊髓束完成视听反射，前庭脊髓束调节躯干四肢姿势，红核脊髓束影响屈肌张力"},{"q":"子宫圆韧带的作用","o":["牵引子宫颈向后","维持子宫前倾","上提子宫底","防止子宫向下脱垂","防止子宫向两侧移位"],"a":1,"e":"子宫圆韧带起自子宫角前下方，经腹股沟管止于大阴唇皮下，牵拉子宫向前，维持子宫前倾，是维持前倾的主要结构。子宫主韧带防止子宫脱垂，子宫骶韧带向后上牵引子宫颈、协同维持前倾前屈，阔韧带限制子宫向两侧移动"},{"q":"小脑幕切迹与鞍背之间成一环形孔即小脑幕裂孔，该孔之间有","o":["中脑","脑桥","脑干","延髓","小脑"],"a":0,"e":"小脑幕切迹与鞍背之间形成小脑幕裂孔，内有中脑通过；幕切迹上方的海马旁回和钩下移即形成小脑幕切迹疝，压迫大脑脚和动眼神经，出现同侧瞳孔散大和对侧肢体瘫。枕骨大孔有延髓通过，脑桥位于斜坡上方，小脑居幕下"},{"q":"关于胫神经的叙述，错误的是","o":["为坐骨神经主干的延续","在腘窝内，胫神经位于腘血管的浅面","在踝管内分为足底内侧神经和足底外侧神经","支配足底所有短肌","支配小腿外侧群肌"],"a":4,"e":"胫神经为坐骨神经主干的直接延续，在腘窝内位于腘血管的浅面，于踝管内分为足底内侧神经和足底外侧神经，支配小腿后群肌和足底全部短肌。小腿外侧群即腓骨长、短肌由腓浅神经支配，故该项描述有误"},{"q":"肾的被膜从内向外依次是","o":["肾筋膜、脂肪囊、纤维囊","肾筋膜、纤维囊、脂肪囊","脂肪囊、纤维囊、肾筋膜","脂肪囊、肾筋膜、纤维囊","纤维囊、脂肪囊、肾筋膜"],"a":4,"e":"肾的被膜自内向外为纤维囊、脂肪囊和肾筋膜，纤维囊贴于肾实质表面、易于剥离，脂肪囊即肾床，肾筋膜包被肾和肾上腺并发出小梁固定肾。肾筋膜位于最外层，与纤维囊之间隔以脂肪囊，二者并不相贴"},{"q":"声门裂位于","o":["两侧喉室之间","两侧声襞之间","两侧声韧带之间","两侧前庭襞之间","方形膜和弹性圆锥之间"],"a":1,"e":"声门裂是两侧声襞与杓状软骨底、声带突之间的裂隙，为喉腔最狭窄处，前2/3位于声带之间为膜间部，后1/3为软骨间部。两侧前庭襞之间为前庭裂，较声门裂宽；声韧带是声襞的支架，喉室位于前庭襞与声襞之间"},{"q":"椎前神经节不包括哪个结构","o":["腹腔神经节","主动脉肾神经节","肠系膜上神经节","肠系膜下神经节","星状神经节"],"a":4,"e":"椎前神经节位于脊柱前方、同名动脉根部，包括腹腔神经节、主动脉肾神经节、肠系膜上神经节和肠系膜下神经节。星状神经节即颈胸神经节，由颈下神经节与第1胸神经节合并而成，位于脊柱两旁，属椎旁神经节"},{"q":"损伤后导致共济失调的纤维束","o":["脊髓丘脑前束","脊髓丘脑侧束","脊髓小脑束","皮质脊髓侧束","皮质脊髓前束"],"a":2,"e":"脊髓小脑前、后束把躯干和下肢的本体感觉传入小脑，参与肌张力和运动协调，损伤后出现共济失调、醉汉步态。脊髓丘脑束传导痛温觉与粗触觉，皮质脊髓侧束和皮质脊髓前束管理随意运动，损伤表现为瘫痪而非共济失调"},{"q":"位于中脑顶盖的结构是","o":["红核","黑质","动眼神经核","三叉神经中脑核","上丘"],"a":4,"e":"中脑顶盖由一对上丘和一对下丘构成，上丘为视觉反射中枢，下丘为听觉反射中枢。红核、黑质位于被盖与大脑脚底，动眼神经核位于中央灰质腹侧，三叉神经中脑核位于中央灰质外侧，均属中脑其他部分而非顶盖"},{"q":"右侧内囊膝损伤可出现","o":["左侧下肢肌瘫痪","右侧下肢肌瘫痪","左侧面肌全部瘫痪","左侧睑裂以下面肌瘫痪","右侧舌肌瘫痪"],"a":3,"e":"右侧内囊膝含来自左侧中央前回下部的皮质核束，损伤后对侧面下部肌和舌肌核上瘫，故左侧睑裂以下面肌瘫痪，伸舌偏向左侧。面上部肌受双侧皮质核束支配，额纹和闭眼不受影响；上下肢瘫由内囊后肢皮质脊髓束损伤引起"},{"q":"桡神经沟位于","o":["肱骨体中部的后面内上斜向外下的浅沟","肱骨体中部的前面内上斜向外下的浅沟","肱骨体中部的后面外上斜向内下的浅沟","肱骨体中部的前面外上斜向内下的浅沟","肱骨体中部的后面横行的浅沟"],"a":0,"e":"桡神经沟位于肱骨体后面中部，自内上斜向外下，容纳桡神经和肱深动脉，肱骨中段骨折易伤及桡神经而出现垂腕。肱骨前面有结节间沟，后面内侧的尺神经沟位于内上髁后方，两者走行方向与桡神经沟不同"},{"q":"舌咽神经管理的腺体是","o":["腮腺","泪腺","舌下腺","下颌下腺","甲状腺"],"a":0,"e":"舌咽神经的一般内脏运动纤维起自下泌涎核，经鼓室神经、岩小神经至耳神经节换元，节后纤维经耳颞神经管理腮腺分泌。面神经的副交感纤维经鼓索和下颌下神经节管理舌下腺、下颌下腺，经岩大神经和翼腭神经节管理泪腺"},{"q":"胸骨角平对","o":["第1肋","第2肋","第3肋","第4肋","第5肋"],"a":1,"e":"胸骨角由胸骨柄与胸骨体连接处向前突出形成，两侧平对第2肋软骨，是计数肋和肋间隙的起点，向后平第4胸椎体下缘。第1肋与胸骨柄相接，故不能作为计数起点；胸骨角平面同时是上、下纵隔的分界"},{"q":"关于腹主动脉分支，错误的说法是","o":["分为壁支和脏支","脏支包括成对和不成对的","最上方不成对的脏支为腹腔干","阑尾动脉为其主要分支之一","肾上腺中动脉为该动脉发出的脏支"],"a":3,"e":"腹主动脉分壁支和脏支，脏支中成对的有肾上腺中动脉、肾动脉、睾丸或卵巢动脉，不成对的有腹腔干、肠系膜上动脉和肠系膜下动脉，最上方者为腹腔干。阑尾动脉起自回结肠动脉，属肠系膜上动脉的三级分支"},{"q":"关于肺静脉的正确记述是","o":["注入右心房","含有静脉血","含左上、左下肺静脉","含右上、右中、右下肺静脉","位于肺根的最上方"],"a":2,"e":"肺静脉每侧两条，即左上、左下肺静脉和右上、右下肺静脉，起自肺门注入左心房后部，输送含氧量高的血液。右上肺静脉收集右肺上、中叶血液，故不存在右中肺静脉；肺静脉位于肺根前下方，内含动脉血"},{"q":"寰枕关节属于","o":["屈戌关节","车轴关节","椭圆关节","鞍状关节","球窝关节"],"a":2,"e":"寰枕关节由枕髁与寰椎侧块上关节凹构成，属双轴椭圆关节，可作俯仰和侧屈运动。寰枢正中关节为车轴关节，桡腕关节为典型椭圆关节，拇指腕掌关节为鞍状关节，肩、髋关节为球窝关节，指间关节为屈戌关节"},{"q":"关于心脏表面标志正确的说法是","o":["冠状沟分隔左、右心房","界沟分隔心房、心室","室间沟深部为室间隔","心尖左侧有心尖切迹","冠状沟位于人体的冠状面上"],"a":2,"e":"前、后室间沟是左、右心室在心表面的分界，沟底深部即室间隔，沟内有室间支及心大静脉走行。冠状沟分隔心房与心室，界沟位于右心房表面、分隔腔静脉窦与右心耳，二者均不位于冠状面上，也不分隔左右心房"},{"q":"背侧丘脑腹后外侧核接受","o":["三叉丘系纤维","内侧丘系、脊髓丘系","嗅觉纤维","味觉纤维","内脏感觉纤维"],"a":1,"e":"腹后外侧核接受内侧丘系和脊髓丘系的纤维，发出丘脑中央辐射经内囊后肢投射至中央后回中、上部，传导对侧躯干和四肢的感觉。三叉丘系和味觉纤维止于腹后内侧核；嗅觉纤维直接入嗅球和嗅皮质，不经丘脑腹后核"},{"q":"关于腹膜腔的叙述，错误的是","o":["女性腹膜腔与外界相通","为全身最大的浆膜","有吸收功能","由壁腹膜和脏腹膜围成","包裹所有的腹腔脏器"],"a":4,"e":"腹膜腔是壁腹膜与脏腹膜之间的潜在腔隙，内含少量浆液，有吸收功能，女性经输卵管腹腔口、子宫和阴道与外界相通。腹膜仅覆盖腹、盆腔脏器表面，肾、胰等腹膜外位器官只有一面被覆，并非包裹所有腹腔脏器"},{"q":"关于胸导管的叙述，下列哪项是正确的","o":["于奇静脉和腹主动脉之间上行","上段与右侧纵隔胸膜所相邻","在第5胸椎平面处斜行向左","在下纵隔，胸导管位于食管的左侧","最后注入右颈静脉角"],"a":2,"e":"胸导管平第12胸椎下缘起自乳糜池，经主动脉裂孔入胸腔，沿脊柱右前方、胸主动脉与奇静脉之间上行，至第5胸椎高度经食管后方斜向左侧，再沿脊柱左前方上行，注入左静脉角。其上段与左侧纵隔胸膜相邻，在下纵隔位于食管右后方"},{"q":"正中神经损伤典型症状的状态是","o":["“垂腕症”","“猿手”","“爪形手”","“方肩”","“翼状肩”"],"a":1,"e":"正中神经损伤后鱼际肌萎缩、手掌平坦，桡侧三个半指掌面感觉障碍，拇指不能对掌和对指，手形称“猿手”，高位损伤时前臂屈肌亦受累。垂腕为桡神经损伤，爪形手为尺神经损伤，方肩为腋神经损伤，翼状肩为胸长神经损伤"},{"q":"眼球壁三层结构，由外向内依次为","o":["虹膜、血管膜、视网膜","纤维膜、血管膜、视网膜","纤维膜、角膜、视网膜","角膜、血管膜、视网膜","角膜、巩膜、视网膜"],"a":1,"e":"眼球壁自外向内为纤维膜、血管膜和视网膜，纤维膜前1/6为角膜、后5/6为巩膜，血管膜由虹膜、睫状体和脉络膜组成，视网膜分虹膜部、睫状体部和视部。角膜与巩膜同属纤维膜，不能与纤维膜并列为三层之一"},{"q":"关于盲肠描述正确的是","o":["其右侧接回肠","长3～5cm","位置不固定","一部分被腹膜包裹","为腹膜内位器官"],"a":4,"e":"盲肠为腹膜内位器官，各面均被腹膜覆盖，因无系膜或仅有短小系膜而位置相对固定，回肠末端开口于其左后壁，阑尾附于其后内侧壁。盲肠长约6～8cm，位于右髂窝，向上续为升结肠，其右侧并不接回肠"},{"q":"尺骨的骨性标志不包括","o":["尺骨后缘","桡切迹","鹰嘴","尺骨头","茎突"],"a":0,"e":"官方答案为【尺骨后缘】，但依据教材，正确答案为【桡切迹】。鹰嘴、尺骨后缘全长、尺骨头和尺骨茎突均可在体表扪及，属尺骨骨性标志；桡切迹位于尺骨近端外侧，与桡骨头环状关节面构成桡尺近侧关节，包于关节囊内，不能触及，才是被排除项"},{"q":"以下哪个不是迷走神经颈部的分支","o":["喉上神经","耳支","咽支","脑膜支","左喉返神经"],"a":4,"e":"迷走神经在颈部发出喉上神经、咽支、耳支、脑膜支及颈心支，耳支发自上神经节，分布于耳廓后面皮肤。喉返神经在胸部发出，右侧绕右锁骨下动脉、左侧绕主动脉弓后返回颈部，故左喉返神经不属颈部发出分支"},{"q":"不直接起自腹主动脉的是","o":["脾动脉","肠系膜上动脉","睾丸动脉","肾动脉","肾上腺中动脉"],"a":0,"e":"脾动脉为腹腔干三大分支之一，沿胰上缘蜿蜒左行至脾门，沿途发出胰支，脾大时走行更为迂曲。肠系膜上动脉、睾丸或卵巢动脉、肾动脉、肾上腺中动脉均直接起自腹主动脉的前壁或侧壁，不经腹腔干"},{"q":"脊髓蛛网膜","o":["位于软脊膜的内面","位于硬脑膜的外面","其外面有脑脊液流动","与硬脊膜之间有终池","与软脊膜之间的间隙称蛛网膜下隙"],"a":4,"e":"脊髓蛛网膜为半透明无血管的薄膜，位于硬脊膜与软脊膜之间，其与软脊膜之间的宽阔间隙为蛛网膜下隙，内含脑脊液。下端起自脊髓末端至第2骶椎的一段扩大为终池，内容马尾；它与硬脊膜之间为硬膜下隙，并非终池所在"},{"q":"关于锥体交叉和内侧丘系交叉，下列说法错误的是","o":["位于延髓内，锥体交叉位置较低","位于延髓内，内侧丘系交叉位置较高","在延髓内位于同一平面","锥体交叉是运动纤维交叉","内侧丘系交叉属于感觉纤维交叉"],"a":2,"e":"锥体交叉位于延髓下部，是皮质脊髓束75%～90%纤维的交叉处，属运动纤维交叉；内侧丘系交叉位于其上方，由薄束核和楔束核发出的感觉纤维交叉形成。两者在延髓内上下分居不同平面，“同平面”之说与延髓内部结构不符"},{"q":"鼓索含有","o":["特殊内脏运动和一般内脏感觉两种纤维","一般内脏运动和一般内脏感觉两种纤维","特殊内脏感觉和一般内脏感觉两种纤维","特殊内脏感觉和特殊内脏运动两种纤维","特殊内脏感觉和一般内脏运动两种纤维"],"a":4,"e":"鼓索在面神经出茎乳孔前发出，穿岩鼓裂出鼓室加入舌神经，含特殊内脏感觉和一般内脏运动两种纤维：前者司舌前2/3味蕾，后者经下颌下神经节换元后控制舌下腺和下颌下腺分泌。面神经本干另含支配面肌的特殊内脏运动纤维"},{"q":"临床上，可触及肩胛骨的主要骨性标志包括","o":["肩胛冈、肩峰、肩胛骨下角、内侧缘及肩胛下窝","肩胛冈、肩峰、肩胛骨下角、内侧缘及冈下窝","肩胛冈、肩峰、肩胛骨下角、内侧缘及喙突","肩胛冈、肩峰、肩胛骨下角、内侧缘及冈上窝","肩胛冈、肩峰、肩胛骨下角、内侧缘及肩胛切迹"],"a":2,"e":"肩胛冈、肩峰、肩胛下角、内侧缘和喙突均可在体表扪及，肩胛下角平第7肋，是背部计数肋的标志。肩胛下窝、冈上窝和冈下窝为骨面凹陷，被肌覆盖不可触及；肩胛切迹位于上缘，位置深在，亦不能扪及"},{"q":"关于鼓室内侧壁的描述，不正确的是","o":["中部的隆起称为岬","岬的后上方有前庭窗","岬的后下方有蜗窗","前庭窗的后上方有面神经管凸","蜗窗由镫骨底封闭"],"a":4,"e":"鼓室内侧壁中部隆起为岬，由耳蜗第一圈隆凸形成，岬的后上方为前庭窗，由镫骨底及其周缘韧带封闭；岬的后下方为蜗窗，由第二鼓膜封闭。前庭窗后上方有面神经管凸，为面神经水平段所在，是手术易损伤处"},{"q":"只接受对侧皮质核束纤维的神经核是","o":["三叉神经运动核","滑车神经核","动眼神经核","舌下神经核","展神经核"],"a":3,"e":"舌下神经核位于延髓上部舌下神经三角深面，只接受对侧皮质核束纤维，故核上瘫时伸舌偏向病灶对侧，核下瘫则同侧舌肌萎缩。面神经核下部亦仅受对侧皮质核束支配；动眼、滑车、展和三叉神经运动核均接受双侧纤维"},{"q":"外旋肩关节的肌是","o":["胸大肌","背阔肌","冈上肌","小圆肌","大圆肌"],"a":3,"e":"小圆肌起自肩胛骨外侧缘背面，止于肱骨大结节下部，由腋神经支配，使肩关节旋外。冈下肌同为旋外肌；胸大肌、背阔肌和大圆肌均使肩关节旋内，其中背阔肌与大圆肌兼后伸、内收，冈上肌主司外展"},{"q":"寰枢正中关节属于","o":["屈戌关节","车轴关节","椭圆关节","鞍状关节","球窝关节"],"a":1,"e":"寰枢正中关节由枢椎齿突与寰椎前弓后面及寰椎横韧带构成，属车轴关节，沿垂直轴旋转使头转向一侧。寰枢外侧关节由寰椎侧块下关节面与枢椎上关节面构成，属平面关节；寰枕关节为椭圆关节，司俯仰和侧屈"},{"q":"有关腹膜腔，描述正确的是","o":["经横结肠及胃结肠韧带分为结肠上区和结肠下区","大、小腹膜腔经网膜孔相通","半卧位最低部位是右肝下间隙","各间隙之间均相互交通","左结肠旁沟积液不易流出"],"a":1,"e":"网膜囊即小腹膜腔，借网膜孔与腹膜腔其余部分即大腹膜腔相通，网膜孔位于肝十二指肠韧带后方。腹膜腔以横结肠及其系膜分为结肠上区和结肠下区，各间隙借沟和隐窝相互通连；半卧位时最低处为盆腔的直肠子宫陷凹"},{"q":"关于面静脉走行的正确的描述是","o":["起自内眦静脉","注入颈外静脉","在颈内、颈外动脉的深面走行","通过面深静脉与乙状窦相通","位于面动脉前方"],"a":0,"e":"面静脉起自内眦静脉，在面动脉后方下行，跨过颈内、外动脉表面，至舌骨大角附近注入颈内静脉，经眼上静脉与海绵窦相通，经面深静脉与翼静脉丛相通。面静脉无瓣膜，面部感染可逆行入颅，故鼻根至两口角称危险三角"},{"q":"听小骨链正确的关节顺序是","o":["锤骨-砧骨-镫骨","锤骨-镫骨-砧骨","砧骨-锤骨-镫骨","镫骨-砧骨-锤骨","镫骨-锤骨-砧骨"],"a":0,"e":"鼓室内三块听小骨以关节连成链，锤骨柄附于鼓膜，锤骨头与砧骨体形成砧锤关节，砧骨长脚与镫骨头形成砧镫关节，镫骨底封闭前庭窗，声波振动经此链传入内耳。其余排列均颠倒或错置了砧锤、砧镫关节的连接顺序"},{"q":"筛窦后群开口于","o":["中鼻道","上鼻道","下鼻道","蝶筛隐窝","鼻泪管"],"a":1,"e":"筛窦分前、中、后三群，前群和中群开口于中鼻道，后群开口于上鼻道，故后群感染易波及毗邻的视神经管。额窦开口于中鼻道筛漏斗，上颌窦开口于中鼻道半月裂孔，蝶窦开口于蝶筛隐窝，鼻泪管开口于下鼻道"},{"q":"关于胸腺的描述，不正确的是","o":["向上可伸入胸廓上口","位于胸骨柄的后方","上纵隔的前部","胸腺是淋巴器官","新生儿的胸腺较小"],"a":4,"e":"胸腺位于上纵隔前部、胸骨柄后方，分左右两叶，上端可伸入胸廓上口至颈部，是中枢淋巴器官，培育并向周围淋巴器官输送T细胞。新生儿和幼儿胸腺相对较大，重10～15g，性成熟期达高峰，此后逐渐萎缩并被结缔组织替代"},{"q":"最强大的伸髋关节肌是","o":["股二头肌","半腱肌","半膜肌","臀大肌","臀中肌"],"a":3,"e":"臀大肌位于臀部浅层，起自髂骨翼外面和骶骨背面，止于髂胫束和股骨臀肌粗隆，是伸髋关节最强大的肌，下肢固定时可伸直躯干、防止前倾。股二头肌、半腱肌和半膜肌属屈膝伸髋肌，伸髋力量较弱；臀中肌主要外展髋关节"},{"q":"对纵隔的描述，正确的选项是","o":["位于胸膜腔内","上界是肺尖","容纳心、肺","两侧界是纵隔胸膜","两侧界是肺门"],"a":3,"e":"纵隔是两侧纵隔胸膜之间全部器官、结构和结缔组织的总称，前界胸骨，后界脊柱胸段，上界胸廓上口，下界膈，以胸骨角平面分为上、下纵隔。纵隔位于胸膜腔之外，心居其中，肺不属纵隔结构，肺门位于纵隔两侧面"},{"q":"尺神经在腕部豌豆骨外侧受损后，出现的症状不包括","o":["骨间肌萎缩","掌骨沟明显深陷","第4、5掌指关节过伸，指骨间关节屈曲","小鱼际肌萎缩","垂腕征"],"a":4,"e":"尺神经在腕部豌豆骨外侧损伤只累及手内肌与手尺侧感觉：骨间肌、小鱼际肌萎缩，掌骨间沟深陷，第4、5掌指关节过伸而指骨间关节屈曲呈爪形。垂腕征是桡神经在桡神经沟或腋部损伤、桡侧腕伸肌瘫痪的表现，与尺神经无关。掌骨沟深陷由骨间肌萎缩致掌骨间软组织凹陷，同属尺神经损害体征"},{"q":"棘突宽而短，呈板状，水平伸向后方的椎骨是","o":["寰椎","第2～6颈椎","隆椎","胸椎","腰椎"],"a":4,"e":"腰椎椎体粗壮，棘突宽短呈板状，几乎水平伸向后方，棘突间隙宽大，临床常在此穿刺。胸椎棘突细长、向后下方倾斜呈叠瓦状；第2～6颈椎棘突短而末端分叉；隆椎棘突长而不分叉；寰椎无椎体亦无棘突。板状水平后伸的棘突为腰椎所独有"},{"q":"可伸和外展桡腕关节的肌肉是","o":["肱桡肌","桡侧腕长伸肌","指伸肌","掌长肌","尺侧腕伸肌"],"a":1,"e":"桡侧腕长伸肌起自肱骨外上髁，肌腱止于第2掌骨底，收缩时伸腕并使腕外展，是伸与外展桡腕关节兼具的肌。桡侧腕短伸肌只伸腕而外展不明显，尺侧腕伸肌伸腕同时使腕内收，指伸肌主司伸指，掌长肌与肱桡肌则屈肘屈腕"},{"q":"左侧内囊损伤表现为","o":["左额纹消失","左侧能闭眼，左口角下垂","左侧不能闭眼，右口角下垂","右侧能闭眼，右口角下垂并向左侧偏斜","右侧不能闭眼，左口角下垂并向左侧偏斜"],"a":3,"e":"内囊后肢含皮质核束与皮质脊髓束，左侧内囊损伤致右侧上运动神经元性面瘫及偏瘫：上半面肌受双侧皮质核束支配，额纹保留、闭眼正常；下半面肌仅受对侧支配，故右口角下垂并被健侧牵向左侧。左额纹消失、左侧不能闭眼提示左侧周围性面瘫，属面神经或其核损害"},{"q":"含有内脏运动纤维的是","o":["三叉神经","副神经","面神经","舌下神经","滑车神经"],"a":2,"e":"面神经含特殊内脏运动、一般内脏运动、特殊内脏感觉与一般躯体感觉四种纤维，其副交感纤维起自上泌涎核，控制泪腺、下颌下腺与舌下腺分泌。三叉神经以一般躯体感觉为主，运动纤维只支配咀嚼肌；副神经、舌下神经与滑车神经均为纯躯体运动性，不含内脏运动纤维"},{"q":"脚踩到钉子后，下肢反射性的屈曲，分析该反射属于","o":["牵张反射","深反射","屈曲反射","单突触反射","病理反射"],"a":2,"e":"踩钉后肢体回缩属屈曲反射，皮肤痛觉经多突触通路引起屈肌收缩、伸肌舒张，是防御性反射，中枢分布于脊髓多个节段并受高位中枢调控。牵张反射由肌被快速牵拉触发，属单突触深反射，如膝跳反射；病理反射是锥体束损害后出现的异常反射"},{"q":"开口于上鼻道的器官","o":["额窦","上颌窦","筛窦前群","筛窦中群","筛窦后群"],"a":4,"e":"筛窦后群开口于上鼻道。额窦、上颌窦及筛窦前群、中群均开口于中鼻道，蝶窦则开口于上鼻甲后上方的蝶筛隐窝，故上鼻道只承接后筛窦。半坐位时上颌窦窦口位置最高，是上颌窦炎不易引流的原因"},{"q":"关于肾的位置描述，正确的是","o":["位于腹膜后间隙前","右肾略高于左肾","肾门高度约位于第2腰椎体平面","第12肋斜越左肾后面中部","两肾下端距离较近"],"a":3,"e":"左肾上端平第11胸椎下缘，下端平第2腰椎下缘，第12肋斜越左肾后面中部；右肾受肝推挤低于左肾约半个椎体，第12肋只斜越右肾后面上部。肾门约平第1腰椎体平面，两肾上端距离较近、下端距离较远"},{"q":"和眼球运动无关的眼球外肌是","o":["上睑提肌","上直肌","下直肌","上斜肌","内直肌"],"a":0,"e":"上睑提肌起自视神经管前方，止于上睑皮肤与睑板，由动眼神经支配，只提上睑而不参与眼球运动。上直肌、下直肌、内直肌与上斜肌均为眼球外肌，分别使眼球上转、下转、内转与下转外旋。故与眼球运动无关者为上睑提肌"},{"q":"关于迷走神经不正确的是","o":["分布于颈、胸、腹腔大部分脏器的平滑肌、心肌、腺体","左迷走神经勾绕锁骨下动脉经食管前面下行形成前干","参与心丛的形成","腹腔支加入腹腔神经丛","喉上神经支配环甲肌与声门裂以上的喉黏膜"],"a":1,"e":"左迷走神经勾绕主动脉弓，右迷走神经勾绕右锁骨下动脉，穿食管裂孔后左迷走神经形成前干、右迷走神经形成后干，该选项自相矛盾。迷走神经分布于颈、胸、腹腔大部分脏器的平滑肌、心肌与腺体，参与心丛，腹腔支加入腹腔神经丛，喉上神经支配环甲肌及声门裂以上喉黏膜"},{"q":"下颌神经出入颅腔的部位","o":["茎乳孔","眶下裂","圆孔","破裂孔","卵圆孔"],"a":4,"e":"三叉神经第三支即下颌神经，经卵圆孔出颅入颞下窝。上颌神经经圆孔入翼腭窝，眼神经经眶上裂入眶；面神经经茎乳孔出颅；破裂孔在活体被软骨封闭，无神经主干经此出入。故下颌神经的通道是卵圆孔"},{"q":"关于眼的神经支配的叙述，错误的是","o":["展神经支配外直肌","滑车神经支配上斜肌","上直肌由动眼神经支配","感觉神经来自三叉神经的眼支","瞳孔开大肌受副交感神经支配"],"a":4,"e":"瞳孔开大肌受交感神经支配，交感兴奋使瞳孔散大；副交感纤维自动眼神经副核发出，经睫状神经节支配瞳孔括约肌与睫状肌，司缩瞳与晶状体调节。展神经支配外直肌，滑车神经支配上斜肌，上直肌由动眼神经支配，眼球感觉经三叉神经眼支传导"},{"q":"关于舌扁桃体描述正确的是","o":["参与构成咽峡","位于界沟前方","其后方有舌盲孔","由淋巴组织构成","位于舌的两侧"],"a":3,"e":"舌扁桃体位于舌根背面黏膜内，由淋巴组织构成，参与组成咽淋巴环。界沟前方为舌体，后方为舌根，舌盲孔正位于界沟中点、舌扁桃体前方。咽峡由腭垂、两侧腭舌弓与舌根围成；舌扁桃体位于舌根而非舌的两侧"},{"q":"关于空、回肠描述正确的是","o":["空肠上接十二指肠上曲","回肠下续结肠","近侧3/5为空肠，远侧2/5为回肠","约2%的成人，在回肠末端0.3～1m范围内，有Meckel憩室","空肠肠壁内有集合淋巴"],"a":3,"e":"约2%的成人回肠末端0.3～1m范围内可见Meckel憩室，为胚胎卵黄蒂残留形成的盲囊。空肠起自十二指肠空肠曲而非十二指肠上曲，回肠末端续于盲肠；近侧2/5为空肠、远侧3/5为回肠；集合淋巴滤泡见于回肠，空肠只有孤立淋巴滤泡"},{"q":"只能外展肩关节的肌是","o":["胸大肌","背阔肌","冈上肌","小圆肌","三角肌"],"a":2,"e":"冈上肌起自冈上窝，止于肱骨大结节上部，收缩时使肩关节外展，是唯一只司外展而不兼其他运动的肌。三角肌亦能外展肩关节，但兼可前屈、后伸与旋转；胸大肌、背阔肌主内收内旋；小圆肌使肩关节外旋"},{"q":"关于尺神经正确的是","o":["发自臂丛外侧束","支配前臂所有屈肌","经肱骨下端尺神经沟下行进入前臂","损伤后不影响拇指的任何功能","肱骨外侧髁骨折时易受损"],"a":2,"e":"尺神经发自臂丛内侧束，经肱骨内上髁后方的尺神经沟下行入前臂，该沟处位置表浅，肱骨内上髁骨折时最易损伤。前臂屈肌大部由正中神经支配，尺神经只支配尺侧腕屈肌与指深屈肌尺侧半；损伤后拇指不能内收、各指不能并拢"},{"q":"关于胆总管的描述正确的是","o":["直径0.3～0.5cm","位于肝固有动脉的左侧","位于肝胃韧带内","由左、右肝管汇合形成","由肝总管和胆囊管汇合形成"],"a":4,"e":"胆总管由肝总管与胆囊管汇合而成，长7～8cm，直径0.6～0.8cm，行于肝十二指肠韧带内，居肝固有动脉右侧、肝门静脉前方。左、右肝管汇合形成肝总管；胆总管不位于肝胃韧带内。故唯\"由肝总管和胆囊管汇合形成\"成立"},{"q":"临床上上肢出血可压迫哪根血管进行止血","o":["压迫颈总动脉进行止血","压迫颞浅动脉进行止血","压迫面动脉进行止血","压迫肱动脉进行止血","压迫股动脉进行止血"],"a":3,"e":"上肢出血时在肱二头肌内侧沟中部将肱动脉压向肱骨，可控制前臂与手部出血，此处动脉表浅、搏动易触及。颈总动脉压迫用于头颈部出血，颞浅动脉用于额颞部，面动脉用于面部，股动脉用于下肢，均不适用于上肢"},{"q":"脑脊液产生于","o":["脑组织","硬脑膜","蛛网膜","软脑膜","脑室脉络丛"],"a":4,"e":"脑脊液主要由各脑室内的脉络丛产生，侧脑室脉络丛产量最大，经室间孔、第三脑室、中脑水管、第四脑室及正中孔与外侧孔入蛛网膜下隙，最终经蛛网膜粒渗入上矢状窦。硬脑膜、蛛网膜与软脑膜只构成脑的被膜，脑组织本身不分泌脑脊液"},{"q":"海绵窦外侧壁自上而下排列正确的是","o":["展神经、动眼神经和上颌神经","动眼神经、滑车神经、眼神经和上颌神经","展神经和颈内动脉","眼神经、上颌神经、动眼神经和滑车神经","滑车神经、眼神经、动眼神经和展神经"],"a":1,"e":"海绵窦外侧壁内自上而下依次为动眼神经、滑车神经、眼神经与上颌神经；展神经位于窦腔内、颈内动脉外侧。动眼神经位置最上，下颌神经已出颅不入窦壁，其余组合的层次顺序均与解剖不符"},{"q":"在脊柱，连于各个椎体与椎间盘之间，有限制脊柱过度前屈的韧带是","o":["棘上韧带","黄韧带","后纵韧带","前纵韧带","横突间韧带"],"a":2,"e":"后纵韧带位于椎体后方，连于各椎体与椎间盘之间，限制脊柱过度前屈。前纵韧带位于椎体前方，限制过度后伸；黄韧带连于相邻椎弓板之间，棘上韧带连于棘突尖端，横突间韧带连于横突之间，三者位置均不在椎体与椎间盘之间"},{"q":"儿童期功能低下时可导致呆小症，为下列哪个内分泌腺","o":["垂体","松果体","甲状腺","甲状旁腺","肾上腺"],"a":2,"e":"甲状腺在儿童期功能低下时甲状腺激素合成不足，骨骼与神经系统发育受阻，表现为身材矮小、智力低下，即呆小症。垂体功能低下致侏儒症，身材匀称而智力正常；甲状旁腺主司钙磷代谢，功能低下引起手足搐搦；松果体与肾上腺不引起该病"},{"q":"上肢带骨包括","o":["肩胛骨","肱骨","桡骨","尺骨","手骨"],"a":0,"e":"上肢带骨包括锁骨与肩胛骨，二者以胸锁关节、肩锁关节相连，将上肢连于躯干。肱骨、桡骨与尺骨属自由上肢骨，手骨由腕骨、掌骨与指骨组成，亦属自由上肢骨。肩胛骨为三角形扁骨，贴于胸廓后外侧"},{"q":"在仰卧时，腹膜腔最低的部位是","o":["十二指肠上隐窝","盲肠后隐窝","肝肾隐窝","膀胱上窝","腹股沟内侧窝"],"a":2,"e":"仰卧位时肝肾隐窝位于肝右叶下方与右肾、结肠右曲之间，是腹膜腔最低处，积液常先聚于此，为腹腔穿刺引流的常用部位。十二指肠上隐窝、盲肠后隐窝、膀胱上窝与腹股沟内侧窝位置较高，或仅为腹膜形成的局部凹陷"},{"q":"输送尿液离开肾的结构是","o":["乳头孔","肾小盏","肾大盏","肾盂","输尿管"],"a":3,"e":"肾盂由2～3个肾大盏汇合而成，出肾门后向下弯行，约平第2腰椎上缘渐细移行为输尿管，是尿液流出肾脏的通道。乳头孔、肾小盏与肾大盏均在肾窦内承接、汇集尿液，尚未离开肾脏；输尿管是肾盂的延续，已位于肾外"},{"q":"关于输尿管盆部的描述，正确的是","o":["沿腰大肌前面下行至盆底","属于腹膜内位器官","经骨盆上口入盆后称为输尿管盆部","女性经子宫动脉的前上方至膀胱底","男性经输精管的前上方至膀胱底"],"a":2,"e":"输尿管腹部沿腰大肌前面下行，经骨盆上口入小骨盆后即称盆部，斜穿膀胱壁开口于膀胱。输尿管为腹膜外位器官，不在腹膜腔内；女性输尿管经子宫动脉后下方、子宫颈外侧达膀胱底，男性经输精管后下方交叉，故\"前上方\"均错"},{"q":"关于颈外动脉正确的是","o":["在平对环状软骨下缘高度发自颈总动脉","在平对甲状软骨上缘高度发自颈总动脉","有分支分布于脑","在下颌颈处分为面动脉和颞浅动脉","分布于甲状腺侧叶下部"],"a":1,"e":"颈外动脉在平甲状软骨上缘处自颈总动脉发出，上行至下颌颈高度分为上颌动脉与颞浅动脉。颈内动脉供应脑与视器，颈外动脉分支只营养颈、面、头皮与硬脑膜；甲状腺上动脉分布于甲状腺侧叶上部，故\"侧叶下部\"与\"分支分布脑\"均错"},{"q":"关于肾的叙述，错误的是","o":["左肾蒂较右肾蒂长","肾窦是肾门的延续","肾窦内没有输尿管","肾锥体的数目与肾乳头总数一致","肾筋膜包被在肾上腺和肾的周围"],"a":3,"e":"2～3个肾锥体尖端合并成一个肾乳头，肾乳头数7～12个，少于肾锥体数，故\"数目一致\"不成立。左肾蒂较右肾蒂长，因下腔静脉靠近右肾；肾窦是肾门向内延续的腔隙，容纳肾小盏、肾大盏、肾盂及血管，不含输尿管；肾筋膜包被肾与肾上腺"},{"q":"心尖由哪部分构成","o":["左心室","右心室","左心房","右心房","动脉圆锥"],"a":0,"e":"心尖圆钝游离，由左心室构成，朝向左前下方，体表位于左侧第5肋间隙锁骨中线内侧1～2cm，可触及心尖搏动。右心室构成胸肋面大部与下缘一部分，左心房构成心底及膈面大部，右心房构成胸肋面右侧，动脉圆锥为右心室流出道"},{"q":"关于肛管的描述正确的是","o":["上端在尿生殖膈平面连续直肠","与直肠的分界线称为白线","肛窦是由肛瓣和相邻肛柱的下端形成","发生在齿状线以上的痔称为外痔","发生在齿状线以下的痔称为内痔"],"a":2,"e":"肛窦由相邻肛柱下端与肛瓣共同围成，窦底有肛腺开口，易积存粪屑而感染。肛管上端在盆膈平面续于直肠，二者分界为齿状线而非白线；齿状线以上为内痔、以下为外痔，故\"以上称外痔、以下称内痔\"恰好颠倒"},{"q":"不属于腰丛的是","o":["股外侧皮神经","髂腹下神经","髂腹股沟神经","生殖股神经","臀上神经"],"a":4,"e":"腰丛由第12胸神经前支部分纤维及第1～4腰神经前支构成，分支有髂腹下神经、髂腹股沟神经、股外侧皮神经、生殖股神经、股神经与闭孔神经。臀上神经发自骶丛，经梨状肌上孔出盆，支配臀中肌、臀小肌与阔筋膜张肌"},{"q":"滑膜关节的基本结构不包括","o":["关节囊外层","关节唇","关节面","关节囊内层","关节腔"],"a":1,"e":"滑膜关节的基本结构为关节面、关节囊与关节腔，关节囊分外层纤维膜与内层滑膜。关节唇、关节盘与韧带属辅助结构，仅见于部分关节，如髋臼唇、膝关节半月板。故关节唇不属基本结构"},{"q":"参与瞳孔对光反射的结构是","o":["红核","黑质","顶盖前区","下丘","上丘"],"a":2,"e":"瞳孔对光反射的传入冲动经视神经止于顶盖前区，由此发出纤维经后连合交叉至双侧动眼神经副核，再经睫状神经节至瞳孔括约肌。上丘与视觉反射有关，下丘是听觉中继站，红核参与肌张力调节，黑质参与运动的发起与调节"},{"q":"下泌涎核发出纤维参与组成","o":["面神经","舌咽神经","迷走神经","副神经","舌下神经"],"a":1,"e":"下泌涎核位于延髓，其副交感节前纤维经舌咽神经及鼓室神经、岩小神经至耳神经节换元，节后纤维支配腮腺。上泌涎核纤维随面神经至下颌下神经节与翼腭神经节，迷走神经背核纤维随迷走神经分布，舌下神经与副神经不含副交感纤维"},{"q":"支配眼球外肌的神经","o":["动眼神经、滑车神经、展神经","三叉神经、舌咽神经、面神经","舌咽神经、迷走神经、舌下神经","动眼神经、滑车神经、三叉神经","三叉神经、面神经"],"a":0,"e":"运动眼球的6块肌中，上直肌、下直肌、内直肌、下斜肌由动眼神经支配，上斜肌由滑车神经支配，外直肌由展神经支配；上睑提肌亦属动眼神经，但只提上睑。三叉神经眼支司眼球感觉，面神经、舌咽神经与舌下神经均不支配眼球运动"},{"q":"指骨间关节属于","o":["屈戌关节","车轴关节","椭圆关节","鞍状关节","球窝关节"],"a":0,"e":"指骨间关节只有屈伸运动，关节面呈滑车状，属屈戌关节。车轴关节如桡尺近侧关节只作旋转；椭圆关节如桡腕关节可屈伸、收展与环转；鞍状关节如拇指腕掌关节可对掌；球窝关节如肩关节运动幅度最大"},{"q":"有关右心房错误的描述是","o":["界嵴分隔腔静脉窦和固有心房","固有心房的前上部为右心耳","Koch三角的深面为房室结","右心房收集除心脏以外体循环的静脉血","梳状肌起自界嵴"],"a":3,"e":"右心房接受上腔静脉、下腔静脉及冠状窦回流的血液，收集的是除肺以外全身的静脉血，包含心脏本身的静脉血，故\"除心脏以外\"错误。界嵴分隔腔静脉窦与固有心房，固有心房前上部突出为右心耳，梳状肌起自界嵴，Koch三角深面为房室结"},{"q":"喉室位于喉腔内，属于","o":["喉前庭","喉中间腔","声门下腔","弹性圆锥","方形膜"],"a":1,"e":"喉腔以室襞与声襞分为喉前庭、喉中间腔与声门下腔，室襞与声襞之间的裂隙状隐窝即喉室，属喉中间腔。喉前庭位于前庭襞以上，声门下腔位于声襞以下至环状软骨下缘；弹性圆锥与方形膜属喉的连结结构，并非腔隙"},{"q":"对滑车神经的描述，正确的是","o":["起于同侧的滑车神经核","经上丘下方出脑","紧贴颈内动脉穿海绵窦","经眶上裂入眶","支配下斜肌"],"a":3,"e":"滑车神经起于中脑下丘下方的滑车神经核，纤维向后绕过导水管周围灰质，经下丘下方出脑，是唯一自脑干背侧出脑的脑神经，经海绵窦外侧壁、眶上裂入眶，支配上斜肌。故\"经上丘下方出脑\"\"紧贴颈内动脉\"\"支配下斜肌\"均错"},{"q":"在上肢骨的连结，有肱二头肌长头腱经过关节囊的关节是","o":["胸锁关节","肩关节","肩锁关节","肘关节","腕关节"],"a":1,"e":"肩关节囊松弛薄弱，肱二头肌长头腱起自盂上结节，经关节囊内、结节间沟下行穿出囊外，其腱鞘与关节腔相通，是肩关节的特征。胸锁关节、肩锁关节、肘关节与腕关节均无肌腱穿行于关节囊内"},{"q":"蝶窦开口于","o":["上鼻道","中鼻道","下鼻道","蝶筛隐窝","上鼻甲下方"],"a":3,"e":"蝶窦位于蝶骨体内，被中隔分为左右两腔，各自向前开口于上鼻甲后上方的蝶筛隐窝。额窦、上颌窦与筛窦前群、中群均开口于中鼻道，下鼻道承接鼻泪管开口，上鼻甲下方即上鼻道，主要接受后筛窦"},{"q":"关于胸神经前支说法正确的是","o":["进入肋间隙形成12对肋间神经","神经纤维来自脊神经前根","支配肋间肌的运动神经","第1肋间神经的外侧皮支称为肋间臂神经","在胸、腹壁皮肤具有明显的节段性分布特点"],"a":4,"e":"胸神经前支在胸腹壁皮肤呈明显的节段性分布，临床据此判断脊髓损伤平面，如乳头平第4胸节、剑突平第6胸节、脐平第10胸节。第1胸神经前支大部加入臂丛、第12胸神经前支大部加入腰丛，故非12对均成典型肋间神经；其纤维由前根与后根在椎间孔处合成"},{"q":"支配肱二头肌的神经是","o":["肌皮神经","尺神经","腋神经","桡神经","正中神经的分支"],"a":0,"e":"肱二头肌由肌皮神经支配，该神经发自臂丛外侧束，穿喙肱肌后行于肱二头肌与肱肌之间，支配臂前群三肌，终支为前臂外侧皮神经。尺神经支配尺侧腕屈肌与手内肌，腋神经支配三角肌与小圆肌，桡神经支配臂后群与前臂伸肌"},{"q":"心底由哪个心房及心室构成","o":["左心室和右心室","右心室和右心房","左心房和右心房","左心室和左心房","右心室和左心房"],"a":2,"e":"心底朝向右后上方，主要由左心房构成，小部分为右心房，是肺静脉入心处所在。心尖与胸肋面大部由右心室、左心室构成，膈面大部由左心室构成。故心底只由左、右心房构成，与心室无关"},{"q":"肾窦内的结构不包括","o":["肾柱","肾小盏","肾大盏","肾盂","肾血管"],"a":0,"e":"肾窦是肾门向内延续的腔隙，容纳肾小盏、肾大盏、肾盂、肾动脉分支、静脉属支、神经与脂肪组织。肾柱是伸入肾锥体之间的肾皮质，与肾锥体同处肾实质内，不在窦内，故为唯一不属肾窦的结构"},{"q":"关于神经元的论述错误的是","o":["是神经系统结构和功能的基本单位","突起分为树突和轴突","具有接受刺激及传导神经冲动的功能","由胞体和突起两部分构成","双极神经元属运动神经元"],"a":4,"e":"双极神经元胞体发出一个树突与一个轴突，属感觉神经元，见于视网膜双极细胞及前庭蜗神经节细胞，并非运动神经元；运动神经元多为多极神经元。神经元是神经系统结构与功能的基本单位，由胞体与突起构成，能接受刺激、整合并传导冲动"},{"q":"关于乙状窦的说法，正确的是","o":["直接注入颈内静脉","不成对","位于枕骨横沟内","是窦汇的延续","是直窦的延续"],"a":0,"e":"乙状窦位于颞骨乳突部乙状沟内，是横窦的延续，向下出颈静脉孔直接续为颈内静脉。窦汇由上矢状窦、直窦与横窦汇合而成，乙状窦只间接与之相连；直窦向后分为左右横窦；乙状窦左右各一，并非不成对结构"},{"q":"关于膀胱分部的叙述，错误的是","o":["膀胱颈","膀胱体","膀胱底","膀胱尖","前列腺部"],"a":4,"e":"膀胱分尖、体、底、颈四部：膀胱尖朝前上，膀胱底朝后下，膀胱体居二者之间，膀胱颈即尿道内口处，四部均属膀胱本体。前列腺部是男性尿道穿经前列腺的一段，属尿道分部，与膀胱分部无关"},{"q":"第3～6颈椎的形态结构特征包括","o":["椎体大，呈心形","横突末端有颈动脉结节","有横突孔","上、下关节突的关节面呈冠状位","棘突长而不分叉"],"a":2,"e":"第3～6颈椎椎体较小，横突根部有横突孔，椎孔较大呈三角形，棘突短而末端分叉。椎体大而呈心形是胸椎特征，颈动脉结节在第6颈椎横突前结节而不在棘突末端，棘突长而不分叉属隆椎，关节突关节面呈冠状位属胸椎"},{"q":"肾实质的结构不包括","o":["肾锥体","肾乳头","肾小盏","乳头孔","肾柱"],"a":2,"e":"肾实质分皮质与髓质，含肾锥体、肾乳头、乳头孔与肾柱，肾柱即伸入锥体之间的皮质。肾小盏属肾窦内的排尿管道，边缘包绕肾乳头承接尿液，与肾大盏、肾盂同属排尿通路而非实质，故不属肾实质"},{"q":"关于第Ⅰ躯体感觉区的叙述，错误的是","o":["位于中央后回和中央旁小叶后部","接受对侧半躯体痛、温、触、压以及位置和运动觉","投影区的大小与各部形体大小无关","投影区的大小取决于该部感觉敏感程度","头面部投影区是上下颠倒"],"a":4,"e":"第Ⅰ躯体感觉区位于中央后回与中央旁小叶后部，接受对侧半身痛温触压及位置运动觉，投射特点为上下颠倒而头部为正、左右交叉、投影范围与感觉敏感程度成正比。故\"头面部投影上下颠倒\"错误，手指与唇投影区最大正是敏感度决定范围之证"},{"q":"关于颈椎正确的是","o":["均有椎体及椎弓","1、2颈椎无横突孔","棘突末端都分叉","第6颈椎棘突末端膨大成颈动脉结节","第7颈椎又名隆椎"],"a":4,"e":"第7颈椎棘突长而不分叉，末端隆起于皮下易于触及，故名隆椎，是计数椎骨序数的标志。寰椎无椎体亦无棘突；第1、2颈椎同样有横突孔；第2～6颈椎棘突末端才分叉；颈动脉结节位于第6颈椎横突前结节，不在棘突"},{"q":"颈椎的形态结构特征为","o":["椎体粗壮","椎体横断面呈肾形","椎孔呈卵圆形或三角形","关节突的关节面近似冠状位","棘突呈板状，水平伸向后方，彼此之间的间隙较大"],"a":3,"e":"官方答案为关节突的关节面近似冠状位，但依据教材，正确答案为椎孔呈卵圆形或三角形。颈椎关节突的关节面近似水平位，故颈部屈伸旋转灵活；关节面呈冠状位是胸椎特征，与叠瓦状棘突共同限制胸椎活动。颈椎椎体小、椎孔较大呈三角形，与该选项相符，D项把胸椎的关节面方位移植于颈椎，不能成立"},{"q":"附着于延髓脑桥沟的脑神经，从内侧向外侧为","o":["迷走神经、舌咽神经、前庭蜗神经","舌咽神经、前庭蜗神经、面神经","展神经、面神经、前庭蜗神经","面神经、展神经、三叉神经","前庭蜗神经、面神经、展神经"],"a":2,"e":"延髓脑桥沟内自内侧向外侧依次为展神经、面神经与前庭蜗神经，三者均位于延髓与脑桥腹侧交界处。三叉神经经脑桥基底部与小脑中脚交界处出入，舌咽、迷走神经自橄榄后沟后部出脑，舌下神经自锥体与橄榄之间的前外侧沟出脑"},{"q":"没有通过内囊后肢的上、下行纤维是","o":["丘脑中央辐射","视辐射","皮质脊髓束","听辐射","皮质核束"],"a":4,"e":"内囊后肢自前向后依次为丘脑中央辐射、皮质脊髓束、视辐射与听辐射；皮质核束经内囊膝部下行，故未通过后肢。听辐射经豆状核后部转向颞叶，仍属后肢范围，丘脑中央辐射与视辐射亦在后肢内"},{"q":"下列关于动脉摸脉点的描述正确的是","o":["面动脉在活体上易触摸到搏动的部位在咬肌后缘与下颌骨下缘交界处","足背动脉在活体上易触摸到搏动的部位是踝关节后方，内、外踝连线的中点","股动脉在活体上易触摸到搏动的部位是股动脉的上段","桡动脉在活体上诊脉的部位是桡动脉上段","股动脉在活体上易触摸到搏动的部位是股动脉的下段"],"a":2,"e":"股动脉在腹股沟韧带中点稍下方位置表浅，可触及搏动，即股动脉上段，下肢出血时在此将其压向耻骨上支止血。面动脉摸脉点在咬肌前缘而非后缘与下颌骨下缘交界处，足背动脉在内外踝连线中点、踝关节前方而非后方，桡动脉摸脉点在桡骨茎突内侧的下段而非上段"},{"q":"肱骨外科颈的部位是","o":["肱骨大、小结节交界处","肱骨头周围的环形沟","肱骨头与肱骨干的交界处","肱骨上端干骺端处","肱骨上端与肱骨干的交界处"],"a":4,"e":"肱骨外科颈为肱骨上端与肱骨干交界处，管径稍细，是骨折好发部位，骨折易伤及腋神经。肱骨大、小结节之间为结节间沟，有肱二头肌长头腱通过；肱骨头周围的环形浅沟为解剖颈；干骺端指骺板所在部位，与外科颈概念不同"},{"q":"属于骨迷路的结构是","o":["椭圆囊","耳蜗","球囊","膜半规管","蜗管"],"a":1,"e":"骨迷路由骨半规管、前庭与耳蜗三部分构成，耳蜗为骨性螺旋管，前庭居二者之间。椭圆囊、球囊、膜半规管与蜗管均为膜迷路结构，套于骨迷路内，两者之间充以外淋巴，故骨迷路只含前三者"},{"q":"关于锥体系的叙述，错误的是","o":["含有皮质脊髓束","含有皮质核束","含有上、下运动神经元","含有小脑","含有中央前回和中央旁小叶的Betz细胞"],"a":3,"e":"锥体系由上运动神经元及其发出的皮质脊髓束与皮质核束组成，上运动神经元包括中央前回和中央旁小叶前部的Betz细胞，下运动神经元为脑神经运动核与脊髓前角细胞。小脑属锥体外系，与锥体系无关"},{"q":"下列属于海马结构的是","o":["齿状回","扣带回","海马旁回钩","杏仁体","海马旁回"],"a":0,"e":"海马结构由海马、齿状回与下托构成，齿状回位于海马内侧，二者共同卷曲于侧脑室下角。扣带回、海马旁回及海马旁回钩属边缘叶；杏仁体是独立核团，属基底核与边缘系统，不属海马结构"},{"q":"棘突较长，向后下方倾斜，呈叠瓦状的椎骨是","o":["寰椎","第2～6颈椎","隆椎","胸椎","腰椎"],"a":3,"e":"胸椎棘突较长，向后下方倾斜，相邻棘突呈叠瓦状排列，限制胸椎屈伸幅度。腰椎棘突宽短呈板状、水平后伸，棘突间隙最大；第2～6颈椎棘突短而末端分叉；隆椎棘突长而不分叉；寰椎无棘突"},{"q":"直肠癌首先转移的淋巴结是","o":["直肠上淋巴结","闭孔淋巴结","左结肠淋巴结","腰淋巴结","腹股沟深淋巴结"],"a":0,"e":"直肠的淋巴主要沿直肠上血管回流至直肠上淋巴结，再经肠系膜下淋巴结至腹主动脉旁淋巴结，故直肠癌首先转移至直肠上淋巴结。齿状线以下的淋巴流向腹股沟浅淋巴结，闭孔淋巴结收纳盆腔脏器与下肢的淋巴，腰淋巴结收纳腹后壁及腹腔成对脏器的淋巴"},{"q":"穿行于右纤维三角内的是","o":["结间束","房室束","左束支","右束支","浦肯野纤维"],"a":1,"e":"房室束由房室结发出，穿行于右纤维三角内，至室间隔膜部后缘分为左、右束支。右纤维三角又称中央纤维体，是房室束进入室间隔的必经之路。结间束行于心房壁内，左、右束支位于室间隔两侧心内膜下，浦肯野纤维分布于心室肌内"},{"q":"躯干和四肢的意识性本体感觉传导通路中，第2级神经元发出纤维进行交叉的部位在","o":["脊髓","延髓","脑桥","中脑","背侧丘脑"],"a":1,"e":"意识性本体感觉通路的第2级神经元胞体在薄束核与楔束核，发出的内弓状纤维在延髓中下部越中线交叉，形成内侧丘系交叉，故交叉部位在延髓。第1级神经元在脊神经节，第3级在背侧丘脑腹后外侧核"},{"q":"可分为皮质和髓质的内分泌器官是","o":["甲状腺","肾上腺","垂体","松果体","卵泡和黄体"],"a":1,"e":"肾上腺表面为皮质、内部为髓质：皮质分泌糖皮质激素、盐皮质激素与性激素，髓质分泌肾上腺素与去甲肾上腺素。甲状腺由滤泡构成，无皮质髓质之分；垂体分腺垂体与神经垂体；松果体为单一实质腺体"},{"q":"舌咽神经不分布于","o":["咽鼓管","腮腺","鼓室","颈动脉窦","心肌"],"a":4,"e":"舌咽神经分布于咽壁、咽鼓管、鼓室、腭扁桃体、颈动脉窦与颈动脉小球、舌后1/3黏膜及腮腺，其颈动脉窦支司压力感受器反射。心肌由迷走神经支配，舌咽神经不含至心脏的纤维"},{"q":"关于腹膜腔，下列描述不正确的是","o":["膀胱和肾的手术可在腹膜腔外进行","网膜囊是腹膜腔的一部分","是密闭腔隙，不与外界相通","腹膜腔内仅有少量浆液","腹腔脏器的穿孔可引起急性腹膜炎"],"a":2,"e":"腹膜腔是壁腹膜与脏腹膜之间的潜在腔隙，男性完全封闭，女性经输卵管腹腔口、输卵管、子宫与阴道与外界相通，故\"密闭不相通\"错误。膀胱与肾为腹膜外位器官，手术可在腹膜外进行；网膜囊属腹膜腔一部分；腔内仅有少量浆液，脏器穿孔可引起急性腹膜炎"},{"q":"面神经管理","o":["面部皮肤","舌前2/3味觉","舌前2/3一般感觉","舌后1/3味觉","舌后1/3一般感觉"],"a":1,"e":"面神经含特殊内脏感觉纤维，胞体在膝神经节，周围突经鼓索随舌神经分布至舌前2/3味蕾，故司舌前2/3味觉。舌前2/3一般感觉由三叉神经下颌神经的舌神经传导，舌后1/3的味觉与一般感觉均由舌咽神经管理，面部皮肤感觉属三叉神经"},{"q":"肩关节的特征不包括","o":["肱骨头大","关节盂小","有关节盘","有囊外韧带","有盂唇"],"a":2,"e":"肩关节由肱骨头与浅小的关节盂构成，关节面差大，囊松弛薄弱，有盂唇加深关节窝，囊外有喙肩韧带等加强，运动灵活。关节盘见于膝关节、胸锁关节与下颌关节，肩关节腔内无关节盘"},{"q":"骶副交感核","o":["位于S2～S4节段板层Ⅶ的外侧部","在于S1～S5节段板层Ⅶ侧部","位于T1～L4节段板层Ⅶ侧部","位于T5～L1节段板层Ⅶ侧部","是副交感节后神经元胞体所在的部位"],"a":0,"e":"骶副交感核位于第2～4骶节板层Ⅶ外侧部，发出的节前纤维随盆内脏神经至盆腔脏器壁内节换元。胸1～腰3侧角为交感中枢，不属副交感；副交感节后神经元胞体位于器官壁内或器官旁神经节，不在脊髓内"},{"q":"可屈膝、踝关节的肌是","o":["腓肠肌","胫骨前肌","胫骨后肌","腓骨长肌","比目鱼肌"],"a":0,"e":"腓肠肌起自股骨内、外侧髁后面，止于跟骨结节，跨越膝与踝两个关节，收缩时屈膝并使足跖屈，与比目鱼肌合称小腿三头肌。胫骨前肌使足背屈并内翻，胫骨后肌使足内翻跖屈，腓骨长肌使足外翻跖屈"},{"q":"关于蜗管的叙述，错误的是","o":["位于蜗螺旋管内","蜗管盘绕蜗轴两圈半","局部膜壁增厚形成壶腹嵴","和骨螺旋板一起分隔蜗螺旋管为前庭阶和鼓阶","下壁的基底膜上有螺旋器"],"a":2,"e":"蜗管位于蜗螺旋管内，盘绕蜗轴两圈半，下壁为基底膜、上有螺旋器，外侧壁为血管纹，上壁为前庭膜，与骨螺旋板共同把蜗螺旋管分为前庭阶与鼓阶。壶腹嵴是膜半规管壶腹壁增厚形成的位觉感受器，与蜗管无关"},{"q":"自脑干背面出脑的神经是","o":["动眼神经","滑车神经","面神经","副神经","舌下神经"],"a":1,"e":"滑车神经是唯一自脑干背面出脑的脑神经，纤维起于下丘下方的滑车神经核，绕过导水管周围灰质向后出脑。动眼神经自脚间窝出脑，面神经自延髓脑桥沟外侧出脑，舌下神经自锥体与橄榄之间出脑，副神经由延髓根与脊髓根合成后经颈静脉孔出颅"},{"q":"前尿道是指","o":["前列腺部","尿道膜部","尿道海绵体部","前列腺部、膜部","膜部、海绵体部"],"a":2,"e":"男性尿道以尿生殖膈为界分前、后尿道：前列腺部与膜部合称后尿道，尿道海绵体部称前尿道。前列腺部穿前列腺，膜部穿尿生殖膈，位置深在，损伤多由骨盆骨折引起；海绵体部最长，位于阴茎内，损伤机会最多"},{"q":"下肢深部感觉传导通路的交叉部位在","o":["脊髓前连合","脑桥臂","延髓内侧丘系交叉","中脑结合臂","间脑视交叉"],"a":2,"e":"下肢深部感觉经薄束、楔束上行至延髓薄束核与楔束核，换元后纤维越中线形成内侧丘系交叉，故交叉部位在延髓。脊髓前连合是脊髓丘脑束与脊髓小脑束的交叉部位，与深感觉无关；视交叉属视觉通路"},{"q":"第二鼓膜封闭","o":["蜗窗的组织膜","前庭窗的组织膜","外耳道底的组织膜","内耳道底的组织膜","鼓室的组织膜"],"a":0,"e":"蜗窗又称圆窗，被第二鼓膜封闭，位于鼓岬后下方的小凹内，可缓冲外淋巴压力波动。前庭窗由镫骨底封闭，外耳道底为鼓膜，内耳道底有面神经与前庭蜗神经通过，鼓室为含气腔隙，均无第二鼓膜"},{"q":"黄韧带的特征不包括","o":["是椎弓间的连结","位于椎弓板之间","能限制脊柱过度前伸","参与组成椎管","由黄色弹性纤维构成"],"a":2,"e":"黄韧带连于相邻椎弓板之间，由黄色弹性纤维构成，参与围成椎管后壁，限制脊柱过度前屈并协助维持直立。限制脊柱过度后伸的是前纵韧带，两者作用方向相反，故该项不属黄韧带特征"},{"q":"延髓内的脑神经核","o":["脑桥核","面神经核","上橄榄核","迷走神经背核","上泌涎核"],"a":3,"e":"迷走神经背核位于延髓，属一般内脏运动核，发出副交感纤维随迷走神经分布至胸腹腔脏器。脑桥核位于脑桥基底部，面神经核、上橄榄核与上泌涎核亦均在脑桥，均不属延髓内的脑神经核"},{"q":"斜方肌麻痹时，不能做下列哪项动作","o":["充分外展肩关节","充分屈肩关节","使肩胛骨向脊柱靠近","使肩胛骨贴近胸廓","充分内收肩关节"],"a":2,"e":"斜方肌上部使肩胛骨上提，中部使肩胛骨向脊柱靠拢，下部下降肩胛骨，由副神经支配，麻痹后肩胛骨向脊柱靠拢无力。肩关节外展由三角肌与冈上肌完成，屈肩由三角肌前部、胸大肌等完成，内收由胸大肌、背阔肌完成"},{"q":"背侧丘脑腹后内侧核接受","o":["内侧丘系","外侧丘系","三叉丘系","脊髓丘脑束","脊髓小脑束"],"a":2,"e":"背侧丘脑腹后内侧核接受三叉丘系及孤束核发出的味觉纤维，投射至中央后回下部的头面部感觉区。腹后外侧核接受内侧丘系与脊髓丘脑束；外侧丘系止于下丘与内侧膝状体，属听觉通路；脊髓小脑束止于小脑，与丘脑无关"},{"q":"以下关于泪器的描述，正确的是","o":["泪器属于眼球的一部分","泪器由泪腺和鼻泪管两部分组成","泪腺分泌的泪液可防止结膜干燥","泪囊为一膜性盲囊，其下端为盲端","泪点是泪小管的开口"],"a":4,"e":"泪点是泪小管的起始开口，位于上下睑缘内侧端，泪液经泪点、泪小管、泪囊、鼻泪管流入下鼻道。泪器由泪腺与泪道组成，泪道含泪点、泪小管、泪囊与鼻泪管，不止两部；泪囊下端续鼻泪管，上端才是盲端；泪器属眼副器，不属眼球壁"},{"q":"关于大肠描述正确的是","o":["长约2m","在右髂窝处从回肠而起","阑尾不属于大肠","大肠都没有系膜","包括盲肠、阑尾、结肠、直肠和肛管5部分"],"a":4,"e":"大肠包括盲肠、阑尾、结肠、直肠与肛管五部分，全长约1.5m，围绕于空回肠周围呈方框状。盲肠位于右髂窝，回肠末端开口于盲肠；阑尾属大肠的一部分；升结肠、横结肠与乙状结肠均有系膜"},{"q":"损伤后导致本体感觉丧失的纤维束","o":["薄束、楔束","脊髓丘脑束","脊髓小脑束","皮质脊髓束","红核脊髓束"],"a":0,"e":"薄束与楔束传导同侧躯干四肢的意识性本体感觉与精细触觉，损伤后同侧本体感觉丧失、精细触觉障碍并出现感觉性共济失调。脊髓丘脑束传导对侧痛温觉与粗触觉，损伤后痛温觉丧失而本体感觉保留；脊髓小脑束参与非意识性本体感觉，皮质脊髓束与红核脊髓束为下行运动束"},{"q":"有关腰淋巴结的描述，正确的是","o":["位于腹膜前隙内","沿髂内动脉和髂外静脉排列","引流腹腔成对器官的淋巴","收纳腹股沟浅淋巴结的输出淋巴管","输出淋巴管汇合成左、右肠干"],"a":2,"e":"腰淋巴结沿腹主动脉与下腔静脉排列，收纳腹腔成对器官、腹后壁及髂总淋巴结的输出淋巴管，其输出管汇合成左、右腰干。腹股沟浅淋巴结的输出管注入髂外淋巴结；肠干由腹腔不成对脏器的淋巴管汇成，不属腰淋巴结输出"},{"q":"胞质中含有GFAP（胶质纤维酸性蛋白）的胶质细胞是","o":["施万细胞","室管膜细胞","小胶质细胞","少突胶质细胞","星形胶质细胞"],"a":4,"e":"星形胶质细胞的胞质富含胶质纤维酸性蛋白，这是其免疫组化标志，该细胞参与构成血-脑屏障并修复损伤。少突胶质细胞形成中枢髓鞘，施万细胞形成周围髓鞘，室管膜细胞衬于脑室腔面，小胶质细胞属吞噬细胞"},{"q":"心的下缘由哪部分构成","o":["左心室和心尖","右心室和心尖","左心室和右心室","左心室和左心耳","右心室和右心耳"],"a":1,"e":"心的下缘即锐缘，介于胸肋面与膈面之间，接近水平位，由右心室与心尖构成。膈面大部分由左心室、小部分由右心室构成，胸肋面大部分由右心室与右心房构成，故下缘不涉及左心室"},{"q":"躯干和四肢的非意识性本体感觉传导通路的第2级神经元位于","o":["脊髓的胶状质","脊髓的后角固有核","脊髓的胸核和腰骶膨大第Ⅴ～Ⅶ外侧部","延髓的楔束核","延髓的薄束核"],"a":2,"e":"非意识性本体感觉通路的第2级神经元位于脊髓胸核与腰骶膨大第Ⅴ～Ⅶ层外侧部，发出纤维经脊髓小脑后束与前束止于小脑，传递肌与关节位置信息以调节肌张力。薄束核与楔束核是意识性通路的第2级神经元，后角固有核与胶状质属痛温觉通路"},{"q":"关于肾的构造，错误的描述是","o":["肾实质可分浅层的皮质和深层的髓质两部分","肾髓质由许多小的管道组成","肾锥体基底朝向皮质，尖朝向肾窦","肾乳头开口于肾盂","肾锥体之间的皮质为肾柱"],"a":3,"e":"肾乳头突入肾小盏，其顶端乳头孔排出的终尿流入肾小盏，再经肾大盏、肾盂、输尿管排出，故\"开口于肾盂\"错误。肾实质分浅层皮质与深层髓质，髓质由肾锥体等管道构成，锥体底朝皮质、尖朝肾窦，锥体之间的皮质为肾柱"},{"q":"展神经","o":["经眶上裂入眶","支配上直肌","主干损伤眼外斜视","含有感觉纤维","含有副交感纤维"],"a":0,"e":"展神经经眶上裂入眶，支配外直肌，损伤后外直肌瘫痪，眼球内斜、外展受限并出现复视。展神经为躯体运动神经，不含感觉纤维与副交感纤维；上直肌由动眼神经支配，故\"支配上直肌\"错误"},{"q":"脑干内的副交感神经核","o":["疑核、动眼神经副核、上泌涎核、下泌涎核","迷走神经背核、动眼神经核、上泌涎核、下泌涎核","动眼神经副核、孤束核、泌涎核、迷走神经背核","动眼神经副核、上泌涎核、下泌涎核、迷走神经背核","动眼神经副核、面神经核、疑核、副神经核"],"a":3,"e":"脑干内的一般内脏运动核即副交感核，包括动眼神经副核、上泌涎核、下泌涎核与迷走神经背核，分别控制瞳孔与晶状体、泪腺与下颌下腺舌下腺、腮腺及胸腹脏器。疑核、动眼神经核、面神经核与副神经核均为特殊内脏运动核，孤束核为内脏感觉核"},{"q":"关于尺动脉的叙述，错误的是","o":["该动脉在平桡骨颈高度处发自肱动脉","其主要分支为骨间总动脉和掌深支","其体表投影为：自肘窝中点稍下至豌豆骨桡侧","其压迫止血部位为：在腕部的尺侧腕屈肌的内侧","压迫该动脉其止血范围为：整个前臂和手部"],"a":4,"e":"尺动脉在平桡骨颈高度发自肱动脉，主要分支为骨间总动脉与掌深支，体表投影为肘窝中点稍下至豌豆骨桡侧，压迫止血点在腕部尺侧腕屈肌内侧。其供血限于前臂尺侧与手掌尺侧，桡侧及手背大部由桡动脉供应，故\"整个前臂和手部\"超出其区"},{"q":"延髓前正中裂两旁的隆起的外侧是","o":["锥体","橄榄","薄束结节","楔束结节","听结节"],"a":1,"e":"延髓前正中裂两侧的隆起为锥体，内含皮质脊髓束；锥体外侧的隆起为橄榄，深面为下橄榄核。锥体与橄榄之间的前外侧沟有舌下神经根出脑，橄榄后沟有舌咽、迷走与副神经根。薄束结节、楔束结节位于延髓背侧下部，听结节属脑桥背侧结构"},{"q":"舌下神经核","o":["接受双侧皮质核束的支配","发出舌下神经经橄榄背外侧出脑","管理舌的感觉和运动","受损后伸舌时舌尖偏向健侧","受损后舌肌萎缩"],"a":4,"e":"舌下神经核位于延髓，属躯体运动核，只接受对侧皮质核束支配，纤维经锥体与橄榄之间出脑，支配全部舌内肌与大部分舌外肌。核下性损伤时同侧舌肌萎缩，伸舌偏向患侧；核上性损伤无肌萎缩。该神经只司运动，不传导舌的感觉"},{"q":"躯干和四肢的非意识性本体感觉传导通路由多少级神经元组成","o":["1级","2级","3级","4级","5级"],"a":1,"e":"非意识性本体感觉通路只有2级神经元：第1级在脊神经节，第2级胞体在胸核与腰骶膨大Ⅴ～Ⅶ层外侧部，轴突经脊髓小脑束直达小脑皮质。意识性本体感觉通路有3级神经元，需经背侧丘脑腹后外侧核中继"},{"q":"支配心脏的副交感神经来自","o":["舌咽神经","迷走神经","副神经","膈神经","三叉神经"],"a":1,"e":"心脏的副交感节前纤维起自迷走神经背核与疑核，经迷走神经心支至心丛内的心神经节换元，节后纤维支配窦房结、房室结与心房肌，抑制心率。舌咽神经、三叉神经、副神经与膈神经均不含至心脏的副交感纤维"},{"q":"四分法为解剖学常用的纵隔区分法。中纵隔位于","o":["上纵隔内","上、下纵隔之间","前纵隔内","前、后纵隔之间","后纵隔内"],"a":3,"e":"四分法以胸骨角至第4胸椎下缘的平面分上、下纵隔，下纵隔再以心包为界分前、中、后三区，中纵隔即前、后纵隔之间的心包与心所在区，内有心、心包、升主动脉、肺动脉干、上腔静脉下部与膈神经"},{"q":"第四脑室位于","o":["脑桥与中脑之间","延髓、脑桥与小脑之间","脑桥、中脑与小脑之间","中脑、小脑与延髓之间","中脑、间脑与小脑之间"],"a":1,"e":"第四脑室是延髓、脑桥与小脑之间的腔隙，底为菱形窝，顶为小脑蚓与上下髓帆，向上经中脑水管通第三脑室，向下通脊髓中央管，并借正中孔与外侧孔通蛛网膜下隙。中脑与小脑之间为四叠体及小脑上脚所在区，无脑室腔"},{"q":"舌咽神经分布的区域不包括","o":["舌前2/3","咽壁","鼓室","颈动脉窦","颈动脉小球"],"a":0,"e":"舌咽神经分布于咽壁、咽鼓管、鼓室、腭扁桃体、颈动脉窦与颈动脉小球、舌后1/3黏膜及腮腺。舌前2/3的味觉由面神经鼓索管理，其一般感觉由三叉神经舌神经传导，均非舌咽神经分布区"},{"q":"项韧带的特征不包括","o":["续于棘上韧带","向前附着于颈椎棘突","由弹性纤维构成","向上附着于人字缝","向下达第7颈椎棘突"],"a":3,"e":"项韧带为棘上韧带在颈部向上的延续，由弹性纤维构成，向前附着于颈椎棘突，向上附着于枕外隆凸与枕外嵴，向下达第7颈椎棘突。人字缝位于枕骨与顶骨之间，是颅盖骨缝，并非项韧带的附着处"},{"q":"腹外斜肌腱膜形成的结构不包括","o":["耻骨梳韧带","腹股沟管浅环","腹股沟镰","腹白线","腔隙韧带"],"a":2,"e":"腹外斜肌腱膜在髂前上棘与耻骨结节之间增厚形成腹股沟韧带，并衍生出腔隙韧带、耻骨梳韧带、腹白线与腹股沟管浅环。腹股沟镰由腹内斜肌腱膜与腹横肌腱膜在腹直肌外侧缘处联合而成，与腹外斜肌无关"},{"q":"外侧丘系的纤维束走行及功能的描述，正确的是","o":["经延髓、脑桥和中脑中线的外侧上行","终止于上丘","终止于外侧膝状体","大部分纤维终止于下丘中央核","仅传导对侧耳的听觉信息"],"a":3,"e":"蜗神经核发出的纤维大部分经斜方体交叉至对侧，与同侧未交叉纤维共同组成外侧丘系，行于脑干被盖腹外侧，大部分止于下丘中央核换元，小部分止于内侧膝状体。上丘属视觉反射中枢，外侧膝状体是视觉通路中继站，该系传导双耳听觉信息"},{"q":"经眶上裂进出眶的神经是","o":["视神经","嗅神经","滑车神经","上颌神经","滑车上神经"],"a":2,"e":"经眶上裂进出眶的有动眼神经、滑车神经、展神经与眼神经，滑车神经经眶上裂入眶支配上斜肌。视神经经视神经管入眶，嗅神经经筛孔入颅，上颌神经经圆孔出颅，滑车上神经是眼神经的终支，在眶内分支后经眶上切迹出眶至额部皮肤"},{"q":"关于窦房结正确的描述是","o":["内脏神经的作用决定其兴奋","借房室束连于房室结","是心脏的正常起搏点","位于房间隔下部右侧心内膜下","属于特殊神经组织"],"a":2,"e":"窦房结位于上腔静脉与右心房交界处界沟上端的心外膜深面，自律性最高，是心脏的正常起搏点，冲动经结间束与心房肌传至房室结。窦房结由特殊心肌细胞构成，属心传导系而非神经组织，其自律性由自身决定，内脏神经只起调节作用"},{"q":"以下具有吞噬能力的神经胶质细胞为","o":["施万细胞","室管膜细胞","小胶质细胞","少突胶质细胞","星形胶质细胞"],"a":2,"e":"小胶质细胞是中枢神经系统内具有吞噬能力的胶质细胞，来源于单核巨噬细胞系统，可吞噬坏死组织与异物。星形胶质细胞参与构成血-脑屏障，少突胶质细胞形成中枢髓鞘，室管膜细胞衬覆脑室，施万细胞形成周围神经髓鞘，均无吞噬功能"},{"q":"下列关于肺动脉干的描述正确的是","o":["起自左心房","位于心包内","起始处位于主动脉根的后方","由左前下方行向右后上方","运输动脉血"],"a":1,"e":"肺动脉干位于心包内，起自右心室，在升主动脉前方向左后上方斜行，至主动脉弓下方分为左、右肺动脉，运输含氧低的静脉血。其起始处位于主动脉根前方而非后方，发出部位是右心室而非左心房"},{"q":"三角肌的形态结构特征包括","o":["位于臂部","受桡神经支配","使肩关节外展","只起于肩胛骨","止于肱骨桡神经沟下方"],"a":2,"e":"三角肌位于肩部，起自锁骨外侧1/3、肩峰与肩胛冈，止于肱骨三角肌粗隆，由腋神经支配，主要使肩关节外展，前部纤维屈肩、后部纤维伸肩。桡神经支配臂后群与前臂伸肌，其起点也不限于肩胛骨"},{"q":"属于听觉感受器的结构是","o":["椭圆囊斑","球囊斑","壶腹嵴","螺旋器","膜壶腹"],"a":3,"e":"螺旋器位于蜗管基底膜上，由毛细胞与支持细胞构成，是听觉感受器，感受声波振动。椭圆囊斑与球囊斑感受直线加速度，壶腹嵴感受角加速度，均属位觉感受器；膜壶腹是膜半规管的膨大部，并非感受器本身"},{"q":"患者，女。乳房上部有一个结节，请问该处的淋巴管最容易注入的是","o":["胸肌淋巴结","膈上淋巴结","尖淋巴结","胸骨旁淋巴结","锁骨下淋巴结"],"a":2,"e":"乳房上部的淋巴管多直接注入尖淋巴结，再经锁骨下淋巴干入胸导管或右淋巴导管。乳房外侧部注入胸肌淋巴结，内侧部注入胸骨旁淋巴结，下部注入膈上淋巴结，故上部结节最先至尖淋巴结"},{"q":"下述哪个不是髂内动脉的分支","o":["子宫动脉","膀胱下动脉","直肠下动脉","卵巢动脉","阴部内动脉"],"a":3,"e":"卵巢动脉在肾动脉稍下方起自腹主动脉，斜向下外跨输尿管与髂外动脉入盆，分布于卵巢与输卵管，不属髂内动脉分支。子宫动脉、膀胱下动脉、直肠下动脉与阴部内动脉均为髂内动脉分支"},{"q":"外侧膝状体接受","o":["深感觉的传导通路纤维","痛、温觉的传导通路纤维","触觉的传导通路纤维","视觉的传导通路纤维","听觉的传导通路纤维"],"a":3,"e":"外侧膝状体接受视束纤维，发出视辐射经内囊后肢至距状沟两侧视区，是视觉通路的中继站。内侧膝状体接受外侧丘系与下丘臂纤维，与听觉有关；深感觉、痛温觉与触觉纤维止于腹后外侧核"},{"q":"脑干内的特殊内脏运动核支配","o":["咀嚼肌、表情肌、咽喉肌","舌肌","心肌","平滑肌","眼球外肌"],"a":0,"e":"脑干的特殊内脏运动核包括三叉神经运动核、面神经核、疑核与副神经核，支配咀嚼肌、表情肌、咽喉肌及胸锁乳突肌、斜方肌。舌肌由舌下神经核支配，属躯体运动；心肌与平滑肌由一般内脏运动核控制；眼球外肌由动眼、滑车、展神经核支配"},{"q":"关于肝门静脉或肝门静脉系的特点，正确的描述是","o":["静脉压低于下腔静脉","静脉高压时很少发生食管静脉丛曲张","肝门静脉因含有许多瓣膜而扩张","静脉高压可引起脐周静脉网曲张和痔","血流少于肝固有动脉"],"a":3,"e":"门静脉系统无静脉瓣，压力升高时血液经侧支反流，出现食管静脉丛曲张、脐周静脉网曲张与直肠静脉丛曲张形成痔。门静脉压高于下腔静脉，肝血流量70%来自门静脉，远多于肝固有动脉，故\"压力低于下腔静脉\"\"血流少于肝固有动脉\"均错"},{"q":"关于喉返神经的叙述，错误的是","o":["右侧勾绕腋动脉","左侧勾绕主动脉弓","上行于气管食管沟内","入喉内改名为喉下神经","与甲状腺下动脉交叉"],"a":0,"e":"喉返神经右侧勾绕右锁骨下动脉，左侧勾绕主动脉弓，沿气管食管沟上行，在环甲关节后方入喉改称喉下神经，与甲状腺下动脉交叉。右侧勾绕腋动脉之说与解剖不符，锁骨下动脉才是其绕行对象"},{"q":"一患者入院检查后发现对侧偏身躯体深浅感觉缺失，余无异常发现，该患者损伤的什么结构","o":["丘脑中央辐射","丘脑前辐射","额桥束","听辐射","视辐射"],"a":0,"e":"丘脑中央辐射即腹后核至中央后回的投射纤维，行于内囊后肢，一侧损伤致对侧半身躯体深浅感觉全部缺失，运动功能可不受累。丘脑前辐射至额叶，损伤引起精神障碍；额桥束属运动协调通路；听辐射、视辐射损伤分别产生听力障碍与同向偏盲"},{"q":"关于喉的描述，正确的是","o":["上界为甲状软骨上缘","下界为环状软骨下缘","成人位于第2～4 颈椎前方","前方有甲状腺峡","后方为食管"],"a":1,"e":"喉的下界为环状软骨下缘，与气管相续，上界为会厌上缘。成人喉位于第3～6颈椎前方，可随吞咽移动，前方为皮肤、浅筋膜与舌骨下肌群，甲状腺峡位于其前方下部，后方为喉咽而非食管"},{"q":"短骨不包括","o":["豌豆骨","指骨","大多角骨","足舟骨","骰骨"],"a":1,"e":"短骨近于立方，多成群分布于腕、踝部，如腕骨中的豌豆骨、大多角骨、月状骨，跗骨中的足舟骨、骰骨，能承受较大压力并作小幅灵活运动。指骨虽短小，却具骨干与两端，属长骨，故不属短骨"},{"q":"锁骨的形态结构特征不包括","o":["全长可在体表扪及","分为一体两端","内侧端粗大为胸骨端","外侧端扁平为肩峰端","其内侧1/3段凸向前"],"a":4,"e":"锁骨内侧2/3凸向前，外侧1/3凹向前，全长位置表浅可扪及，分一体两端，内侧端粗大为胸骨端，外侧端扁平为肩峰端。故\"内侧1/3凸向前\"把凸向与分段比例同时说错，内侧才是凸向前的一段"},{"q":"关于大唾液腺的叙述，错误的是","o":["腮腺位于外耳道下方","腮腺管开口于平对上颌第2磨牙牙冠的颊黏膜上","下颌下腺管开口于舌下阜","舌下腺大管开口于舌下襞","舌下腺较小"],"a":3,"e":"舌下腺大管开口于舌下阜，小管开口于舌下襞。腮腺管开口于平对上颌第2磨牙牙冠的颊黏膜，下颌下腺管开口于舌下阜，舌下腺为三对大唾液腺中最小者。故舌下腺大管的开口部位描述错误"},{"q":"含有心传导系右束支的结构是","o":["界嵴","室上嵴","室间隔膜部","隔缘肉柱","乳头肌"],"a":3,"e":"右束支沿室间隔右侧心内膜深面下行，起始段行于隔缘肉柱内，故隔缘肉柱含右束支。室间隔膜部有房室束穿过，界嵴是右心房内结构，室上嵴为右心室流入道与流出道的分界，乳头肌连腱索，均不含束支主干"},{"q":"生成雄激素的结构是","o":["精曲小管上皮","睾丸网","睾丸间质细胞","精直小管","附睾管"],"a":2,"e":"睾丸间质细胞位于精曲小管之间的结缔组织内，受黄体生成素调节，分泌雄激素即睾酮。精曲小管上皮含生精细胞与支持细胞，司精子发生；睾丸网与精直小管为精子排出通道；附睾管储存精子并促其成熟"},{"q":"关于卵巢的描述，正确的是","o":["卵巢位置固定主要靠卵巢窝","卵巢悬韧带又称为卵巢子宫索","上端有卵巢固有韧带连于子宫","前缘借卵巢系膜连于子宫阔韧带","下端又称为输卵管端"],"a":3,"e":"卵巢前缘有卵巢系膜附着，借此连于子宫阔韧带后层，血管神经由此出入称卵巢门。卵巢悬韧带内含卵巢血管，又称骨盆漏斗韧带；卵巢固有韧带连于子宫角；上端称输卵管端，下端称子宫端"},{"q":"头面部的触觉传导至","o":["三叉神经脊束核","三叉神经中脑核","三叉神经脑桥核","脊神经节","三叉神经运动核"],"a":2,"e":"头面部触觉纤维入脑后止于三叉神经脑桥核即感觉主核，由此发出纤维交叉组成三叉丘系。痛温觉纤维止于三叉神经脊束核，本体感觉纤维止于三叉神经中脑核，三叉神经运动核支配咀嚼肌，脊神经节属躯体感觉通路"},{"q":"肩胛骨的形态结构特征不包括","o":["三角形扁的不规则骨","贴于胸廓的后外侧面","介于第2～7肋骨之间","腹侧面或肋面称为肩胛下窝","可分为二面、三缘和三个角"],"a":0,"e":"肩胛骨为三角形扁骨，贴于胸廓后外面，介于第2～7肋之间，分二面、三缘和三个角，肋面称肩胛下窝，后面被肩胛冈分为冈上窝与冈下窝。扁骨与不规则骨属两类不同的骨，肩胛骨内无含气腔，故\"不规则骨\"错误"},{"q":"男性生殖系统中负责分泌雄性激素的是","o":["睾丸间质细胞","精曲小管","精囊","白膜","前列腺"],"a":0,"e":"睾丸间质细胞位于精曲小管之间的结缔组织内，受黄体生成素调控，分泌雄激素即睾酮，是男性体内雄激素的主要来源。精曲小管产生精子，精囊分泌精囊液，前列腺分泌前列腺液，白膜为睾丸被膜，均不分泌雄激素"},{"q":"关于桡动脉的叙述，错误的是","o":["该动脉在平桡骨颈高度处发自肱动脉","其主要分支是掌浅支和拇主要动脉","其体表投影为自肘窝中点稍下至桡骨茎突的连线","其压迫止血部位在桡骨茎突的上方，肱桡肌腱的内侧","压迫该动脉其止血范围为：整个前臂和手部"],"a":4,"e":"桡动脉在平桡骨颈高度发自肱动脉，主要分支为掌浅支与拇主要动脉，体表投影为肘窝中点稍下至桡骨茎突的连线，摸脉及压迫止血点在桡骨茎突内上方、肱桡肌腱内侧。其供血限于前臂桡侧与手掌，尺侧由尺动脉供应，故\"整个前臂和手部\"超出其范围"},{"q":"眼球壁中膜由前向后包括","o":["虹膜、脉络膜、视网膜","瞳孔、虹膜、睫状体","虹膜、睫状体、脉络膜","瞳孔、睫状体、脉络膜","脉络膜、睫状体、虹膜"],"a":2,"e":"眼球壁中膜即血管膜，由前向后为虹膜、睫状体与脉络膜，分别司瞳孔调节、晶状体调节与营养眼球。视网膜属内膜；瞳孔是虹膜中央的孔，并非膜性结构，故凡含\"瞳孔\"的组合均不成立"},{"q":"关于内囊，正确的选项是","o":["位于丘脑、尾状核和豆状核之间的白质板","位于豆状核、丘脑和尾状核之间的白质板","位于豆状核、尾状核和丘脑之间的白质板","位于豆状核、丘脑、尾状核之间的白质板","位于丘脑、尾状核、豆状核和屏状核之间的白质板"],"a":0,"e":"本题原题配有图片，图片未随文档保留，以下解析依文字线索推断：题干涉及图片/信息缺失，无法作答。内囊是位于尾状核、背侧丘脑与豆状核之间的白质板，水平切面呈向外开放的V形，分前肢、膝与后肢。本题A、B、C、D四项所列核团完全相同，仅词序不同，内容等同而无可择，E项另加屏状核亦不成立，故无唯一正确项\n\n官方题库中缺失图片"},{"q":"使足做背屈和内翻运动的肌是","o":["小腿三头肌","胫骨前肌","趾长伸肌","腓骨长肌","腓骨短肌"],"a":1,"e":"胫骨前肌起自胫骨外侧面上部，肌腱止于内侧楔骨与第1跖骨底，收缩时使足背屈并内翻，是维持足内侧纵弓的重要肌。小腿三头肌使足跖屈，趾长伸肌主伸趾，腓骨长肌与腓骨短肌使足外翻跖屈"},{"q":"通过心脏右纤维三角的结构是","o":["房室束","左束支","右束支","结间束","窦房结支"],"a":0,"e":"右纤维三角位于左、右房室口与主动脉口之间，房室束由其内穿过，是传导系的关键通道，该处纤维化可致房室传导阻滞。左、右束支起自房室束分叉之后，结间束行于心房壁，窦房结支属血管分支"},{"q":"关于腘淋巴结的叙述，正确的是","o":["沿大隐静脉末端和腘血管排列","注入腹股沟浅淋巴结","输出淋巴管沿股神经上行","引流小腿深层结构的淋巴","分为浅、中、深三群"],"a":3,"e":"腘淋巴结位于腘窝内，沿腘血管与小隐静脉末端排列，收纳足外侧、小腿后外侧的浅淋巴及小腿深部结构的淋巴，输出管注入髂外淋巴结或腹股沟深淋巴结。腹股沟浅淋巴结沿大隐静脉末端排列，腘淋巴结无浅、中、深三群之分"},{"q":"关于脊髓小脑说法正确的是","o":["因传出纤维主要终止于脊髓而得名","由绒球和小结构成","参与随意运动的调控","种系进化上最早出现","参与肌张力的调节"],"a":4,"e":"脊髓小脑由脊髓小脑前束与后束经小脑上、下脚止于小脑皮质，传递肌与关节位置及肌张力信息，参与肌张力调节。其名称源于纤维起于脊髓而非止于脊髓；绒球小结叶属前庭小脑，协调随意运动主要属新小脑即大脑小脑"},{"q":"骨骼肌在受到外力牵拉伸长时，引起其收缩的反射属于","o":["内脏躯体反射","牵张反射","内脏反射","屈曲反射","躯体内脏反射"],"a":1,"e":"骨骼肌受外力牵拉而伸长时反射性收缩称牵张反射，感受器为肌梭，传入纤维属Ⅰa类，中枢在脊髓，为单突触深反射，膝跳反射即典型例子。内脏躯体反射与躯体内脏反射指内脏与躯体间的反射联系，屈曲反射由皮肤痛刺激引起，属多突触反射"},{"q":"第2颈椎的特征不包括","o":["又名枢椎","有椎体","与寰椎前弓后面的齿突凹相关节","体积最大","向上伸出齿突"],"a":3,"e":"枢椎有椎体，向上伸出齿突，与寰椎前弓后面的齿突凹构成寰枢关节，是头颈旋转的枢纽。枢椎棘突粗大而分叉，并非体积最大；体积最大、椎体最粗壮的椎骨是腰椎，寰椎则无椎体亦无棘突"},{"q":"蚓状肌对第2～5指的作用是","o":["屈掌指关节和屈指骨间关节","伸掌指关节和屈指骨间关节","屈掌指关节和伸指骨间关节","伸掌指关节和伸指骨间关节","屈近侧指间关节和伸远侧指间关节"],"a":2,"e":"蚓状肌起自指深屈肌腱，止于第2～5指指背腱膜，收缩时屈掌指关节、伸指骨间关节，与骨间肌协同完成精细动作。骨间肌兼有内收、外展功能，屈指骨间关节实为指浅、指深屈肌的作用"},{"q":"海绵窦直接注入","o":["上矢状窦","下矢状窦","直窦","岩上窦","乙状窦"],"a":3,"e":"海绵窦的血液经岩上窦、岩下窦引流，其中直接注入岩上窦，再经横窦、乙状窦至颈内静脉。上矢状窦注入窦汇，下矢状窦注入直窦，直窦汇入窦汇，乙状窦是海绵窦血的间接通路，故均非直接注入对象"},{"q":"成人子宫正常的姿势是","o":["前倾前屈","前倾后屈","后倾前屈","后倾后屈","前倾侧屈"],"a":0,"e":"成人子宫呈前倾前屈位：前倾指子宫长轴与阴道长轴间向前的角度，前屈指子宫体与子宫颈间向前的弯曲，二者使子宫伏于膀胱上方。后倾后屈属异常位置，可影响受孕，前倾侧屈亦非正常姿势"},{"q":"支配泪腺分泌的神经是","o":["面神经","舌咽神经","副神经","三叉神经","迷走神经"],"a":0,"e":"泪腺由面神经的副交感纤维支配：节前纤维起自上泌涎核，经岩大神经、翼管神经至翼腭神经节换元，节后纤维经颧神经、泪腺神经入泪腺。三叉神经眼支只司泪腺感觉，舌咽神经、迷走神经与副神经均无至泪腺的分泌纤维"},{"q":"颅腔内前庭蜗神经瘤最容易压迫的神经是","o":["面神经","三叉神经","展神经","迷走神经","舌下神经"],"a":0,"e":"前庭蜗神经瘤发生于内耳道内的前庭蜗神经鞘，瘤体增大首先压迫同侧的面神经，因面神经与前庭蜗神经伴行于内耳道，故早期出现面瘫。三叉神经、展神经位于海绵窦及眶内，迷走神经、舌下神经位于颈静脉孔以下或延髓，距离较远"},{"q":"梨状隐窝位于","o":["鼻咽部","口咽部","喉咽部","固有口腔","咽隐窝的两侧"],"a":2,"e":"梨状隐窝位于喉咽部，在喉口两侧、甲状软骨板内侧与杓状软骨之间，是异物易滞留处。鼻咽部的隐窝为咽隐窝，是鼻咽癌好发部位；口咽部有腭扁桃体窝，固有口腔属口腔本部，均不含梨状隐窝"},{"q":"使足做跖屈和外翻动作的肌是","o":["腓肠肌","趾长屈肌","胫骨后肌","腓骨长肌","比目鱼肌"],"a":3,"e":"腓骨长肌起自腓骨外侧面上部，肌腱经外踝后方绕足底，止于内侧楔骨与第1跖骨底，收缩时使足跖屈并外翻，参与维持足横弓与外侧纵弓。腓肠肌、比目鱼肌只使足跖屈，胫骨后肌使足内翻跖屈，趾长屈肌主屈趾"},{"q":"属于膜迷路的是","o":["椭圆囊、球囊、耳蜗","椭圆囊、膜半规管、蜗管","前庭、膜半规管、耳蜗","前庭、膜半规管、蜗管","前庭、骨半规管、耳蜗"],"a":1,"e":"膜迷路包括椭圆囊、球囊、膜半规管与蜗管，内含内淋巴，分别司位觉与听觉。前庭、骨半规管与耳蜗属骨迷路；耳蜗为骨性螺旋管，其内的膜性管道才是蜗管，故含前庭、骨半规管、耳蜗的组合均不成立"},{"q":"关于角膜的叙述，错误的是","o":["角膜占纤维膜的后1/6","营养物质来源于毛细血管、泪液和房水","无血管，富有感觉神经末梢","角膜具有屈光作用","无色透明且富有弹性"],"a":0,"e":"角膜占纤维膜的前1/6，中央薄周边厚，无色透明富弹性，无血管而富含感觉神经末梢，营养靠房水、泪液与角膜缘毛细血管，具屈光作用。巩膜占纤维膜后5/6，故\"后1/6\"把前后比例颠倒"},{"q":"关于主动脉小球描述正确的是","o":["在主动脉弓下方，位于动脉韧带内","属于化学感受器","属于压力感受器","位于主动脉弓的壁内","位于主动脉弓的前方"],"a":1,"e":"主动脉小球位于主动脉弓下方、动脉韧带附近，属化学感受器，感受血液二氧化碳分压、氧分压与氢离子浓度变化，反射性调节呼吸。颈动脉窦与主动脉弓壁内的压力感受器感受血压变化，\"位于弓壁内\"\"位于弓前方\"均与位置不符"},{"q":"躯干和四肢的意识性本体感觉传导通路中的第2级神经元胞体位于","o":["三叉神经节内","脊髓后角固有核","脊髓侧角","延髓薄束核和楔束核","延髓的下橄榄核"],"a":3,"e":"意识性本体感觉通路的第2级神经元胞体位于延髓薄束核与楔束核，发出纤维交叉后组成内侧丘系上行。第1级在脊神经节，第3级在背侧丘脑腹后外侧核；三叉神经节属头面部感觉通路，脊髓侧角为交感节前神经元，下橄榄核属锥体外系"},{"q":"骨的描述，不正确的是","o":["是一种器官","成人有206块","主要有骨组织构成","锁骨属于躯干骨","指骨属于长骨"],"a":3,"e":"骨是器官，成人共206块，主要由骨组织构成，按形态分长骨、短骨、扁骨与不规则骨。锁骨与肩胛骨属上肢带骨，躯干骨只包括椎骨、肋与胸骨。指骨虽短小但具骨干与两端，属长骨"},{"q":"关于内侧丘系在脑干各部内位置的叙述，错误的是","o":["发出该束神经纤维的细胞体位于同侧薄束核和楔束核内","在延髓，内侧丘系位于中线和下橄榄核间，锥体背侧","在脑桥，内侧丘系经过斜方体","在中脑，内侧丘系纤维在上丘高度位于红核背外侧","内侧丘系向上终止于同侧的背侧丘脑腹后外侧核"],"a":0,"e":"内侧丘系由对侧薄束核与楔束核发出的二级纤维交叉形成，故其纤维的胞体位于对侧而非同侧。该束在延髓位于中线外侧、锥体背侧，在脑桥穿过斜方体，在中脑行于红核背外侧，向上止于腹后外侧核"},{"q":"不属于颈内动脉行程分部的是","o":["颈部","岩部","海绵窦部","前床突上部","前床突下部"],"a":4,"e":"颈内动脉以颅底为界分颈部、岩部、海绵窦部与前床突上部四段，前床突上部又称床突上段，位置最高，分出眼动脉与后交通动脉等分支。无“前床突下部”这一分部，该名称系将床突上段误拆而成，其余四部均为标准分部"},{"q":"脑干由哪些结构组成","o":["由丘脑、中脑和脑桥组成","由间脑、中脑和脑桥组成","由间脑、中脑和延髓组成","由中脑、脑桥和延髓组成","由间脑、脑桥和延髓组成"],"a":3,"e":"脑干自上而下由中脑、脑桥与延髓三部分组成，向上以大脑脚与间脑相接，向下在枕骨大孔处续于脊髓，内含第Ⅲ～Ⅻ对脑神经核及多条上下行传导束。间脑与丘脑属前脑结构，不属脑干，故含间脑或丘脑的组合均错"},{"q":"不属于肝蒂的结构","o":["肝圆韧带","肝固有动脉左、右支","肝门静脉的左、右支","肝的神经","肝的淋巴管"],"a":0,"e":"肝蒂为出入肝门诸结构的总称，含肝固有动脉左右支、肝门静脉左右支、肝左右管、肝的神经与淋巴管，共同包裹于肝十二指肠韧带内。肝圆韧带是脐静脉闭锁后的遗迹，位于肝镰状韧带游离缘，不属肝蒂内容"},{"q":"具有伸膝关节作用的肌","o":["缝匠肌","半腱肌","半膜肌","股二头肌","股四头肌"],"a":4,"e":"股四头肌是伸膝的主要肌，四头合成一腱止于髌骨并续为髌韧带止于胫骨粗隆，其中股直肌还可屈髋。缝匠肌屈髋屈膝并使小腿内旋；半腱肌、半膜肌与股二头肌属腘绳肌，屈膝并伸髋，均无伸膝作用"},{"q":"左心房可见到的结构是","o":["上、下腔静脉口","冠状窦口","卵圆窝","界嵴","二尖瓣口"],"a":4,"e":"左心房通向左侧房室口，该口周缘附有二尖瓣，是血液进入左心室的通道，故二尖瓣口位于左心房。上、下腔静脉口与冠状窦口均开口于右心房，界嵴是右心房内壁的肌性隆起。卵圆窝位于房间隔的右侧面，为胚胎卵圆孔闭合后的遗迹"},{"q":"不穿过眶上裂的神经是","o":["眼神经","视神经","动眼神经","滑车神经","展神经"],"a":1,"e":"眶上裂位于蝶骨大、小翼之间，眼神经、动眼神经、滑车神经、展神经及眼静脉均经此入眶。视神经伴眼动脉穿视神经管入眶，故不经过眶上裂。眼神经为三叉神经第一支，属感觉神经；动眼、滑车、展神经均为眼球外肌的运动神经，四者同在眶上裂内通过，易被一并设错"},{"q":"在腕骨，从桡侧至尺侧，近侧列的腕骨是","o":["月骨、手舟骨、三角骨、豌豆骨","三角骨、月骨、手舟骨、豌豆骨","豌豆骨、月骨、三角骨、手舟骨","手舟骨、月骨、大多角骨、豌豆骨","手舟骨、月骨、三角骨、豌豆骨"],"a":4,"e":"近侧列由桡侧向尺侧依次为手舟骨、月骨、三角骨、豌豆骨，四骨借韧带连成弧形，与桡骨下端和尺骨头相关节。大多角骨、小多角骨、头状骨、钩骨属远侧列，故含大多角骨的组合不能成立。豌豆骨位于三角骨掌侧，是尺侧腕屈肌腱内的籽骨，位置最靠尺侧"},{"q":"关于颈内动脉正确的描述是","o":["在颈部发出舌动脉","其颈部位居颈外动脉的内侧","供应脑的前2/3","伴行于颈内静脉外侧","起始处的膨大称颈动脉小球"],"a":2,"e":"颈内动脉在颈部无分支，经颈动脉管入颅，主要发出眼动脉及大脑前、中动脉，供应脑的前2/3及视器。舌动脉是颈外动脉的分支，颈动脉窦才是其起始处的膨大，颈动脉小球为化学感受器。颈内动脉在颈部初居颈外动脉的后外侧，并非恒定位于其内侧"},{"q":"大脑动脉环由下列动脉组成","o":["两侧大脑前动脉、两侧颈内动脉、两侧大脑后动脉、前交通动脉、后交通动脉","两侧大脑前动脉、两侧大脑后动脉、前交通动脉、后交通动脉","两侧大脑前动脉、两侧大脑后动脉、前交通动脉、两侧基底动脉","两侧大脑前动脉、两侧颈内动脉、两侧基底动脉、前交通动脉","两侧大脑前动脉、两侧颈内动脉、椎动脉、后交通动脉"],"a":0,"e":"大脑动脉环由前交通动脉、两侧大脑前动脉始段、两侧颈内动脉末段、两侧后交通动脉和两侧大脑后动脉始段围成，位于蝶鞍上方，沟通颈内动脉系与椎-基底动脉系。基底动脉本身不参与组成；椎动脉经枕骨大孔入颅后才合成基底动脉，基底动脉再发出大脑后动脉"},{"q":"关于固有鼻腔，描述正确的是","o":["顶部的鼻黏膜有嗅细胞","中鼻甲的鼻黏膜有嗅细胞","下鼻道的鼻黏膜有嗅细胞","内壁有鼻毛","内壁有皮脂腺"],"a":0,"e":"嗅区位于上鼻甲内侧面及与其相对的鼻中隔上部，黏膜内含嗅细胞，能感受气味的化学刺激。中鼻甲、下鼻道均属呼吸区，黏膜为假复层纤毛柱状上皮，只含一般感觉末梢。鼻毛和皮脂腺见于鼻前庭，属鼻腔前部的皮肤被覆区，不属固有鼻腔的内壁结构"},{"q":"关于左心室正确的记述是","o":["入口周缘有三尖瓣","左上部为动脉圆锥","流出道与肺动脉口相延续","前内侧部为主动脉前庭","内有隔缘肉柱"],"a":3,"e":"左心室以二尖瓣前尖为界分为流入道与流出道，流出道即主动脉前庭，位于左心室前内侧部，由室间隔上部和二尖瓣前尖围成。入口周缘为二尖瓣而非三尖瓣，动脉圆锥是右心室的流出道，隔缘肉柱位于右心室。流出道向上通主动脉口，与肺动脉口并无延续关系"},{"q":"关于颈总动脉和颈外动脉的叙述，错误的是","o":["右颈总动脉发自主动脉弓，左颈总动脉起自头臂干","颈总动脉的分支有颈内动脉和颈外动脉","其体表投影为：自胸锁关节至耳屏稍前下方作一连线，甲状软骨上缘以上为颈外动脉，以下为颈总动脉","其压迫止血部位为：在环状软骨弓的侧方，可摸到颈总动脉搏动，将动脉压向后内侧的第6颈椎横突上","压迫该动脉其止血范围为头面部"],"a":0,"e":"右颈总动脉起自头臂干，左颈总动脉直接起自主动脉弓，二者在甲状软骨上缘分为颈内、颈外动脉。体表投影为胸锁关节至耳屏前下方的连线，压迫点在环状软骨侧方、第6颈椎横突即颈动脉结节处。头臂干发自主动脉弓，将左右两侧的起源对调即为错误叙述"},{"q":"腹部的动脉","o":["脏支分为成对和不成对两种","成对脏支只有肾动脉和睾丸动脉","阑尾动脉发自肠系膜下动脉","脾动脉是肠系膜上动脉的分支","胃网膜左动脉是胃十二指肠动脉的分支"],"a":0,"e":"腹主动脉的脏支按是否成对分为两类，成对的有肾上腺中动脉、肾动脉和睾丸（卵巢）动脉，不成对的有腹腔干、肠系膜上动脉和肠系膜下动脉。阑尾动脉发自回结肠动脉，属肠系膜上动脉的分支；脾动脉为腹腔干的分支；胃网膜左动脉亦发自脾动脉"},{"q":"收缩时，可在颧弓下方摸到坚硬的条状隆起的肌是","o":["颞肌后束","二腹肌前腹","翼内肌浅头","咬肌","翼外肌"],"a":3,"e":"咬肌起自颧弓下缘及内面，止于下颌支外面的咬肌粗隆，位置表浅，咬紧牙时在颧弓下方、下颌角上方可触到坚硬的肌性隆起。颞肌位于颧弓深面，翼内肌、翼外肌均位于下颌支内侧，体表不能触及。二腹肌前腹位于下颌骨下方，收缩时降下颌骨，不形成该隆起"},{"q":"不属于下丘脑的结构是","o":["乳头体","灰结节","漏斗","视交叉","外侧膝状体"],"a":4,"e":"下丘脑位于丘脑下沟下方，包括视交叉、灰结节、漏斗、垂体和乳头体等，漏斗核、视上核、室旁核均属其核团。外侧膝状体属后丘脑，与内侧膝状体同为特异性感觉中继核，分别中继视觉和听觉冲动。乳头体虽露于脑底，仍归入下丘脑，不可与后丘脑混淆"},{"q":"喉返神经不支配下列何结构","o":["环杓后肌","环杓侧肌","环甲肌","杓斜肌","杓横肌"],"a":2,"e":"喉返神经支配除环甲肌以外的全部喉内肌，包括环杓后肌、环杓侧肌、杓横肌和杓斜肌，损伤后声带麻痹、声音嘶哑。环甲肌由喉上神经外支支配，收缩时紧张声带，损伤后仅音调降低而声带运动仍存。喉上神经内支为感觉支，分布于声门裂以上的喉黏膜"},{"q":"内耳的结构不包括","o":["前庭","耳蜗","半规管","内耳道","内淋巴"],"a":3,"e":"内耳位于颞骨岩部骨质内，由骨迷路和膜迷路组成，骨迷路包括半规管、前庭和耳蜗，膜迷路内含内淋巴。内耳道是颞骨岩部后面的骨性管道，有面神经、前庭蜗神经及迷路血管通过，属神经血管的通路，不属内耳结构。骨迷路与膜迷路共同构成位置觉和听觉的末梢装置"},{"q":"与喉直接相连通的结构是","o":["鼻咽","口咽","喉咽","鼻腔","口腔"],"a":2,"e":"喉位于颈前部，上通喉咽，下接气管，喉口朝向后上方与喉咽相通，吞咽时喉上提、会厌封闭喉口。鼻咽经咽鼓管通鼓室，口咽经咽峡通口腔，二者均不直接连于喉。鼻腔与喉之间隔以咽腔，并不直接相通，不能作为喉的连通结构"},{"q":"枢椎是","o":["第1颈椎","第2颈椎","第7颈椎","胸椎","腰椎"],"a":1,"e":"枢椎为第2颈椎，椎体向上伸出齿突，与寰椎前弓后面相关节，构成寰枢关节，使头能作旋转运动。寰椎为第1颈椎，无椎体和棘突；第7颈椎棘突长而不分叉，称隆椎；胸椎有肋凹，腰椎椎体粗壮，均不具备齿突这一特征"},{"q":"支配臂肌前群的神经是","o":["正中神经","桡神经","尺神经","腋神经","肌皮神经"],"a":4,"e":"臂前群有肱二头肌、肱肌和喙肱肌，均由肌皮神经支配，该神经穿喙肱肌后行于肱二头肌与肱肌之间，终支为前臂外侧皮神经。桡神经支配臂后群的肱三头肌，腋神经支配三角肌和小圆肌，正中神经、尺神经主要支配前臂和手肌。肱骨骨折可致屈肘无力"},{"q":"关于阴道穹的描述，正确的是","o":["上部与子宫颈阴道部之间环行的凹陷称阴道前庭","阴道穹可分为互不连通的4部","以阴道穹前部最深","阴道穹后部与膀胱子宫陷凹相邻仅隔阴道壁和腹膜","直肠子宫陷凹积液时，可经阴道穹后部进行穿刺"],"a":4,"e":"阴道穹是阴道上端包绕子宫颈阴道部形成的环形间隙，分前、后、左、右四部且互相连通，以后部最深。后穹仅隔阴道壁和腹膜与直肠子宫陷凹相邻，故可经此穿刺引流积液或积血。前部邻膀胱子宫陷凹；阴道前庭为女阴的菱形区，与阴道穹无关"},{"q":"子宫淋巴管注入的淋巴结是","o":["髂内淋巴结","腰淋巴结","肠系膜上淋巴结","髂外淋巴结","腹股沟深淋巴结"],"a":0,"e":"子宫的淋巴引流分区分段：子宫底和体上部沿卵巢血管注入腰淋巴结，体下部和子宫颈注入髂内、闭孔淋巴结，宫颈的部分淋巴管还可至髂外淋巴结。肠系膜上淋巴结引流小肠及右半结肠，与子宫无关。腹股沟深淋巴结收纳下肢和会阴深部的淋巴，不是子宫的主要回流途径"},{"q":"下列关于前列腺的描述，正确的是","o":["由平滑肌构成","是成对的中空性器官","呈尖朝上、底朝下","体后面有纵行的前列腺沟","活体直肠指诊，触摸不到前列腺"],"a":3,"e":"前列腺为不成对的实质性器官，由腺组织和平滑肌构成，底朝上邻膀胱颈，尖朝下抵尿生殖膈，体后面有纵行的前列腺沟，直肠指诊可触及。其内有尿道和射精管穿过，故非中空性器官，且为单个而非成对。活体指诊正是经直肠前壁触及该沟及腺体形态的变化"},{"q":"隆椎就是","o":["第1颈椎","第2颈椎","第4颈椎","第6颈椎","第7颈椎"],"a":4,"e":"第7颈椎棘突特别长，末端不分叉，低头时在颈后正中线隆起明显，故名隆椎，是计数椎骨序数的标志。寰椎无棘突，枢椎棘突短而粗大，第4、6颈椎棘突短且末端分叉。胸椎棘突细长呈叠瓦状，腰椎棘突呈板状水平后伸，均不作计数标志"},{"q":"临床上行冠状动脉造影术一般首选哪条动脉为入口","o":["面动脉","颈总动脉","肱动脉","颈外动脉","尺动脉"],"a":2,"e":"冠状动脉开口于主动脉窦，导管需经外周动脉逆行送入主动脉根部，肱动脉位置表浅、管径适中，与正中神经伴行可达腋部，是经上肢入路的经典途径。面动脉、颈外动脉供应头颈部，走向相反；颈总动脉上行入颅；尺动脉管径细小，均不宜作为造影入口"},{"q":"可牵拉下颌骨向前下，并作侧方运动的肌是","o":["翼外肌","颞肌","翼内肌","咬肌","二腹肌"],"a":0,"e":"翼外肌起自蝶骨大翼下面和翼突外侧面，止于下颌颈及关节囊、关节盘，两侧同时收缩使下颌骨前伸并下降而张口，单侧收缩使下颌骨移向对侧。咬肌、颞肌、翼内肌均为提下颌肌，其中咬肌兼有前伸作用。二腹肌前腹虽降下颌骨，但不参与侧方运动"},{"q":"关于解剖学姿势的描述，错误的是","o":["身体直立","上肢自然下垂于躯干两侧","两眼向正前方平视","手掌向内侧","足尖向前"],"a":3,"e":"解剖学姿势规定身体直立、两眼平视前方、上肢下垂于躯干两侧、掌心向前、两足并拢且足尖向前。手掌向内侧即掌心向后，是该姿势中最易记错的一项。此姿势是描述器官位置及轴、面方位的统一标准，与人体自然站立时手掌相对的状态不同"},{"q":"关于右淋巴导管的描述，正确的是","o":["接受右支气管纵隔干","注入颈外静脉","接受尖淋巴结的输出淋巴管","引流全身3/4部位的淋巴","接受Virchow淋巴结的输出淋巴管"],"a":0,"e":"右淋巴导管由右颈干、右锁骨下干和右支气管纵隔干汇合而成，长约1.0～1.5cm，注入右静脉角，引流右头颈、右上肢、右胸及右肺等约占全身1/4的淋巴。引流3/4者为胸导管。其注入部位不是颈外静脉；尖淋巴结的输出管经颈干汇入，并非直接注入该导管"},{"q":"背阔肌受哪个神经支配","o":["胸长神经","胸背神经","副神经","腋神经","肩胛上神经"],"a":1,"e":"背阔肌起自下6个胸椎棘突、全部腰椎棘突、髂嵴后部及胸腰筋膜，止于肱骨小结节嵴，使肩关节内收、后伸和旋内，由胸背神经（C6～C8）支配。胸长神经支配前锯肌，副神经支配斜方肌，肩胛上神经支配冈上肌和冈下肌，腋神经支配三角肌与小圆肌"},{"q":"与面神经有关的核团是","o":["三叉神经运动核","下泌涎核","孤束核","疑核","副神经核"],"a":2,"e":"面神经含特殊内脏感觉纤维，胞体位于膝神经节，周围突分布于舌前2/3味蕾，中枢突止于孤束核上部，故孤束核与面神经相关。上泌涎核才是面神经的副交感核，下泌涎核属舌咽神经。三叉神经运动核支配咀嚼肌，疑核支配咽喉肌，副神经核支配胸锁乳突肌和斜方肌"},{"q":"胸椎的形态结构特征是","o":["关节突关节面呈水平位","横突肋凹与肋结节相关节","棘突特别短","第1胸椎有横突孔","椎体横断面呈肾形"],"a":1,"e":"胸椎椎体两侧有肋凹，横突末端前面有横突肋凹，与肋结节关节面相关节，这是胸椎的典型特征。胸椎关节突关节面呈冠状位，利于旋转而限制侧屈；棘突细长，斜向后下呈叠瓦状。横突孔仅见于颈椎，肾形的椎体横断面是腰椎的特征"},{"q":"关节唇的特征不包括","o":["增大关节面","可加深关节窝","附着于关节窝周缘","增加关节的稳定性","是透明软骨环"],"a":4,"e":"关节唇是附着于关节窝周缘的纤维软骨环，可增大关节面、加深关节窝、增加关节稳定性，髋臼唇和盂唇即属此类。其组织学性质为纤维软骨而非透明软骨，后者构成关节软骨与骺软骨。关节盘位于两关节面之间，位置和作用与关节唇不同"},{"q":"属于腹膜外位器官的是","o":["肝","子宫","脾","肾上腺","膀胱"],"a":3,"e":"腹膜外位器官仅一面被腹膜覆盖，位置固定，如肾、肾上腺、胰腺、十二指肠降部和水平部、输尿管及膀胱。肝、脾、子宫为腹膜内位或间位器官，表面大部分有腹膜被覆。肾上腺贴于肾上端，位于腹膜之后，属典型的腹膜外位器官"},{"q":"收缩时使舌尖伸向对侧的肌肉是","o":["舌纵肌","舌骨舌肌","舌横机","颏舌肌","茎突舌肌"],"a":3,"e":"颏舌肌起自下颌体后面的颏棘，止于舌正中线两侧，两侧同时收缩拉舌向前下，单侧收缩使舌尖伸向对侧。一侧颏舌肌瘫痪时舌尖偏向患侧，为舌下神经损伤的体征。舌骨舌肌、茎突舌肌主要牵舌向后上，舌横肌缩小舌的横径，舌纵肌改变舌的长度与厚度"},{"q":"属于副交感神经节前纤维的神经是","o":["内脏大神经","腰内脏神经","内脏小神经","盆内脏神经","心上中下神经"],"a":3,"e":"盆内脏神经由骶髓2～4节段骶副交感核发出的节前纤维组成，经盆丛分布于盆腔脏器，属副交感神经。内脏大、小神经和腰内脏神经均由胸腰段侧角发出，属交感节前纤维。心丛中的心上、中、下神经为交感节后纤维，与盆内脏神经的性质相反"},{"q":"下列关于膜迷路的描述，正确的是","o":["膜迷路是套在骨迷路内封闭的膜性管和囊","由椭圆囊、球囊、膜半规管和蜗螺旋管组成","膜迷路和骨迷路在蜗顶蜗孔处相交通","椭圆囊、球囊、内淋巴囊位于前庭内","膜迷路将骨迷路分为半规管、前庭和耳蜗3部分"],"a":0,"e":"膜迷路是套在骨迷路内、形态相似的封闭膜性管和囊，内含内淋巴，包括椭圆囊、球囊、膜半规管和蜗管，借纤维束固定于骨迷路。蜗螺旋管属骨迷路，膜迷路与骨迷路之间充以外淋巴，二者并不相通。骨迷路本身分为半规管、前庭和耳蜗三部分"},{"q":"胸长神经","o":["属于锁骨下分支","属于臂丛内侧束的分支","属于臂丛外侧束的分支","沿着肩胛下肌表面下行","受损后，肩胛骨内侧缘翘起"],"a":4,"e":"胸长神经起自臂丛根（C5～C7），属锁骨上分支，沿前锯肌表面下行并支配该肌，损伤后前锯肌瘫痪，肩胛骨内侧缘翘起，形成翼状肩。沿肩胛下肌表面走行者是肩胛下神经，胸背神经沿肩胛骨外侧缘下行。该神经不属内侧束或外侧束的分支"},{"q":"与桡神经伴行走在桡神经沟内的动脉是","o":["肱动脉","肱深动脉","旋肱前动脉","旋肱后动脉","腋动脉"],"a":1,"e":"肱深动脉起自肱动脉，与桡神经伴行进入肱骨后面的桡神经沟，分支营养肱三头肌和肱骨，并参与构成肘关节网。旋肱后动脉伴腋神经穿四边孔，分布于三角肌和肩关节；旋肱前动脉绕肱骨外科颈前方；肱动脉主干沿肱二头肌内侧沟下行"},{"q":"胶状质属于脊髓灰质","o":["Ⅰ层","Ⅱ层","Ⅲ层","Ⅳ层","Ⅴ层"],"a":1,"e":"脊髓灰质分为10层，第Ⅱ层为胶状质，由密集的小细胞组成，主要接受后根细纤维的传入，参与痛觉信息的调制。第Ⅰ层为边缘层，第Ⅲ、Ⅳ层为后角固有核所在，第Ⅴ层位于后角颈部。第Ⅶ层含胸核，与脊髓小脑后束的起始有关"},{"q":"外展并参与屈、伸肩关节的肌是","o":["三角肌","胸大肌","背阔肌","冈上肌","小圆肌"],"a":0,"e":"三角肌起自锁骨外侧段、肩峰和肩胛冈，止于肱骨三角肌粗隆，中部纤维外展肩关节，前部纤维前屈并旋内，后部纤维后伸并旋外，由腋神经支配。冈上肌只起始外展15°，小圆肌使肩关节旋外，胸大肌和背阔肌均为内收肌"},{"q":"尺骨的形态结构不包括","o":["位于前臂的内侧，分为一体两端","上端前面有一半月形的滑车切迹","下端后内侧有向下的突起称尺骨茎突","下端有尺骨头","滑车切迹前下方的突起称鹰嘴"],"a":4,"e":"尺骨上端滑车切迹后上方的突起为鹰嘴，前下方的突起为冠突，二者之间为滑车切迹，与肱骨滑车相关节。尺骨头位于下端，头后内侧的锥状突起为尺骨茎突，较桡骨茎突高约1cm。把鹰嘴说成位于前下方，即与冠突的位置互换"},{"q":"脊神经后根内含有","o":["特殊躯体感觉纤维","特殊内脏感觉纤维","躯体运动纤维","内脏运动纤维","躯体感觉和内脏感觉纤维"],"a":4,"e":"脊神经后根由脊神经节内假单极神经元的中枢突构成，含躯体感觉和内脏感觉纤维，将冲动传入脊髓。前根由脊髓前角和侧角运动神经元的轴突组成，含躯体运动和内脏运动纤维。特殊躯体感觉、特殊内脏感觉纤维仅见于脑神经，脊神经不含此类成分"},{"q":"关于喉前庭，描述正确的是","o":["又称为喉腔","位于喉口与前庭襞之间","呈上窄下宽状","位于弹性圆锥下方","与声门下腔相连接"],"a":1,"e":"喉前庭为喉口至前庭襞之间的部分，上宽下窄，前壁为会厌软骨，后壁为杓状软骨上部及杓间切迹。前庭襞至声襞之间为喉中间腔，声襞以下为声门下腔。喉腔是包括喉前庭在内的总称，弹性圆锥位于声襞平面以下，不构成喉前庭的边界"},{"q":"关于三叉丘系正确的是","o":["由同侧三叉神经脊束核和部分三叉神经脑桥核发出的纤维组成","由对侧三叉神经脊束核和部分三叉神经脑桥核发出的纤维组成","三叉神经脊束纤维的直接延续","在脑干的内侧丘系的腹侧上升","大部分纤维传导同侧头面部的痛、温觉信息"],"a":1,"e":"三叉丘系由对侧三叉神经脊束核及部分三叉神经脑桥核发出的纤维交叉后上行组成，终于背侧丘脑腹后内侧核，传导对侧头面部的痛、温觉和触压觉。三叉神经脊束为一级传入纤维，尚未交叉；该系在脑干位于内侧丘系的背外侧，并非其腹侧"},{"q":"构成肾髓质的结构是","o":["肾皮质","肾柱","肾锥体","肾乳头","肾窦"],"a":2,"e":"肾髓质位于肾实质深部，由15～20个肾锥体构成，锥体底朝向皮质，尖端钝圆称肾乳头，伸入肾小盏。肾柱是伸入锥体之间的肾皮质，肾窦为肾门向内凹陷的腔隙，内含肾盏、肾盂及血管等。肾乳头只是锥体尖端的结构，不能代表髓质整体"},{"q":"限制子宫向两侧移动的韧带是","o":["子宫骶韧带","子宫圆韧带","子宫主韧带","子宫阔韧带","骨盆漏斗韧带"],"a":3,"e":"子宫阔韧带是覆盖子宫前、后面的腹膜自子宫侧缘向两侧延伸形成的双层腹膜皱襞，可限制子宫向两侧移动。子宫圆韧带维持子宫前倾，子宫骶韧带牵引宫颈向后上，子宫主韧带防止子宫下垂，三者均不能限制侧方移动。卵巢悬韧带又名骨盆漏斗韧带，功能为悬吊卵巢"},{"q":"患者，女，27岁。足月妊娠，初次正常分娩时需注意保护的结构是","o":["大阴唇","小阴唇","阴阜","会阴体","阴蒂"],"a":3,"e":"会阴体位于阴道口与肛门之间，是会阴中心腱所在，盆膈、尿生殖膈及会阴浅、深横肌等均附着于此，分娩时易发生撕裂，故接生时须加以保护。大、小阴唇及阴阜属外生殖器的皮肤结构，阴蒂为勃起器官，均不承受分娩时的张力"},{"q":"关于中耳的描述，错误的是","o":["中耳由鼓室、咽鼓管、乳突窦和乳突小房组成","大部分位于颞骨岩部内，为含气的不规则小腔隙","中耳向外借鼓膜与外耳道相隔","中耳向内借内耳道底与内耳相邻","中耳向前借咽鼓管通鼻咽部"],"a":3,"e":"中耳包括鼓室、咽鼓管、乳突窦和乳突小房，位于颞骨岩部内，为含气的不规则腔隙，向外借鼓膜与外耳道相隔，向前借咽鼓管通鼻咽部。鼓室内侧壁即迷路壁，上有前庭窗、蜗窗与内耳相邻。内耳道底位于内侧壁后部，是面神经和前庭蜗神经的出入口，并非中耳与内耳的间隔"},{"q":"眼球外肌中使瞳孔转向外侧的包括","o":["上斜肌和下斜肌","上直肌和上斜肌","外直肌和下直肌","外直肌和上直肌","下直肌和下斜肌"],"a":0,"e":"上斜肌的肌腱经滑车转向后外，止于眼球赤道后方，收缩使瞳孔转向下外；下斜肌止于眼球下外方，收缩使瞳孔转向上外，二者均含外转成分。外直肌单独使瞳孔转向外侧，上直肌转向上内，下直肌转向下内，内直肌转向内侧"},{"q":"可伸膝关节的肌是","o":["缝匠肌","股四头肌","大收肌","阔筋膜张肌","臀大肌"],"a":1,"e":"股四头肌由股直肌、股内侧肌、股外侧肌和股中间肌组成，四头合成一腱包绕髌骨续为髌韧带止于胫骨粗隆，是伸膝关节的主要肌群，股直肌兼有屈髋作用。缝匠肌屈髋屈膝，大收肌内收髋关节，阔筋膜张肌紧张髂胫束，臀大肌伸髋"},{"q":"脉管系统的构成","o":["心血管系统和淋巴管组成","心、动脉、毛细血管和静脉","心血管系统和淋巴器官","心、动脉、静脉和淋巴导管","心血管系统和淋巴系统"],"a":4,"e":"脉管系统包括心血管系统和淋巴系统，前者由心、动脉、毛细血管和静脉组成，输送血液；后者由淋巴管道、淋巴器官和淋巴组织组成，引流组织液并参与免疫。仅列心与各类血管只涵盖心血管系统，淋巴器官也不能代表淋巴系统的全部组成"},{"q":"关于颈内静脉的叙述，错误的是","o":["延续于乙状窦","位于颈动脉鞘内","与面静脉汇合成锁骨下静脉","属支有舌静脉和咽静脉","外伤时可致空气栓塞"],"a":2,"e":"颈内静脉在颈静脉孔处续于乙状窦，行于颈动脉鞘内，与颈总动脉、迷走神经伴行，属支有面静脉、舌静脉、咽静脉等，管壁薄且与颈深筋膜愈着，损伤后管腔不易闭合，可致空气栓塞。其下端与锁骨下静脉汇合成头臂静脉，面静脉只是其属支"},{"q":"关于面静脉的正确描述是","o":["起自翼静脉丛","注入颈外静脉","通过眼上及眼下静脉与海绵窦交通","通过面深静脉与颅内静脉相通","在颈内、外动脉的深部走行"],"a":2,"e":"面静脉起自内眦静脉，伴面动脉下行，借眼上静脉与海绵窦交通，借面深静脉经翼静脉丛与颅内静脉相通，且缺乏静脉瓣，故面部感染可蔓延至颅内。其下端注入颈内静脉，而非颈外静脉；行程位于面动脉后外侧的浅层，不深入颈内、外动脉的深部"},{"q":"与成人比较，婴幼儿耳的特点是","o":["外耳道短而弯曲","鼓膜更为倾斜，近似呈水平位","检查鼓膜时，应将耳郭拉向后上方","小儿咽鼓管短而窄","外耳道骨性部分占比例更大"],"a":1,"e":"婴幼儿鼓膜较成人更为倾斜，几乎呈水平位，故检查时须将耳郭向后下方牵拉，使外耳道变直方能看清。小儿外耳道短而狭窄，骨性部尚未完全骨化，软骨部所占比例大；咽鼓管短而宽、近水平位，是中耳炎易发的解剖基础。上述各点恰与成人特点相反"},{"q":"脑干内的非脑神经核","o":["动眼神经核","动眼神经副核","红核","展神经核","面神经核"],"a":2,"e":"红核位于中脑上丘平面，属锥体外系的非脑神经核，接受小脑和大脑皮质纤维，发出红核脊髓束兴奋屈肌运动神经元。动眼神经核、动眼神经副核、展神经核、面神经核均直接发出脑神经纤维，属脑神经核。黑质、下橄榄核、脑桥核亦属非脑神经核"},{"q":"左、右肺根内自前向后排列的主要结构是","o":["肺动脉、肺静脉和主支气管","肺静脉、肺动脉和主支气管","肺动脉、主支气管和肺静脉","肺静脉、主支气管和肺动脉","主支气管、肺静脉和肺动脉"],"a":1,"e":"左、右肺根内主要结构自前向后均为肺静脉、肺动脉、主支气管，肺动脉居于二者之间。自上而下则右侧为主支气管、肺动脉、肺静脉，左侧为肺动脉、主支气管、肺静脉，故上下顺序左右不同。将肺静脉置于最后或把主支气管列于最前，均与排列规律不符"},{"q":"既能屈髋关节又能伸膝关节的肌是","o":["缝匠肌","股薄肌","股直肌","髂腰肌","股二头肌"],"a":2,"e":"股直肌起自髂前下棘，向下参与构成股四头肌腱，跨越髋、膝两个关节，可屈髋关节并伸膝关节。缝匠肌、股薄肌为屈髋屈膝的双关节肌，髂腰肌只屈髋，股二头肌屈膝伸髋。选项中仅股直肌兼具屈髋与伸膝作用"},{"q":"关于甲状腺的描述，错误的是","o":["紧贴喉和气管上部的两侧和前方","呈“H”形，分为左右侧叶和中间的甲状腺峡","有时甲状腺峡向上伸出一锥状叶","甲状腺峡位于第4～5气管软骨环的前方","甲状腺可分泌甲状腺素"],"a":3,"e":"甲状腺呈H形，由左、右侧叶及中间的甲状腺峡组成，侧叶贴于喉和气管上部的两侧，峡多位于第2～4气管软骨环前方，有时向上伸出锥状叶。甲状腺滤泡分泌甲状腺素，调节代谢。将峡的位置下移至第4～5软骨环，与临床常见的低位峡相混"},{"q":"舌下阜","o":["有舌下腺小管的开口","只有下颌下腺管的开口","有舌腺的开口","有下颌下腺管和舌下腺大管的开口","其深面藏有舌下腺"],"a":3,"e":"舌下阜位于舌系带根部的两侧，为下颌下腺管和舌下腺大管的共同开口处，唾液经此排入口腔。舌下腺小管与舌腺的导管直接开口于舌下襞黏膜。舌下阜深面邻舌下腺，但其本身是黏膜隆起，不是腺体所在的结构"},{"q":"视网膜脱离发生于","o":["双极细胞与节细胞之间","视网膜与脉络膜之间","脉络膜与巩膜之间","视网膜内层与外层之间","视锥、视杆细胞与双极细胞之间"],"a":3,"e":"视网膜由外层的色素上皮层和内层的神经细胞层构成，两层之间在发育中留有潜在间隙，是视网膜脱离的解剖基础。色素上皮与脉络膜连接紧密，巩膜与脉络膜之间为脉络膜周间隙；视细胞与双极细胞、双极细胞与节细胞之间均为突触联系，不易分离"},{"q":"胸导管穿经下述哪个结构进入到胸腔","o":["食管裂孔","腰肋三角","主动脉裂孔","膈肌","腔静脉孔"],"a":2,"e":"胸导管起自乳糜池，经主动脉裂孔（平第12胸椎）由腹腔进入胸腔，在脊柱前方上行，最终注入左静脉角。食管裂孔有食管和迷走神经前后干通过，腔静脉孔有下腔静脉通过，腰肋三角为膈的薄弱区，可发生膈疝。三者均非胸导管的通路"},{"q":"对感觉器的描述正确的有","o":["感觉器即感受器","结构简单，由感觉神经末梢形成","视器和前庭蜗器均为感觉器","仅可感受机体外环境刺激","只分布于内脏器官"],"a":2,"e":"感觉器由感受器和附属结构构成，视器和前庭蜗器均属感觉器，前者感受光刺激，后者感受声和位置觉刺激。感受器仅是感觉神经末梢及其特化结构，范围更窄，不能等同于感觉器。感受器既接受外环境刺激，也接受内环境刺激，并广泛分布于内脏与血管"},{"q":"下牙槽神经","o":["主要行于下颌管内","为感觉神经，是上颌神经的分支","发出颊神经","分布于上、下颌牙和牙龈、口唇周围皮肤黏膜","发出舌神经"],"a":0,"e":"下牙槽神经为下颌神经后股的分支，属躯体感觉神经，与下牙槽动脉伴行进入下颌孔，行于下颌管内，分支支配下颌牙、牙龈及颏部皮肤。颊神经、舌神经均为下颌神经的独立分支，并非由下牙槽神经发出；上颌牙由上牙槽神经支配"},{"q":"心的正常起搏点","o":["窦房结","房室结","房室束","左、右束支","浦肯野纤维"],"a":0,"e":"窦房结位于上腔静脉与右心房交界处的界沟上端，是心的正常起搏点，自律性最高，每分钟约60～100次，冲动经结间束传至心房肌和房室结。房室结为次级起搏点，房室束及左、右束支、浦肯野纤维只承担传导，不能取代窦房结的起搏地位"},{"q":"房室结的滋养动脉通常起自","o":["左冠状动脉","右冠状动脉","前室间支","后室间支","旋支"],"a":1,"e":"房室结位于房间隔下部右侧心内膜深面，其血供在多数人来自右冠状动脉发出的房室结支，少数来自左冠状动脉旋支。前室间支主要供应左心室前壁和室间隔前2/3，后室间支供应下壁，旋支供应左心房及左心室侧壁"},{"q":"关于鼓膜的描述，错误的是","o":["构成鼓室外侧壁的大部分","位于外耳道与鼓室之间，与外耳道底约成45°～50°的倾斜角","婴儿鼓膜更为倾斜，几乎呈水平位","鼓膜周缘较厚，附着在颞骨鼓部和鳞部","鼓膜中心部向内凹陷，称鼓膜脐，为砧骨柄末端附着处"],"a":4,"e":"鼓膜为椭圆形半透明薄膜，与外耳道底约成45°～50°角，周缘较厚附着于颞骨鼓部和鳞部，中心向内凹陷称鼓膜脐，是锤骨柄末端的附着处。婴儿鼓膜更倾斜，几乎呈水平位。将鼓膜脐归于砧骨柄，混淆了听小骨的连接关系，锤骨柄才是紧张于鼓膜内的结构"},{"q":"具有次级起搏作用的是心传导系的哪部分","o":["窦房结","结间束","房室结","房室束","左、右束支"],"a":2,"e":"房室结位于房间隔下部，自律性较低，正常时受窦房结超速驱动而不表现起搏功能，当窦房结冲动不能下传时方作为次级起搏点发放冲动，频率约每分钟40～60次。结间束为传导束，房室束及左、右束支只传导不产生节律，浦肯野纤维网亦无起搏作用"},{"q":"中耳鼓室位于","o":["颞骨岩部","颞骨鼓部","颞骨乳突","颞骨鳞部","枕骨体"],"a":0,"e":"鼓室为位于颞骨岩部内的不规则含气腔隙，介于鼓膜与内耳外侧壁之间，容积约1～2ml，向前经咽鼓管通鼻咽部。颞骨鼓部构成鼓室的外侧壁及骨性外耳道壁，乳突内为乳突小房，鳞部构成颅骨侧面的骨板。枕骨体位于颅后部，与鼓室无关"},{"q":"关于肛管的叙述，错误的是","o":["以齿状线区分内、外痔","白线是肛门内、外括约肌的分界线","肛窦易积存粪便","肛直肠线为肛柱下端的连线","在齿状线下方有一宽约1cm的环形区为肛梳"],"a":3,"e":"肛管上段黏膜的纵行皱襞称肛柱，肛柱上端的连线为肛直肠线，是直肠与肛管的分界；肛柱下端与肛瓣基部相连成齿状线，为黏膜与皮肤的分界，也是内、外痔的分界。白线位于齿状线下方约1cm，是肛门内、外括约肌的分界。肛窦开口向上，易积存粪便而诱发感染"},{"q":"关于肺动脉正确的说法是","o":["发自左心室","左肺动脉横过胸主动脉的后方","其末端与主动脉弓下缘之间有动脉韧带","是肺的营养性血管","将动脉血运至肺"],"a":2,"e":"肺动脉干起自右心室，在主动脉弓下缘分为左、右肺动脉，分叉处与主动脉弓下缘之间连有动脉韧带，为胚胎动脉导管闭锁后的遗迹。肺动脉运送静脉血至肺进行气体交换，属功能性血管，支气管动脉才是肺的营养血管。左肺动脉横过胸主动脉的前方"},{"q":"可使髋关节伸和旋外的肌是","o":["缝匠肌","股四头肌","大收肌","阔筋膜张肌","臀大肌"],"a":4,"e":"臀大肌起自髂骨翼外面和骶、尾骨背面，止于股骨臀肌粗隆和髂胫束，是髋关节最强大的伸肌，并使髋关节旋外，由臀下神经支配。阔筋膜张肌屈髋并内旋，缝匠肌屈髋屈膝，股四头肌屈髋伸膝，大收肌主要内收髋关节，均不以伸髋、旋外为主"},{"q":"关于乳房，错误的是","o":["乳腺癌晚期，局部皮肤可出现橘皮样改变","乳腺位于浅筋膜内","乳头位于第2肋","乳房的外侧可达腋中线","位于胸大肌前方"],"a":2,"e":"成年女性乳房位于胸大肌及其筋膜浅面，内侧至胸骨旁线，外侧达腋中线，上起第2～3肋，下至第6～7肋，乳头约平第4肋间隙。乳腺癌累及皮肤悬韧带可致局部皮肤凹陷，淋巴回流受阻则呈橘皮样变。将乳头定位于第2肋，与其正常体表位置不符"},{"q":"腹膜内位器官有","o":["肝","卵巢","子宫","胆囊","十二指肠降部"],"a":1,"e":"腹膜内位器官各面几乎全被腹膜包裹，活动度较大，如胃、空肠、回肠、盲肠、阑尾、横结肠、乙状结肠、脾、卵巢和输卵管。肝、胆囊、膀胱、子宫为腹膜间位器官，十二指肠降部等为腹膜外位器官。卵巢借卵巢系膜悬于阔韧带后层，属典型的内位器官"},{"q":"属于特殊内脏运动核的神经核","o":["动眼神经核","滑车神经核","面神经核","展神经核","舌下神经核"],"a":2,"e":"特殊内脏运动核支配由鳃弓衍化的骨骼肌，面神经核发出纤维支配面肌、颈阔肌、二腹肌后腹和镫骨肌，属此类。动眼神经核、滑车神经核、展神经核、舌下神经核支配眼球外肌和舌肌，属一般躯体运动核。疑核、三叉神经运动核和副神经核亦为特殊内脏运动核"},{"q":"属于结肠下区的间隙是","o":["左肝下后间隙","右肝下间隙","肝肾隐窝","左结肠旁沟","左肝下前间隙"],"a":3,"e":"结肠下区位于横结肠及其系膜以下，包括左、右结肠旁沟及左、右肠系膜窦，左结肠旁沟位于降结肠与左侧腹壁之间。肝肾隐窝、左肝下前间隙、左肝下后间隙和右肝下间隙均位于结肠上区，属膈下间隙的组成部分，与结肠下区不在同一平面"},{"q":"关于网状结构的叙述，错误的是","o":["网状结构存在于整个脑干内","网状结构内有很多核团","脊髓也有网状结构","与上行和下行传导束无联系","脑干网状结构内含有重要的生命中枢"],"a":3,"e":"脑干网状结构位于脑干中央部，介于各传导束与脑神经核之间，由散在的神经元和纵横交错的纤维构成，向上、向下均与传导束有广泛联系，并含心血管中枢、呼吸中枢等重要生命中枢。脊髓颈段以上的灰质与白质交界区亦具网状结构特征"},{"q":"神经系统的结构和功能基本单位是","o":["神经胶质","神经节","神经元","神经核","神经纤维"],"a":2,"e":"神经元是神经系统结构和功能的基本单位，能接受刺激、整合信息并传导冲动。神经胶质是支持、营养和形成髓鞘的细胞，数量多但不具传导功能；神经核为中枢内形态和功能相近的神经元胞体聚集；神经纤维是轴突及其鞘膜，神经节为周围部神经元胞体的聚集处"},{"q":"后纵隔出现包块，不可能发生的是","o":["胸腺瘤","支气管囊肿","神经瘤","主动脉瘤","膈疝"],"a":0,"e":"后纵隔位于心包后方与脊柱胸段之间，内有胸主动脉、食管、胸导管、奇静脉、半奇静脉、迷走神经、交感干及纵隔后淋巴结等，故主动脉瘤、神经源性肿瘤、支气管囊肿和膈疝均可发生于此。胸腺位于前纵隔，其肿瘤不会出现在后纵隔"},{"q":"棘突短而末端分叉的椎骨是","o":["寰椎","第2～6颈椎","隆椎","胸椎","腰椎"],"a":1,"e":"第2～6颈椎棘突短，末端分叉，是颈椎的特征之一。寰椎无棘突，仅有后结节；隆椎即第7颈椎，棘突长而不分叉；胸椎棘突细长，斜向后下呈叠瓦状；腰椎棘突呈板状，水平后伸。短小与末端分叉两项须同时具备，方为第2～6颈椎"},{"q":"间脑是","o":["仅次于端脑的中枢高级部","交感神经低级中枢","副交感神经低级中枢","位于脑桥与端脑之间","位于中脑与小脑之间"],"a":0,"e":"间脑位于中脑与端脑之间，体积不到中枢神经系统的2%，是仅次于端脑的中枢高级部位，包括背侧丘脑、后丘脑、上丘脑、底丘脑和下丘脑。交感神经低级中枢在胸腰段脊髓侧角，副交感者位于脑干副交感核和骶髓，均不属间脑"},{"q":"交感神经","o":["低级中枢位于脊髓胸1～腰3节段的中间外侧核","节前纤维经灰交通支终止于椎旁神经节","节后纤维仅分布于躯干、四肢的血管、汗腺和竖毛肌","不支配肾上腺","低级中枢位于脊髓胸1～腰3节段的中间内侧核"],"a":0,"e":"交感神经低级中枢位于脊髓T1～L3节段灰质的中间带外侧核，节前纤维经白交通支进入椎旁节或直接至椎前节换元，节后纤维经灰交通支返回脊神经，分布于血管、汗腺和竖毛肌，并随血管至内脏。肾上腺髓质直接接受节前纤维支配，无节后神经元"},{"q":"位于前列腺后方的结构是","o":["膀胱","直肠","精囊","输精管壶腹","尿道球腺"],"a":1,"e":"前列腺位于膀胱颈与尿生殖膈之间，前方为耻骨联合，后方紧邻直肠，故可经直肠指诊触及前列腺沟，以判断其大小和质地。精囊和输精管壶腹位于膀胱底后方、前列腺的后上方，尿道球腺位于尿生殖膈内，均不在前列腺的正后方"},{"q":"精子产生于","o":["生精小管","精囊","睾丸小隔","睾丸网","睾丸间质细胞"],"a":0,"e":"生精小管为睾丸内高度迂曲的管道，管壁生精上皮中的精原细胞经分裂、分化形成精子，管壁外的间质细胞分泌雄激素。睾丸小隔为结缔组织间隔，睾丸网收纳直精小管输送的精子，精囊只分泌精囊液，均不产生精子"},{"q":"不属于眼球屈光装置的结构是","o":["角膜","房水","晶状体","玻璃体","巩膜"],"a":4,"e":"眼球屈光装置包括角膜、房水、晶状体和玻璃体，四者与视网膜共同构成折光系统，使外界光线聚焦于视网膜。巩膜为致密结缔组织构成的纤维膜，维持眼球形态并保护内容物，屈光力极弱，不属屈光装置。角膜是屈光力最强的部分"},{"q":"关于肺的形态，描述正确的是","o":["右肺狭长","肺底平坦","后缘锐利","前缘有心压迹","肺底也叫膈面"],"a":4,"e":"肺呈半圆锥形，肺底凹向上贴于膈，故又称膈面；肺尖钝圆突入颈根部，前缘锐薄，左肺前缘有心切迹，后缘钝圆贴于脊柱。右肺因肝的推挤而宽短，左肺因心偏左而狭长。将前后缘的锐钝颠倒，或把右肺说成狭长，均与形态不符"},{"q":"关于泪器的叙述，错误的是","o":["泪器属于眼副器","泪道包括泪点、泪小管、泪囊和鼻泪管","泪腺位于眶上壁前外侧部的泪腺窝内","泪小管为连结泪点与泪囊的小管","由泪腺和泪小管组成"],"a":4,"e":"泪器由泪腺和泪道组成，泪道包括泪点、泪小管、泪囊和鼻泪管，泪液经此流入鼻腔。泪腺位于眶上壁前外侧的泪腺窝内，属眼副器。将泪器说成仅由泪腺和泪小管构成，既遗漏了泪囊和鼻泪管，也把泪道的局部当成了泪器的全部"},{"q":"关于腋神经的叙述，错误的是","o":["发自臂丛后束","穿经四边孔","支配三角肌和大圆肌","伴旋肱后动脉绕肱骨外科颈后行至肩胛区","受损后患者肩部失去圆隆外形"],"a":2,"e":"腋神经发自臂丛后束，伴旋肱后动脉穿四边孔，绕肱骨外科颈至三角肌深面，支配三角肌和小圆肌，并发出臂外侧上皮神经。大圆肌由肩胛下神经支配，背阔肌由胸背神经支配。损伤后三角肌萎缩，肩部失去圆隆外形呈方肩，外展受限"},{"q":"关于输卵管的正确描述是","o":["为一对长而直的肌性管道","与卵巢门相通连","末端开口于腹膜腔","内侧端膨大弯曲，连于子宫底两侧","输卵管峡部，长而狭窄"],"a":2,"e":"输卵管内侧端穿子宫壁开口于子宫腔，外侧端游离，其输卵管伞开口于腹膜腔，故女性腹膜腔经输卵管、子宫、阴道与外界相通。输卵管峡部短而狭窄，壶腹部才是长而弯曲膨大的部分。输卵管与卵巢门并无通连，排卵后卵子直接落入腹膜腔"},{"q":"下列何种结构受损可使对侧躯体感觉障碍","o":["丘脑前辐射","内囊膝","丘脑中央辐射","颞桥束","枕桥束"],"a":2,"e":"丘脑中央辐射即丘脑上辐射，由背侧丘脑腹后核发出的纤维经内囊后肢投射至中央后回，传导对侧躯干和四肢的深浅感觉，一侧受损即出现对侧躯体感觉障碍。内囊膝有皮质核束通过，损伤致对侧核下性面瘫、舌瘫；丘脑前辐射与颞桥束、枕桥束参与锥体外系联系"},{"q":"关于臂丛的叙述，错误的是","o":["胸长神经属于锁骨上分支","腋神经属于锁骨下分支","锁骨中点后方的臂丛结构较集中，为臂丛阻滞麻醉部位","第1胸神经前支加入臂丛","胸长神经发出分支支配胸大、小肌"],"a":4,"e":"胸长神经起自臂丛根，沿前锯肌表面下行并支配该肌，损伤后出现翼状肩，它不支配胸大、小肌，后二者由胸内、外侧神经支配。胸长神经属锁骨上分支，腋神经属锁骨下分支，第1胸神经前支参与组成臂丛下干。锁骨中点后方是臂丛阻滞的常用部位"},{"q":"下列结构不是由腹膜形成的是","o":["输卵管系膜","卵巢系膜","子宫主韧带","睾丸鞘膜","鞘韧带"],"a":2,"e":"子宫主韧带位于阔韧带下部，由结缔组织和平滑肌纤维构成，自子宫颈两侧连于盆侧壁，是防止子宫下垂的主要结构，不含腹膜成分。输卵管系膜、卵巢系膜均为阔韧带的一部分，睾丸鞘膜和鞘韧带由腹膜鞘突衍化而来，均属腹膜形成的结构"},{"q":"关于腋神经的叙述，正确的是","o":["发自臂丛内侧束","支配背阔肌","行程中有胸背动脉伴行","支配肱三头肌","损伤后影响肩关节的外展功能"],"a":4,"e":"腋神经发自臂丛后束，穿四边孔绕肱骨外科颈，支配三角肌和小圆肌，是肩关节外展的主要神经，损伤后外展障碍并出现方肩。背阔肌由胸背神经支配，肱三头肌由桡神经支配。与腋神经伴行的是旋肱后动脉，胸背动脉则伴胸背神经"},{"q":"输送尿液离开肾锥体的结构是","o":["乳头孔","肾盂","肾大盏","输尿管","肾髓质"],"a":0,"e":"肾锥体尖端合并成肾乳头，乳头孔位于肾乳头表面，终尿经乳头孔流入肾小盏，故乳头孔是尿液离开肾锥体的通道。肾盂由肾大盏汇合而成，属肾窦内的集尿结构；输尿管上接肾盂；肾髓质是肾锥体所在的部位，并非输出管道"},{"q":"右肺根内结构自上而下排列的顺序是","o":["肺静脉、肺动脉、支气管","肺静脉、支气管、肺动脉","肺动脉、支气管、肺静脉","肺动脉、肺静脉、支气管","支气管、肺动脉、肺静脉"],"a":4,"e":"右肺根内主支气管居上，肺动脉居中，肺静脉居下，自上而下为支气管、肺动脉、肺静脉。左肺根自上而下为肺动脉、主支气管、肺静脉。自前向后的排列左右一致，均为肺静脉、肺动脉、主支气管，故上下顺序的左右差异是常见设错点"},{"q":"咽鼓管鼓室口开口于鼓室的哪一个壁上","o":["前壁","后壁","上壁","下壁","内侧壁"],"a":0,"e":"咽鼓管骨部向后外方开口于鼓室前壁的咽鼓管鼓室口，软骨部向前内开口于鼻咽侧壁的咽鼓管咽口，平对下鼻甲后方。鼓室后壁有鼓室窦和锥隆起，上壁为盖壁，下壁为颈静脉壁，内侧壁为迷路壁并具前庭窗、蜗窗。开口于前壁是其通气功能的解剖基础"},{"q":"关于眼球外肌的错误描述是","o":["是受躯体运动神经支配的骨骼肌","各直肌共同起自总腱环","所有的直肌都受动眼神经支配","上睑提肌开大眼裂，由动眼神经支配","上直肌位于上睑提肌下方"],"a":2,"e":"眼球外肌均为骨骼肌，受躯体运动神经支配，除外直肌由展神经、上斜肌由滑车神经支配外，其余直肌及上睑提肌、下斜肌均由动眼神经支配。上直肌位于上睑提肌下方，各直肌共同起自总腱环。将全部直肌归于动眼神经，忽略了外直肌的展神经支配"},{"q":"关于贵要静脉的正确描述是","o":["起自手背静脉网桡侧","接受前臂正中静脉","注入肱静脉","收集前臂后面的静脉血","在臂部与头静脉交通"],"a":2,"e":"贵要静脉起自手背静脉网尺侧，沿前臂尺侧上行，在肘窝接受肘正中静脉，至臂中部穿深筋膜注入肱静脉。头静脉起自手背静脉网桡侧，沿前臂桡侧上行注入腋静脉或锁骨下静脉。前臂正中静脉注入肘正中静脉或头静脉，收集前臂前面的浅层静脉血"},{"q":"关于大脑小脑说法正确的是","o":["接受同侧大脑皮质的传入纤维，故称为大脑小脑","接受对侧脑桥核经小脑中脚的传入纤维","传出纤维主要止于脑干网状结构","传出纤维主要止于背侧丘脑前核群","传出纤维主要止于后丘脑"],"a":1,"e":"大脑小脑即新小脑，接受对侧脑桥核发出的纤维，经小脑中脚入小脑，协调随意运动。其传出纤维经齿状核至背侧丘脑腹外侧核，再投射至大脑皮质运动区，形成皮质-脑桥-小脑-皮质环路，故称大脑小脑。旧小脑才主要经顶核投射至脑干网状结构和前庭核"},{"q":"大脑中央前回的动脉血供主要来自","o":["大脑前动脉","前交通动脉","基底动脉","大脑后动脉","大脑中动脉"],"a":4,"e":"大脑中动脉的皮质支分布于大脑半球外侧面的大部分，包括中央前回、中央后回及额中回、额下回等，故中央前回的血供主要来自大脑中动脉。大脑前动脉供应额、顶叶内侧面及上缘，大脑后动脉供应枕叶及颞叶底面，前交通动脉只连接两侧大脑前动脉"},{"q":"下颌神经穿过的颅底孔裂是","o":["棘孔","卵圆孔","圆孔","破裂孔","茎乳孔"],"a":1,"e":"下颌神经为三叉神经第三支，属混合神经，经卵圆孔出颅至颞下窝。上颌神经穿圆孔，眼神经经眶上裂入眶，脑膜中动脉穿棘孔，面神经出茎乳孔。卵圆孔的位置与下颌神经的行程一致，损伤后可致咀嚼肌瘫痪及下颌牙、舌前2/3黏膜感觉障碍"},{"q":"不属于阴囊深层结构的是","o":["精索外筋膜","提睾肌","精索内筋膜","肉膜","睾丸鞘膜"],"a":3,"e":"阴囊由浅入深依次为皮肤、肉膜、精索外筋膜、提睾肌、精索内筋膜和睾丸鞘膜，肉膜属浅筋膜，含平滑肌纤维，可随温度舒缩以调节睾丸温度。精索外筋膜、提睾肌、精索内筋膜及睾丸鞘膜均属深层结构，故肉膜不在其列"},{"q":"关于股动脉的叙述，错误的是","o":["在腹股沟韧带中点的深面续于髂总动脉","其主要分支为股深动脉、腹壁浅动脉、旋髂浅动脉和阴部外动脉","其体表投影为：大腿外展外旋，自腹股沟韧带中点至收肌结节作一连线，此线的上2/3为股动脉","其压迫止血部位为：在腹股沟韧带中点处将股动脉压向耻骨上支","压迫该动脉其止血范围为下肢大部分"],"a":0,"e":"股动脉为髂外动脉的延续，在腹股沟韧带中点深面进入股三角，体表投影为大腿外展外旋时腹股沟韧带中点至收肌结节的连线，上2/3为股动脉。压迫止血点在腹股沟韧带中点处，将动脉压向耻骨上支。其与髂总动脉之间隔着髂外动脉，故不能说续于髂总动脉"},{"q":"主动脉弓的分支有","o":["右颈总动脉","右锁骨下动脉","冠状动脉","椎动脉","头臂干"],"a":4,"e":"主动脉弓凸侧自右向左发出头臂干、左颈总动脉和左锁骨下动脉，头臂干再分为右颈总动脉和右锁骨下动脉。右颈总动脉、右锁骨下动脉不是主动脉弓的直接分支，椎动脉发自锁骨下动脉，冠状动脉起自升主动脉根部。故弓的直接分支中仅头臂干列于选项"},{"q":"关于胰的叙述，错误的是","o":["是人体最大的消化腺","分为4部分","胰头被十二指肠包绕","钩突紧邻肠系膜上血管","副胰管开口于十二指肠小乳头"],"a":0,"e":"胰分头、颈、体、尾四部，胰头被十二指肠呈C形包绕，钩突向左下伸至肠系膜上血管后方，副胰管多开口于十二指肠小乳头。胰兼有外分泌和内分泌功能，但人体最大的消化腺是肝，肝还承担代谢、解毒和分泌胆汁等功能。该项表述与解剖学事实相反"},{"q":"一侧副神经损伤出现","o":["头不能向患侧侧屈","头不能向健侧侧屈","不能点头","不能伸舌","舌尖偏向健侧"],"a":0,"e":"副神经由颅根和脊髓根组成，脊髓根支配胸锁乳突肌和斜方肌。一侧损伤时胸锁乳突肌瘫痪，头不能向患侧侧屈，也不能使面部转向对侧，同时患侧肩胛骨下垂、耸肩无力。伸舌与舌尖偏斜为舌下神经损伤的表现，点头动作主要靠颈前肌群，与副神经无关"},{"q":"分布于下列何处的感受器为本体觉感受器","o":["血管","内耳基底膜","肌腱和关节","空腔性脏器壁内","皮肤和黏膜"],"a":2,"e":"本体觉感受器位于肌、肌腱、关节和骨膜内，感受肌肉张力、关节位置和运动状态，冲动经后索和内侧丘系上传。内耳基底膜的螺旋器属听觉感受器，皮肤与黏膜感受痛、温、触、压等浅感觉，空腔脏器壁内及血管壁的感受器属内脏感受器，均不属本体觉"},{"q":"小腿前群肌包括","o":["腓骨长肌","趾长伸肌","腓骨短肌","趾长屈肌","腓肠肌"],"a":1,"e":"小腿前群肌包括胫骨前肌、趾长伸肌、拇长伸肌和第三腓骨肌，作用为伸踝关节、伸趾和使足内翻。腓骨长肌、腓骨短肌属外侧群，使足外翻；趾长屈肌和腓肠肌属后群，屈趾、屈踝。前群位于骨间膜前面，由腓深神经支配，损伤后出现足下垂"},{"q":"属于舌下面的结构是","o":["界沟","舌盲孔","舌系带","舌扁桃体","菌状乳头"],"a":2,"e":"舌下面黏膜在正中线上形成舌系带，向下连于口腔底前部，其根部两侧为舌下阜，有下颌下腺管和舌下腺大管开口。界沟、舌盲孔位于舌根与舌体交界处，属舌背结构；舌扁桃体位于舌根背面；菌状乳头散布于舌体和舌尖上面，均不在舌下面"},{"q":"关于臂丛正确的是","o":["由5～8颈神经前支反复分支组合后形成臂丛","在腋窝内最后形成3个神经干","在腋窝内最后形成3个神经束夹持腋动脉","从后束发出正中神经","从外侧束发出桡神经"],"a":2,"e":"臂丛由C5～C8前支和T1前支的大部分组成，先合成上、中、下三干，再分为前、后股，最后在腋窝内形成外侧束、内侧束和后束，三束分别位于腋动脉的外侧、内侧和后方，共同夹持该动脉。正中神经由内、外侧根合成，桡神经发自后束"},{"q":"前庭蜗神经含有","o":["一般躯体感觉纤维","一般躯体运动纤维","一般内脏感觉纤维","一般内脏运动纤维","特殊躯体感觉纤维"],"a":4,"e":"前庭蜗神经由前庭神经和蜗神经组成，传导平衡觉和听觉冲动，二者均属特殊躯体感觉纤维，其感受器位于内耳膜迷路。该神经不含运动纤维，也不含内脏感觉或内脏运动纤维。一般躯体感觉纤维分布于皮肤和口鼻黏膜，由三叉神经等传导"},{"q":"上消化道不包括","o":["口腔","咽","空肠","胃","十二指肠"],"a":2,"e":"临床上以十二指肠末端为界，口腔、咽、食管、胃和十二指肠属上消化道，空肠及其以下至肛管为下消化道。空肠位于腹腔内，属小肠的中段，由肠系膜上动脉的分支供血，淋巴引流至肠系膜淋巴结，不属上消化道的范畴"},{"q":"包绕外侧沟后端的脑区","o":["颞上回","颞中回","额下回","缘上回","角回"],"a":3,"e":"顶下小叶位于顶内沟下方，分为包绕外侧沟后端的缘上回和围绕颞上沟末端的角回，二者同属Wernicke区，与语言理解有关。颞上回、颞中回位于颞叶外侧面，额下回后部为Broca区，与运动性语言有关。缘上回受损可致失用，角回受损可致失读"},{"q":"有关正中神经的构成，正确的是","o":["发自臂丛外侧束的分支","发自臂丛内侧束的分支","发自臂丛后束的分支","由外侧根与内侧根构成","是臂丛锁骨上分支"],"a":3,"e":"正中神经由发自臂丛外侧束的外侧根和发自内侧束的内侧根会合而成，两根夹持腋动脉，合成后沿肱二头肌内侧沟下行。桡神经发自后束，尺神经发自内侧束，肌皮神经发自外侧束。正中神经属锁骨下分支，不属锁骨上分支"},{"q":"属于间脑的结构是","o":["橄榄核","红核","黑质","苍白球","漏斗核"],"a":4,"e":"漏斗核位于下丘脑结节区，又称弓状核，其神经元分泌释放激素或抑制激素，经结节漏斗束至垂体门脉系统，调控腺垂体的内分泌功能。苍白球属端脑的旧纹状体，红核、黑质位于中脑，橄榄核位于延髓。上述核团均不属间脑，与漏斗核的归属不同"},{"q":"以下关于小脑的描述，正确的是","o":["位于颅中窝","上面隔小脑幕与大脑枕叶相邻","绒球属于新小脑","小脑扁桃体位于小脑半球的后方","借小脑下脚与脑桥联系"],"a":1,"e":"小脑位于颅后窝，上方借大脑横裂中的小脑幕与大脑枕叶相隔，下面为延髓和第四脑室。绒球属原小脑即前庭小脑，与平衡有关；小脑扁桃体位于半球下面前内侧，邻近枕骨大孔，颅内压增高时可形成小脑扁桃体疝。小脑下脚主要与延髓联系，中脚与脑桥相连"},{"q":"下列哪种结构不属于端脑的连合纤维","o":["胼胝体","前连合","额钳","穹窿连合","后连合"],"a":4,"e":"端脑的连合纤维包括胼胝体、前连合和穹窿连合，胼胝体前部的纤维称额钳，后部纤维称枕钳，均联系两侧半球相应的皮质区。后连合位于上丘脑，是联系中脑与间脑的纤维束，不属端脑连合纤维。投射纤维构成内囊，联络纤维联系同侧半球各叶"},{"q":"内侧丘系描述正确的是","o":["发自脊髓胸核","发自薄束核和楔束核","是交叉前的纤维","终于同侧上丘核","传导躯干四肢的温、痛觉"],"a":1,"e":"内侧丘系由对侧薄束核和楔束核发出的二级纤维经内侧丘系交叉后组成，向上终于背侧丘脑腹后外侧核，传导对侧躯干、四肢的意识性本体感觉和精细触觉。脊髓胸核发出的纤维组成脊髓小脑后束；该系纤维已经交叉；温、痛觉由脊髓丘脑系传导"},{"q":"小儿中耳炎的主要感染途径是","o":["咽鼓管","外耳道","鼓膜","鼓室","乳突窦"],"a":0,"e":"咽鼓管连通鼻咽部与鼓室，小儿咽鼓管短、宽而近水平位，咽部感染易经此侵入鼓室，是小儿中耳炎的主要感染途径。外耳道与中耳之间隔以鼓膜，其感染多由外部损伤引起；乳突窦与鼓室相通，是炎症蔓延的去路而非入口"},{"q":"大脑脚脚底外侧1/5通过","o":["皮质脊髓束","皮质核束","额桥束","顶、枕、颞桥束","内侧纵束"],"a":3,"e":"大脑脚底自内侧向外侧依次为额桥束（内侧1/5）、锥体束（中3/5）和顶枕颞桥束（外侧1/5），后者止于脑桥核，参与锥体外系环路。皮质核束位于锥体束内，行于中3/5；内侧纵束位于被盖背侧中线两旁，不进入脚底。故外侧1/5为顶、枕、颞桥束"},{"q":"与甲状腺上动脉伴行的神经是","o":["迷走神经","喉返神经","喉上神经喉内支","喉上神经喉外支","颈交感干"],"a":3,"e":"喉上神经外支伴甲状腺上动脉下行，支配环甲肌，甲状腺手术结扎甲状腺上动脉时应紧贴腺体，以免损伤该神经。喉上神经内支与喉上动脉伴行，穿甲状舌骨膜入喉；喉返神经与甲状腺下动脉关系密切；迷走神经、颈交感干均不与甲状腺上动脉伴行"},{"q":"关于孤束核的叙述，错误的是","o":["孤束核位于迷走神经背核的腹外侧","孤束核主要位于延髓内","孤束上部接受来自第Ⅶ、Ⅸ、Ⅹ对脑神经的纤维","孤束核仅接受一般内脏感觉信息","孤束下部接受来自第Ⅸ、Ⅹ对脑神经的纤维"],"a":3,"e":"孤束核位于延髓，居迷走神经背核的腹外侧，其上部为味觉核，接受Ⅶ、Ⅸ、Ⅹ对脑神经的特殊内脏感觉纤维，下部接受Ⅸ、Ⅹ对脑神经的一般内脏感觉纤维。故该核既接受一般内脏感觉，也接受味觉信息，说其仅接受一般内脏感觉与该核的分部功能不符"},{"q":"下列管道中，无明显狭窄者为","o":["食管","男性尿道","输尿管","输精管","输卵管"],"a":3,"e":"输精管为附睾管的直接延续，管径约0.3cm，管壁厚、肌层发达，全程管径较均匀，无明显的生理性狭窄。食管有3处狭窄，男性尿道有尿道内口、膜部和尿道外口3处狭窄，输尿管有3处狭窄，输卵管在间质部和峡部亦明显变细"},{"q":"屈第2～5掌指关节和伸第2～5指骨间关节的肌是","o":["拇收肌","拇短屈肌","蚓状肌","拇短展肌","小指伸肌"],"a":2,"e":"蚓状肌起自指深屈肌腱，经掌指关节桡侧止于指背腱膜，收缩时屈第2～5指掌指关节并伸其指骨间关节，由正中神经和尺神经双重支配。骨间肌作用相似并兼内收、外展；拇收肌、拇短屈肌、拇短展肌只作用于拇指，小指伸肌仅伸小指"},{"q":"桡骨的骨性标志包括","o":["桡骨茎突和桡骨粗隆","桡骨茎突和桡骨头","桡骨颈和桡骨头","桡骨粗隆和桡骨颈","桡骨茎突和尺切迹"],"a":1,"e":"桡骨下端外侧向下的突起为桡骨茎突，下端内面为尺切迹，与尺骨头相关节；上端的膨大为桡骨头，头下方的隆起为桡骨粗隆。桡骨茎突和桡骨头位置表浅，均可扪及，为常用的骨性标志。桡骨颈、桡骨粗隆位置较深，尺切迹位于关节面，均不能触及"},{"q":"下列属于氨基酸能通路的是","o":["胆碱能通路","去甲肾上腺素能通路","5-羟色胺能通路","谷氨酸能通路","多巴胺能通路"],"a":3,"e":"氨基酸能神经元以γ-氨基丁酸、谷氨酸、甘氨酸等为递质，谷氨酸是中枢主要的兴奋性递质，也是初级传入的主要递质。胆碱能通路以乙酰胆碱为递质；去甲肾上腺素、多巴胺属儿茶酚胺类，与5-羟色胺同属单胺类递质，上述三类均不属氨基酸能"},{"q":"眼的神经支配，正确的是","o":["动眼神经支配外直肌","滑车神经支配下斜肌","睫状肌由交感神经支配","瞳孔括约肌由副交感神经支配","眼球的痛温觉由视神经支配"],"a":3,"e":"瞳孔括约肌呈环形排列，受动眼神经副交感纤维支配，兴奋时瞳孔缩小；瞳孔开大肌由颈上神经节发出的交感纤维支配。外直肌由展神经支配，下斜肌由动眼神经支配，上斜肌才由滑车神经支配。眼球的痛温觉由眼神经传导，视神经只传导视觉"},{"q":"关于子宫位置的叙述，错误的是","o":["子宫下端位于坐骨棘平面以下","位于盆腔中央","位于膀胱与直肠之间","两侧有输卵管和卵巢","呈前倾前屈位"],"a":0,"e":"未妊娠子宫位于盆腔中央，介于膀胱与直肠之间，两侧有输卵管和卵巢，呈前倾前屈位，子宫颈下端在坐骨棘平面稍上方。子宫脱垂时宫颈口才低于坐骨棘平面，属病理状态。子宫底位于小骨盆入口平面以下，直立时伏于膀胱上面"},{"q":"仰视时，眼球收缩是","o":["两眼上直肌和下斜肌同时收缩","两眼下直肌和下斜肌同时收缩","两眼下直肌和上斜肌同时收缩","两眼上直肌和上斜肌同时收缩","两眼内直肌和下斜肌同时收缩"],"a":0,"e":"仰视时两眼上直肌和下斜肌同时收缩，上直肌使瞳孔转向上内，下斜肌转向上外，二者协同使视线上抬。俯视时下直肌与上斜肌同时收缩；侧视时同侧外直肌与对侧内直肌协同；聚视中线由两侧内直肌完成。上斜肌的作用为下外，不能参与仰视"},{"q":"可上提和后退下颌骨的肌是","o":["翼外肌","颞肌","翼内肌","咬肌","二腹肌"],"a":1,"e":"颞肌起自颞窝，肌束呈扇形汇聚止于下颌骨冠突，垂直纤维收缩上提下颌骨，后部纤维收缩使下颌骨后退，故兼具上提和后退作用。咬肌只上提并前伸下颌骨，翼外肌使下颌骨前伸和侧移，翼内肌上提，二腹肌前腹降下颌骨"},{"q":"声带麻痹是由于损伤了","o":["颈交感干","舌咽神经","副神经","喉返神经","喉上神经喉内支"],"a":3,"e":"喉返神经支配除环甲肌以外的全部喉内肌，包括声带肌和环杓后肌等，一侧损伤致声带麻痹、声音嘶哑，双侧损伤可致失音和呼吸困难。喉上神经外支损伤只引起环甲肌麻痹、音调降低；喉上神经内支为感觉支；颈交感干损伤出现Horner综合征"},{"q":"关于背侧丘脑的描述，正确的是","o":["分为前核群、内侧核群和外侧核群","内髓板由密集排列的细胞组成","外髓板紧邻内囊外侧","内髓板内的核团称为正中核","网状核紧邻第三脑室侧壁"],"a":0,"e":"背侧丘脑灰质内的内髓板呈Y字形，将丘脑分为前核群、内侧核群和外侧核群，外侧核群腹层内含腹后内侧核和腹后外侧核等特异性中继核。内髓板由白质纤维构成，其内散在的核团称板内核；外髓板分隔丘脑与网状核，网状核居丘脑外侧，邻近内囊"},{"q":"患者有足下垂和足背皮肤感觉缺失，损伤可能涉及","o":["腓深神经","胫神经","腓浅神经","股神经","闭孔神经"],"a":0,"e":"腓深神经支配小腿前群肌和足背肌，损伤后胫骨前肌、趾长伸肌瘫痪，不能伸踝伸趾，出现足下垂，并伴足背第1、2趾相对缘皮肤感觉障碍。胫神经损伤出现钩状足和足底感觉障碍；腓浅神经损伤只致足外翻无力、足背感觉减退，无足下垂；股神经、闭孔神经支配大腿"},{"q":"属于腹膜形成的结构是","o":["子宫阔韧带","子宫圆韧带","子宫主韧带","子宫骶韧带","卵巢固有韧带"],"a":0,"e":"子宫阔韧带是覆盖子宫前、后面的腹膜向两侧延伸形成的双层腹膜皱襞，上缘包裹输卵管，后层覆盖卵巢，属腹膜形成的结构。子宫圆韧带、子宫主韧带、子宫骶韧带均由结缔组织和平滑肌构成，表面仅部分被腹膜；卵巢固有韧带为索状结构，亦非腹膜形成"},{"q":"关于阑尾的描述正确的是","o":["附于结肠起始部","位于左髂窝内","根部是3条结肠带集中之处","属腹膜间位器官","一般长度在10cm以上"],"a":2,"e":"阑尾根部连于盲肠后内侧壁，3条结肠带均会聚于根部，术中沿独立带向下追踪是寻找阑尾的可靠方法，其根部体表投影为McBurney点。阑尾一般长6～8cm，属腹膜内位器官，多位于右髂窝，但位置变异大，可至盆腔、盲肠后或肝下"},{"q":"脊髓副交感神经低级中枢位于","o":["胸腰部的脊髓侧角中","全部骶节中的骶副交感核","骶2～4节中的骶副交感核","全部腰节中的中间外侧核","腰2～4节中的中间外侧核"],"a":2,"e":"副交感神经的低级中枢包括脑干的一般内脏运动核和脊髓骶部S2～S4节段的骶副交感核，后者发出节前纤维经盆内脏神经至盆丛。胸腰部侧角是交感神经的低级中枢，腰髓中间外侧核亦属交感，骶髓并无中间外侧核。全部骶节的说法超出S2～S4的范围"},{"q":"属于一般内脏运动柱的脑神经核","o":["动眼神经核","舌下神经核","面神经核","副神经核","迷走神经背核"],"a":4,"e":"一般内脏运动柱含动眼神经副核、上泌涎核、下泌涎核和迷走神经背核，发出副交感节前纤维。迷走神经背核位于延髓，支配胸腹腔脏器的平滑肌、心肌和腺体。动眼神经核、舌下神经核属一般躯体运动核，面神经核与副神经核属特殊内脏运动核"},{"q":"成对的脑颅骨是","o":["蝶骨","枕骨","筛骨","额骨","顶骨"],"a":4,"e":"脑颅由8块骨组成，其中成对的是顶骨和颞骨，不成对的是额骨、筛骨、蝶骨和枕骨。顶骨左右各一，位于颅盖中部，与额骨、枕骨及对侧顶骨以缝相连。蝶骨、筛骨、枕骨、额骨分别位于颅底或颅前部，各只一块，故不成对"},{"q":"迷走神经的纤维成分不包括","o":["副交感纤维","特殊内脏运动纤维","一般内脏感觉纤维","一般躯体感觉纤维","特殊内脏感觉纤维"],"a":4,"e":"迷走神经含4种纤维成分：一般内脏运动即副交感纤维、一般内脏感觉纤维、一般躯体感觉纤维和特殊内脏运动纤维，分别起自迷走神经背核、孤束核、三叉神经脊束核和疑核。特殊内脏感觉纤维分布于味蕾和嗅器，只见于面神经、舌咽神经等，迷走神经不含此成分"},{"q":"关于腭的叙述，错误的是","o":["腭是固有口腔的顶","软腭称为腭帆","腭垂是腭帆后缘中部向下的突起","腭舌弓延至舌根","腭咽弓延至咽侧壁"],"a":1,"e":"硬腭构成固有口腔顶的前2/3，软腭位于后1/3，其后份斜向后下才称腭帆，故不能把整个软腭等同于腭帆。腭帆后缘中部向下的突起为腭垂，两侧前方为腭舌弓、后方为腭咽弓，二者分别延至舌根外侧和咽侧壁"},{"q":"关于纵隔，正确的叙述是","o":["两侧界为纵隔胸膜","容纳心和肺","后界为胸主动脉和食管","位于胸膜腔内","下界为壁腹膜"],"a":0,"e":"纵隔是两侧纵隔胸膜之间全部器官、结构和结缔组织的总称，前界为胸骨，后界为脊柱胸段，上界为胸廓上口，下界为膈，整体稍偏左，呈矢状位。心位于中纵隔，肺位于纵隔两侧的胸膜腔内，不属纵隔内容；胸膜腔是胸膜围成的潜在间隙，纵隔位于两侧纵隔胸膜之间而非腔内"},{"q":"男性的生殖腺是","o":["前列腺","精囊","睾丸","尿道球腺","附睾"],"a":2,"e":"睾丸为男性生殖腺，位于阴囊内，产生精子并分泌雄激素，雄激素由生精小管之间的间质细胞产生。前列腺、精囊和尿道球腺为附属腺，只分泌精液的组成成分；附睾为输精管道，兼有储存精子和促进精子成熟的功能，均非生殖腺"},{"q":"对于静脉特点的正确描述是","o":["数量比动脉少","管壁粗","弹性大","大部分有静脉瓣","吻合较少"],"a":3,"e":"与同级动脉相比，静脉数量多、管径粗、管壁薄、弹性小、容量大，吻合丰富，四肢等受重力影响部位的静脉内大多有静脉瓣，可防止血液逆流。动脉弹性大、吻合较少。将管壁薄说成管壁粗、弹性小说成弹性大，均与静脉的结构特点相反"},{"q":"关于内侧丘系正确的是","o":["纤维来自同侧的薄束核和楔束核","终止于背侧丘脑腹后内侧核","位于锥体束的腹侧","在中脑位于红核的内侧","传导对侧躯干、四肢意识性本体感觉和精细触觉"],"a":4,"e":"内侧丘系由对侧薄束核、楔束核发出的纤维交叉后组成，传导对侧躯干和四肢的意识性本体感觉及精细触觉，终于丘脑腹后外侧核。该系在延髓位于锥体背侧，在脑桥行于斜方体，在中脑位于红核外侧。腹后内侧核接受三叉丘系，与头面部感觉有关"},{"q":"属于一般内脏运动核的是","o":["孤束核","迷走神经背核","疑核","面神经核","副神经核"],"a":1,"e":"一般内脏运动核包括动眼神经副核、上泌涎核、下泌涎核和迷走神经背核，发出副交感纤维支配平滑肌、心肌和腺体。迷走神经背核位于延髓第四脑室底，控制胸腹腔脏器的活动。孤束核为内脏感觉核，疑核、面神经核、副神经核均属特殊内脏运动核"},{"q":"在十二指肠镜检查中，内镜插入大约多长才能到达食管的第2处狭窄","o":["15cm","20cm","25cm","30cm","40cm"],"a":2,"e":"食管第2狭窄位于左主支气管后方与其交叉处，平第4、5胸椎，距中切牙约25cm，是食管癌和异物滞留的好发部位。第1狭窄在食管起始处，距中切牙15cm；第3狭窄在食管裂孔处，距中切牙40cm。20cm、30cm均不对应任何生理性狭窄"},{"q":"根据神经元的功能和传导方向将神经元分为","o":["假单极神经元、双极神经元和多极神经元","感觉神经元、运动神经元和联络神经元","胆碱能神经元、单胺能神经元和肽能神经元","假单极神经元、双极神经元和中间神经元","传入神经元、传出神经元和运动神经元"],"a":1,"e":"按功能和传导方向，神经元分为感觉（传入）神经元、运动（传出）神经元和联络（中间）神经元，分别负责传入、传出和中枢内的联系。按突起数目分为假单极、双极和多极神经元，按递质分为胆碱能、单胺能、肽能等。把前两类混为一谈即出现重复归类的错误"},{"q":"关于脊柱的形态结构描述，正确的是","o":["共由24块椎骨连结而成","椎间盘的厚度约占脊柱全长的1/2","有颈、胸、腰、骶四个生理弯曲","由于胸部椎间盘较薄，故该处运动幅度较大","仅能作少量的屈、伸运动"],"a":2,"e":"成人脊柱由24块椎骨、1块骶骨和1块尾骨借椎间盘、韧带和关节连结而成，侧面观有颈、胸、腰、骶4个生理性弯曲，颈曲、腰曲凸向前，胸曲、骶曲凸向后。椎间盘的总厚度约占脊柱全长的1/4，胸部椎间盘较薄故活动度小，脊柱可作屈伸、侧屈、旋转和环转运动"},{"q":"锥体外系传导通路不包括","o":["皮质—新纹状体—背侧丘脑—皮质环路","新纹状体—黑质环路","苍白球—底丘脑环路","皮质—脑桥—小脑—皮质环路","皮质—脊髓环路"],"a":4,"e":"锥体外系主要包括皮质-新纹状体-背侧丘脑-皮质环路、新纹状体-黑质环路、苍白球-底丘脑环路和皮质-脑桥-小脑-皮质环路，起调节肌张力、协调随意运动的作用。皮质-脊髓环路即锥体束，属锥体系，是发起随意运动的直接通路，不属锥体外系"},{"q":"棘突特别长，末端不分叉，活体易于摸到，为记数椎骨序数的标志的椎骨是","o":["第1颈椎","第2颈椎","第7颈椎","胸椎","腰椎"],"a":2,"e":"第7颈椎棘突特别长，末端不分叉，低头时在颈后正中隆起明显，故称隆椎，是计数椎骨序数的标志。寰椎无棘突，枢椎棘突短而粗大，胸椎棘突细长但斜向后下呈叠瓦状，腰椎棘突呈板状，其长度和形态均不宜作为计数标志"},{"q":"关于咽鼓管的叙述，错误的是","o":["咽鼓管连通鼻咽部与鼓室","咽鼓管使鼓室的气压与外界的大气压相等，以保持鼓膜内、外侧的压力平衡","咽鼓管骨部向后外开口于咽鼓管鼓室口","咽鼓管软骨部向前内开口于咽鼓管咽口，平时处于开放状态","小儿咽鼓管短而宽，接近水平位，故咽部感染可经咽鼓管侵入鼓室"],"a":3,"e":"咽鼓管骨部向外后开口于鼓室前壁，软骨部向前内开口于鼻咽侧壁的咽鼓管咽口，咽口平时闭合，吞咽或打哈欠时张开，以平衡鼓膜两侧的气压。小儿咽鼓管短、宽而近水平位，咽部感染易经此入鼓室。将咽口说成平时开放，与通气调节的生理状态相反"},{"q":"中脑内的副交感神经核","o":["动眼神经核","动眼神经副核","上泌涎核","下泌涎核","迷走神经背核"],"a":1,"e":"动眼神经副核又称E-W核，位于中脑上丘平面，发出副交感节前纤维随动眼神经至睫状神经节换元，节后纤维支配瞳孔括约肌和睫状肌。动眼神经核为躯体运动核，上泌涎核在脑桥，下泌涎核和迷走神经背核在延髓，三者均不在中脑"},{"q":"鱼际肌不包括","o":["拇短伸肌","拇短屈肌","拇短展肌","拇收肌","拇对掌肌"],"a":0,"e":"鱼际肌包括拇短展肌、拇短屈肌、拇对掌肌和拇收肌，分别使拇指外展、屈曲、对掌和内收，除拇收肌由尺神经支配外，其余由正中神经支配。拇短伸肌属前臂后群深层肌，位于手背侧，止于拇指近节指骨底，不属鱼际肌"},{"q":"肾乳头突入的结构是","o":["肾锥体","肾柱","肾皮质","肾窦","肾小盏"],"a":4,"e":"肾锥体尖端合并成肾乳头，突入肾小盏，乳头孔排出的终尿先入肾小盏，再经肾大盏、肾盂和输尿管入膀胱。肾柱是伸入锥体之间的皮质，肾皮质位于实质浅层，肾窦为肾门内的腔隙，容纳肾盏、肾盂及脂肪、血管，均不直接承接乳头"},{"q":"关于眼球外肌作用的叙述，错误的是","o":["眼球外肌都是骨骼肌","上直肌可使瞳孔转向上内侧","外直肌可使瞳孔转向内侧","上斜肌可使瞳孔转向下外侧","上、下斜肌都可使瞳孔转向外侧"],"a":2,"e":"外直肌起自总腱环，止于眼球外侧赤道前方，收缩使瞳孔转向外侧，故说其转向内侧是错误的。上直肌转向上内，上斜肌转向下外，下斜肌转向上外，上、下斜肌均含外转成分。眼球外肌均为骨骼肌，分别由动眼、滑车、展神经支配"},{"q":"关于大、小隐静脉的正确描述是","o":["小隐静脉在足内侧缘起自足背静脉弓","大隐静脉接受腹壁下静脉","小隐静脉注入股静脉","大隐静脉含有较少的瓣膜","小隐静脉经外踝后方上行"],"a":4,"e":"小隐静脉在足外侧缘起自足背静脉弓，经外踝后方沿小腿后面上行，穿深筋膜注入腘静脉。A项实为内外侧颠倒，足内侧缘起自足背静脉弓的是大隐静脉；C项小隐静脉注入腘静脉，注入股静脉的才是大隐静脉；D项大隐静脉为全身最长的静脉，瓣膜并不少"},{"q":"肾蒂各结构的排列，从前向后依次是","o":["肾静脉、肾动脉、肾盂","肾静脉、肾盂、肾动脉","肾盂、肾静脉、肾动脉","肾盂、肾动脉、肾静脉","肾动脉、肾静脉、肾盂"],"a":0,"e":"肾蒂内自前向后依次为肾静脉、肾动脉和肾盂末端，因下腔静脉靠近右肾，右肾蒂较左肾蒂短。B、C、D三项把肾盂置于肾静脉之前，实为颠倒；自上而下才是肾动脉、肾静脉、肾盂，两个方位常被互换设错"},{"q":"脑桥内与迷走神经背核属于同一功能柱的核团","o":["上泌涎核","脑桥核","展神经核","面神经核","三叉神经脑桥核"],"a":0,"e":"一般内脏运动柱共4对，即动眼神经副核、上泌涎核、下泌涎核和迷走神经背核，脑桥内属此柱的正是上泌涎核。展神经核属一般躯体运动柱；面神经核属特殊内脏运动柱；三叉神经脑桥核属一般躯体感觉柱；脑桥核为基底部中继核，不属脑神经核"},{"q":"关于结膜的描述，正确的是","o":["睑结膜与睑板结合疏松，易于分离","球结膜覆盖在巩膜和角膜前面","睑结膜和球结膜相互移行构成结膜囊","结膜囊为密闭的囊腔","结膜穹窿分为结膜上穹和结膜下穹"],"a":4,"e":"结膜穹窿是睑结膜与球结膜的移行处，分为结膜上穹和结膜下穹，上穹较下穹深。A项睑结膜与睑板结合紧密，不易分离；B项球结膜只覆盖眼球前面，角膜表面由角膜上皮覆盖，并无结膜；D项结膜囊经睑裂与外界相通，并非密闭"},{"q":"关于胸膜腔的描述，正确的是","o":["由肋胸膜和脏胸膜围成","由壁胸膜相互返折形成","不与外界相通","左、右两侧经气管相通","内有左、右肺"],"a":2,"e":"胸膜腔是脏、壁胸膜在肺根处相互移行围成的封闭潜在腔隙，只含少量浆液，与外界不通。A项肋胸膜与脏胸膜并不直接围成胸膜腔；B项壁胸膜各部相互返折处形成的是胸膜隐窝；E项胸膜腔内不含肺，肺位于胸膜腔之外"},{"q":"不位于肝脏脏面的结构是","o":["肝圆韧带","静脉韧带","镰状韧带","肝门","胆囊窝"],"a":2,"e":"镰状韧带是腹前壁上部和膈下面连于肝上面的双层腹膜，位于肝膈面，故不属脏面结构。A项肝圆韧带位于脏面左纵沟前部；B项静脉韧带位于静脉韧带裂内；D项肝门为脏面横沟；E项胆囊窝位于脏面右纵沟前部，均属脏面"},{"q":"前锯肌收缩时","o":["可内收肩关节","使肩胛骨向前和紧贴胸廓","使肩关节前屈","使肩关节后伸","使肩胛骨下角旋内"],"a":1,"e":"前锯肌起自上位8～9个肋骨外面，止于肩胛骨内侧缘和下角，收缩时拉肩胛骨向前并紧贴胸廓，下部肌束使下角旋外以助臂上举。A项内收肩关节由胸大肌、背阔肌完成；E项下角旋外而非旋内；C、D项肩关节屈伸由三角肌、胸大肌等完成，与前锯肌无关"},{"q":"下列说法正确的是","o":["屏状核与岛叶皮质之间的白质称最外囊","屏状核与岛叶皮质之间的白质称外囊","大脑内的弓状纤维主要联系同侧半球各叶","皮质核束经内囊后肢下行","下纵束和扣带属于连合纤维"],"a":0,"e":"屏状核位于岛叶皮质与豆状核之间，其与岛叶皮质间的白质为最外囊。B项外囊位于屏状核与豆状核之间；C项弓状纤维联系同侧相邻脑回，并非只限同侧各叶；D项皮质核束经内囊膝部下行；E项下纵束、扣带属联络纤维，连合纤维为胼胝体、前连合等"},{"q":"男性输精管道不包括下列哪个结构","o":["男性尿道","射精管","输精管","附睾","睾丸"],"a":4,"e":"男性输精管道由附睾、输精管、射精管和男性尿道组成，睾丸是生殖腺，产生精子并分泌雄激素，不属于排出管道。A项男性尿道兼有排精功能，属输精管道；B、C项射精管、输精管为管道主体；D项附睾为管道起始段，兼具贮存精子作用"},{"q":"正确描述阴道的是","o":["位于尿道的前方","穿过盆膈","上端包绕子宫颈的全部","上端直接通子宫腔","阴道口开口于阴道前庭"],"a":4,"e":"阴道下部较窄，以阴道口开口于阴道前庭，前庭大腺导管亦开口于此。A项阴道位于尿道后方；B项阴道穿过的是尿生殖膈而非盆膈；C项阴道上端只包绕子宫颈阴道部，并非全部；D项阴道上端续于子宫颈管，经子宫口才通子宫腔"},{"q":"可足背屈和足内翻的肌是","o":["比目鱼肌","胫骨前肌","胫骨后肌","腓骨长肌","腓肠肌"],"a":1,"e":"胫骨前肌起自胫骨上端外侧面，止于内侧楔骨和第1跖骨底，收缩时伸踝关节即使足背屈，并使足内翻。C项胫骨后肌使足内翻但兼跖屈；D项腓骨长肌使足外翻并跖屈；A、E项比目鱼肌、腓肠肌只使踝跖屈，不参与足内翻"},{"q":"肱骨的下端的形态结构不包括","o":["外侧部半球形的肱骨小头","内侧部滑车状的肱骨滑车","滑车前面上方有鹰嘴窝","滑车内侧突起为内上髁","内上髁后面的浅沟称尺神经沟"],"a":2,"e":"鹰嘴窝位于滑车后上方，伸肘时容纳尺骨鹰嘴，而非滑车前面上方。A项肱骨小头居外侧部前面，与桡骨相关节；B项肱骨滑车居内侧部，与尺骨相关节；C项滑车前上方为冠突窝，小头前上方为桡窝，两窝位置常被混说"},{"q":"神经元的基本结构是","o":["胞体和突起","周围突和中枢突","胞体和轴突","胞体和神经","突触"],"a":0,"e":"每个神经元在形态上都可分为胞体和突起两部分，突起又分树突与轴突，这是神经元的基本结构。B项周围突、中枢突是假单极神经元突起的分段名称；C项只提胞体与轴突，遗漏树突；D项神经是神经纤维集合成的结构，不是神经元本身的组成"},{"q":"髋骨的重要体表标志不包括","o":["髂嵴","髂前上棘","耻骨结节","坐骨结节","坐骨棘"],"a":4,"e":"坐骨棘位于坐骨体后缘、伸向盆腔，位置深在，不能经体表扪到，故不属体表标志。A项髂嵴、B项髂前上棘、C项耻骨结节、D项坐骨结节均可清楚扪及，是常用的定位与穿刺标志；坐骨棘只作为骶棘韧带附着处及会阴麻醉的深部定位标志"},{"q":"关于前列腺的位置和毗邻，描述正确的是","o":["底位于尿生殖膈上面","尖邻接膀胱颈","后方邻盆膈","后上方有输精管壶腹和精囊","前方邻直肠"],"a":3,"e":"前列腺底朝上邻膀胱颈，尖朝下邻尿生殖膈，后方隔直肠膀胱隔与直肠相邻，后上方有输精管壶腹和精囊。A、B两项把底与尖的毗邻颠倒；C项后方邻接的是直肠而非盆膈；E项前方为耻骨联合，直肠在后方"},{"q":"关于神经纤维的正确描述是","o":["是神经元的轴突","是树突包被髓鞘而成","仅存在于周围神经系统","有髓纤维比无纤维的传导速度快","神经纤维的直径与传导速度快慢无关"],"a":3,"e":"神经纤维由轴突及包被其外的髓鞘、神经膜构成，有髓纤维呈跳跃式传导，速度明显快于无髓纤维；传导速度还与纤维直径成正比，越粗越快。B项树突一般不形成神经纤维；C项中枢内同样存在神经纤维；E项直径与速度密切相关"},{"q":"对动眼神经的描述，正确的是","o":["由动眼神经核发出的纤维组成","由大脑脚内侧出脑","和视神经一起经视神经孔入眶","与瞳孔光反射无关","分支至角膜"],"a":1,"e":"动眼神经根连于脚间窝下部、大脑脚内侧，由一般躯体运动纤维和起自动眼神经副核的副交感纤维组成。C项动眼神经经眶上裂入眶，经视神经管的是视神经；D项副交感纤维经睫状神经节参与瞳孔对光反射；E项角膜由眼神经分支支配"},{"q":"蛛网膜粒突入","o":["上矢状窦","下矢状窦","直窦","窦汇","乙状窦"],"a":0,"e":"脑蛛网膜在上矢状窦处形成绒毛状突起突入窦内，即蛛网膜粒，脑脊液经此渗入上矢状窦。B项下矢状窦位于大脑镰下缘，向后汇入直窦；C项直窦由大脑大静脉与下矢状窦汇成，向后通窦汇；E项乙状窦续于颈内静脉，均无蛛网膜粒突入"},{"q":"关于眼的神经分布的叙述，错误的是","o":["视觉由眼神经传导","眼的一般感觉由三叉神经传导","瞳孔开大肌由交感神经支配","瞳孔括约肌和睫状肌由动眼神经支配","眼球外肌的运动由动眼、滑车和展神经支配"],"a":0,"e":"视觉由视神经传导，视神经属特殊躯体感觉纤维；眼神经是三叉神经第一支，只司眼球、泪腺等的一般感觉。C项瞳孔开大肌由交感神经支配；D项瞳孔括约肌与睫状肌由动眼神经副交感纤维经睫状神经节支配；E项眼球外肌由动眼、滑车、展神经支配"},{"q":"瘫痪时可产生“塌肩”现象的肌是","o":["大圆肌","斜方肌","背阔肌","三角肌","前锯肌"],"a":1,"e":"斜方肌以腱膜起自枕外隆凸、项韧带及全部胸椎棘突，止于锁骨外侧1/3、肩峰和肩胛冈，瘫痪后肩胛骨下角外移、肩胛冈下移，出现塌肩。E项前锯肌瘫痪表现为翼状肩；D项三角肌瘫痪呈方肩；A、C项大圆肌、背阔肌参与肩关节内收后伸"},{"q":"心包横窦位于","o":["心包腔前下部","升主动脉与肺动脉后方","下腔静脉和心包后壁之间","上腔静脉和右肺血管之间","主动脉和左心房后壁之间"],"a":1,"e":"心包横窦是心包腔在升主动脉、肺动脉后方与上腔静脉、左心房前壁之间的间隙，可容手指通过。C、E项描述的是心包斜窦，位于左心房后壁与心包后壁之间；A项心包腔前下部为心包前下窦，与横窦位置不同"},{"q":"关于桡神经的叙述，错误的是","o":["从臂丛后束发出","在臂后区发出分支支配肱三头肌","肱骨中段骨折易导致该神经的损伤","桡神经深支又称为骨间后神经","与前臂前群肌的支配无关"],"a":4,"e":"桡神经深支穿旋后肌后改称骨间后神经，支配前臂后群伸肌；但前臂前群第一层的肱桡肌由桡神经支配，故说与前臂前群无关不成立。A项桡神经发自臂丛后束；B项在臂后区发支支配肱三头肌；C项肱骨中段桡神经沟处骨折易致垂腕"},{"q":"支配瞳孔括约肌的神经的节后纤维发自","o":["动眼神经副核","翼腭神经节","下神经节","睫状神经节","颈交感干神经节"],"a":3,"e":"动眼神经副核发出副交感节前纤维加入动眼神经，入眶后止于睫状神经节换元，节后纤维经睫状短神经入眼球支配瞳孔括约肌和睫状肌。A项为节前纤维的起点；B项翼腭神经节支配泪腺；D项下颌下神经节支配舌下腺、下颌下腺；E项颈上神经节支配瞳孔开大肌"},{"q":"男性膀胱后面毗邻的结构中不包括","o":["精囊","输精管壶腹","输尿管盆部","前列腺","直肠前壁"],"a":3,"e":"男性膀胱底的后方与精囊、输精管壶腹和直肠前壁相邻，输尿管盆部经膀胱后外侧下行，均属后方毗邻；前列腺位于膀胱颈下方，是膀胱的下方毗邻而非后方。C项输尿管盆部紧贴膀胱后壁外上角，常被误认为前方结构"},{"q":"上腔静脉在注入右心房之前接受的静脉是","o":["奇静脉","半奇静脉","副半奇静脉","颈内静脉","锁骨下静脉"],"a":0,"e":"奇静脉在右膈脚处起自右腰升静脉，沿胸主动脉右侧上行，至第4胸椎高度勾绕右肺根上方注入上腔静脉，是上腔静脉注入右心房前接受的唯一成对大静脉。B、C项半奇静脉与副半奇静脉均先注入奇静脉；D、E项颈内静脉与锁骨下静脉汇合成头臂静脉，不直接注入上腔静脉"},{"q":"有关内淋巴的描述，不正确的是","o":["位于膜迷路内","来自蜗管外侧壁","经内淋巴囊回流入血液循环","和外淋巴在蜗孔处相交通","可以传递声波"],"a":3,"e":"内淋巴位于膜迷路内，由蜗管外侧壁血管纹产生，经内淋巴管至内淋巴囊回流入血，其波动刺激基底膜螺旋器而传递声波。D项错误：蜗孔连通的是前庭阶与鼓阶，两阶内均为外淋巴；膜迷路为封闭管道，内、外淋巴互不相通"},{"q":"下列结构中，何者与精子的排出无关","o":["附睾","输精管","射精管","膀胱","尿道"],"a":3,"e":"精子经附睾、输精管、射精管和尿道排出，膀胱只储存尿液，与排精通路无关。A项附睾为精子成熟与贮存的管道；B、C项输精管、射精管是排精的主要通道；E项尿道兼排尿与排精，前列腺部接受射精管开口"},{"q":"连于胃小弯的韧带是","o":["脾胃韧带","胃膈韧带","胃结肠韧带","脾肾韧带","肝胃韧带"],"a":4,"e":"小网膜由肝门连于胃小弯和十二指肠上部，连于胃小弯的部分即肝胃韧带，内含胃左、右血管。A项胃脾韧带连胃底与脾门；C项胃结肠韧带连胃大弯与横结肠；D项脾肾韧带连脾门与左肾前面，均不与胃小弯相连"},{"q":"侧脑室，正确的选项是","o":["位于左、右侧大脑半球之间","侧脑室中央部位于室间孔和胼胝体压部之间","侧脑室经室间孔与第四脑室相通","后角伸入颞叶","前角伸向顶叶"],"a":1,"e":"侧脑室分四部，中央部位于顶叶内，界于室间孔与胼胝体压部之间。A项侧脑室左、右各一，位于大脑半球内而非两半球之间；C项经室间孔相通的是第三脑室，第四脑室经中脑水管相通；D项后角伸入枕叶，E项前角伸向额叶"},{"q":"下列结构中不属于男性内生殖器的是","o":["前列腺","男性尿道","睾丸","阴茎","尿道球腺"],"a":3,"e":"男性内生殖器由生殖腺睾丸、生殖管道（附睾、输精管、射精管、男性尿道）和附属腺（精囊、前列腺、尿道球腺）组成，阴茎属外生殖器。B项男性尿道属生殖管道；D项阴茎与阴囊同为外生殖器；E项尿道球腺为附属腺"},{"q":"关于室间隔正确的描述是","o":["呈垂直位","大部分缺乏肌质","缺损多发生于膜部","主要由结缔组织构成","前、后缘的表面标志部明显"],"a":2,"e":"室间隔膜部菲薄，缺乏肌质，是室间隔缺损最常见的部位。A项室间隔呈斜位而非垂直位；C项膜部虽由结缔组织构成，但室间隔大部分为肌部；D项整个室间隔并非以结缔组织为主；E项前、后室间沟即为室间隔在表面的标志，十分明显"},{"q":"有关鼓膜的描述，正确的是","o":["构成鼓室外侧壁的大部分","位于内耳道与鼓室之间","婴儿鼓膜更为倾斜，近似呈垂直位","鼓膜边缘较薄，附着于颞骨鼓部和鳞部","鼓膜中心向内凹陷，称为鼓膜脐，内侧面为镫骨附着处"],"a":0,"e":"鼓室外侧壁大部分由鼓膜构成，故又称鼓膜壁。B项鼓膜位于外耳道与鼓室之间，内耳道通向内耳；C项小儿鼓膜更为倾斜，几乎呈水平位；D项鼓膜边缘大部分附着于颞骨，附着部较厚；E项鼓膜脐是锤骨柄末端附着处，而非镫骨"},{"q":"分泌雄性激素的器官是","o":["胸腺","睾丸","垂体","甲状腺","甲状旁腺"],"a":1,"e":"睾丸生精小管之间的间质细胞分泌雄激素，故睾丸兼具产生精子与内分泌功能。A项胸腺为淋巴器官，分泌胸腺激素；C项垂体分泌促性腺激素等，调节而非直接产生雄激素；D项甲状腺分泌甲状腺激素；E项甲状旁腺分泌甲状旁腺激素"},{"q":"界嵴分隔","o":["心房与心室","左心房与右心房","右心室的流入道与流出道","主动脉前庭与左心室","腔静脉窦与固有心房"],"a":4,"e":"右心房腔面与界沟对应处的纵行肌隆起为界嵴，其分隔前部的固有心房与后部的腔静脉窦。C项分隔右心室流入道与流出道的是室上嵴；D项主动脉前庭属左心室流出道；A、B项界嵴并不分隔心房与心室或左右心房，房间隔分隔左右心房"},{"q":"颞下颌关节的特征不包括","o":["有关节盘","关节面覆盖透明软骨","囊外有外侧韧带加强","关节腔分上、下两部分","易向前脱位"],"a":1,"e":"颞下颌关节的关节面覆盖纤维软骨而非透明软骨，这是其区别于多数滑膜关节的特点。A项关节腔内有椭圆形纤维软骨关节盘，分为上、下两层；C项囊外有外侧韧带加强；E项关节囊前部松弛，故易向前脱位"},{"q":"属于椎旁神经节的是","o":["腹腔神经节","主动脉肾神经节","肠系膜上神经节","肠系膜下神经节","骶神经节"],"a":4,"e":"骶交感干位于骶骨前面、骶前孔内侧，由2～3对骶神经节和1个奇神经节构成，骶神经节属椎旁神经节。A、B、C、D项腹腔神经节、主动脉肾神经节、肠系膜上及下神经节均位于脊柱前方，属椎前神经节"},{"q":"左室前壁及室间隔前部心肌梗死，可能累及的血管是","o":["左冠状动脉主干","前室间支","旋支","后室间支","右冠状动脉主干"],"a":1,"e":"前室间支沿前室间沟下行，分布于左心室前壁、前乳头肌、心尖、室间隔前2/3及右室前壁一小部分，其阻塞即致该区梗死。C项旋支分布于左室侧壁与后壁；D项后室间支供应室间隔后1/3；E项右冠状动脉主干供应右心室，均与左室前壁不符"},{"q":"腹内斜肌腱膜形成的结构不正确的是","o":["腹股沟镰","弓状线","腹白线","腹直肌鞘","精索内筋膜"],"a":4,"e":"精索内筋膜是腹横筋膜的延续，与腹内斜肌腱膜无关。A项腹股沟镰由腹内斜肌与腹横肌腱膜联合构成；B项弓状线为腹直肌鞘后层的下缘；C项腹白线由两侧三层扁肌腱膜交织而成；D项腹直肌鞘前层含腹内斜肌腱膜，均与其有关"},{"q":"右侧大脑半球中央旁小叶前部损害可引起","o":["左侧下肢肌瘫痪","右侧下肢肌瘫痪","左侧下肢皮肤感觉障碍","右侧下肢皮肤感觉障碍","右侧上肢肌瘫痪"],"a":0,"e":"中央旁小叶前部为下肢运动代表区，经锥体交叉支配对侧，故右侧损害出现左侧下肢肌瘫痪。B项同侧瘫痪不符合交叉支配规律；C、D项该区后部为下肢感觉区，损害表现为感觉障碍而非瘫痪；E项上肢代表区在中央前回中部"},{"q":"与泪腺分泌有关的神经节","o":["睫状神经节","下颌下神经节","耳神经节","翼腭神经节","颈上神经节"],"a":3,"e":"面神经的副交感节前纤维经岩大神经至翼腭神经节换元，节后纤维随泪腺神经分布于泪腺，控制其分泌。A项睫状神经节支配瞳孔括约肌与睫状肌；B项下颌下神经节支配舌下腺、下颌下腺；C项耳神经节支配腮腺；E项颈上神经节属交感，与腺体分泌无关"},{"q":"关于肺静脉的正确描述是","o":["位于后纵隔内","每侧通常有一条","注入右心房","有静脉血流动","属于肺的功能性血管"],"a":4,"e":"肺有两套血管，肺动脉与肺静脉共同构成肺循环，属肺的功能性血管，与气体交换直接相关。A项肺静脉行于肺根内，不属后纵隔；B项每侧通常有上、下两条肺静脉；C项注入左心房；D项其内为含氧丰富的动脉血"},{"q":"喉上神经支配","o":["环杓后肌","环杓侧肌","环甲肌","甲杓肌","杓会厌肌"],"a":2,"e":"喉上神经外支为特殊内脏运动纤维，伴甲状腺上动脉下行，支配唯一的喉外群肌环甲肌，收缩可紧张并拉长声带。A、B、D、E项环杓后肌、环杓侧肌、甲杓肌和杓会厌肌均属喉内肌，由喉返神经支配"},{"q":"关于肺的叙述，错误的是","o":["肺底又称为膈面","两肺的前缘都有心切迹","左肺的前缘有左肺小舌","肺与胸廓相邻的面称为肋面","纵隔面中央凹陷处称为肺门"],"a":1,"e":"心切迹仅见于左肺前缘下部，其下方突起为左肺小舌，右肺前缘并无心切迹。A项肺底即膈面，与膈相邻；D项肋面与胸廓前外侧壁相邻；E项纵隔面中央凹陷处即肺门，为支气管、血管出入处，均描述正确"},{"q":"脊髓丘脑束","o":["包括脊髓丘脑前束和脊髓丘脑侧束","脊髓丘脑前束主要传导痛、温觉信息","脊髓丘脑侧束主要传导粗触觉、压觉信息","纤维起自脊神经节","经脊髓灰质Ⅰ和Ⅳ～Ⅷ层中继后止于背侧丘脑"],"a":0,"e":"脊髓丘脑束由脊髓丘脑侧束与脊髓丘脑前束合成，在脑干内又称脊髓丘系。B、C两项把功能说反，前束传导粗略触觉与压觉，侧束传导痛、温觉；D项纤维起自脊髓灰质第Ⅰ、Ⅳ～Ⅷ层细胞而非脊神经节"},{"q":"以下关于垂体的描述，哪项正确","o":["位于颅前窝的垂体窝内","分为前、中、后叶","产生的激素可影响甲状腺、肾上腺和性腺的分泌活动","分泌胰岛素","没有导管腺"],"a":2,"e":"腺垂体分泌促甲状腺激素、促肾上腺皮质激素和促性腺激素，分别促进甲状腺、肾上腺皮质和生殖腺的分泌活动。A项垂体位于蝶骨体上面的垂体窝，属颅中窝；B项按发生分为腺垂体与神经垂体；D项胰岛素由胰岛B细胞分泌；E项垂体为无导管腺"},{"q":"具有伸膝关节的肌是","o":["股四头肌","缝匠肌","股二头肌","大收肌","小腿三头肌"],"a":0,"e":"股四头肌跨过髋、膝两关节前方，起自髂前下棘和股骨，经髌骨、髌韧带止于胫骨粗隆，收缩时伸膝关节并屈髋关节。B项缝匠肌屈髋屈膝；C项股二头肌屈膝；D项大收肌内收髋；E项小腿三头肌使踝跖屈"},{"q":"在骨连结，纤维连结包括","o":["骺软骨","棘间韧带","耻骨联合","椎间盘","骶椎合成骶骨"],"a":1,"e":"棘间韧带是连结相邻棘突的薄层纤维，附着于棘突根部至尖端，属纤维连结。A项骺软骨、D项椎间盘、C项耻骨联合均为软骨连结，其中耻骨联合属纤维软骨连结；E项骶椎融合成骶骨属骨性结合，皆非纤维连结"},{"q":"与鼓室相通的管道是","o":["内耳道","外耳道","蜗管","骨半规管","咽鼓管"],"a":4,"e":"咽鼓管连通鼻咽部与鼓室，长3.5～4.0cm，可使鼓室内外气压平衡，小儿短而平直故易患中耳炎。A项内耳道通内耳；B项外耳道与鼓室之间隔以鼓膜；C项蜗管、D项骨半规管均属内耳结构，不与鼓室相通"},{"q":"鼓室黏膜的感觉神经来源于","o":["上颌神经","舌咽神经","面神经","迷走神经","前庭蜗神经"],"a":1,"e":"鼓室黏膜的感觉由舌咽神经的鼓室神经传导，其胞体位于舌咽神经下神经节。C项面神经的鼓索虽穿经鼓室，但只司舌前2/3味觉与下颌下腺、舌下腺分泌；E项前庭蜗神经司听觉与平衡；D项迷走神经耳支分布外耳道皮肤"},{"q":"临床上做多项血液指标检查，采血最常见的血管是","o":["手背静脉网","贵要静脉","头静脉","肘正中静脉","前臂正中静脉"],"a":3,"e":"肘正中静脉在肘窝处连接头静脉与贵要静脉，管径粗、位置表浅而恒定，是临床采血、输液最常用的血管。A项手背静脉网多用于输液穿刺；B、C项贵要静脉、头静脉分别位于前臂尺侧与桡侧；E项前臂正中静脉细小且变异多"},{"q":"外伤损伤右侧端脑枕叶的患者会产生","o":["双眼左侧视野偏盲","左眼右侧视野偏盲","右眼右侧视野偏盲","右眼全盲","左眼全盲"],"a":0,"e":"一侧视区接受双眼同侧半视网膜的纤维，主司对侧半视野，故右枕叶视区损伤出现双眼左侧视野同向性偏盲。A、C项单眼偏盲见于视神经或视交叉外侧部损伤；B项双眼颞侧偏盲为视交叉中部受损；D、E项单眼全盲为视神经损伤"},{"q":"属于颈内动脉的直接分支的是","o":["后交通动脉","前交通动脉","大脑后动脉","小脑上动脉","迷路动脉"],"a":0,"e":"后交通动脉在视束下方后行，连接颈内动脉与大脑后动脉，是颈内动脉的直接分支，也是两套动脉系的吻合支。B项前交通动脉连接两侧大脑前动脉；C项大脑后动脉起自基底动脉；D项小脑上动脉、E项迷路动脉均属椎-基底动脉系分支"},{"q":"关于脑桥核正确的是","o":["位于脑桥基底部","位于脑桥被盖部","接受锥体束纤维传导来的信息","接受来自小脑皮质的运动信息","发出纤维参与形成小脑下脚"],"a":0,"e":"脑桥核为分散于脑桥基底部的神经元群，接受同侧大脑皮质广泛区域的皮质脑桥纤维，发出纤维交叉组成小脑中脚入小脑。B项被盖部含脑神经核与上行传导束；C项其传入纤维来自大脑皮质而非锥体束；E项小脑下脚由脊髓小脑后束等构成"},{"q":"关于直肠的叙述，错误的是","o":["直肠下段扩大称为直肠壶腹","直肠横襞是镜检的定位标志","在第2骶椎前起自乙状结肠","直肠骶曲凸向后","直肠会阴曲凸向前"],"a":2,"e":"直肠在第3骶椎前方起自乙状结肠，而非第2骶椎。A项直肠下段膨大称直肠壶腹；B项直肠横襞恒定，是直肠镜检的定位标志；D项直肠骶曲凸向后，E项会阴曲凸向前，两曲方向相反，常被互换设错"},{"q":"嗅神经含有","o":["一般躯体感觉纤维","一般躯体运动纤维","特殊内脏感觉纤维","特殊内脏运动纤维","一般内脏运动纤维"],"a":2,"e":"嗅神经由上鼻甲和鼻中隔上部黏膜内嗅细胞的中枢突聚成嗅丝，穿筛孔入颅前窝连于嗅球，属特殊内脏感觉纤维。A、B项一般躯体感觉与运动纤维分别司痛温触压与骨骼肌运动；D项特殊内脏运动纤维支配鳃弓衍化的表情肌、咽喉肌；E项一般内脏运动为副交感纤维"},{"q":"关于大隐静脉的正确描述是","o":["起自外踝前方","属于深静脉","经腹股沟韧带深面注入股静脉","收集除小腿外侧部的下肢静脉血液","深静脉回流受阻时可发生曲张"],"a":4,"e":"大隐静脉与深静脉间借穿静脉交通，穿静脉瓣膜朝向深静脉，深静脉回流受阻或瓣膜关闭不全时血液反流，导致浅静脉曲张。A项大隐静脉起自足内侧缘；B项属浅静脉；C项经隐静脉裂孔注入股静脉；D项其收集范围不含小腿外侧部，但尚不是全部"},{"q":"属于面神经的功能包括","o":["支配胸锁乳突肌","支配肩胛提肌","支配舌前2/3的味觉","支配舌前2/3的痛温觉","支配舌后1/3的味觉"],"a":2,"e":"面神经的鼓索含特殊内脏感觉纤维，随舌神经分布于舌前2/3的味蕾，司味觉。A、B项胸锁乳突肌与肩胛提肌由副神经支配；D项舌前2/3痛温觉由三叉神经下颌神经的舌神经传导；E项舌后1/3味觉由舌咽神经司理"},{"q":"关节韧带的特征不包括","o":["连接相邻两骨","囊外韧带可与关节囊分离","是致密纤维结缔组织束","囊内韧带位于关节腔内","能增加关节的稳固"],"a":3,"e":"囊内韧带位于关节囊内，但被滑膜包裹，并不游离于关节腔内，故此项表述有误。A项韧带连接相邻两骨并增加关节稳固；B项囊外韧带可与关节囊分离，如腓侧副韧带；C项韧带由致密纤维结缔组织束构成，均正确"},{"q":"上肢骨与躯干骨连结的唯一的滑膜关节是","o":["胸锁关节","肩锁关节","肩关节","喙肩韧带","肩锁韧带"],"a":0,"e":"胸锁关节由锁骨的胸骨端与胸骨柄的锁切迹构成，是上肢骨与躯干骨之间唯一的滑膜关节。B项肩锁关节为锁骨与肩胛骨之间的平面关节；C项肩关节属自由上肢骨之间的连结；D、E项喙肩韧带、肩锁韧带为韧带，并非关节"},{"q":"阑尾根部的体表投影","o":["右髂前上棘与脐连线的中、外1/3交点","右髂前下棘与脐连线的中、外1/3交点","两侧髂前下棘连线的右、中1/3交点","两侧髂结节连线的右、中1/3交点","两侧髂前下棘连线的左、中1/3交点"],"a":0,"e":"阑尾根部的体表投影点为右髂前上棘与脐连线的中、外1/3交点，称McBurney点，是阑尾炎压痛的标志部位。B项起点应为髂前上棘而非髂前下棘；C、E项两条髂前下棘连线位置过低；D项髂结节连线属另一标志线，与阑尾无关"},{"q":"关于右冠状动脉正确的描述是","o":["起于主动脉前窦","窦房结的主要供血动脉","与心大静脉伴行","分布室间隔后2/3","由右心耳与主动脉根部穿出"],"a":1,"e":"约60%的窦房结支起自右冠状动脉起始1～2cm处，故右冠状动脉是窦房结的主要供血动脉。A项右冠状动脉起于主动脉右窦；C项与心小静脉伴行，与心大静脉伴行的是前室间支；D项供应室间隔后1/3而非后2/3；E项其自右心耳与肺动脉干之间穿出"},{"q":"关于小脑髓质的描述，正确的是","o":["小脑深部的灰质团块","被小脑皮质包裹的白质纤维","位于最中间的小脑蚓","出入小脑的3对脚","小脑皮质与小脑核之间的联系纤维"],"a":1,"e":"小脑髓质是被小脑皮质包裹的白质，内含小脑核并联系皮质与核团。A项小脑深部的灰质团块称小脑核，包括齿状核、栓状核、球状核和顶核；C项小脑蚓为皮质部而非髓质；D项三对小脑脚为出入小脑的纤维束，不属髓质本身"},{"q":"关于视网膜的叙述，错误的是","o":["视网膜的视部分为色素上皮层和神经层","视网膜属于眼球壁的内层","视网膜视部最大、最厚，附于脉络膜的内面","视网膜视部全都有感光的能力","视网膜分为虹膜部、睫状体部、脉络膜部3部分"],"a":3,"e":"视网膜视部并非全部有感光能力，视神经盘处无感光细胞，形成生理性盲点。A项视部分色素上皮层与神经层，两层间潜在间隙是视网膜脱离的基础；B项视网膜属眼球壁内层；E项视网膜分虹膜部、睫状体部与脉络膜部，视部即脉络膜部"},{"q":"患者，女。食管下段癌症。试分析食管胸下段淋巴管大部分注入的是","o":["纵隔前淋巴结","胃左淋巴结和纵隔后淋巴结","颈外侧深淋巴结","气管支气管淋巴结","纵隔后淋巴结"],"a":1,"e":"食管胸下段的淋巴主要注入胃左淋巴结和纵隔后淋巴结，后者沿胸主动脉与食管排列并注入胸导管。D项气管旁淋巴结、气管支气管淋巴结收纳食管胸上段及肺的淋巴；C项颈外侧深淋巴结收纳食管颈部；A项纵隔前淋巴结引流胸腺、心包前部"},{"q":"前列腺输出管开口于","o":["尿道海绵体部","尿道前列腺部","尿道膜部","尿道球部","射精管"],"a":1,"e":"前列腺的输出管开口于尿道前列腺部后壁尿道嵴两侧，射精管则开口于该部后壁的精阜。A、C、D项尿道海绵体部、膜部、尿道球部均无前列腺输出管开口；E项射精管是输精管末端与精囊排出管汇合成的管道，为前列腺输出管的毗邻而非其开口处"},{"q":"关于肠系膜上动脉描述正确的是","o":["供应范围包括空肠、升结肠、横结肠和降结肠","分支有左结肠动脉","平对第1腰椎高度起自腹主动脉前壁","分支包括胰十二指肠上动脉","分出直肠上动脉"],"a":2,"e":"肠系膜上动脉在腹腔干稍下方，约平第1腰椎高度起自腹主动脉前壁，经胰头与胰体交界处后方下行。A项其供应至横结肠左2/3，降结肠由肠系膜下动脉供血；B项左结肠动脉、E项直肠上动脉为肠系膜下动脉分支；D项胰十二指肠上动脉来自胃十二指肠动脉"},{"q":"内脏大神经","o":["属于副交感神经节前纤维","属于交感神经节前纤维","属于交感神经节后纤维","属于内脏感觉纤维","属于副交感节后纤维"],"a":1,"e":"内脏大神经由第5～9胸节侧角发出的交感节前纤维组成，穿交感干下行止于腹腔神经节换元。A、E项副交感节前纤维起自脑干一般内脏运动核和骶副交感核；C项节后纤维由椎旁或椎前神经节细胞发出；D项内脏感觉纤维经内脏神经传入而非传出"},{"q":"有关呼吸道的描述，正确的是","o":["口腔属于上呼吸道","鼻属于上呼吸道","气管属于上呼吸道","喉属于下呼吸道","肺属于下呼吸道"],"a":1,"e":"临床上以喉为界，鼻、咽、喉为上呼吸道，气管和各级支气管为下呼吸道，故鼻属上呼吸道。A项口腔为消化管起始部；C项气管属下呼吸道；D项喉属上呼吸道；E项肺为呼吸器官，是气体交换场所，不列入呼吸道"},{"q":"掌浅弓","o":["由骨间总动脉与桡动脉末端吻合形成","由尺动脉的末端与桡动脉的末端吻合形成","由尺动脉末端与桡动脉掌浅支吻合形成","由尺动脉的掌深支与桡动脉的掌浅支吻合形成","与掌深弓没有吻合"],"a":2,"e":"掌浅弓由尺动脉末端与桡动脉掌浅支吻合而成，位于掌腱膜深面。A项骨间总动脉分为骨间前、后动脉，不参与成弓；B项两动脉末端吻合的是掌深弓的构成方式之一，桡动脉末端与尺动脉掌深支成深弓；E项浅弓与深弓间有广泛吻合"},{"q":"投射纤维是大脑髓质的主要纤维，它们大都经过内囊，其中下行的投射纤维不包括","o":["丘脑中央辐射","皮质脊髓束","额桥束","皮质核束","顶枕颞桥束"],"a":0,"e":"投射纤维中下行者包括皮质脊髓束、皮质核束、额桥束和顶枕颞桥束，分别经内囊后肢、膝部和前肢下行。A项丘脑中央辐射由背侧丘脑腹后核至中央后回，属上行投射纤维，传递皮肤、肌和关节的感觉"},{"q":"穿过茎乳孔的是","o":["舌咽神经","面神经","副神经","舌下神经","脑膜中动脉"],"a":1,"e":"面神经经内耳门、内耳道穿内耳道底进入面神经管，最后从茎乳孔出颅，随即入腮腺分为数支。A项舌咽神经、C项副神经随迷走神经同经颈静脉孔出颅；D项舌下神经经舌下神经管出颅；E项脑膜中动脉穿棘孔入颅"},{"q":"以下关于房水及其循环的描述中正确的是","o":["房水为无色透明的液体，无折光作用","房水由虹膜产生，充满眼房内","房水可为角膜和晶状体提供营养","房水循环受阻可降低眼内压","房水经瞳孔由眼前房进入后房"],"a":2,"e":"房水由睫状体产生，充填眼房，为角膜和晶状体提供营养并维持正常眼压。A项房水无色透明且参与屈光；B项产生部位是睫状体而非虹膜；D项回流受阻使眼压升高，导致青光眼；E项房水由后房经瞳孔流入前房"},{"q":"后角固有核位于脊髓灰质的","o":["Ⅰ～Ⅱ层","Ⅱ～Ⅲ层","Ⅲ～Ⅳ层","Ⅳ～Ⅴ层","Ⅴ～Ⅵ层"],"a":2,"e":"脊髓灰质第Ⅲ、Ⅳ层内较大的细胞群组成后角固有核，接受大量后根传入纤维，并发出纤维联络脊髓不同节段。A项第Ⅰ层为后角边缘核；B项第Ⅱ层为胶状质；D项第Ⅴ层为后角颈；E项第Ⅵ层为后角基底部，均非固有核所在"},{"q":"胃网膜右动脉起自","o":["胰十二指肠上动脉","胃十二指肠动脉","脾动脉","肝固有动脉","肠系膜上动脉"],"a":1,"e":"胃十二指肠动脉经十二指肠上部后方下行，至胃下缘分为胃网膜右动脉和胰十二指肠上动脉。A项胰十二指肠上动脉为其分支而非来源；C项胃网膜左动脉起自脾动脉；D项胃右动脉起自肝固有动脉；E项肠系膜上动脉发出胰十二指肠下动脉"},{"q":"股骨的重要体表标志不包括","o":["股骨内侧髁","股骨大转子","股骨小转子","股骨外侧髁","收肌结节"],"a":2,"e":"股骨小转子位于股骨上端后内侧，被髂腰肌等肌包绕，位置深在，不能体表扪及。A、D项股骨内、外侧髁在膝部可清楚扪到；B项大转子是髋部最重要的骨性标志；E项收肌结节位于内侧髁上方，亦可触及"},{"q":"与间脑相连的脑神经是","o":["三叉神经","面神经","动眼神经","视神经","滑车神经"],"a":3,"e":"视神经向后内行经视神经管入颅中窝，移行为间脑的视交叉，故与间脑相连。A、B项三叉神经、面神经连于脑桥；C项动眼神经、E项滑车神经连于中脑；嗅神经则与端脑相连，各脑神经的连脑部位并不相同"},{"q":"在脊柱，为椎体之间连结，有限制脊柱过度后伸和防止椎间盘向前脱出的韧带是","o":["棘上韧带","黄韧带","前纵韧带","后纵韧带","横突间韧带"],"a":2,"e":"前纵韧带位于椎体前面，宽而坚韧，上自枕骨大孔前缘下达骶骨，能限制脊柱过度后伸并防止椎间盘向前脱出。B项黄韧带连结相邻椎弓板，限制过度前屈；C项后纵韧带限制过度前屈、防髓核向后外侧脱出；A、E项棘上韧带、横突间韧带不位于椎体之间"},{"q":"射精管开口于","o":["尿道海绵体部","尿道膜部","尿道球部","尿道前列腺部","舟状窝"],"a":3,"e":"射精管由输精管末端与精囊排出管汇合而成，长约2cm，穿前列腺实质开口于尿道前列腺部后壁的精阜。A、C项尿道海绵体部与球部位于前尿道；B项膜部为穿尿生殖膈的短段；E项舟状窝为海绵体部末端的膨大"},{"q":"对鼓索的描述，哪项是错误的","o":["出鼓室后并入舌神经","出茎乳孔后入鼓室","其内脏运动纤维在下颌下神经节换元","味觉纤维分布于舌前2/3的味蕾","含有一般内脏运动节前纤维"],"a":1,"e":"鼓索在茎乳孔上方约6mm处自面神经管穿出，经鼓索后小管进入鼓室，而非出茎乳孔后才入鼓室。A项其穿岩鼓裂出鼓室后并入舌神经；C项副交感节前纤维在下颌下神经节换元；D项味觉纤维随舌神经分布舌前2/3；E项其内脏运动纤维属副交感节前纤维"},{"q":"不属于腹膜内位的消化管是","o":["胃","横结肠","升结肠","乙状结肠","回肠"],"a":2,"e":"升结肠属腹膜间位器官，无系膜，其后借结缔组织贴附于腹后壁，故活动性甚小。A项胃、B项横结肠、D项乙状结肠、E项回肠均为腹膜内位器官，各面几乎全被腹膜包被并具系膜，活动度大。结肠带、结肠袋与肠脂垂三者齐备是结肠的共同特征，与其腹膜位置无关"},{"q":"胸长神经支配","o":["肩胛下肌","大圆肌","胸大肌","前锯肌","背阔肌"],"a":3,"e":"胸长神经起自第5～7颈神经根，沿胸侧壁前锯肌表面伴胸外侧动脉下行，支配前锯肌和乳房外侧份，损伤后出现翼状肩。A项肩胛下肌、B项大圆肌由肩胛下神经支配；C项胸大肌由胸内、外侧神经支配；E项背阔肌由胸背神经支配"},{"q":"延髓内的非脑神经核","o":["舌下神经核","疑核","薄束核","迷走神经背核","下泌涎核"],"a":2,"e":"薄束核位于延髓薄束结节深面，是薄束的终止核，属非脑神经核。A项舌下神经核、B项疑核、D项迷走神经背核、E项下泌涎核均为脑神经核，分别与舌下神经、舌咽及迷走神经、迷走神经、舌咽神经相关"},{"q":"有关胸导管的描述正确的是","o":["注入右侧的静脉角","经食管裂孔进入胸腔","至第4胸椎高度斜行向左","不是全身最大的淋巴管","第12胸椎下缘高度起自乳糜池"],"a":4,"e":"胸导管平第12胸椎下缘起自乳糜池，经主动脉裂孔入胸腔，至第5胸椎高度斜向左上，注入左静脉角。A项注入左静脉角而非右侧；B项经主动脉裂孔而非食管裂孔；C项为第5胸椎而非第4胸椎；D项胸导管是全身最大的淋巴管"},{"q":"不属于结肠上区的间隙是","o":["肝肾隐窝","右肝上前间隙","左肝下前间隙","网膜囊","右结肠旁沟"],"a":4,"e":"结肠上区指横结肠及其系膜以上的区域，其内的膈下间隙包括肝肾隐窝、各肝上及肝下间隙与网膜囊。E项右结肠旁沟位于升结肠右侧与腹壁之间，属横结肠以下的结肠下区四个间隙之一。膈下脓肿即指结肠上区内任一间隙积脓"},{"q":"屈髋并使股骨旋外的肌是","o":["臀大肌","臀中肌","臀小肌","梨状肌","髂腰肌"],"a":4,"e":"髂腰肌由腰大肌与髂肌合成，经腹股沟韧带深面止于股骨小转子，收缩时屈髋关节并使股骨旋外。A项臀大肌伸髋并旋外；B项臀中肌外展髋；C项臀小肌外展、旋内；D项梨状肌外展旋外但不屈髋。闭孔内肌、股方肌等只使髋旋外，不参与屈髋"},{"q":"对于垂体的描述，哪项是错误的","o":["位于蝶骨体上面的垂体窝内","借漏斗向上连于下丘脑","可分为腺垂体和神经垂体两部分","神经垂体可分泌垂体素","腺垂体可分泌多种激素"],"a":3,"e":"神经垂体只贮存和释放下丘脑视上核、室旁核合成的抗利尿激素与缩宫素，本身不合成激素。A项垂体位于蝶骨体上面的垂体窝内；B项借漏斗连于下丘脑；C项分腺垂体与神经垂体；E项腺垂体分泌生长激素及多种促激素"},{"q":"一侧耳聋可能是由于什么结构受损引起的","o":["同侧前庭神经受损","对侧前庭神经受损","同侧蜗神经受损","对侧蜗神经受损","面神经受损"],"a":2,"e":"蜗神经传导听觉，其纤维来自同侧螺旋神经节，故一侧受损引起同侧耳聋。A、B项前庭神经司平衡，受损表现为眩晕与眼球震颤，不引起耳聋；D项听觉通路为同侧传入，对侧蜗神经受损不引起患侧耳聋；E项面神经支配表情肌"},{"q":"关于结肠的描述正确的是","o":["介于回肠和直肠之间","各部均有系膜","升结肠和横结肠转折处称为脾曲","乙状结肠是憩室和恶性肿瘤的多发部位","横结肠和降结肠转折处称为肝曲"],"a":3,"e":"乙状结肠系膜中段宽大、活动度大，是憩室和肿瘤的多发部位，也是乙状结肠扭转的解剖基础。A项结肠起自盲肠、下续直肠；B项升结肠、降结肠为腹膜间位，无系膜；C项升结肠与横结肠转折处为肝曲；E项横结肠与降结肠转折处为脾曲"},{"q":"直肠的淋巴管注入的是","o":["腹股沟深淋巴结","髂总淋巴结","骶淋巴结","腹股沟浅淋巴结","髂外淋巴结"],"a":2,"e":"骶淋巴结沿骶正中血管和骶外血管排列，引流盆后壁、直肠、前列腺或子宫等处的淋巴。D项齿状线以下的淋巴注入腹股沟浅淋巴结；A、E项髂外淋巴结收纳下肢、腹前壁下部的淋巴；B项髂总淋巴结为骶淋巴结的输出去向"},{"q":"关于眼的静脉的描述，错误的是","o":["眼下静脉可注入翼静脉丛","向前与面静脉有吻合","向后面注入海绵窦","面部感染可经眼静脉侵入海绵窦，引起颅内感染","涡静脉收纳虹膜的静脉血"],"a":4,"e":"涡静脉为眼球血管膜的主要静脉，多4条，收集脉络膜及睫状体的静脉血，虹膜的血液主要经睫状前静脉回流，故此项归属有误。A项眼下静脉经眶下裂可与翼静脉丛交通；B项眼静脉向前与面静脉吻合；D项面静脉感染可循眼静脉入海绵窦"},{"q":"表面有结肠带的肠管","o":["空肠","回肠","盲肠","阑尾","直肠"],"a":2,"e":"结肠带由肠壁纵行肌增厚形成，与结肠袋、肠脂垂共同构成结肠和盲肠的特征性结构，盲肠表面可见结肠带并会聚于阑尾根部。A、B项空肠、回肠为小肠，无此三特征；D项阑尾、E项直肠同样不具结肠带"},{"q":"患者车祸入院治疗，经检查发现患者右侧上肢瘫痪，其损伤部位在","o":["左侧中央前回上部","左侧中央前回下部","左侧旁中央小叶","右侧中央前回","右侧旁中央小叶"],"a":1,"e":"官方答案为【左侧中央前回下部】，但依据教材，正确答案为【左侧中央前回中部】。中央前回最上部与中央旁小叶前部管理下肢，中部管理躯干和上肢，下部管理面、舌、咽、喉，故右上肢瘫痪的病灶应在左侧中央前回中部；左侧中央前回下部受损应出现对侧头面部肌瘫痪，左侧中央前回上部或旁中央小叶受损则为对侧下肢瘫"},{"q":"与后室间支伴行的静脉","o":["心大静脉","心中静脉","心小静脉","心前静脉","心最小静脉"],"a":1,"e":"心中静脉位于后室间沟内，与后室间支伴行，收纳左右心室后壁、室间隔后部及心尖的静脉血，注入冠状窦。A项心大静脉伴前室间支；C项心小静脉伴右冠状动脉；D项心前静脉直接注入右心房；E项心最小静脉直接开口于心腔"},{"q":"一患者经检查发现为感觉性失语症，损伤的部位位于","o":["舌叶","额下回后1/3部","额中回后部","缘上回","角回"],"a":3,"e":"感觉性失语由听觉性语言中枢受损引起，该中枢位于颞上回后部并涉及缘上回一带，属Wernicke区，患者能听见但不能理解语义。B项额下回后1/3为运动性语言中枢，受损为运动性失语；C项额中回后部为书写中枢；E项角回为视觉性语言中枢"},{"q":"下列核团中哪个属于后丘脑","o":["枕","背外侧核","腹后外侧核","内侧膝状体","后外侧核"],"a":3,"e":"后丘脑位于背侧丘脑后下方，包括内侧膝状体和外侧膝状体，分别中继听觉与视觉冲动。A项枕、B项背外侧核、E项后外侧核均属背侧丘脑；C项腹后外侧核属背侧丘脑腹后核，接受脊髓丘系与内侧丘系"},{"q":"具有使髋关节外展的肌是","o":["臀大肌","臀中肌","半腱肌","半膜肌","股二头肌"],"a":1,"e":"臀中肌起自髂骨翼外面，止于股骨大转子，与臀小肌同为髋外展的主要肌，前部肌束使髋旋内、后部肌束使髋旋外。A项臀大肌伸髋并旋外；C、D项半腱肌、半膜肌屈膝伸髋；E项股二头肌屈膝并伸髋"},{"q":"俯视时，收缩的眼球外肌为","o":["上斜肌和下直肌","下斜肌和下直肌","下斜肌和内直肌","上直肌和下斜肌","上直肌和上斜肌"],"a":0,"e":"俯视时两眼同时收缩下直肌与上斜肌，使瞳孔转向下内与下外，实现双眼共同下转。B项下斜肌作用为转向上外；D项上直肌使瞳孔转向上内；E项上直肌与上斜肌组合并非俯视的协同方式，仰视才是上直肌与下斜肌共同收缩"},{"q":"椎骨的一般形态不包括","o":["前方的椎体","后方的椎弓","椎弓分椎弓根和椎弓板","椎弓板发出5个突起","棘突1个"],"a":3,"e":"椎弓发出7个突起，即1个棘突、1对横突和上、下各1对关节突，故说发出5个突起有误。A项椎体居前，B项椎弓居后，C项椎弓分椎弓根与椎弓板，D项棘突可在体表扪到，均属椎骨的一般形态。各椎孔上下连通构成椎管，容纳脊髓"},{"q":"关于心尖正确的描述是","o":["朝向前下方","平对第5肋间","由左心室形成","偏左侧有心尖切迹","位于心脏裸区"],"a":2,"e":"心尖圆钝游离，由左心室构成，朝向左前下方，在左侧第5肋间隙锁骨中线内侧1～2cm处可触及搏动。A项漏掉朝向左侧；B项平对第5肋间隙而非仅第5肋间；D项心尖切迹位于心尖右侧，为前后室间沟的汇合处；E项裸区位于心底后方"},{"q":"神经组织的两种主要细胞","o":["神经细胞和胶质细胞","神经元和星形胶质细胞","神经细胞和少突胶质细胞","星形胶质细胞和少突胶质细胞","神经元和施万细胞"],"a":0,"e":"神经组织由神经细胞（神经元）和神经胶质细胞两类细胞构成，后者数量为前者的数十倍。B、C、D、E项星形胶质细胞、少突胶质细胞、施万细胞均属胶质细胞的不同种类，不能与神经元并列概括全部细胞成分"},{"q":"关于晶状体的描述，错误的是","o":["位于虹膜的后方、玻璃体的前方","呈双凸透镜状，无色透明，有丰富的血管和神经","晶状体外面包以具有高度弹性的晶状体囊","晶状体实质由平行排列的晶状体纤维所组成","晶状体若因疾病或创伤而变混浊，称为白内障"],"a":1,"e":"晶状体无色透明、富有弹性、不含血管和神经，其营养由房水供给，故有丰富血管神经的描述有误。A项位于虹膜后方、玻璃体前方；C项外面包有高度弹性的晶状体囊；D项实质由平行排列的晶状体纤维组成；E项混浊即白内障"},{"q":"面部的危险三角感染导致颅内感染是由于","o":["面静脉与海绵窦有交通支","面静脉与乙状窦有交通支","面静脉通过板障静脉与颅内交通","面静脉与上矢状窦有交通支","面静脉与横窦有交通支"],"a":0,"e":"面静脉通过眼上、眼下静脉与海绵窦交通，且口角以上缺乏静脉瓣，故面部危险三角区化脓性感染可逆行入颅。B项乙状窦、E项横窦经岩上、岩下窦与海绵窦相连，不与面静脉直接交通；C、D项板障静脉、上矢状窦亦非其直接通路"},{"q":"男性尿道分为","o":["前列腺部、膜部、阴茎部","前列腺部、膜部、尿道球部","前列腺部、膜部、海绵体部","前列腺部、膜部、后尿道","前列腺部、海绵体部"],"a":2,"e":"男性尿道全长分前列腺部、膜部和海绵体部，临床上前两者合称后尿道，海绵体部称前尿道。B项尿道球部只是海绵体部内的膨大部；D、E项后尿道、前尿道为临床分段名称，不是解剖学的三部分。尿道全长有三处狭窄、三个膨大和两个弯曲"},{"q":"关于锁骨下动脉错误的说法是","o":["锁骨中点上方锁骨上窝为该动脉的止血点","在颈根部行经前、中斜角肌之间","在颈根部斜越胸膜顶前方","右侧锁骨下动脉起自头臂干","所有分支均分布于上肢"],"a":4,"e":"锁骨下动脉的分支除供应上肢外，椎动脉入颅供应脑与脊髓，胸廓内动脉分布胸前壁、心包与膈，甲状颈干分布甲状腺、咽、喉及肩部肌。A项锁骨上窝可将其压向第1肋止血；B项行经前、中斜角肌之间；D项右侧起自头臂干"},{"q":"本体感受器的分布不包括","o":["骨骼肌","肌腱","关节","基底膜","膜壶腹"],"a":3,"e":"本体感受器位于骨骼肌的肌梭、肌腱的腱器官和关节囊等处，感受肌张力与关节位置变化。D项基底膜位于蜗管内，上有螺旋器，属听觉感受器；E项膜壶腹为前庭器的一部分，感受头部旋转变速运动，二者均非本体感受器"},{"q":"关于锁骨下动脉的叙述，错误的是","o":["左锁骨下动脉起自主动脉弓，右锁骨下动脉起自头臂干","其分支有椎动脉、胸廓内动脉、甲状颈干和肋颈干","其体表投影为：自胸锁关节至锁骨中点画一凸向上的线，最凸处在锁骨上方1.5cm","其压迫止血部位为：在锁骨中点向下压，将动脉压在第3肋骨上","压迫该动脉其止血范围包括整个上肢"],"a":3,"e":"压迫锁骨下动脉应在锁骨中点上方的锁骨上窝向后下压，将动脉压向第1肋骨，而非锁骨中点向下压在第3肋。A项左起主动脉弓、右起头臂干正确；B项分支有椎动脉、胸廓内动脉、甲状颈干和肋颈干；D项体表投影描述正确"},{"q":"关于面静脉的起始和特点，正确的是","o":["注入颈外静脉","通过面深静脉与海绵窦交通","缺乏静脉瓣","起自翼静脉丛","属于深静脉"],"a":2,"e":"面静脉在口角以上一般缺乏静脉瓣，血液可逆流，是面部感染扩散入颅的解剖基础。A项面静脉注入颈内静脉；B项经眼上、下静脉与海绵窦交通，面深静脉先通翼静脉丛；D项起自内眦静脉；E项面静脉属浅静脉"},{"q":"营养甲状腺的血管中，甲状腺下动脉来自于","o":["颈外动脉","颈内动脉","胸廓内动脉","甲状颈干","颈总动脉"],"a":3,"e":"甲状腺下动脉起自甲状颈干，后者在椎动脉外侧、前斜角肌内侧缘附近起始，迅即分为甲状腺下动脉、肩胛上动脉等。A项甲状腺上动脉起自颈外动脉；C项胸廓内动脉供应胸前壁；E项颈总动脉在颈部无此分支"},{"q":"颅前窝骨折，可能引起","o":["视神经损伤","嗅神经损伤","动眼神经损伤","滑车神经损伤","三叉神经损伤"],"a":1,"e":"嗅丝穿筛板筛孔入颅前窝连于嗅球，颅前窝骨折累及筛板时最易损伤嗅神经，可致嗅觉障碍或脑脊液鼻漏。A项视神经经视神经管，属颅中窝；C、D项动眼神经、滑车神经经眶上裂；E项三叉神经分支经圆孔、卵圆孔"},{"q":"关于舌的叙述，错误的是","o":["颏舌肌两侧收缩时伸舌向前下","舌根和舌体在舌的下面以界沟为界","舌根背部黏膜内有舌扁桃体","舌下面中线上有舌系带，其根部的两侧有舌下阜","舌下襞深面有舌下腺"],"a":1,"e":"界沟位于舌背，呈向前开放的V形，借此将舌分为前2/3的舌体与后1/3的舌根，而非在舌下面分界。A项颏舌肌两侧同时收缩使舌伸向前下；C项舌根黏膜内有舌扁桃体；D项舌系带根部两侧有舌下阜；E项舌下襞深面为舌下腺"},{"q":"下列选项中不属于小脑核的是","o":["栓状核","球状核","红核","顶核","齿状核"],"a":2,"e":"小脑核包括齿状核、栓状核、球状核和顶核，均埋于小脑髓质内。A、B项栓状核与球状核居中间位；D项顶核位于第四脑室顶上方的小脑蚓白质内；E项齿状核最大，位于小脑半球白质内；C项红核位于中脑被盖，属锥体外系核团"},{"q":"节制索位于","o":["右心房","右心室","左心房","左心室","房间隔"],"a":1,"e":"节制索又称隔缘肉柱，是前乳头肌根部横过右心室腔至室间隔下部的一条肌束，构成右心室流入道的下界，可防止心室过度扩张。C、D项左心房、左心室无此结构；E项房间隔为分隔左右心房的隔板。室上嵴则分隔右心室流入道与流出道"},{"q":"可牵拉肩胛骨向前的肌是","o":["胸大肌","肩胛下肌","前锯肌","斜方肌","菱形肌"],"a":2,"e":"前锯肌止于肩胛骨内侧缘和下角，收缩时拉肩胛骨向前并紧贴胸廓。A项胸大肌使肩关节内收、旋内和前屈；B项肩胛下肌使肩关节旋内；D项斜方肌上提、后缩肩胛骨；E项菱形肌拉肩胛骨向后内。胸小肌亦可拉肩胛骨向前下方，但止于喙突"},{"q":"脊髓圆锥","o":["脊髓的膨大部分","脊髓末端变细的部分","约平对第2腰椎下缘","由结缔组织组成","附着于尾骨背面"],"a":1,"e":"脊髓下端逐渐变细呈圆锥状，称脊髓圆锥，末端约平第1腰椎椎体下缘。A项脊髓的膨大部为颈膨大与腰骶膨大；C项平对第1腰椎下缘而非第2腰椎下缘；D项由神经组织构成；E项附着于尾骨背面的是终丝，并非圆锥本身"},{"q":"关于脊柱的侧面观特征不正确的是","o":["有4个生理性的弯曲","腰曲和骶曲在胚胎时已形成","颈曲凸向前","颈曲支持头的抬起","胸曲凹向后"],"a":1,"e":"胚胎时已形成的是胸曲和骶曲，二者凸向后；颈曲和腰曲在出生后随抬头、坐起与行走逐渐形成，凸向前。E项胸曲实为凸向后，本题按其表述判为不确切；A项四个生理弯曲、C项颈曲凸向前、D项颈曲支持抬头均正确"},{"q":"属于脑神经的感觉神经节的是","o":["膝神经节","翼腭神经节","下颌下神经节","耳神经节","睫状神经节"],"a":0,"e":"膝神经节是面神经的感觉神经节，其胞体为假单极神经元，周围突分布于舌前2/3味蕾等，属脑神经感觉神经节。B项翼腭神经节、C项下颌下神经节、D项耳神经节、E项睫状神经节均为副交感神经节，属一般内脏运动通路的中继站"},{"q":"女性易发生逆行性尿路感染，是因为","o":["前上方与阴蒂相邻","膀胱容积大","尿道短、宽而直","尿道开口于阴道前庭","女性抵抗力差"],"a":2,"e":"女性尿道平均长3～5cm，直径约0.6cm，较男性短、宽而直，且开口于阴道前庭，邻近阴道与肛门，故易发生逆行性尿路感染。B项膀胱容积与感染途径无关；D项开口位置只是毗邻条件，逆行感染的关键在于管道短宽直"},{"q":"松果体位于","o":["脚间窝","上髓帆上方","视交叉后方","上丘上方","下丘脑前方"],"a":3,"e":"松果体位于上丘脑，以柄附着于第三脑室顶后部，居于上丘上方，儿童期发达，7岁左右开始退化并出现脑砂。A项脚间窝位于中脑腹侧；C项视交叉位于下丘脑前方；D项上髓帆位于小脑与脑干之间；E项松果体在上丘脑而非下丘脑前方"},{"q":"甲状腺的淋巴注入的淋巴结是","o":["颏下淋巴结","下颌下淋巴结","耳后淋巴结","咽后淋巴结","气管旁淋巴结"],"a":4,"e":"甲状腺的淋巴主要注入气管旁淋巴结，亦可经甲状腺淋巴结、气管前淋巴结间接引流。A项颏下淋巴结收纳下唇、舌尖与口底；B项下颌下淋巴结收纳面颊、鼻腔与上唇；C项耳后淋巴结收纳头皮枕部；D项咽后淋巴结收纳鼻咽与咽后壁"},{"q":"胸骨的形态结构特征包括","o":["成人胸骨体内含有黄骨髓","分为胸骨体和胸骨柄2个部分","与肋软骨都以关节相连","胸骨体左右外侧缘接第1～7肋软骨","上缘有颈静脉切迹"],"a":4,"e":"胸骨柄上缘中份为颈静脉切迹，两侧有锁切迹与锁骨相连，是重要的体表标志。A项成人胸骨体内为红骨髓；B项胸骨分胸骨柄、胸骨体和剑突三部分；C项第1肋软骨与胸骨柄为软骨结合而非关节；D项胸骨体侧缘接第2～7肋软骨"},{"q":"肺的描述中，正确的是","o":["位于胸膜腔内","肺尖高度不超过锁骨水平","左、右肺形态相同","右肺有斜裂和水平裂","外侧缘中部有肺门"],"a":3,"e":"右肺除斜裂外还有水平裂，借此分为上、中、下三叶，左肺仅有斜裂分为上、下两叶。A项肺位于胸膜腔之外、胸腔之内；B项肺尖高出锁骨内侧1/3上方2～3cm；C项左肺前缘有心切迹与左肺小舌，两肺形态不同；E项肺门位于纵隔面而非外侧缘"},{"q":"有关肺根的叙述，错误的是","o":["左肺根上方有主动脉弓跨过","右肺根上方有奇静脉弓跨过","肺动脉位于肺根内最前方","迷走神经行于肺根后方","膈神经行于肺根前方"],"a":2,"e":"肺根内结构自前向后依次为上肺静脉、肺动脉、主支气管和下肺静脉，故肺动脉并非最前。A项左肺根上方有主动脉弓跨过；B项右肺根上方有奇静脉弓跨过；D项迷走神经行于肺根后方；E项膈神经行于肺根前方，均正确"},{"q":"关于右肺的形态，描述错误的是","o":["通常分3叶","分10个肺段","有斜裂和水平裂","较左肺宽而短","前缘有心切迹"],"a":4,"e":"心切迹与左肺小舌只见于左肺前缘下部，右肺前缘并无心切迹，故此项描述有误。A项右肺通常分上、中、下三叶；B项分10个肺段；C项有斜裂与水平裂；D项因膈下肝脏顶推，右肺较左肺宽而短，均正确"},{"q":"关于颈外静脉的正确描述是","o":["由面静脉和下颌后静脉汇合形成","沿胸锁乳突肌深面下行","注入锁骨下静脉或静脉角","主要收集颈部的静脉血","坐立时可显露"],"a":2,"e":"颈外静脉在锁骨上方穿深筋膜，注入锁骨下静脉或静脉角，是颈部最粗的浅静脉。A项由下颌后静脉后支、耳后静脉和枕静脉汇合而成；B项沿胸锁乳突肌表面下行；D项主要收集头皮和颈部的静脉血；E项其充盈可见并非解剖学描述要点"},{"q":"下列关于玻璃体的描述中，正确的是","o":["玻璃体位于虹膜与晶状体之间","富含血管神经","玻璃体前面凹陷称玻璃体凹","玻璃体对视网膜起营养作用","玻璃体发生混浊时，不影响视力"],"a":2,"e":"玻璃体前面以晶状体及其悬韧带为界，呈凹面，称玻璃体凹，其余部分与睫状体、视网膜相邻。A项玻璃体位于晶状体与视网膜之间；B项玻璃体无血管神经；D项对视网膜起支撑作用，营养来自脉络膜与房水；E项混浊时出现飞蚊症，影响视力"},{"q":"脊髓的交感神经低级中枢位于","o":["脊髓网状结构","后角固有核","胸核","中间外侧核","中间内侧核"],"a":3,"e":"脊髓胸1～腰3节段中间带外侧核是交感神经节前神经元胞体所在，即交感神经的低级中枢。A项脊髓网状结构与内脏感觉传导有关；B项后角固有核为感觉中继核；C项胸核发出脊髓小脑后束；E项中间内侧核与内脏感觉传入有关"},{"q":"关于甲状软骨的描述，正确的是","o":["前角借韧带和舌骨大角相连","上角上方为上切迹","下角与杓状软骨相关节","前角上端为喉结","左右软骨板后方连接形成后角"],"a":3,"e":"甲状软骨左右软骨板前缘融合成前角，前角上端向前突出即喉结，成年男性尤为明显。A项上角借韧带连于舌骨大角，下角与环状软骨构成环甲关节；B项上切迹位于喉结上方呈V形；C项下角与环状软骨相关节，非杓状软骨；E项软骨板在前方愈合形成前角"},{"q":"受损致患者瞳孔转向内侧的脑神经","o":["视神经","动眼神经","展神经","面神经","滑车神经"],"a":2,"e":"展神经支配外直肌，受损后外直肌麻痹，内直肌失去拮抗，瞳孔转向内侧并伴眼球不能外展。B项动眼神经损伤使瞳孔转向外下并上睑下垂；E项滑车神经损伤致上斜肌麻痹、复视；A项视神经损伤致视力障碍，与眼位无关"},{"q":"前庭蜗神经纤维瘤时，患者除了有听力障碍和小脑损伤的症状外，肿瘤还可压迫位于附近的哪些神经","o":["动眼神经、滑车神经、面神经和迷走神经","展神经、三叉神经、舌咽神经和迷走神经","动眼神经、三叉神经、舌咽神经和迷走神经","面神经、三叉神经、舌咽神经和舌下神经","面神经、三叉神经、舌咽神经和迷走神经"],"a":4,"e":"前庭蜗神经根位于脑桥小脑三角，该处肿瘤可压迫邻近的面神经、三叉神经、舌咽神经和迷走神经，产生面瘫、面部感觉障碍、吞咽困难等。A、C项动眼神经、滑车神经位于中脑及眶内；D项舌下神经经舌下神经管出颅，位置偏下前"},{"q":"有关锥体系描述正确的是","o":["皮质核束支配双侧脑神经","分为皮质脊髓束和皮质核束","下行纤维都在延髓下端交叉","受损后，反射消失，但骨骼肌不萎缩","起始于中央后回及中央旁小叶后部"],"a":1,"e":"锥体系由皮质脊髓束和皮质核束构成，前者经内囊后肢下行并在延髓锥体交叉，后者经内囊膝部止于脑干脑神经运动核。A项皮质核束并非支配全部脑神经核，面神经核下部与舌下神经核仅受对侧支配；D项上运动神经元损伤腱反射亢进；E项起自中央前回及中央旁小叶前部"},{"q":"分布于舌的脑神经有","o":["滑车神经","三叉神经","副神经","迷走神经","鼻睫神经"],"a":1,"e":"三叉神经的下颌神经发出舌神经，传导舌前2/3黏膜的一般感觉，故三叉神经分布于舌。A项滑车神经支配上斜肌；C项副神经支配胸锁乳突肌与斜方肌；D项迷走神经司咽、喉黏膜感觉；E项鼻睫神经分布于鼻背与眼球"},{"q":"子宫的描述中，正确的是","o":["分为体、颈、峡三部分","子宫内腔即子宫腔","颈部全部位于阴道内","峡部在非妊娠期明显","子宫颈管下通阴道"],"a":4,"e":"子宫颈管呈梭形，下口通阴道，称子宫口，故子宫颈管下通阴道。A项子宫分底、体、颈三部，峡部只是颈体之间的狭窄段；B项内腔含子宫腔与子宫颈管两部分；C项仅子宫颈阴道部突入阴道；D项峡部非妊娠期不明显，长约1cm"},{"q":"左纤维三角的位置是","o":["左、右房室口之间","主动脉口与左房室口之间","主动脉口与右房室口之间","肺动脉口与左房室口之间","肺动脉口与右房室口之间"],"a":1,"e":"左纤维三角位于主动脉口与左房室口之间，是心纤维性支架的组成部分。A项左、右房室口之间为右纤维三角的主体位置；C项主动脉口与右房室口之间亦属右纤维三角；D、E项涉及肺动脉口的位置关系不构成纤维三角"},{"q":"运动时使拇指掌面与小指掌面相对的肌是","o":["拇短展肌","拇长屈肌","拇短屈肌","拇对掌肌","拇收肌"],"a":3,"e":"拇对掌肌起自第1掌骨，止于拇指掌骨外侧缘，收缩时使拇指对掌，即拇指掌面与小指掌面相对。A项拇短展肌外展拇指；C项拇短屈肌屈拇指近节指骨；D项拇收肌使拇指内收；E项为混淆项，手肌外侧群无此名称"},{"q":"面神经内含有","o":["红核的纤维","上泌涎核的纤维","下泌涎核的纤维","下橄榄核的纤维","上橄榄核的纤维"],"a":1,"e":"面神经含起自上泌涎核的副交感节前纤维，经翼腭神经节和下颌下神经节换元后控制泪腺、舌下腺与下颌下腺分泌。C项下泌涎核纤维随舌咽神经至耳神经节支配腮腺；A项红核发出红核脊髓束；D、E项上、下橄榄核为中继核，与面神经无关"},{"q":"纵隔的不同部位可发生不同的肿瘤，其中常发生于中纵隔的是","o":["胸腺瘤","心包囊肿","淋巴瘤","主动脉瘤","支气管囊肿"],"a":1,"e":"中纵隔容纳心包及出入心的大血管，是心包囊肿的好发部位。A项胸腺瘤、C项淋巴瘤、E项支气管囊肿多位于前纵隔；D项主动脉瘤位于后纵隔，与胸主动脉走行一致。前纵隔尚容纳胸腺遗迹与纵隔前淋巴结，后纵隔容纳食管、胸主动脉与胸导管"},{"q":"一患者在肛瘘手术后大便失禁，可能切断了以下哪些肌肉","o":["肛门外括约肌","肛门外括约肌浅部、深部，肠壁纵行肌，肛门内括约肌，耻骨直肠肌","肛门外括约肌和肛门内括约肌","肛提肌、肛门外括约肌皮下部和肛门内括约肌","肛门内括约肌和肛门外括约肌皮下部"],"a":1,"e":"肛直肠环由肛门外括约肌浅部、深部，直肠下份纵行肌，肛门内括约肌及肛提肌（耻骨直肠肌）共同构成，损伤后即致大便失禁。A、C、E项只涉及外括约肌或内括约肌，其中外括约肌皮下部被切断并不引起失禁，单伤内括约肌亦不致失禁"},{"q":"子宫的形态","o":["子宫分为头、体、颈三部分","子宫与阴道相通，不与输卵管相通","子宫颈全部被阴道包绕","子宫口是子宫颈管的下口","子宫峡正常约5cm长"],"a":3,"e":"子宫颈管呈梭形，其下口通阴道即子宫口，故子宫口为子宫颈管的下口。A项子宫分底、体、颈三部而非头、体、颈；B项子宫腔上通输卵管；C项仅子宫颈阴道部被阴道包绕；E项子宫峡长约1cm，妊娠期才逐渐伸展"},{"q":"膈的腔静脉孔约平对","o":["第8胸椎","第9胸椎","第10胸椎","第11胸椎","第12胸椎"],"a":0,"e":"膈的腔静脉孔位于中心腱内，约平第8胸椎水平，有下腔静脉通过。B项第9胸椎无膈的裂孔；C项食管裂孔约平第10胸椎，有食管和迷走神经通过；D项第11胸椎为膈脚与主动脉裂孔的邻近高度；E项主动脉裂孔平第12胸椎"},{"q":"关于精囊的描述正确的是","o":["为单一的囊状器官","位于膀胱前方","由附睾管构成","可储存精子","其输出管与输精管壶腹末端合成射精管"],"a":4,"e":"精囊左右各一，位于膀胱底后方、输精管壶腹下外侧，其排出管与输精管壶腹末端汇合成射精管。A项精囊成对而非单一；B项位于膀胱后方而非前方；C项由迂曲管道构成，并非附睾管；D项贮存精子的是附睾"},{"q":"没有结肠带的肠管是","o":["横结肠","盲肠","直肠","乙状结肠","升结肠"],"a":2,"e":"除直肠、肛管和阑尾外，结肠与盲肠才具有结肠带、结肠袋和肠脂垂三个特征性结构，故直肠无结肠带。A项横结肠、B项盲肠、D项乙状结肠、E项升结肠均属结肠或盲肠，表面均有结肠带，且三条结肠带会聚于阑尾根部"},{"q":"当上肢上举固定时，可作引体向上活动的肌是","o":["斜方肌","背阔肌","肩胛提肌","菱形肌","竖脊肌"],"a":1,"e":"背阔肌起自下6个胸椎及全部腰椎棘突、髂嵴后部，止于肱骨小结节嵴，使肩关节后伸、内收和旋内，上肢上举固定时可协助引体向上。A项斜方肌上提、后缩肩胛骨；C项肩胛提肌上提肩胛骨；D项菱形肌使肩胛骨后缩；E项竖脊肌伸脊柱"},{"q":"以下关于舌下神经描述正确的是","o":["司舌下腺的分泌","损伤时舌肌无萎缩","含有特殊内脏运动纤维","支配全部的舌内肌和舌外肌","一侧舌下神经损伤，患者伸舌舌尖偏向患侧"],"a":4,"e":"舌下神经为一般躯体运动纤维，支配舌内肌和大部分舌外肌，一侧完全损伤时患侧半舌瘫痪，伸舌舌尖偏向患侧。A项司腺体分泌的是副交感纤维；B项瘫痪日久舌肌萎缩；C项其纤维属一般躯体运动而非特殊内脏运动；D项腭舌肌由迷走神经支配"},{"q":"不含有味蕾的结构","o":["菌状乳头","轮廓乳头","丝状乳头","叶状乳头","软腭黏膜"],"a":2,"e":"丝状乳头数目最多、体积最小，遍布舌背前2/3，其中不含味蕾，故无味觉功能。A项菌状乳头、B项轮廓乳头、D项叶状乳头以及E项软腭黏膜上皮内均含味蕾，为味觉感受器，可感受酸、甜、苦、咸"},{"q":"支配舌后三分之一特殊内脏感觉的脑神经是","o":["副神经","舌下神经","滑车神经","舌咽神经","三叉神经"],"a":3,"e":"舌咽神经含特殊内脏感觉纤维，胞体位于下神经节，周围突分布于舌后1/3的味蕾，中枢突止于孤束核上部。B项舌下神经司舌肌运动；E项三叉神经司舌前2/3一般感觉；A项副神经、C项滑车神经分别支配胸锁乳突肌、上斜肌"},{"q":"椎体和椎弓围成","o":["椎间孔","椎孔","横突孔","骶前孔","骶后孔"],"a":1,"e":"椎体后面微凹，与椎弓共同围成椎孔，各椎孔上下贯通构成容纳脊髓的椎管。A项椎间孔由相邻椎弓根与椎体围成，脊神经由此通过；C项横突孔仅见于颈椎，有椎动脉通过；D、E项骶前、后孔为骶神经前、后支的通道"},{"q":"眼副器不包括","o":["眼球外肌","眼睑","结膜","泪器","房水"],"a":4,"e":"眼副器包括眼睑、结膜、泪器、眼球外肌、眶脂体和眶筋膜，对眼球起支持、保护和运动作用。E项房水充填于眼房内，与角膜、晶状体、玻璃体同属眼的屈光装置，为眼球内容物，不属眼副器。眶脂体充填于眼球与眶壁之间，起缓冲作用"},{"q":"声门裂以下黏膜的感觉神经是","o":["面神经","舌咽神经","喉返神经","喉上神经外支","喉上神经内支"],"a":2,"e":"喉返神经（喉下神经）在甲状腺侧叶深面入喉，分布于声门裂以下的喉黏膜，并支配除环甲肌以外的全部喉肌。E项喉上神经内支穿甲状舌骨膜入喉，司声门裂以上黏膜感觉；D项喉上神经外支支配环甲肌；A项面神经、B项舌咽神经不分布于喉"},{"q":"肝外胆道不包括","o":["肝左管","肝右管","胆囊管","胰管","肝总管"],"a":3,"e":"肝外胆道指肝门以外的胆道系统，包括胆囊和输胆管道，后者由肝左管、肝右管、肝总管和胆总管组成。D项胰管引流胰液，与胆总管汇合成肝胰壶腹后共同开口于十二指肠，属胰的排泄管道。胆囊位于肝下面的胆囊窝内，分底、体、颈、管四部"},{"q":"一患者损伤左侧大脑半球角回，下列哪项与角回无关","o":["围绕外侧沟后端","围绕颞上沟末端","又称阅读中枢","损伤可导致失读症","损伤后无视觉障碍"],"a":0,"e":"角回围绕颞上沟末端，为视觉性语言中枢即阅读中枢，损伤后虽无视觉障碍却不能阅读，称失读症。A项围绕外侧沟后端的是缘上回，属听觉性语言中枢的一部分；C、D、E项关于角回的名称、失读表现与视觉完好均描述正确"},{"q":"右肾门前面毗邻的组织器官是","o":["肝方叶","十二指肠降部","结肠右曲","胆囊","肠系膜血管"],"a":1,"e":"右肾内侧缘与十二指肠降部相邻，肾门朝向前内侧，故其前方毗邻十二指肠降部。结肠右曲接触右肾前下部，肝右叶毗邻右肾前上部，二者位置偏上偏外。肠系膜血管不直接贴附肾门，胆囊毗邻的是肝下面而非肾门"},{"q":"神经节是指","o":["神经元树突的集合","神经元胞体在中枢的集合","神经元胞体在周围的集合","神经元轴突的集合","神经元胞体与树突的集合"],"a":2,"e":"在周围部，神经元胞体聚集处称神经节；在中枢部同样聚集则称神经核。树突或轴突的集合在中枢称纤维束、在周围称神经，均不含胞体。胞体与树突的集合描述的是灰质结构，不能等同于神经节。神经节按位置分为脑神经节、脊神经节和内脏运动神经节，均属周围部结构"},{"q":"下丘脑属于","o":["中脑","间脑","端脑","小脑","脑桥"],"a":1,"e":"间脑包括背侧丘脑、后丘脑、上丘脑、底丘脑和下丘脑五部，下丘脑位于第三脑室下方，是内脏活动和内分泌的高级中枢。中脑属脑干，与下丘脑以乳头体、大脑脚为界。端脑指大脑半球，小脑与脑桥分别属小脑和脑干"},{"q":"关于脑神经进出脑的部位，正确的是","o":["延髓脑桥沟内有面神经","中脑脚间窝内有视神经","延髓锥体前方有舌下神经","小脑背面有动眼神经","小脑中脚有展神经"],"a":0,"e":"延髓脑桥沟内自中线向外侧依次连有展神经、面神经和前庭蜗神经根，面神经根恰位于沟内。视神经连于间脑，经视神经管入眶，不属脑干。舌下神经自锥体与橄榄之间的前外侧沟出脑，动眼神经出脚间窝，展神经出延髓脑桥沟内侧端"},{"q":"以下不属于肾上腺分泌的激素的是","o":["盐皮质激素","糖皮质激素","性激素","去甲肾上腺素","促肾上腺激素释放激素"],"a":4,"e":"促肾上腺皮质激素释放激素由下丘脑分泌，作用于腺垂体，不属肾上腺的分泌产物。肾上腺皮质分泌盐皮质激素、糖皮质激素和性激素，髓质分泌肾上腺素和去甲肾上腺素。促肾上腺皮质激素是腺垂体分泌、调节肾上腺皮质者，与释放激素不同"},{"q":"前庭神经","o":["传导本体感觉","起自内耳门处前庭神经节双极神经元","在橄榄体上端入脑","与蜗神经同行，在延髓脑桥沟外侧端入脑","全部纤维终止于延髓内的前庭神经核"],"a":3,"e":"前庭神经与蜗神经合成前庭蜗神经，在延髓脑桥沟外侧端、脑桥小脑三角处入脑，止于前庭神经核群和小脑，传导平衡觉。其胞体位于内耳道底的前庭神经节，非内耳门处。该神经传导平衡觉而非本体感觉，纤维并非全部终止于前庭神经核"},{"q":"三叉丘系为","o":["同侧三叉神经半月节发出的纤维组成","对侧三叉神经半月节发出的纤维组成","同侧三叉神经感觉核发出的纤维组成","对侧三叉神经感觉核发出的纤维组成","对侧三叉神经感觉纤维的直接延续"],"a":3,"e":"三叉丘系又称三叉丘脑束，由对侧三叉神经脊束核和双侧三叉神经脑桥核发出的二级感觉纤维交叉后组成，止于背侧丘脑腹后内侧核。半月节属一级感觉神经元，其纤维入脑后才换元，不直接构成丘系。同侧感觉核的纤维不越边，不能形成对侧传导"},{"q":"关于脾的位置正确的是","o":["左侧第9～11肋深面","胃底前面","胰尾上方","左肋弓下方","结肠左曲后方"],"a":0,"e":"脾位于左季肋部、胃底与膈之间，相当于第9～11肋深面，长轴与第10肋一致，正常时左肋弓下不能触及。脾在胃底的左后方而非前面，与胰尾相邻而非在其上方。结肠左曲位于脾下方，借脾结肠韧带与之相连"},{"q":"疑核发出的纤维加入","o":["前庭蜗神经","舌咽神经","面神经和迷走神经","舌下神经和迷走神经","舌下神经和副神经"],"a":1,"e":"疑核上部发出的纤维加入舌咽神经，支配茎突咽肌；中部纤维加入迷走神经，下部纤维构成副神经脑根。前庭蜗神经为纯感觉神经，不含疑核发出的运动纤维。面神经运动纤维起自面神经核，舌下神经纤维起自舌下神经核"},{"q":"有关脑蛛网膜的描述，下面正确的是","o":["富有血管神经","与硬脊膜之间有硬膜外隙","与软脑膜之间有软脑膜下隙","与软脑膜之间的腔隙内充满脑脊液","与硬脊膜之间为蛛网膜下隙"],"a":3,"e":"脑蛛网膜薄而透明，与软脑膜之间为蛛网膜下隙，隙内充满脑脊液，向下与脊髓蛛网膜下隙相通。该膜缺乏血管和神经，血管丰富的是软脑膜。它与硬脑膜之间是硬膜下隙，硬膜外隙位于硬脑膜与颅骨之间"},{"q":"前列腺分为5叶，不包括","o":["前叶","后叶","中叶","周边叶","两侧叶"],"a":3,"e":"前列腺分前叶、中叶、后叶和左、右侧叶共五叶，前叶很小，位于尿道前方与两侧叶之间。周边叶是依内、外腺分区法的命名，不属五叶分法。中叶位于尿道后方、两侧叶之间，后叶位于中叶后方，均为五叶的组成部分"},{"q":"关于胸腔器官淋巴结的叙述，正确的是","o":["纵隔前淋巴结的输出淋巴管注入胸导管","肺淋巴结沿支气管血管排列","支气管肺淋巴结又称肺门淋巴结","气管旁淋巴结沿气管杈排列","纵隔后淋巴结的输出淋巴管参与合成支气管纵隔干"],"a":2,"e":"支气管肺门淋巴结位于肺门处，又称肺门淋巴结，收纳肺和食管的淋巴，输出管注入气管支气管淋巴结。纵隔前淋巴结的输出管参与合成支气管纵隔干，不注入胸导管。肺淋巴结位于叶、段支气管夹角处，气管旁淋巴结沿气管两侧排列而非气管杈"},{"q":"与胫、腓骨下端组成踝关节的结构是","o":["跟骨结节","足舟骨","距骨滑车","骰骨","内侧楔骨"],"a":2,"e":"踝关节由胫、腓骨下端与距骨滑车构成，属近似单轴的屈戌关节。跟骨结节是跟骨后端隆起，为跟腱附着处。足舟骨、骰骨和楔骨属跗骨前部，参与跗骨间关节，不与胫腓骨下端直接相关节。踝关节囊前后壁松弛，两侧有韧带加强，跖屈时较窄的滑车后部入窝，故易扭伤"},{"q":"脑干内的一般内脏运动核","o":["动眼神经核、迷走神经背核、疑核","上泌涎核、下泌涎核、迷走神经背核","孤束核、迷走神经背核、疑核","孤束核、迷走神经背核、动眼神经核","面神经核、迷走神经背核、动眼神经核"],"a":1,"e":"脑干一般内脏运动核共4对，即动眼神经副核、上泌涎核、下泌涎核和迷走神经背核，发出副交感节前纤维。疑核属特殊内脏运动核，支配咽喉肌。孤束核为一般内脏感觉核，接受内脏感觉传入，不发出运动纤维"},{"q":"关于子宫描述正确的是","o":["子宫颈低于坐骨棘平面","子宫前倾为子宫颈与体之间形成的钝角","子宫峡为子宫颈阴道上部的上端与子宫体相连的部分","子宫的固定装置不包括盆底的肌肉","其交感神经来自盆内脏神经"],"a":2,"e":"子宫峡位于子宫颈阴道上部上端与子宫体相接处，非孕时长约1cm，妊娠期展长形成子宫下段。子宫颈下端在坐骨棘平面稍上方，低于该平面提示子宫脱垂。前倾是子宫长轴与阴道长轴的钝角，前屈才是体与颈之间的钝角；盆底肌参与固定子宫，交感神经来自腹下丛"},{"q":"肺和胸膜的体表投影不同，主要区别是","o":["肺尖低于胸膜顶1cm","在胸腺区，肺与胸膜前界的体表投影差别大","在锁骨中线肺下界较胸膜下界高两个肋","在心包区，右肺与右侧胸膜前界体表投影差别大","在前正中线左、右两侧肺下界与胸膜下界体表投影差别大"],"a":2,"e":"同一部位肺下界一般较胸膜下界高出约两个肋，锁骨中线处肺下缘平第6肋，胸膜下界平第8肋。肺尖与胸膜顶均高出锁骨内侧1/3上方2～3cm，二者不相差1cm。胸腺区、心包区讨论的是胸膜前界与肺前缘的差异，与下界高低无关"},{"q":"面神经连接脑的部位","o":["延髓上端","小脑中脚中下份","延髓脑桥沟靠近锥体上端处","延髓脑桥沟外侧","延髓脑桥沟中线两侧"],"a":3,"e":"面神经根连于延髓脑桥沟外侧部，居展神经与前庭蜗神经之间。三叉神经连于脑桥基底部与小脑中脚交界处。舌下神经自延髓锥体与橄榄之间出脑，属延髓上端前外侧沟，并非面神经的位置。面神经属混合性脑神经，其运动纤维起自面神经核，感觉纤维胞体位于膝神经节"},{"q":"颅内肿瘤的患者出现厌食，肿瘤可能压迫到了","o":["下丘脑前区内侧","下丘脑后区外侧","下丘脑外侧区","下丘脑前区","下丘脑后区"],"a":2,"e":"下丘脑外侧部为摄食中枢，损毁后引起厌食、消瘦；腹内侧核为饱食中枢，损毁则多食肥胖。下丘脑前区含散热中枢，损毁可致高热。后区含冷敏神经元，损毁出现变温症，与摄食行为无关。下丘脑腹内侧核病损则表现为多食、肥胖，与厌食方向相反"},{"q":"关于卵巢的叙述，错误的是","o":["位于卵巢窝内","属于腹膜内位器官","后缘中部血管神经出入处称卵巢门","上端连卵巢悬韧带","下端连卵巢固有韧带"],"a":2,"e":"卵巢前缘借卵巢系膜连于阔韧带，称系膜缘，其中部有血管神经出入，为卵巢门；后缘游离称独立缘。卵巢位于卵巢窝内，属腹膜内位器官，上端连卵巢悬韧带，下端借卵巢固有韧带连子宫，故后缘中部之说错误"},{"q":"孤束核接受的神经纤维来自","o":["第Ⅴ、Ⅵ和Ⅶ对脑神经","第Ⅵ、Ⅶ和Ⅷ对脑神经","第Ⅶ、Ⅷ和Ⅸ对脑神经","第Ⅷ、Ⅸ和Ⅹ对脑神经","第Ⅶ、Ⅸ和Ⅹ对脑神经"],"a":4,"e":"孤束核接受面神经、舌咽神经和迷走神经的一般内脏感觉及味觉纤维，其上部分为味觉核。三叉神经的一般躯体感觉止于三叉神经脊束核，前庭蜗神经止于前庭神经核与蜗神经核。第Ⅵ对展神经为纯运动神经，不含传入纤维"},{"q":"副神经脑根起于","o":["副神经核","疑核","孤束核","上泌涎核","下泌涎核"],"a":1,"e":"副神经由脑根和脊髓根组成，脑根起自疑核下部，出颅后加入迷走神经支配咽喉肌；脊髓根起自副神经核，支配胸锁乳突肌和斜方肌。孤束核为内脏感觉核，上、下泌涎核为副交感核，均不发出副神经纤维"},{"q":"脑干背面出颅的脑神经是","o":["滑车神经","三叉神经","展神经","面神经","前庭蜗神经"],"a":0,"e":"滑车神经在下丘下方、上髓帆处出脑，是唯一自脑干背侧面出脑的脑神经，绕过大脑脚后经眶上裂入眶。三叉神经出脑桥基底部与小脑中脚交界处，展神经、面神经、前庭蜗神经均自延髓脑桥沟出脑，皆在腹侧"},{"q":"齿状韧带","o":["由蛛网膜形成","由硬脊膜形成","其作用是将脊髓的血管固定在椎管上","由软脊膜在脊髓两侧脊神经前、后根之间形成","其尖端附于脊髓上"],"a":3,"e":"齿状韧带由软脊膜在脊髓两侧、脊神经前根与后根之间形成，呈齿状，尖端附于硬脊膜，与脊神经根共同固定脊髓。它不由蛛网膜或硬脊膜形成，固定对象是脊髓而非血管。尖端附着处为硬脊膜，不在脊髓表面"},{"q":"关于胫后动脉的叙述，错误的是","o":["该动脉发自腘动脉","其主要分支包括腓动脉、足底内侧动脉和足底外侧动脉","其体表投影为：自腘窝中点至内踝和跟结节之间的中点连线","其压迫止血部位为：在内踝和跟结节之间向深部压迫","压迫该动脉其止血范围为：整个足部"],"a":4,"e":"胫后动脉发自腘动脉，分支有腓动脉、足底内侧动脉和足底外侧动脉，压迫部位在内踝与跟结节之间。其止血范围为足底及小腿后外侧，足背由胫前动脉供血，整个足部之说不能成立。其体表投影为腘窝中点至内踝与跟结节中点的连线"},{"q":"关于阴部神经的叙述，错误的是","o":["自骶丛发出后，经梨状肌下孔出盆腔","穿坐骨小孔至会阴","在坐骨肛门窝行于阴部管内","在肛区不发出分支","在尿生殖区分为会阴神经和阴茎（蒂）神经"],"a":3,"e":"阴部神经经梨状肌下孔出盆腔，绕坐骨棘穿坐骨小孔入坐骨肛门窝，在阴部管内前行，于尿生殖区分为会阴神经和阴茎（蒂）神经。它在肛区发出肛门神经，支配肛门外括约肌及肛周皮肤，故不发出分支之说错误"},{"q":"管理硬脑膜的神经是","o":["耳大神经","面神经","舌咽神经耳支","副神经","迷走神经"],"a":4,"e":"迷走神经上神经节发出脑膜支，分布于颅后窝硬脑膜，传导一般躯体感觉。耳大神经属颈丛皮支，分布于耳郭及颈前外侧皮肤。面神经、舌咽神经和副神经均不发出脑膜支，颅中窝硬脑膜主要由三叉神经分支管理"},{"q":"关于颞浅动脉的叙述，错误的是","o":["该动脉发自颈外动脉","该动脉主要供应腮腺和额、颞、顶部软组织","其体表投影为该动脉的根部位于外耳门的前方，向上分为两大分支","其压迫止血部位为在外耳门前方可摸到动脉搏动，然后将其压向颞骨","压迫该动脉，其止血范围为项背部"],"a":4,"e":"颞浅动脉为颈外动脉终支之一，根部位于外耳门前方，分布于腮腺及额、颞、顶部软组织，压迫止血范围为头前外侧部。项背部皮肤由枕动脉和颈横动脉等供血，非其范围。压迫点在耳屏前方，不在内眦或口角"},{"q":"含有交感神经节后纤维的神经","o":["内脏大神经","内脏小神经","腰内脏神经","心上、中、下神经","盆内脏神经"],"a":3,"e":"颈上、中、下神经节发出的心支即心上、中、下神经，属交感节后纤维，参与组成心丛。内脏大、小神经和腰内脏神经均为节前纤维，起自脊髓侧角，止于椎前神经节。盆内脏神经为骶副交感节前纤维，亦非节后"},{"q":"关于脑干的内部结构，说法正确的是","o":["灰质在外，白质在内","中央的腔隙为第四脑室","锥体由上行纤维构成","薄束核、楔束核为脑神经核团","锥体交叉在内侧丘系交叉平面之下"],"a":4,"e":"锥体交叉位于延髓下部，内侧丘系交叉位于其上方，故锥体交叉在内侧丘系交叉平面之下。脑干灰质呈核团状散在于白质中，并非灰质在外。第四脑室仅位于延髓上部、脑桥和小脑之间。锥体由下行纤维构成，薄束核、楔束核属非脑神经核"},{"q":"下列属于连合纤维的是","o":["前连合","内囊","钩束","内侧丘系","乳头丘脑束"],"a":0,"e":"前连合在终板上方横过中线，连接两侧颞叶及嗅球，属连合纤维。内囊为投射纤维集中处，钩束联络额叶与颞叶，属联络纤维。内侧丘系是上行感觉传导束，乳头丘脑束联系下丘脑与丘脑前核，均非连合纤维"},{"q":"经圆孔出颅的神经是","o":["展神经","上颌神经","下颌神经","动眼神经","眼神经"],"a":1,"e":"三叉神经第2支上颌神经穿圆孔出颅入翼腭窝，再经眶下裂入眶续为眶下神经。眼神经经眶上裂入眶，下颌神经经卵圆孔出颅。展神经和动眼神经均为运动神经，分别经眶上裂入眶，与圆孔无关。三叉神经三支的出颅部位是常考点，需与眶上裂、卵圆孔相区分"},{"q":"不属于臂丛锁骨下分支的是","o":["胸内侧神经","胸背神经","肌皮神经","胸长神经","胸外侧神经"],"a":3,"e":"胸长神经起自臂丛神经根，在臂丛主要结构后方下行，属锁骨上分支，支配前锯肌。胸内侧神经、胸外侧神经、胸背神经及肌皮神经均由臂丛各束发出，属锁骨下分支。不属锁骨下分支者为胸长神经。臂丛锁骨上分支还含肩胛背神经和肩胛上神经"},{"q":"脊髓小脑束","o":["脊髓小脑前束位于脊髓前索","脊髓小脑后束位于脊髓后索","脊髓小脑前束经小脑下脚进入小脑","脊髓小脑后束经小脑上脚进入小脑","传导下肢和躯干下部非意识性本体感觉和触、压觉信息至小脑"],"a":4,"e":"脊髓小脑前、后束传导下肢和躯干下部的非意识性本体感觉及触压觉至小脑，参与姿势协调。前束位于外侧索前部而非前索，后束位于外侧索后部而非后索。前束经小脑上脚入小脑，后束经小脑下脚入小脑，与选项所述相反"},{"q":"副交感神经的低级中枢位于","o":["间脑和骶2～4脊髓节段","脑干和胸1～腰2脊髓节段","脑干和骶2～4脊髓节段","胸1～腰3脊髓节段","脑干"],"a":2,"e":"副交感神经低级中枢位于脑干的一般内脏运动核和脊髓S2～S4节段的骶副交感核。胸1～腰3节段中间带外侧核是交感神经低级中枢。间脑为高级中枢，不直接发出副交感节前纤维。交感低级中枢位于T1～L3节段，两者节段范围不可混淆"},{"q":"脑干内的一般躯体运动核支配","o":["舌肌、眼球外肌","咽喉肌","表情肌","咀嚼肌","平滑肌、心肌"],"a":0,"e":"一般躯体运动核包括动眼、滑车、展和舌下神经核，支配由肌节衍化的眼球外肌和舌肌。咽喉肌由疑核支配，表情肌由面神经核支配，咀嚼肌由三叉神经运动核支配，三者均属特殊内脏运动核。平滑肌和心肌由一般内脏运动核支配"},{"q":"属于一般躯体运动核的神经核是","o":["三叉神经运动核","滑车神经核","面神经核","副神经核","疑核"],"a":1,"e":"一般躯体运动核共4对，为动眼神经核、滑车神经核、展神经核和舌下神经核，紧靠中线排列。三叉神经运动核、面神经核和疑核均属特殊内脏运动核，分别支配咀嚼肌、面肌和咽喉肌。副神经核位于脊髓颈段，亦属特殊内脏运动柱"},{"q":"顶盖前区参与","o":["内脏反射","瞳孔对光反射","角膜反射","浅反射","听觉反射"],"a":1,"e":"顶盖前区接受视束经上丘臂来的纤维，发出纤维至双侧动眼神经副核，是瞳孔对光反射通路的中继站。角膜反射的传入为三叉神经眼支、传出为面神经。上丘发出顶盖脊髓束完成视觉反射，与听觉反射无关"},{"q":"关于胸膜腔正确的叙述是","o":["由脏、壁胸膜共同围成的窄隙","由壁胸膜相互返折而成","可通过呼吸与外界相通","左、右胸膜腔经气管相通","其内有左、右肺和少量液体"],"a":0,"e":"胸膜腔是脏胸膜与壁胸膜在肺根处相互移行所围成的封闭潜在腔隙，左右各一，互不相通，呈负压，内含少量浆液。壁胸膜自身返折处形成的是胸膜隐窝。胸膜腔不与外界相通，也不含肺，肺位于胸膜腔之外"},{"q":"收缩时，作张口运动的肌是","o":["双侧咬肌","双侧颞肌","口轮匝肌","双侧翼内肌","双侧翼外肌"],"a":4,"e":"翼外肌起自蝶骨大翼下面和翼突外侧面，止于下颌颈，两侧同时收缩使下颌骨前伸并张口。咬肌、颞肌和翼内肌收缩均上提下颌骨，属闭口肌。口轮匝肌为表情肌，关闭口裂，不参与张口。翼外肌一侧收缩时使下颌骨向对侧移动，参与侧方咀嚼运动"},{"q":"关于肺，正确的描述是","o":["肺位于胸膜腔内","右肺上方有主动脉压迹","左肺上方有奇静脉沟","肺尖不超出胸廓上口","肺底位于膈上方，又称膈面"],"a":4,"e":"肺底位于膈上方，因与膈相邻又称膈面，该描述正确。肺位于胸膜腔之外的胸腔内，胸膜腔仅为潜在腔隙。主动脉压迹位于左肺、奇静脉沟位于右肺，左右相反；肺尖高出锁骨内侧1/3上方2～3cm，已超出胸廓上口"},{"q":"不穿行于海绵窦的结构","o":["动眼神经","滑车神经","眼神经","上颌神经","下颌神经"],"a":4,"e":"海绵窦外侧壁自上而下有动眼神经、滑车神经、眼神经和上颌神经通过，展神经在窦内沿颈内动脉外下方行。下颌神经经卵圆孔出颅，不穿海绵窦。不穿行海绵窦者为下颌神经。海绵窦内侧壁尚有颈内动脉和展神经通过，与外侧壁结构需分清"},{"q":"关于桡神经正确的是","o":["从臂丛外侧束发出，下行穿桡神经沟至臂后区","从臂丛后束发出，穿四边孔到达臂后区","在肱三头肌深面穿桡神经沟下行至肘的前外侧","不支配肱桡肌","在臂后区不发出分支支配臂部伸肌群"],"a":2,"e":"桡神经起自臂丛后束，在肱三头肌深面沿桡神经沟绕肱骨中段后行，穿外侧肌间隔至肱桡肌与肱肌之间，达肘前外侧。它支配肱三头肌和肱桡肌，在臂后区发肌支支配伸肌群。穿四边孔的是腋神经。桡神经损伤表现为垂腕，第1、2掌骨间背侧皮肤感觉障碍"},{"q":"窦房结位于","o":["房间隔的心内膜深面","上腔静脉口的心内膜深面","上腔静脉与右心房交界处","右肺静脉入口处","下腔静脉入口处"],"a":2,"e":"窦房结位于上腔静脉与右心房交界处界沟上1/3的心外膜深面，是心的正常起搏点。房间隔心内膜深面为房室结所在。上腔静脉口、下腔静脉口和右肺静脉入口均为心房内开口，其内膜深面不含起搏组织"},{"q":"下列哪条动脉是肝固有动脉的分支","o":["胃网膜右动脉","胃左动脉","胃网膜左动脉","胃十二指肠动脉","胃右动脉"],"a":4,"e":"肝固有动脉在肝十二指肠韧带内发出胃右动脉，沿胃小弯左行与胃左动脉吻合。胃左动脉直接起自腹腔干，胃网膜左动脉起自脾动脉，胃十二指肠动脉为肝总动脉的另一终支。胃网膜右动脉发自胃十二指肠动脉"},{"q":"视网膜视部的3层神经细胞由内向外依次为","o":["感光细胞、双极细胞、节细胞","感光细胞、节细胞、双极细胞","双极细胞、感光细胞、节细胞","节细胞、感光细胞、双极细胞","节细胞、双极细胞、感光细胞"],"a":4,"e":"视网膜视部神经层由外向内为感光细胞、双极细胞和节细胞，节细胞轴突汇成视神经。由内向外则依次为节细胞、双极细胞、感光细胞，与本题问法方向相反。感光细胞属感受器，双极细胞为第1级神经元，节细胞为第2级"},{"q":"舌的味觉纤维走行于","o":["面神经和舌咽神经","面神经和舌下神经","舌下神经和迷走神经","舌咽神经和舌下神经","舌咽神经和舌神经"],"a":0,"e":"舌前2/3味蕾由面神经鼓索传导，舌后1/3味蕾由舌咽神经传导，故味觉纤维走行于面神经和舌咽神经。舌下神经为运动神经，支配舌肌运动。舌神经仅传导舌前2/3的一般感觉，味觉纤维只是搭行其内"},{"q":"引流支气管淋巴的淋巴结是","o":["纵隔前淋巴结","膈上淋巴结","纵隔后淋巴结","肺淋巴结","气管旁淋巴结"],"a":3,"e":"肺淋巴结位于肺叶支气管和肺段支气管分支夹角处，收纳肺内淋巴，输出管注入支气管肺门淋巴结，是肺内的第一级淋巴结。纵隔前、纵隔后淋巴结收纳纵隔器官淋巴。膈上淋巴结位于膈上，气管旁淋巴结沿气管两侧排列"},{"q":"输出淋巴管参与组成肠干的淋巴结是","o":["髂外淋巴结","腰淋巴结","肠系膜上淋巴结","髂内淋巴结","髂总淋巴结"],"a":2,"e":"肠干由腹腔淋巴结、肠系膜上淋巴结和肠系膜下淋巴结的输出淋巴管汇合而成，肠系膜上淋巴结位于肠系膜上动脉根部。腰淋巴结输出管汇成腰干，髂总、髂内、髂外淋巴结的输出管汇成髂干，均不参与组成肠干"},{"q":"关于主动脉弓正确的说法是","o":["位于胸骨角平面之下","自左前方弯向右后方","分支有头臂干、右颈总动脉和右锁骨下动脉","弓的下缘借动脉韧带连于肺动脉","前方有气管，后方有食管"],"a":3,"e":"动脉韧带连于肺动脉干分叉处稍左侧与主动脉弓下缘之间，为动脉导管闭锁的遗迹。主动脉弓位于胸骨角平面以上，自右前方弯向左后方。其凸侧发出头臂干、左颈总动脉和左锁骨下动脉，前方有胸腺，后方才邻气管和食管"},{"q":"尿道球腺开口于","o":["膀胱","尿道前列腺部","尿道球部","尿道膜部","舟状窝"],"a":2,"e":"尿道球腺位于会阴深横肌内，输出管开口于尿道球部，即尿道海绵体内尿道球部的膨大处。尿道前列腺部有前列腺导管开口，尿道膜部穿尿生殖膈，舟状窝为海绵体部前端的膨大，均无尿道球腺开口。尿道有三个狭窄、三个膨大和两个弯曲，尿道球部属膨大之一"},{"q":"有面神经通过的孔是","o":["颈静脉孔","破裂孔","卵圆孔","茎乳孔","枕骨大孔"],"a":3,"e":"面神经经内耳门入内耳道，穿内耳道底入面神经管，最后自茎乳孔出颅。颈静脉孔通过舌咽、迷走、副神经及颈内静脉，卵圆孔通过下颌神经，破裂孔有脑膜中动脉分支及岩深神经通过，枕骨大孔通过延髓"},{"q":"杏仁体错误的是","o":["它与情绪的产生有关","按功能上分，杏仁体不属于基底核","不属于边缘系统","它是内脏活动皮质下中枢","杏仁体位于海马旁回钩的深面"],"a":2,"e":"杏仁体位于侧脑室下角前端上方、海马旁回钩深面，与尾状核末端相连，为边缘系统的皮质下中枢，与内脏活动调节和情绪产生有关。它按功能归属基底核，也是边缘系统的重要组成，故不属于边缘系统之说错误"},{"q":"桡腕关节属于","o":["屈戌关节","车轴关节","椭圆关节","鞍状关节","球窝关节"],"a":2,"e":"桡腕关节由手舟骨、月骨、三角骨近侧关节面与桡骨腕关节面及尺骨头下方关节盘构成，关节头呈椭圆凸面，属典型椭圆关节。屈戌关节仅有屈伸一个轴，车轴关节绕垂直轴旋转，鞍状关节见于拇指腕掌关节，球窝关节见于肩、髋"},{"q":"可使足跖屈和外翻的肌是","o":["腓肠肌","胫骨前肌","胫骨后肌","腓骨长肌","比目鱼肌"],"a":3,"e":"腓骨长肌起自腓骨外侧面，肌腱经外踝后方转向前，止于内侧楔骨和第一跖骨底，收缩使足跖屈并外翻。腓肠肌和比目鱼肌只使足跖屈。胫骨前肌使足背屈并内翻，胫骨后肌使足跖屈并内翻。腓骨短肌亦使足外翻并跖屈，止于第5跖骨粗隆，作用较弱"},{"q":"关于桡动脉的描述错误是","o":["为肱动脉的分支之一","沿肱桡肌内侧深面下行","至桡骨下端，弯行向手背","主干末端参与构成掌浅弓","在腕部常取此动脉摸脉"],"a":3,"e":"桡动脉末端穿第一掌骨间隙入掌深部，与尺动脉掌深支吻合形成掌深弓；其掌浅支才与尺动脉末端构成掌浅弓。桡动脉沿肱桡肌内侧下行，至桡骨下端绕茎突转向手背，腕部桡侧是常用诊脉部位。桡动脉掌浅支尚发支分布于鱼际，拇主要动脉供应拇指两侧缘"},{"q":"加强肩关节囊上壁的韧带是","o":["喙肱韧带","盂肱上韧带","盂肱中韧带","盂肱下韧带","喙肩韧带"],"a":0,"e":"喙肱韧带起自喙突根部，止于肱骨大结节前面，位于关节囊上壁并融入纤维层，加强肩关节上壁。盂肱上、中、下韧带位于关节囊前壁，加强前壁。喙肩韧带连于喙突与肩峰之间，构成喙肩弓，防止肱骨头向上脱位"},{"q":"面神经不含下列哪种纤维成分","o":["特殊内脏运动纤维","一般内脏运动纤维","特殊内脏感觉纤维","一般躯体运动纤维","一般躯体感觉纤维"],"a":3,"e":"面神经含特殊内脏运动、一般内脏运动、特殊内脏感觉和一般躯体感觉四种纤维，不含一般躯体运动纤维。一般躯体运动纤维仅见于动眼、滑车、展和舌下神经，支配眼球外肌和舌肌。面肌由特殊内脏运动纤维支配"},{"q":"关于巩膜静脉窦，叙述正确的是","o":["位于角膜内","位于虹膜内","角膜缘处的巩膜实质内","巩膜静脉窦垂直穿出眼球壁","与房水的循环无关"],"a":2,"e":"巩膜静脉窦位于角膜缘处的巩膜实质内，为环形腔隙，是房水回流的通道，房水经此入睫状前静脉。它不在角膜或虹膜内，也不垂直穿出眼球壁。其与房水循环直接相关，闭塞可致眼压升高。该窦呈环形，前方与巩膜沟相邻，是青光眼发病的关键部位之一"},{"q":"关节囊滑膜的特征不包括","o":["滑膜构成关节囊的内层","富有血管网，覆盖于关节软骨表面","主要由疏松结缔组织构成","可产生滑液，能够提供营养","内面有许多滑膜绒毛"],"a":1,"e":"滑膜衬于纤维膜内面，由疏松结缔组织构成，富含血管网，能产生滑液营养关节软骨，内面常形成滑膜绒毛。它仅附着于关节软骨周缘，不覆盖软骨表面，覆盖关节软骨表面不是滑膜的特征。关节唇和关节盘亦无滑膜覆盖，滑膜只包被关节内其余结构"},{"q":"组成肌腱袖的肌不包括","o":["肩胛下肌","冈上肌","冈下肌","三角肌","小圆肌"],"a":3,"e":"肌腱袖由肩胛下肌、冈上肌、冈下肌和小圆肌的肌腱止于肱骨大、小结节处共同构成，贴附并加强肩关节囊。三角肌覆盖于肩关节外侧，止于肱骨三角肌粗隆，属上肢带肌，不参与肌腱袖组成。四肌肌腱融合成袖状，是肩关节稳定的重要结构，冈上肌最易损伤"},{"q":"肝胰壶腹开口于","o":["十二指肠上部","十二指肠大乳头","十二指肠升部","十二指肠水平部","十二指肠球部"],"a":1,"e":"肝胰壶腹由胆总管与胰管汇合形成，开口于十二指肠降部后内侧壁的十二指肠大乳头，距中切牙约75cm。十二指肠上部近幽门处为十二指肠球，属腹膜内位。水平部和升部无胆胰管开口，副胰管开口于大乳头上方的小乳头"},{"q":"头面部浅感觉通路的第三级神经元胞体在","o":["腹前核","底丘脑核","背侧丘脑腹后内侧核","背侧丘脑腹后外侧核","背侧丘脑腹外侧核"],"a":2,"e":"头面部浅感觉传导通路的第3级神经元胞体位于背侧丘脑腹后内侧核，发出纤维经内囊后肢投射至中央后回下部。腹后外侧核接受内侧丘系和脊髓丘系，传导躯干四肢感觉。腹前核、腹外侧核属运动性核团，底丘脑核属锥体外系"},{"q":"关于颈内静脉的正确描述是","o":["延续于海绵窦","位于颈动脉鞘内","与面静脉汇合成锁骨下静脉","属支有颈外静脉和面静脉","缺乏静脉瓣"],"a":1,"e":"颈内静脉于颈静脉孔处续于乙状窦，在颈动脉鞘内沿颈总动脉外侧下行，至胸锁关节后方与锁骨下静脉合成头臂静脉。其颅内属支为乙状窦和岩下窦，颅外属支有面静脉、舌静脉等。延续于海绵窦的是眼上静脉，颈外静脉注入锁骨下静脉"},{"q":"对下列上肢浅静脉的描述正确的是","o":["头静脉收集前臂尺侧浅层的静脉血","贵要静脉收集前臂桡侧浅层的静脉血","肘正中静脉连接头静脉与贵要静脉","前臂正中静脉收集手背的静脉血","上肢浅静脉的静脉血直接汇入锁骨下静脉"],"a":2,"e":"肘正中静脉在肘窝处连接头静脉与贵要静脉，变异较多，是临床采血和注射的常用血管。头静脉收集手和前臂桡侧浅层静脉血，贵要静脉收集尺侧。前臂正中静脉起自手掌静脉丛注入肘正中静脉，上肢浅静脉最终汇入腋静脉或锁骨下静脉"},{"q":"可伸肘关节和内收肩关节的肌是","o":["肱二头肌","肱三头肌","肱桡肌","旋前圆肌","旋后肌"],"a":1,"e":"肱三头肌长头起自盂下结节，止于尺骨鹰嘴，主伸肘；长头跨越肩关节，可使肩关节后伸和内收。肱二头肌和肱桡肌均屈肘，旋前圆肌、旋后肌为前臂旋转肌。伸肘并内收肩关节者为肱三头肌。肱三头肌受桡神经支配，其长头还可协助肩关节后伸"},{"q":"腭扁桃体位于","o":["扁桃体上窝内","扁桃体小窝内","咽隐窝内","腭咽弓后方的窝内","腭舌弓与腭咽弓之间的窝内"],"a":4,"e":"腭扁桃体位于腭舌弓与腭咽弓之间的三角形凹陷内，该窝称扁桃体窝。咽隐窝位于鼻咽侧壁咽鼓管圆枕后方，是鼻咽癌好发部位。扁桃体小窝为扁桃体表面的上皮凹陷，扁桃体上窝位于其上方，均非扁桃体所在的窝"},{"q":"关于交感神经交通支的叙述，错误的是","o":["分为灰、白交通支","白交通支含有节前纤维","灰交通支含有节后纤维","胸、腰神经均有白交通支","每对脊神经均有灰交通支"],"a":3,"e":"白交通支由节前纤维组成，仅见于T1～L3脊神经，共15对；灰交通支由节后纤维组成，连于全部31对脊神经。腰神经中仅L1～L3有白交通支，L4、L5无，故胸、腰神经均有白交通支之说错误"},{"q":"通过棘孔的结构是","o":["上颌神经","下颌神经","脑膜中动脉","上颌动脉","副神经"],"a":2,"e":"脑膜中动脉为上颌动脉分支，经棘孔入颅，分布于硬脑膜和颅骨，前支经翼点内面，骨折时易致硬膜外血肿。下颌神经经卵圆孔出颅，上颌神经经圆孔出颅。上颌动脉为脑膜中动脉的母支，位于颅外。副神经经颈静脉孔出颅"},{"q":"与桡骨头关节凹组成肱桡关节的结构是","o":["尺骨滑车切迹","肱骨小头","尺骨桡切迹","桡骨尺切迹","桡骨环状关节面"],"a":1,"e":"肱桡关节由肱骨小头与桡骨头关节凹构成，属肘关节的一部分。肱尺关节由肱骨滑车与尺骨滑车切迹构成。尺骨桡切迹与桡骨头环状关节面构成桡尺近侧关节，桡骨尺切迹与尺骨头相关节，均不参与肱桡关节"},{"q":"缩短循环途径，调节局部血流量的是","o":["血管吻合","动脉间吻合","静脉间吻合","动、静脉吻合","侧支吻合"],"a":3,"e":"小动脉与小静脉之间借血管支直接相连形成动、静脉吻合，见于指尖、唇、鼻及勃起组织，可缩短循环途径、调节局部血流量和体温。动脉间吻合与静脉间吻合主要平衡血流分配。侧支吻合在主干阻塞时起代偿供血作用"},{"q":"支配瞳孔括约肌的神经是","o":["动眼神经的交感神经纤维","动眼神经的副交感神经纤维","眼神经的交感神经纤维","三叉神经的副交感神经纤维","面神经的交感神经纤维"],"a":1,"e":"瞳孔括约肌由动眼神经副核发出的副交感节前纤维经睫状神经节换元后支配，收缩时瞳孔缩小。交感纤维经颈上神经节支配瞳孔开大肌，使瞳孔扩大。眼神经为三叉神经第1支，属感觉神经，不支配平滑肌"},{"q":"不属于副交感神经节的是","o":["下颌下神经节","耳神经节","翼腭神经节","膝状神经节","睫状神经节"],"a":3,"e":"颅部副交感神经节共4对，即睫状神经节、翼腭神经节、耳神经节和下颌下神经节。膝状神经节为面神经的感觉神经节，含假单极神经元胞体，传导舌前2/3味觉及耳部皮肤感觉，不属副交感神经节。四个副交感神经节内均有交感根和感觉根穿过而不换元"},{"q":"与鼓室不相连通的结构是","o":["外耳道","咽鼓管","乳突窦","乳突小房","耳蜗"],"a":4,"e":"鼓室向前经咽鼓管通鼻咽，向后经鼓窦入口通乳突窦及乳突小房，向外借鼓膜与外耳道相隔。耳蜗位于内耳，属骨迷路，借前庭窗与鼓室相隔，蜗管内淋巴与鼓室不相通。与鼓室不相连通者为耳蜗。鼓室盖与鼓室相邻，中耳炎可经此波及颅中窝"},{"q":"髋关节属于","o":["屈戌关节","车轴关节","椭圆关节","鞍状关节","球窝关节"],"a":4,"e":"髋关节由髋臼与股骨头构成，属多轴球窝关节，可作屈伸、收展、旋转和环转运动。其髋臼深、韧带强韧，运动幅度较肩关节小。屈戌关节仅一个运动轴，车轴关节绕垂直轴旋转，椭圆关节和鞍状关节均属双轴关节"},{"q":"鼻泪管开口于","o":["下鼻道","上鼻道","中鼻道","泪点","泪囊"],"a":0,"e":"鼻泪管向下开口于下鼻道前上方，流泪时泪液经此流入鼻腔。上鼻道有筛窦后群开口，中鼻道有额窦、上颌窦和前筛窦开口。泪点为泪小管起始处，泪囊位于泪囊窝内，均非鼻泪管的开口部位。鼻泪管上接泪囊，下段位于骨性鼻泪管内，开口处黏膜静脉丛丰富"},{"q":"组成腕关节的结构不包括","o":["手舟骨","月骨","三角骨","豌豆骨","桡骨下端的关节面"],"a":3,"e":"桡腕关节由手舟骨、月骨、三角骨的近侧关节面与桡骨下端关节面及尺骨头下方关节盘构成。豌豆骨位于三角骨掌侧，属腕骨远侧列，不参与桡腕关节。组成腕关节的结构不包括豌豆骨。腕骨近侧列由桡侧向尺侧为手舟骨、月骨、三角骨和豌豆骨"},{"q":"第四脑室","o":["位于延髓、脑桥和中脑之间","底由上髓帆、下髓帆和第四脑室脉络组织组成","底为脑桥和中脑背侧面构成的菱形窝","经室间孔与侧脑室直接相通","脑脊液经单一的第四脑室正中孔和成对的第四脑室外侧孔通入蛛网膜下隙"],"a":4,"e":"第四脑室顶由前髓帆、后髓帆和第四脑室脉络组织构成，脑脊液经单一的正中孔和成对的外侧孔流入蛛网膜下隙。第四脑室位于延髓、脑桥和小脑之间，经中脑导水管通第三脑室；经室间孔与侧脑室相通的是第三脑室。其底为菱形窝，由延髓上部和脑桥背侧面构成"},{"q":"临床行胃大部分切除术时需要结扎的胃左动脉来源于","o":["腹腔干","肝总动脉","脾动脉","胃网膜右动脉","肠系膜上动脉"],"a":0,"e":"胃左动脉在膈主动脉裂孔稍下方直接起自腹腔干，是腹腔干三大分支之一。肝总动脉与脾动脉为腹腔干的另两支，胃网膜右动脉发自胃十二指肠动脉。肠系膜上动脉供应中肠，不发出胃左动脉。腹腔干分支分布于食管腹段、胃、十二指肠、肝、胆、胰和脾"},{"q":"胸廓的组成不包括","o":["胸骨","12对肋","12块胸椎","肋椎关节","胸锁关节"],"a":4,"e":"胸廓由12块胸椎、12对肋、1块胸骨及肋椎关节、胸肋关节共同构成。胸锁关节连接锁骨与胸骨柄，属上肢带骨连结，不参与胸廓构成。肋椎关节和胸肋关节才是胸廓的组成部分。胸廓上口由胸骨柄上缘、第1肋和第1胸椎围成，下口被膈封闭"},{"q":"关节盘的特征不包括","o":["膝关节的关节盘称半月板","将关节腔分为两部","是透明软骨板","有利于运动","周缘附着于关节囊"],"a":2,"e":"关节盘位于两关节面之间，周缘附着于关节囊，将关节腔分为两部分，可缓冲震荡并增加运动形式，膝关节的关节盘称半月板。关节盘由纤维软骨构成，并非透明软骨，是透明软骨板不属其特征。关节盘可使两关节面更为适合，缓冲冲击，并增加关节运动形式"},{"q":"含有假单极神经元的部位是","o":["副交感神经节内","交感神经节内","基底核内","脊神经节内","前庭神经节内"],"a":3,"e":"脊神经节内为假单极神经元胞体，其周围突分布至感受器，中枢突经后根入脊髓。交感神经节和副交感神经节内为多极神经元，属节后神经元。基底核为中枢灰质核团。前庭神经节含双极神经元，不属假单极"},{"q":"支配腮腺的副交感节前纤维的胞体位于","o":["动眼神经副核","迷走神经背核","孤束核","上泌涎核","下泌涎核"],"a":4,"e":"下泌涎核发出副交感节前纤维，经舌咽神经鼓室神经、岩小神经至耳神经节换元，节后纤维经耳颞神经支配腮腺。上泌涎核支配泪腺、下颌下腺和舌下腺。动眼神经副核支配瞳孔括约肌和睫状肌，迷走神经背核支配胸腹腔脏器"},{"q":"心前壁主要由哪部分心腔构成","o":["左心室","右心室","左心房","右心房","腔静脉窦"],"a":1,"e":"右心室前壁介于右冠状沟、前室间沟、心右缘与肺动脉口平面之间，构成胸肋面即心前壁的大部分。左心室构成心尖和膈面大部分。左、右心房位于心的后上方，腔静脉窦为右心房后部的光滑区。右心室流入道内有乳头肌、肉柱和三尖瓣复合体，流出道为动脉圆锥"},{"q":"关于子宫的正确描述是","o":["位于小骨盆腔内，属腹膜内位器官","上端宽而圆凸的部分为子宫体","颈下端在坐骨棘平面稍下方","子宫颈与阴道上部相接处狭窄称子宫峡","正常位置为前倾前屈位"],"a":4,"e":"成年人膀胱空虚时子宫呈轻度前倾前屈位，前倾为子宫长轴与阴道长轴的钝角，前屈为体与颈之间的钝角。子宫属腹膜间位器官，仅子宫底和体上部有腹膜覆盖。子宫颈下端位于坐骨棘平面稍上方，子宫峡在颈与体相接处而非颈与阴道相接处"},{"q":"经白质前连合交叉至对侧形成的纤维束是","o":["薄、楔束","脊髓丘脑束","红核脊髓束","皮质脊髓前束","皮质脊髓侧束"],"a":1,"e":"脊髓丘脑束起自脊髓灰质Ⅰ、Ⅳ～Ⅷ层，纤维上升1～2节段后经白质前连合交叉至对侧，组成脊髓丘脑侧束和前束。薄束、楔束在同侧后索上行，不交叉。红核脊髓束起自中脑红核。皮质脊髓侧束在延髓锥体交叉，皮质脊髓前束主要在同侧前索下行"},{"q":"神经系统","o":["基本组织是神经胶质","结构和功能的基本单位是神经元","神经胶质主要是感受刺激","胶质细胞也有传导神经冲动的功能","周围神经只包括脑神经和脊神经"],"a":1,"e":"神经元是神经系统结构和功能的基本单位，具有感受刺激和传导冲动的功能。神经胶质是基本组织之一，主要起支持、营养、保护和绝缘作用，无传导冲动功能。周围神经还包括内脏神经，并非只有脑神经和脊神经"},{"q":"脊髓第8胸节平对","o":["第2胸椎","第3胸椎","第4胸椎","第5胸椎","第6胸椎"],"a":4,"e":"脊髓节段与椎骨序数对应为：上胸髓平对同序数椎骨减1，中胸髓T5～T8平对同序数椎骨减2，故第8胸节平对第6胸椎。下胸髓平对同序数减3。颈髓5～8和上胸髓平对同序数减1，与本题不符"},{"q":"骶骨的形态结构特征包括","o":["有5对骶前孔","由4块骶椎融合而成","与第4腰椎相关节","骶管内有脊髓通过","于骶角处可寻骶管裂孔进行神经阻滞麻醉"],"a":4,"e":"骶管裂孔位于骶骨下端，两侧有向下突出的骶角，临床以骶角为标志行骶管麻醉。骶骨由5块骶椎融合而成，盆面有4对骶前孔。骶骨底与第5腰椎相关节。骶管内通过马尾及终丝，脊髓下端平第1腰椎下缘，已不进入骶管"},{"q":"甲状颈干的分支有","o":["甲状腺下动脉","颈升动脉","肩胛下动脉","甲状腺上动脉","肩胛背动脉"],"a":0,"e":"甲状颈干在椎动脉外侧起自锁骨下动脉，迅即分出甲状腺下动脉、肩胛上动脉、颈横动脉等。甲状腺上动脉为颈外动脉首个分支。肩胛下动脉发自腋动脉，肩胛背动脉多起自颈横动脉或锁骨下动脉，均非甲状颈干直接分支"},{"q":"分布于肺的神经","o":["内脏大神经","内脏小神经","内脏最小神经","肋下神经","迷走神经"],"a":4,"e":"迷走神经的支气管支与肺支加入肺丛，其副交感纤维支配支气管平滑肌和腺体，传入纤维传导肺的感觉。内脏大、小神经和内脏最小神经为交感节前纤维，支配腹腔脏器血管。肋下神经为胸神经前支，分布于腹壁"},{"q":"关于睾丸的描述不正确的是","o":["后缘有附睾体尾附着","精曲小管上皮合成和分泌雌性激素","睾丸上端被附睾头遮盖","后缘白膜增厚，凸入睾丸内形成睾丸纵隔","从睾丸网发出12～15条睾丸输出小管进入附睾"],"a":1,"e":"生精小管上皮产生精子，雄性激素由生精小管之间结缔组织内的间质细胞分泌，故精曲小管上皮合成和分泌雌性激素之说错误。睾丸上端被附睾头遮盖，后缘有附睾体、尾附着；白膜在后缘增厚形成睾丸纵隔，睾丸网发出12～15条输出小管入附睾"},{"q":"不参与组成大脑动脉环的动脉","o":["大脑前动脉","大脑中动脉","大脑后动脉","前交通动脉","后交通动脉"],"a":1,"e":"大脑动脉环由前交通动脉、两侧大脑前动脉、两侧颈内动脉、两侧后交通动脉和两侧大脑后动脉构成。大脑中动脉为颈内动脉的直接延续，向外侧入外侧沟，不参与此环。不参与组成者为大脑中动脉。大脑动脉环位于脑底蝶鞍上方，围绕视交叉、灰结节和乳头体"},{"q":"下腔静脉的直接接纳的静脉是","o":["肝门静脉","肝静脉","脾静脉","胃左静脉","胃右静脉"],"a":1,"e":"肝左、中、右静脉在腔静脉沟上端即第二肝门处出肝，直接注入下腔静脉。肝门静脉由肠系膜上静脉与脾静脉汇合而成，收集腹腔不成对脏器的静脉血，入肝后逐级分支。脾静脉、胃左静脉和胃右静脉均为肝门静脉系属支，不直接入下腔静脉"},{"q":"通过海绵窦与颈内动脉伴行的神经","o":["动眼神经","滑车神经","眼神经","上颌神经","展神经"],"a":4,"e":"展神经穿海绵窦，在窦内沿颈内动脉外下方前行，与颈内动脉伴行，经眶上裂入眶支配外直肌。动眼神经、滑车神经、眼神经和上颌神经均行于海绵窦外侧壁，不与颈内动脉伴行。通过海绵窦与颈内动脉伴行者是展神经"},{"q":"动眼神经含有的副交感纤维来源于","o":["滑车神经核","展神经核","动眼神经核","E-W核","三叉神经运动核"],"a":4,"e":"官方答案为【三叉神经运动核】，但依据教材，正确答案为【E-W核】。动眼神经的副交感节前纤维起自动眼神经副核，即E-W核，经睫状神经节换元后支配瞳孔括约肌和睫状肌。三叉神经运动核属特殊内脏运动核，发出纤维支配咀嚼肌，与动眼神经无关。动眼神经核发出躯体运动纤维，支配眼球外肌"},{"q":"关于淋巴结的描述正确的是","o":["青年人有100个","当中凹陷为淋巴结门","可称为淋巴组织","基本上为深淋巴结","和免疫反应无关"],"a":1,"e":"淋巴结一侧隆凸连输入淋巴管，另一侧凹陷，凹陷中央为淋巴结门，有输出淋巴管、神经和血管出入。淋巴结属淋巴器官，不是淋巴组织。人体淋巴结数量远多于100个，且分浅、深两群，并非基本为深淋巴结。其主要功能为滤过淋巴和进行免疫应答"},{"q":"关于指压法压迫止血描述正确的是","o":["当前臂和手部出血时，肱动脉的常用指压法止血部位在肱动脉的起始段","手指出血时，采用指压法进行止血的部位应在手指的两侧","头皮出血时，常用的指压法压迫止血点在口角处","面部出血时，常用的指压法压迫止血点在咬肌后缘与下颌骨下缘交界处","头皮出血时，常用的指压法压迫止血点在内眦"],"a":1,"e":"指掌侧固有动脉行于手指两侧，手指出血时在指根两侧向指骨压迫即可止血。肱动脉压迫点在臂中部肱二头肌内侧沟，非起始段。面动脉压迫点在下颌骨下缘与咬肌前缘交界处，颞浅动脉压迫点在耳屏前方，均不在口角或内眦"},{"q":"上纵隔最前方的结构是","o":["左、右头臂静脉","上腔静脉","气管","主动脉弓","胸腺"],"a":4,"e":"上纵隔内结构自前向后依次为胸腺、左头臂静脉、右头臂静脉、上腔静脉、膈神经、迷走神经、主动脉弓及其三大分支，最后为气管、食管和胸导管。最前方者为胸腺，头臂静脉和上腔静脉位于其后，气管居后部"},{"q":"十二指肠大乳头","o":["位于十二指肠水平部","距中切牙65cm","位于十二指肠环形皱襞上","上面有肝胰壶腹的开口","其下方有十二指肠小乳头"],"a":3,"e":"十二指肠大乳头为肝胰壶腹的开口处，位于十二指肠降部后内侧壁纵行皱襞的下端，距中切牙约75cm。十二指肠小乳头位于大乳头上方1～2cm，为副胰管开口。水平部无乳头结构，距中切牙65cm与实测不符"},{"q":"关于骨迷路描述，错误的是","o":["骨迷路是由骨密质构成的不规则的腔与管","由耳蜗、前庭和骨半规管构成，沿颞骨岩部的长轴排列","前庭后上部有5个小孔与3个半规管相通","前庭外侧壁有前庭窗和蜗窗","前庭窗由第一鼓膜封闭，蜗窗由第二鼓膜封闭"],"a":4,"e":"前庭窗由镫骨底封闭，蜗窗由第二鼓膜封闭，第一鼓膜之说不能成立。骨迷路由骨密质围成，分耳蜗、前庭和骨半规管，沿颞骨岩部长轴排列。前庭后上部有5个小孔通骨半规管，外侧壁有前庭窗和蜗窗"},{"q":"鼻腔嗅区黏膜存在于","o":["鼻翼","上鼻甲","中鼻甲","下鼻甲","鼻前庭"],"a":1,"e":"嗅区位于上鼻甲、与其相对的鼻中隔及二者上方鼻腔顶部，黏膜内含嗅细胞。中鼻甲、下鼻甲黏膜属呼吸区，富含鼻腺。鼻前庭为鼻翼内侧的腔隙，覆以皮肤。鼻翼不含嗅黏膜。嗅区黏膜呈棕黄色，呼吸区黏膜呈粉红色，两者色泽与腺体分布不同"},{"q":"与肩胛骨的关节盂组成肩关节的结构是","o":["肱骨头","肱骨大结节","肱骨小结节","肱骨外科颈","肱骨解剖颈"],"a":0,"e":"肩关节由肱骨头与肩胛骨关节盂构成，称盂肱关节，为典型多轴球窝关节。肱骨大、小结节为肌腱附着处，不参与关节面。肱骨外科颈为骨折好发部位，解剖颈为头周围的环状浅沟，均非关节的组成结构"},{"q":"属于非特异性投射核团的是","o":["腹前核","腹外侧核","腹后内侧核","腹后外侧核","中线核"],"a":4,"e":"非特异性投射核团属原丘脑，包括中线核、板内核和网状核，接受脑干网状结构传入，弥散投射至大脑皮质。腹前核、腹外侧核属特异性中继核，参与运动调节。腹后内侧核和腹后外侧核为特异性感觉接替核"},{"q":"迷走神经不支配","o":["环甲肌","乙状结肠","咽中缩肌","胃","十二指肠"],"a":1,"e":"迷走神经副交感纤维支配结肠左曲以上的消化管，包括胃、十二指肠和横结肠；乙状结肠位于结肠左曲以下，由盆内脏神经支配。环甲肌由喉上神经外支支配，咽中缩肌由咽丛支配，二者均属迷走神经分支范围"},{"q":"损伤一侧大脑皮质躯体运动区可导致","o":["对侧肢体瘫痪和肌张力减退","对侧肢体瘫痪并伴有感觉障碍","对侧肢体震颤并伴有肌张力增强","同侧共济运动障碍和感觉障碍","对侧肢体瘫痪和肌张力增强"],"a":4,"e":"一侧大脑皮质躯体运动区损伤属上运动神经元瘫，表现为对侧肢体痉挛性瘫痪，肌张力增高、腱反射亢进、浅反射消失。皮质运动区不含感觉神经元，故不伴感觉障碍。震颤及肌张力增强见于锥体外系病变，共济障碍见于小脑损伤"},{"q":"男性输精管结扎常选择在哪个部位进行","o":["睾丸部","精索部","盆部","腹股沟管部","壶腹部"],"a":1,"e":"输精管精索部介于睾丸上端与腹股沟管皮下环之间，位置表浅易于触及，是结扎的理想部位。睾丸部位置过低且邻近附睾，盆部深在，腹股沟管部位于管内，壶腹部已膨大，均不适宜结扎。结扎后精子不能排出，但间质细胞分泌雄激素不受影响"},{"q":"一侧皮质核束","o":["只支配对侧动眼神经核","只支配对侧动眼神经副核","支配双侧面神经核","只支配对侧舌下神经核","只支配对侧疑核"],"a":3,"e":"皮质核束小部分纤维交叉至对侧，终止于面神经核支配面下部肌的神经元和舌下神经核，故二者仅接受对侧支配。动眼神经核、动眼神经副核、疑核及面神经核上部均接受双侧皮质核束纤维，不呈单侧支配"},{"q":"有肋凹的椎骨是","o":["第1颈椎","第2颈椎","第7颈椎","胸椎","腰椎"],"a":3,"e":"胸椎椎体两侧面后份的上、下缘有半圆形肋凹，与肋头相关节，第1、10～12胸椎另有全肋凹。颈椎横突有横突孔，第6颈椎横突末端有颈动脉结节。腰椎无肋凹，横突有乳突和副突。有肋凹者为胸椎"},{"q":"在骨连结中，骨性连结包括","o":["骺软骨","前臂骨间膜","耻骨连合","椎间盘","髂骨、坐骨和耻骨合成髋骨"],"a":4,"e":"髂骨、坐骨和耻骨在髋臼处融合，16岁左右完全骨化，属骨性连结。骺软骨为透明软骨结合，前臂骨间膜为纤维连结，耻骨联合和椎间盘均为纤维软骨结合。属骨性连结者只有三骨合成髋骨。纤维连结和软骨连结均保留一定活动度，骨性连结则完全不能活动"},{"q":"舌咽神经分布不包括","o":["腮腺","颈动脉窦","舌前2/3味觉","舌后1/3味觉","鼓室"],"a":2,"e":"舌前2/3味觉由面神经鼓索传导，舌后1/3味觉才由舌咽神经传导。舌咽神经还发出腮腺支、颈动脉窦支和鼓室神经，分布至腮腺、颈动脉窦、鼓室及咽部黏膜。不属其分布者为舌前2/3味觉。舌咽神经还支配茎突咽肌，损伤后咽反射减弱或消失"},{"q":"视觉传导通路中的第2级神经元是","o":["视锥细胞","视杆细胞","双极细胞","节细胞","外侧膝状体"],"a":3,"e":"视觉传导路由3级神经元组成，视锥、视杆细胞为感受器，双极细胞为第1级神经元，节细胞为第2级神经元，其轴突汇成视神经。第3级神经元胞体位于外侧膝状体。第2级神经元是节细胞。视神经损伤后节细胞变性，视网膜鼻侧半纤维交叉至对侧视束"},{"q":"腹前外侧群的肌肉不包括","o":["腹外斜肌","腹内斜肌","腹横肌","腰大肌","腹直肌"],"a":3,"e":"腹前外侧群肌包括腹外斜肌、腹内斜肌、腹横肌和腹直肌，参与维持腹内压和脊柱运动。腰大肌位于腹后壁，属腹后群肌，与髂肌合成髂腰肌，主要屈髋关节，不属腹前外侧群。腹直肌位于腹前壁正中线两侧，腹外斜肌、腹内斜肌和腹横肌由浅入深"},{"q":"女性外阴部发生炎症后，最容易形成囊肿的部位是","o":["大阴唇","小阴唇","阴阜","阴蒂","前庭大腺"],"a":4,"e":"前庭大腺位于大阴唇后部、前庭球后端深面，导管开口于阴道前庭，炎症时导管阻塞易形成前庭大腺囊肿。大阴唇、小阴唇为皮肤皱襞，阴阜为脂肪垫，阴蒂由海绵体构成，均无分泌导管，不易形成囊肿"},{"q":"下述哪一项包含在淋巴系统的组成中","o":["组织液","毛细血管","淋巴器官","淋巴小结","脾髓"],"a":2,"e":"淋巴系统由淋巴管道、淋巴组织和淋巴器官组成，淋巴器官包括淋巴结、胸腺、脾和扁桃体。组织液是血液经毛细血管滤过形成的，毛细血管属心血管系统。淋巴小结属淋巴组织，脾髓为脾的实质，均非系统组成的一级结构"},{"q":"视神经","o":["外包三层膜，为相应脑膜的延续","经眶上裂入颅中窝","为双极神经元的中枢突组成","完全受损，伤侧全盲且瞳孔对光反射消失","连于端脑"],"a":0,"e":"视神经由视网膜节细胞的轴突汇集而成，外包硬脑膜、蛛网膜和软脑膜三层，蛛网膜下隙与脑的相通。它经视神经管入颅，连于间脑而非端脑。视神经完全损伤时伤侧眼全盲，直接对光反射消失，间接对光反射仍存在"},{"q":"分泌雄性激素的是","o":["睾丸间质细胞","睾丸网","精囊","白膜","前列腺"],"a":0,"e":"睾丸间质细胞位于生精小管之间的结缔组织内，分泌雄性激素。睾丸网为生精小管汇合形成的管道，精囊和前列腺为附属腺，分泌物参与精液组成。白膜为睾丸表面的致密结缔组织被膜，均无内分泌功能"},{"q":"一男性患者，左侧内囊出血，导致右侧视野偏盲，其因是视辐射通过","o":["豆状核下部","豆状核后部","豆丘部","豆状核与尾状核之间","内囊前肢与后肢之间"],"a":1,"e":"视辐射由外侧膝状体至视皮质，经内囊豆状核后部向后行，故该部出血致对侧同向性偏盲。内囊前肢行额桥束，膝部行皮质核束，豆丘部行皮质脊髓束和丘脑中央辐射，豆状核下部行听辐射及颞桥束，均与视觉传导无关"},{"q":"小脑扁桃体","o":["属于古小脑","属于小脑的淋巴组织","位于小脑下面靠近枕骨大孔处","位于小脑上面靠近小脑幕切迹处","属于旧小脑"],"a":2,"e":"小脑扁桃体位于小脑半球下面、蚓部两侧，紧邻延髓和枕骨大孔，颅内压增高时可被挤入枕骨大孔形成小脑扁桃体疝。它属小脑半球的新小脑部分，非古小脑或旧小脑。小脑幕切迹处为颞叶海马旁回钩疝入的部位"},{"q":"损伤后导致肢体瘫痪的纤维束","o":["红核脊髓束","脊髓丘脑束","顶盖脊髓束","皮质脊髓侧束","皮质脊髓前束"],"a":3,"e":"皮质脊髓侧束由延髓锥体交叉后的纤维在对侧侧索下行，止于前角运动神经元，支配四肢肌，损伤后出现同侧肢体瘫痪。脊髓丘脑束传导痛温觉，红核脊髓束和顶盖脊髓束调节肌张力与反射。皮质脊髓前束支配躯干肌，损伤不引起肢体瘫痪"},{"q":"心底朝向","o":["右侧","右前方","右后方","后方","右后上方"],"a":4,"e":"心底朝向右后上方，主要由左心房和小部分右心房构成，与大血管根部相连。心尖朝向左前下方，由左心室构成。胸肋面朝向前上方，膈面朝向下后方。心底的朝向为右后上方。心底后方与食管、胸主动脉及肺静脉相邻，是心与大血管连接部"},{"q":"拇指腕掌关节属于","o":["屈戌关节","车轴关节","椭圆关节","鞍状关节","球窝关节"],"a":3,"e":"拇指腕掌关节由大多角骨与第1掌骨底构成，两关节面均呈鞍状，互为关节头和关节窝，属双轴鞍状关节，可作屈伸、收展、环转和对掌运动。屈戌关节仅一个轴，车轴关节绕垂直轴旋转，椭圆关节见于桡腕关节，球窝关节见于肩、髋"},{"q":"不是肠系膜上动脉分支的动脉是","o":["空肠动脉","回肠动脉","升结肠动脉","横结肠动脉","降结肠动脉"],"a":4,"e":"肠系膜上动脉发出空肠动脉、回肠动脉、回结肠动脉、右结肠动脉和中结肠动脉，供应结肠左曲以上肠管。降结肠由肠系膜下动脉发出的左结肠动脉供血，故降结肠动脉不属肠系膜上动脉分支。横结肠由中结肠动脉供应"},{"q":"既屈膝关节又屈髋关节的肌是","o":["股薄肌","缝匠肌","股四头肌","半膜肌","股二头肌"],"a":1,"e":"缝匠肌起自髂前上棘，止于胫骨上端内侧面，跨髋、膝两关节，可屈髋并屈膝，还能使已屈的膝旋内。股薄肌属内侧群，仅内收髋。股四头肌屈髋伸膝。半膜肌和股二头肌屈膝伸髋，作用方向与本题相反"},{"q":"有关颈总动脉的描述错误的是","o":["头颈部出血可压迫此动脉","左侧者发自头臂干","分杈处的后壁上有颈动脉小球","分支为颈内、外动脉","两侧均经胸锁关节后方"],"a":1,"e":"左颈总动脉直接起自主动脉弓，右颈总动脉起自头臂干，左侧者发自头臂干之说错误。两侧颈总动脉均经胸锁关节后方上行，至甲状软骨上缘分为颈内、颈外动脉。分叉处后壁有颈动脉小球，属化学感受器；颈动脉窦位于分叉处，可压迫止血"},{"q":"桡骨的形态结构不包括","o":["位于前臂的外侧，分为一体两端","上端有膨大的桡骨头","头下方变细称桡骨颈","颈的内下方有一突起称桡骨粗隆","桡骨茎突较尺骨茎突低1cm"],"a":4,"e":"桡骨位于前臂外侧，分一体两端，上端膨大为桡骨头，头下变细为桡骨颈，颈内下方有桡骨粗隆。生理情况下尺骨茎突较桡骨茎突高约1cm，桡骨茎突较尺骨茎突低1cm之说颠倒，不属桡骨形态特征"},{"q":"关于尺动脉描述正确的是","o":["行于肱桡肌肌腱与桡侧腕屈肌肌腱之间","其下段为临床上诊脉的常用部位","在尺侧腕屈肌与指浅屈肌之间下行","是掌深弓的主要组成动脉","其终末支为掌深支"],"a":2,"e":"尺动脉在尺侧腕屈肌与指浅屈肌之间下行，经豌豆骨桡侧至手掌，末端与桡动脉掌浅支吻合构成掌浅弓。行于肱桡肌腱与桡侧腕屈肌腱之间的是桡动脉，腕部诊脉部位亦为桡动脉。掌深弓由桡动脉末端与尺动脉掌深支构成"},{"q":"关于皮质脊髓侧束正确的是","o":["在脊髓外侧索前部下行","是小部分在延髓椎体交叉的纤维","其下行纤维终止于中间神经元","起于中央后回大椎体细胞","一侧脊髓损伤出现同侧肢体随意运动障碍"],"a":4,"e":"皮质脊髓侧束由延髓锥体交叉后的大部分纤维构成，行于脊髓侧索后部，止于同侧前角运动神经元，一侧脊髓损伤出现同侧肢体随意运动障碍。它起自中央前回，非中央后回。其纤维主要终止于前角运动神经元。外侧索前部为脊髓小脑前束"},{"q":"关于房室结的叙述，错误的是","o":["心肌收缩的起搏点","多由右冠状动脉的分支供应","位于房室交界区的中央部","病变后可引起异位搏动","具有延搁传导的作用"],"a":0,"e":"窦房结才是心的正常起搏点，房室结是重要的次级起搏点，具有传导延搁作用，病变时可引起异位搏动。房室结位于房室交界区中央部，多由右冠状动脉分支供应。心肌收缩的起搏点不是房室结的叙述。房室结位于Koch三角内，其前端发出房室束"},{"q":"硬脑膜窦","o":["内含动脉血","窦壁内有丰富的平滑肌","损伤后平滑肌收缩能自行止血","与颅外静脉无交通","由硬脑膜在某些部位两层分开，内衬内皮细胞构成"],"a":4,"e":"硬脑膜窦由硬脑膜两层在某些部位分开、内面衬以内皮细胞构成，窦内含静脉血，壁内无平滑肌，损伤后不能收缩止血。它与颅外静脉有广泛交通，如眼静脉、导静脉，与颅外静脉无交通之说错误。上矢状窦、横窦和乙状窦均属此类，最终汇入颈内静脉"},{"q":"不含有毛细血管的是","o":["骨","软骨","肌肉","舌","胃"],"a":1,"e":"毛细血管遍布全身，但角膜、晶状体、毛发、软骨、牙釉质和被覆上皮无毛细血管，软骨的营养靠基质渗透。骨、肌肉、舌和胃均有丰富的毛细血管网。不含毛细血管者为软骨。软骨无血管，营养由软骨膜血管经基质扩散供给，故修复能力弱"},{"q":"下列何结构受损伤，可致对侧偏身运动障碍","o":["红核脊髓束","皮质核束","皮质脊髓束","内囊后肢","内囊后肢和内囊膝"],"a":4,"e":"内囊膝部行皮质核束，后肢豆丘部行皮质脊髓束，二者损伤共同导致对侧偏身运动障碍即偏瘫。单纯皮质脊髓束损伤只引起肢体瘫，单纯皮质核束损伤表现为对侧核上瘫。内囊后肢的丘脑中央辐射损伤产生对侧偏身感觉障碍"},{"q":"分泌雌性激素的内分泌腺是","o":["甲状腺","甲状旁腺","卵巢","松果体","胸腺"],"a":2,"e":"卵巢为女性生殖腺，卵泡壁细胞产生雌激素和孕激素，排卵后黄体继续分泌二者。甲状腺分泌甲状腺激素，甲状旁腺分泌甲状旁腺激素调节钙磷代谢。松果体分泌褪黑素，胸腺分泌胸腺激素，均与雌激素无关"},{"q":"薄束和楔束","o":["起自肌、腱、关节和皮肤的感受器","止于脑桥的薄束核和楔束核","传导非意识性本体感觉信息","薄束位于后索外侧部，楔束位于内侧部","损伤后精细触觉丧失"],"a":4,"e":"薄、楔束传导同侧躯干四肢的本体感觉和皮肤精细触觉，损伤后精细触觉与位置觉、振动觉丧失。两束起自脊神经节假单极神经元的中枢突，止于延髓的薄束核和楔束核。薄束位于后索内侧部，楔束位于外侧部，方向与选项相反。二者传导意识性本体感觉"},{"q":"骨质的描述，不正确的是","o":["骨质分骨密质和骨松质","骨密质均分布于骨表面","颅盖骨的松质骨称为板障","颅盖的内板厚而紧韧","骨质均有骨组织构成"],"a":3,"e":"颅盖骨外板厚而坚韧、富有弹性，内板薄而松脆，骨折多见于内板。骨质分骨密质和骨松质，骨密质并非均匀分布于骨表面，扁骨为内外板夹板障。板障即颅盖骨的骨松质，内有板障静脉。骨质均由骨组织构成"},{"q":"关于肾上腺的描述，哪项错误","o":["左、右各一","左侧的近似半月形","右侧的呈三角形","分泌盐皮质激素","调节血钙平衡"],"a":4,"e":"血钙平衡由甲状旁腺激素和降钙素共同调节，与肾上腺无关。左、右肾上腺各一，左侧呈半月形，右侧呈三角形。肾上腺皮质分泌盐皮质激素、糖皮质激素和性激素，分别调节水盐代谢、糖代谢和第二性征"},{"q":"颈总动脉","o":["约平对甲状软骨上缘高度分出颈内动脉和颈外动脉","右侧的起自升主动脉","左侧的起自头臂干","走行于气管和喉的后方","颈动脉窦位于颈总动脉的起始处"],"a":0,"e":"颈总动脉在甲状软骨上缘高度分为颈内动脉和颈外动脉，分叉处称颈动脉杈。左颈总动脉起自主动脉弓，右颈总动脉起自头臂干。它沿气管、喉的外侧上行而非后方。颈动脉窦位于分叉处，不是起始处。颈动脉窦为压力感受器，受刺激可反射性引起心率减慢、血压下降"},{"q":"某患者手术中损伤右侧外侧丘系，下面关于外侧丘系的叙述，正确的是","o":["起始于双侧蜗神经核和上橄榄核","全部由对侧的蜗神经核发出的轴突形成","没有外侧丘系核的纤维参与","大部分纤维不交叉","右侧外侧丘系损伤导致双耳的听觉障碍"],"a":0,"e":"外侧丘系主要由双侧蜗神经核发出的二级纤维组成，并有双侧上橄榄核发出的三级纤维加入，故传导为双侧性。一侧外侧丘系损伤不引起明显耳聋，因听觉冲动可经双侧通路上行。大部分纤维交叉，并非全部来自对侧"},{"q":"子宫骶韧带的作用是","o":["固定子宫于骶骨前方","防止子宫脱垂","牵引子宫颈向后上","牵引子宫底向前下","防止子宫倾向一侧"],"a":2,"e":"子宫骶韧带从子宫颈后面上外侧向后绕过直肠两侧，止于第2、3骶椎前面筋膜，牵引子宫颈向后上，协同圆韧带维持前倾前屈位。防止子宫脱垂的是子宫主韧带。牵引子宫底向前下的是子宫圆韧带。防止子宫侧倾的是阔韧带"},{"q":"临床上逆行胰胆管造影（ERCP）是将内镜插至十二指肠，找到十二指肠大乳头以后，由内镜活检孔插入造影管至十二指肠大乳头上的肝胰壶腹开口，注入造影剂，作胆胰管X线造影。造影管插入的长度至少是","o":["25cm","35cm","45cm","55cm","75cm"],"a":4,"e":"十二指肠大乳头距中切牙约75cm，内镜经口、食管、胃到达十二指肠降部时，造影管插入深度至少需75cm方能抵达肝胰壶腹开口。35cm仅达食管下段，45～55cm尚在胃内，均不足以到达乳头"},{"q":"有关局部淋巴结的叙述，正确的为","o":["是引流器官淋巴液的第一级淋巴结","切除肿瘤时不用切除局部淋巴结","不能清除肿瘤细胞和寄生虫","是引流器官淋巴的第二级淋巴结","不在器官附近"],"a":0,"e":"引流某一器官或部位淋巴的第一级淋巴结称局部淋巴结，临床称哨位淋巴结，肿大常反映其引流区存在病变。肿瘤手术需清扫局部淋巴结。它能阻截和清除细菌、毒素、寄生虫及肿瘤细胞。局部淋巴结位于器官附近或淋巴引流途中"},{"q":"对喉返神经的描述，正确的是","o":["其终支称为喉下神经","右喉返神经在右锁骨下动脉后方发出","分支至甲状舌骨肌","支配全部喉肌","分布于喉中间腔和声门下腔黏膜"],"a":0,"e":"喉返神经的终末支称喉下神经，在甲状腺侧叶深面入喉，分布于声门裂以下喉黏膜及除环甲肌以外的所有喉肌。环甲肌由喉上神经外支支配，故不支配全部喉肌。右喉返神经在右锁骨下动脉前方发出并绕其向后，分支不达甲状舌骨肌"},{"q":"第3～6颈椎的特征不包括","o":["椎体较小","横断面呈椭圆形","有钩椎关节","上、下关节突的关节面呈冠状位","第6颈椎横突末端有颈动脉结节"],"a":3,"e":"第3～7颈椎椎体上面侧缘向上突起形成椎体钩，与上位椎体唇缘构成钩椎关节；椎体较小，横断面呈椭圆形，第6颈椎横突末端有颈动脉结节。关节突关节面呈冠状位的是胸椎，颈椎关节面近水平位，该项不属颈椎特征"},{"q":"在骨连结，透明软骨结合包括","o":["骺软骨","前臂骨间膜","耻骨连合","椎间盘","髂骨、坐骨和耻骨合成髋骨"],"a":0,"e":"透明软骨结合指两骨间借透明软骨相连，如长骨骨干与骺之间的骺软骨、蝶骨与枕骨的结合。前臂骨间膜为纤维连结。耻骨联合与椎间盘属纤维软骨结合。髂骨、坐骨与耻骨融合成髋骨为骨性结合。纤维软骨结合见于椎间盘和耻骨联合，透明软骨结合多随年龄骨化"},{"q":"长骨不包括","o":["腓骨","肋","指骨","掌骨","跖骨"],"a":1,"e":"长骨呈长管状，分一体两端，腓骨、指骨、掌骨和跖骨均属长骨。肋为弓形扁骨，属扁骨，内含骨松质，不具长骨的骨髓腔与两端膨大结构。不属于长骨者为肋。短骨呈立方状，如腕骨和跗骨；籽骨位于肌腱内，髌骨为最大籽骨"},{"q":"腰椎的形态结构特征为","o":["横突末端有横突肋凹","椎体横断面呈心形","椎孔似圆形","关节突的关节面几乎呈矢状位","棘突较细长，向后下方倾斜，彼此呈叠瓦状排列"],"a":3,"e":"腰椎椎体粗壮，上、下关节突粗大，关节面几乎呈矢状位，限制旋转而利于屈伸，棘突宽短呈板状水平后伸。横突末端有横突肋凹是胸椎特征，椎体横断面呈心形亦为胸椎。椎孔呈卵圆形或三角形，叠瓦状棘突为胸椎特征"},{"q":"关于淋巴液的生成，正确的叙述是","o":["来自于组织液的少部分水分和大分子物质","来自于毛细血管静脉端的静脉血","来自于毛细血管","来自于毛细血管动脉端的动脉血","来自于脑脊液"],"a":0,"e":"组织液与细胞交换物质后，约90%经毛细血管静脉端回流入血，约10%的水分和大分子物质进入毛细淋巴管形成淋巴液。淋巴液来自组织液而非血浆或脑脊液，也不直接来自毛细血管腔。淋巴系统是心血管系统的辅助系统"},{"q":"基底动脉","o":["由左、右椎动脉合成","与小脑腹侧相邻","走行于延髓背侧","穿经枕骨大孔","直接参与构成大脑动脉环"],"a":0,"e":"左、右椎动脉经枕骨大孔入颅，在脑桥与延髓交界处腹侧面汇合成基底动脉，沿脑桥基底沟上行，至脑桥上缘分为大脑后动脉。基底动脉行于脑桥腹侧而非延髓背侧，本身不穿枕骨大孔，也不直接参与构成大脑动脉环"},{"q":"前臂屈肌群中，受正中神经和尺神经双重支配的是","o":["指浅屈肌","旋前圆肌","指深屈肌","尺侧腕屈肌","拇长屈肌"],"a":2,"e":"指深屈肌桡侧半由正中神经骨间前神经支配，尺侧半由尺神经支配，是前臂屈肌中双重神经支配者。指浅屈肌、旋前圆肌、拇长屈肌均由正中神经支配。尺侧腕屈肌由尺神经单独支配。双重支配者为指深屈肌"},{"q":"属上颌动脉分支的血管是","o":["咽升动脉","甲状腺上动脉","舌动脉","面动脉","脑膜中动脉"],"a":4,"e":"脑膜中动脉为上颌动脉的分支，经棘孔入颅，分前、后支分布于硬脑膜和颅骨。咽升动脉、甲状腺上动脉、舌动脉和面动脉均直接起自颈外动脉，属颈外动脉分支，不属上颌动脉。上颌动脉还发出下牙槽动脉、眶下动脉和上牙槽后动脉等"},{"q":"损伤后导致对侧损伤平面以下痛觉、温觉丧失的纤维束是","o":["网状脊髓束","脊髓丘脑束","脊髓小脑束","皮质脊髓束","顶盖脊髓束"],"a":1,"e":"脊髓丘脑束经白质前连合交叉至对侧外侧索和前索上行，传导对侧躯干四肢的痛温觉和粗触压觉，损伤后对侧损伤平面1～2节段以下痛温觉丧失。脊髓小脑束传导非意识性本体感觉，皮质脊髓束支配随意运动，网状脊髓束和顶盖脊髓束调节肌张力与反射"},{"q":"可使肩关节旋内的肌不包括","o":["胸大肌","背阔肌","大圆肌","小圆肌","肩胛下肌"],"a":3,"e":"肩关节旋内由胸大肌、背阔肌、大圆肌和肩胛下肌共同完成，四肌均使肱骨绕纵轴向前内旋转。小圆肌起自肩胛骨外侧缘上2/3背面，止于肱骨大结节下部，作用为使肩关节旋外。冈下肌位于冈下窝，同为旋外肌；肩胛下肌经关节囊前面止于小结节，司内收和旋内"},{"q":"属于前臂后群深层的肌是","o":["拇收肌","拇短屈肌","拇短展肌","拇对掌肌","拇短伸肌"],"a":4,"e":"前臂后群深层由外上向内下依次为旋后肌、拇长展肌、拇短伸肌、拇长伸肌和示指伸肌，均起自桡尺骨及骨间膜背面，作用与其名称一致。拇短伸肌止于拇指近节指骨底，司伸拇指。拇收肌、拇短屈肌、拇短展肌和拇对掌肌均属手肌，位于手掌鱼际及拇收肌群，不属前臂肌"},{"q":"关于小腿三头肌的叙述，错误的是","o":["肌腱称为跟腱","止于跟骨","站立时稳定踝关节和膝关节","收缩时背屈踝关节和屈膝关节","分为深、浅层排列"],"a":3,"e":"小腿三头肌由浅层腓肠肌和深层比目鱼肌组成，向下移行为跟腱止于跟骨结节，作用是屈踝关节即跖屈，并屈膝关节，站立时可固定两关节、防止身体前倾。背屈踝关节由小腿前群肌完成，胫骨前肌、趾长伸肌、拇长伸肌均属此群，故该项把跖屈误作背屈"},{"q":"产生卵子和分泌女性激素的器官是","o":["子宫","输卵管","卵巢","阴道","前庭大腺"],"a":2,"e":"卵巢是女性生殖腺，既产生卵子又分泌雌激素和孕激素，卵泡壁细胞分泌雌激素，黄体分泌孕激素与雌激素。输卵管是输送卵子的肌性管道，壶腹部为受精部位。子宫为孕育胎儿的肌性器官。前庭大腺属附属腺，分泌黏液润滑阴道口，无产生生殖细胞的功能"},{"q":"后尿道是指","o":["尿道前列腺部","尿道海绵体部、尿道膜部","尿道前列腺部、尿道膜部","海绵体部","膜部"],"a":2,"e":"临床上将尿道前列腺部和膜部合称后尿道，前者穿过前列腺实质，后者穿过尿生殖膈，均位于尿生殖膈以上。海绵体部穿过尿道海绵体，长约12～17cm，称前尿道。三个狭窄为尿道内口、膜部和尿道外口，三个膨大为前列腺部、尿道球部和舟状窝"},{"q":"男性尿道最狭窄处是","o":["尿道内口","尿道外口","尿道膜部","尿道前列腺部","尿道球部"],"a":1,"e":"男性尿道有三个狭窄，分别为尿道内口、尿道膜部和尿道外口，其中尿道外口最窄，呈矢状裂隙，是导尿和膀胱镜检最易受阻处。尿道膜部为穿过尿生殖膈的一段，位置固定，骨盆骨折时易受损伤。尿道前列腺部与尿道球部属三个膨大部，管径反而较宽"},{"q":"关于黄斑的描述，正确的是","o":["位于视神经盘的鼻侧约3、5mm稍下方","是感光最敏锐处","由密集的视杆细胞构成","位于视网膜脉络膜部","黄斑中央凹0、5mm范围内有丰富的血液供应"],"a":1,"e":"黄斑位于视神经盘颞侧约3.5mm稍下方，其中央凹陷称中央凹，此区无血管，视锥细胞密集，是感光最敏锐处。黄斑由视锥细胞构成，视杆细胞主司暗视觉，分布于视网膜周边部。视神经盘才是视神经纤维汇集穿出处，为生理性盲点，位于黄斑鼻侧"},{"q":"下列哪条动脉为腹腔干的三大分支之一","o":["胃左动脉","胃右动脉","肠系膜上动脉","肠系膜下动脉","肝固有动脉"],"a":0,"e":"腹腔干在膈的主动脉裂孔稍下方起自腹主动脉前壁，迅即分为胃左动脉、肝总动脉和脾动脉三大分支。胃右动脉发自肝固有动脉，沿胃小弯与胃左动脉吻合。肝固有动脉是肝总动脉的分支。肠系膜上、下动脉直接起自腹主动脉前壁，不属腹腔干的分支"},{"q":"甲状旁腺位于","o":["甲状腺的前面","甲状腺的两侧","甲状腺的两层被膜之间","甲状腺的上方","甲状腺的下方"],"a":2,"e":"甲状旁腺为棕黄色黄豆大小的扁椭圆形小体，上下各一对，位于甲状腺侧叶后缘，处于真被膜即纤维囊与假被膜即甲状腺鞘之间的囊鞘间隙内，也可埋入甲状腺实质。上甲状旁腺位置恒定，居侧叶后缘上、中1/3交界处。甲状腺前面、上方及下方均无此腺"},{"q":"顶盖前区","o":["位于中脑和间脑的交界部，导水管周围灰质的腹侧","接受外侧丘系的纤维","接受内侧丘系的纤维","发出纤维仅支配同侧的动眼神经副核","发出纤维支配双侧动眼神经副核"],"a":4,"e":"顶盖前区位于中脑与间脑交界处，居导水管周围灰质的背侧，接受视束和上丘臂来的纤维，发出纤维经后连合或导水管腹侧至双侧动眼神经副核，是瞳孔对光反射通路的中继站。外侧丘系为听觉传导束，止于下丘。内侧丘系传导本体感觉和精细触觉，止于丘脑腹后外侧核"},{"q":"动脉摸脉点","o":["足背动脉在活体上易触摸到搏动的部位是踝关节后方，内、外踝连线的中点","股动脉在活体上易触摸到搏动的部位是其下段","面动脉在活体上易触摸到搏动的部位在咬肌前缘与下颌骨下缘交界处","桡动脉在活体上诊脉的部位是桡动脉中段","颞浅动脉在活体上易触摸到搏动的部位是在外耳门的后方"],"a":2,"e":"面动脉在咬肌止点前缘绕过下颌骨下缘至面部，该处位置表浅，可触及搏动，面颊部出血可在此压迫止血。足背动脉的摸脉点在踝关节前方、内踝与外踝连线中点、拇长伸肌腱外侧。股动脉在腹股沟韧带中点稍下方。桡动脉在腕部桡骨茎突内侧。颞浅动脉在外耳门前方"},{"q":"中枢神经系统内形成髓鞘的细胞","o":["施万细胞","室管膜细胞","小胶质细胞","少突胶质细胞","星形胶质细胞"],"a":3,"e":"中枢神经系统的髓鞘由少突胶质细胞形成，一个少突胶质细胞可包绕多条轴突，形成节段性髓鞘。施万细胞是周围神经系统的成髓鞘细胞，只形成一条轴突的髓鞘。星形胶质细胞参与构成血脑屏障，小胶质细胞源于单核巨噬细胞，室管膜细胞衬于脑室面并参与屏障与脑脊液分泌"},{"q":"肾上腺素由哪个内分泌器官分泌","o":["胰岛","睾丸间质细胞","卵巢","肾上腺皮质","肾上腺髓质"],"a":4,"e":"肾上腺髓质的嗜铬细胞分泌肾上腺素和去甲肾上腺素，前者作用于心肌使心率加快、收缩力增强。肾上腺皮质分泌糖皮质激素、盐皮质激素和少量性激素，与髓质功能截然不同。胰岛分泌胰岛素和胰高血糖素，睾丸间质细胞分泌雄激素，卵巢分泌雌激素和孕激素"},{"q":"关于女性尿道的描述，正确的是","o":["尿道内口周围被横纹肌组成的膀胱括约肌环绕","短而直，穿过尿生殖膈","位于阴道下段的后面","尿道下端有尿道阴道括约肌环绕，不受意识支配","尿道旁腺感染时，可形成囊肿而致尿路阻塞"],"a":1,"e":"女性尿道平均长3～5cm，较男性短、宽而直，向前下方穿过尿生殖膈，开口于阴道前庭，故易发生逆行感染。尿道内口周围为平滑肌构成的膀胱括约肌，非横纹肌。穿尿生殖膈处被横纹肌性的尿道阴道括约肌环绕，受意识支配。尿道位于阴道前壁，不在其后面"},{"q":"颈椎的形态结构特征是","o":["关节面都呈冠状位","横突孔只存在于1～6颈椎","都有棘突","都有一个较小的椎体","第6颈椎横突末端前有颈动脉结节"],"a":4,"e":"第6颈椎横突末端前方有明显的隆起，称颈动脉结节，颈总动脉经其前方，头面部出血时可将动脉压向结节暂时止血。颈椎关节面近水平位，横突孔在7个颈椎均存在。寰椎无椎体和棘突，仅有前弓、后弓和侧块。第7颈椎棘突最长且不分叉"},{"q":"下列关于腹膜的描述，错误的是","o":["腹膜是覆盖于腹、盆腔壁内和腹、盆腔脏器表面的黏膜","衬于腹、盆腔壁内的腹膜称为壁腹膜","覆盖于腹、盆腔脏器表面的腹膜称为脏腹膜","壁腹膜和脏腹膜相互延续、移行","腹膜具有分泌、吸收、保护、支持、修复等功能"],"a":0,"e":"腹膜是覆盖于腹、盆腔壁内和脏器表面的一层薄而光滑的浆膜，呈半透明状，并非黏膜。衬于壁内的称壁腹膜，覆于脏器表面的称脏腹膜，二者相互延续移行。腹膜具有分泌、吸收、保护、支持和修复等功能，男性腹膜腔密闭，女性经输卵管腹腔口与外界相通"},{"q":"关于胸神经的叙述，错误的是","o":["上11对前支进入肋间隙","第12对前支为肋下神经","第2对前支分布于乳头平面的皮肤区","第6对前支分布于剑突平面的皮肤区","第7～12对前支下行进入腹内斜肌和腹横肌之间"],"a":2,"e":"胸神经前支皮支的分布具明显节段性：T2相当胸骨角平面，T4相当乳头平面，T6相当剑突平面，T8相当两侧肋弓中点连线，T10相当脐平面，故乳头平面归第4胸神经前支分布。第1～11对前支行于肋间隙称肋间神经，第12对居第12肋下方称肋下神经"},{"q":"关于鼓室的描述，正确的是","o":["为颞骨乳突部内的含气的小腔","其黏膜与咽鼓管内的黏膜相延续","借咽鼓管与口咽部相通","内侧壁上有锥隆起，内藏镫骨肌","向内可通迷路"],"a":1,"e":"鼓室内面及听小骨等结构均被覆黏膜，此黏膜与咽鼓管、乳突窦和乳突小房的黏膜相延续，故咽部感染可经咽鼓管波及鼓室。鼓室位于颞骨岩部内，不在乳突部。咽鼓管连通鼻咽部而非口咽部。锥隆起位于鼓室后壁，内藏镫骨肌，不在内侧壁"},{"q":"使髋关节后伸的肌是","o":["大收肌","髂腰肌","臀大肌","梨状肌","股薄肌"],"a":2,"e":"臀大肌起自髂骨翼外面和骶骨背面，止于髂胫束和臀肌粗隆，是髋关节最强大的伸肌，兼使髋旋外，下肢固定时可伸直躯干、防止前倾。髂腰肌为屈髋肌。大收肌与股薄肌属股内侧群，司内收。梨状肌使髋外展和旋外，无伸髋作用"},{"q":"小腿后群肌包括","o":["趾长屈肌","趾长伸肌","腓骨短肌","胫骨前肌","腓骨长肌"],"a":0,"e":"小腿后群肌分浅、深两层，浅层为腓肠肌和比目鱼肌，深层包括腘肌、趾长屈肌、拇长屈肌和胫骨后肌，均司踝跖屈或屈趾，由胫神经支配。趾长伸肌与胫骨前肌属前群，司踝背屈。腓骨长肌和腓骨短肌属外侧群，司足外翻"},{"q":"喉腔的最狭窄处是","o":["前庭裂","喉中间腔","声门下腔","声门裂","喉口"],"a":3,"e":"声门裂是两侧声襞与杓状软骨底及声带突之间的裂隙，较前庭裂长而窄，为喉腔最狭窄处，也是喉阻塞的好发部位。前庭裂为两侧前庭襞之间的裂隙，宽于声门裂。喉中间腔位于前庭裂与声门裂之间，声门下腔位于声门裂以下，管径均较大"},{"q":"三叉神经","o":["含有特殊内脏运动纤维和一般躯体感觉纤维","特殊内脏传出纤维支配面部表情肌","一般躯体传入纤维接受整个头面部的感觉信息","在脑桥下部下缘出脑","传导舌后1/3的黏膜感觉"],"a":0,"e":"三叉神经为混合性脑神经，含一般躯体感觉纤维和特殊内脏运动纤维，前者传导面部皮肤、眼、口腔、鼻腔及硬脑膜的感觉，后者支配咀嚼肌。面部表情肌由面神经支配。舌后1/3黏膜感觉由舌咽神经传导。三叉神经自脑桥基底部与小脑中脚交界处出脑"},{"q":"关于左心室流出道位置，哪项正确","o":["位于左心室腔前部","位于左心室腔前外侧部","位于左心室腔前内侧部","位于左心室腔后外侧部","位于左心室腔后内侧部"],"a":2,"e":"左心室以二尖瓣前尖为界分为流入道和流出道，流出道又称主动脉前庭，位于左心室腔的前内侧部，由室间隔上部和二尖瓣前尖围成，室间隔构成其前内侧壁。流入道又称左心室窦部，位于二尖瓣前尖的左后方。前外侧、后外侧及后内侧部均非流出道所在"},{"q":"胸骨角向后平对","o":["第2胸椎体下缘","第3胸椎体下缘","第4胸椎体下缘","第5胸椎体下缘","第6胸椎体下缘"],"a":2,"e":"胸骨角为胸骨柄与胸骨体连接处向前微突的横嵴，两侧平对第2肋软骨，是计数肋的标志，向后平对第4胸椎椎体下缘。该平面相当于气管杈、主动脉弓下缘、上下纵隔分界及心房上缘。第2、3胸椎下缘偏上，第5、6胸椎下缘偏下"},{"q":"胸上肢肌包括","o":["肋间内肌、肋间外肌、肋间最内肌","三角肌、大圆肌、小圆肌","胸大肌、胸小肌、前锯肌","胸大肌、胸小肌、肩胛下肌","胸大肌、胸小肌、背阔肌"],"a":2,"e":"胸上肢肌包括胸大肌、胸小肌、前锯肌和锁骨下肌，起自上肢带骨或胸廓，止于肱骨或肩胛骨，运动上肢带和肩关节。肋间外肌、肋间内肌、肋间最内肌属胸固有肌，司肋的运动。三角肌、大圆肌、小圆肌属上肢带肌。背阔肌属背肌浅层"},{"q":"关于结肠的叙述，错误的是","o":["结肠右曲也称为肝曲","结肠左曲也称为脾曲","乙状结肠好发憩室和恶性肿瘤","降结肠属于腹膜外位器官","横结肠属于腹膜内位器官"],"a":3,"e":"升结肠与降结肠均为腹膜间位器官，其前面和两侧被腹膜覆盖，后面借结缔组织贴于腹后壁，降结肠并非腹膜外位。结肠右曲又称肝曲，左曲又称脾曲，乙状结肠为憩室和恶性肿瘤的好发部位。横结肠有系膜连于腹后壁，属腹膜内位器官，活动度大"},{"q":"面神经中分布于泪腺的纤维的终止核为","o":["疑核","上泌涎核","下泌涎核","面神经核","孤束核"],"a":1,"e":"面神经的一般内脏运动纤维起自上泌涎核，节前纤维经岩大神经至翼腭神经节换元，节后纤维分布于泪腺及鼻腔、口腔黏膜的腺体。下泌涎核发出纤维经舌咽神经至耳神经节，支配腮腺。面神经核为特殊内脏运动核，支配表情肌。孤束核接受味觉等内脏感觉"},{"q":"关于胸导管的叙述，正确的是","o":["起自左右腰干","经膈的食管裂孔进入胸腔","至第3胸椎高度向左侧斜行","注入左静脉角","引流全身1/4部位的淋巴"],"a":3,"e":"胸导管起自第1腰椎前方的乳糜池，由左、右腰干和肠干汇合而成，经主动脉裂孔入胸腔，沿脊柱右前方上行，至第5胸椎高度斜向左侧，最终注入左静脉角。注入前接受左颈干、左锁骨下干和左支气管纵隔干，引流全身约3/4部位的淋巴"},{"q":"以下关于眼副器的描述，正确的是","o":["包括眼睑、结膜、眼球外肌和眼的血管神经","泪腺的排泄管开口于结膜上穹内侧部","参与屈光调节","对眼球有保护、运动和支持作用","参与房水及泪液的产生"],"a":3,"e":"眼副器包括眼睑、结膜、泪器、眼球外肌、眶脂体和眶筋膜，位于眼球周围，对眼球起保护、运动和支撑作用。眼的血管神经不属眼副器。泪腺排泄管开口于结膜上穹的外侧部。屈光调节由睫状肌和晶状体完成，房水由睫状体产生，二者均属眼球本身的结构与功能"},{"q":"新纹状体是指","o":["尾状核和豆状核","豆状核和屏状核","壳和苍白球","尾状核和壳","苍白球和屏状核"],"a":3,"e":"纹状体由尾状核和豆状核组成，豆状核又分为壳和苍白球。种系发生上尾状核和壳较新，合称新纹状体；苍白球较古老，称旧纹状体。新纹状体接受大脑皮质纤维，发出纤维至苍白球和黑质，是锥体外系重要环节。屏状核位于岛叶皮质深面，不属纹状体"},{"q":"下列脑神经中，属于运动性质的是","o":["嗅神经","视神经","三叉神经","展神经","前庭蜗神经"],"a":3,"e":"十二对脑神经中，动眼神经、滑车神经、展神经、副神经和舌下神经为运动性；嗅神经、视神经和前庭蜗神经为感觉性；三叉、面、舌咽、迷走神经为混合性。展神经起自展神经核，经眶上裂入眶，支配外直肌。嗅神经、视神经、前庭蜗神经均不含运动纤维"},{"q":"下列关于输精管的描述，错误的是","o":["输精管为附睾管的直接延续","长度约50cm，左侧较右侧稍长","输精管以其行程可分为4部","输精管精索部为最长段","输精管盆部近末端膨大形成输精管壶腹"],"a":3,"e":"输精管长约50cm，左侧略长于右侧，按行程分为睾丸部、精索部、腹股沟管部和盆部四部，其中盆部最长。精索部介于睾丸上端与腹股沟管皮下环之间，位置表浅，为结扎输精管的理想部位，并非最长段。盆部近末端膨大形成输精管壶腹，与精囊排出管合成射精管"},{"q":"与端脑相连的脑神经是","o":["动眼神经","嗅神经","滑车神经","视神经","三叉神经"],"a":1,"e":"十二对脑神经中仅嗅神经与端脑相连，由鼻腔嗅黏膜内嗅细胞的中枢突聚成嗅丝，穿筛板筛孔入颅前窝止于嗅球。视神经与间脑相连，动眼神经和滑车神经与中脑相连，三叉神经与脑桥相连。嗅神经属特殊内脏感觉纤维，传导嗅觉，损伤可致嗅觉障碍"},{"q":"缰三角属于","o":["上丘脑","下丘脑","后丘脑","底丘脑","背侧丘脑"],"a":0,"e":"上丘脑位于第三脑室顶后部周围，为背侧丘脑与中脑顶盖前区相移行的部分，包括松果体、缰连合、缰三角、丘脑髓纹和后连合。缰三角内含缰核，接受丘脑髓纹纤维，发出缰核脚间束至中脑。后丘脑为内侧膝状体和外侧膝状体，底丘脑为丘脑底核所在"},{"q":"桡侧近侧关节属于","o":["屈戌关节","车轴关节","椭圆关节","鞍状关节","球窝关节"],"a":1,"e":"桡尺近侧关节由桡骨环状关节面与尺骨桡切迹及桡骨环状韧带构成，属车轴关节，可沿垂直轴作旋转运动。桡腕关节为椭圆关节，可行屈伸、收展和环转。拇指腕掌关节为鞍状关节。肩关节为典型球窝关节。屈戌关节只绕冠状轴屈伸，如指间关节"},{"q":"管理小指皮肤感觉的神经是","o":["正中神经","桡神经","尺神经","腋神经","肌皮神经"],"a":2,"e":"尺神经经肱骨内上髁后方下行，在腕部经豌豆骨外侧入掌，其掌皮支与手背支分布于手掌、手背尺侧缘及小指和环指尺侧半皮肤。正中神经分布于桡侧三个半手指掌面。桡神经分布于手背桡侧半及桡侧两个半手指近节背面。腋神经分布于三角肌区皮肤"},{"q":"分布于半球内侧面顶枕沟以前大脑皮质的动脉是","o":["大脑中动脉","大脑前动脉","大脑后动脉","前交通动脉","基底动脉"],"a":1,"e":"大脑前动脉的皮质支分布于顶枕沟以前的半球内侧面、额叶底面一部分及额顶两叶上外侧面上部，胼胝体周围动脉和旁中央动脉即为其主要分支。大脑中动脉分布于半球上外侧面大部。大脑后动脉分布于颞叶底面和枕叶内侧面。前交通动脉连接两侧大脑前动脉"},{"q":"视觉中枢位于","o":["枕叶距状沟两侧皮质","外侧膝状体","顶盖前区","中脑上丘","角回"],"a":0,"e":"视觉中枢位于枕叶距状沟上、下方的皮质，即楔叶和舌回，属17区，接受外侧膝状体发出的视辐射纤维。外侧膝状体是视觉通路在丘脑的中继站，不是皮质中枢。顶盖前区参与瞳孔对光反射，中脑上丘与视觉反射有关，角回为阅读中枢所在"},{"q":"前锯肌的滋养动脉是","o":["肋间后动脉","旋肩胛动脉","胸背动脉","胸外侧动脉","胸廓内动脉"],"a":3,"e":"胸外侧动脉发自腋动脉，伴胸长神经沿胸侧壁下行，分支分布于前锯肌、胸大肌和胸小肌，是前锯肌的主要滋养动脉。胸背动脉伴胸背神经分布于背阔肌。旋肩胛动脉穿三边孔分布于冈下窝诸肌。肋间后动脉供应胸壁，胸廓内动脉供应胸前壁及乳房内侧部"},{"q":"齿状韧带形成于","o":["硬脊膜","硬脑膜","蛛网膜","软脊膜","软脑膜"],"a":3,"e":"软脊膜薄而富含血管，紧贴脊髓表面并伸入沟裂，在脊髓两侧、脊神经前根与后根之间向外突出形成齿状韧带，其尖端附于硬脊膜，起固定脊髓的作用。硬脊膜与椎管骨膜之间为硬膜外隙。脊髓蛛网膜与软脊膜之间为蛛网膜下隙。齿状韧带并非由蛛网膜形成"},{"q":"皮质脊髓束主要传导","o":["支配同侧上下肢骨骼肌的随意运动","支配对侧上下肢骨骼肌的随意运动","支配同侧躯干四肢骨骼肌的随意运动","支配对侧躯干四肢骨骼肌的随意运动","支配双侧躯干四肢骨骼肌的随意运动"],"a":1,"e":"皮质脊髓束起自大脑皮质中央前回等处的锥体细胞，经内囊后肢、大脑脚底、脑桥基底部下行，在延髓锥体交叉处大部分纤维交叉至对侧，终于脊髓前角运动神经元，支配对侧上、下肢骨骼肌的随意运动。躯干肌受双侧皮质支配，一侧束损伤时躯干肌不瘫"},{"q":"踝部作静脉输液时，最佳的静脉是","o":["胫前静脉","穿静脉","小隐静脉","足背静脉弓","大隐静脉"],"a":4,"e":"大隐静脉起自足背静脉弓内侧，经内踝前方沿下肢内侧上行，在内踝前方位置表浅而恒定，是踝部及下肢静脉输液、注射的常用部位。小隐静脉经外踝后方上行。足背静脉弓位置较深、管径细，穿刺困难。胫前静脉与穿静脉均属深静脉，不宜作浅静脉输液用"},{"q":"薄束描述错误的是","o":["成自第5胸节以下的脊神经节细胞的中枢突","T5以下占据脊髓后索全部","主要传导同侧下肢的深感觉和精细触觉","上行至同侧薄束核内交换神经元","上行至对侧薄束核内交换神经元"],"a":4,"e":"薄束由第5胸节及以下的脊神经节细胞中枢突组成，在脊髓后索内上行，于T5以下占据后索全部，传导同侧下肢的深感觉和精细触觉，止于延髓同侧薄束核换元，再发纤维经内侧丘系交叉至对侧。楔束由第4胸节以上纤维组成，居后索外侧部。薄束并不过中线"},{"q":"输卵管常用结扎部位在","o":["输卵管子宫部","输卵管漏斗","输卵管壶腹","输卵管峡","输卵管伞"],"a":3,"e":"输卵管峡位于子宫角外侧，短而直，管腔细，壁较厚，为输卵管结扎术的常用部位。壶腹部粗而长，约占全长2/3，管腔大，为卵子受精的常见部位，异位妊娠多发生于此。漏斗末端的输卵管伞有拾卵作用。子宫部穿子宫壁，管径最细，不作结扎部位"},{"q":"关于正中神经正确的是","o":["发自臂丛后束","发出分支支配臂前群肌","发出分支支配除拇收肌以外的鱼际肌","损伤后影响小指功能，不能屈曲","损伤后可出现“爪形手”"],"a":2,"e":"正中神经发自臂丛内、外侧束，在臂部无分支，于前臂支配除肱桡肌、尺侧腕屈肌和指深屈肌尺侧半以外的全部屈肌和旋前肌，在腕部发出返支支配除拇收肌以外的鱼际肌。手部还支配第1、2蚓状肌。小指感觉由尺神经司理，爪形手为尺神经损伤的表现"},{"q":"关节腔的特征不包括","o":["由关节囊滑膜层围成","是滑膜关节的基本结构","含少量滑液","关节腔内呈负压","是密闭腔隙"],"a":0,"e":"关节腔由关节囊滑膜层与关节面共同围成，是滑膜关节的基本结构之一，为密闭的潜在腔隙，腔内仅含少量滑液并呈负压，对维持关节稳固有作用。滑膜层只构成腔的周壁，关节面参与围成腔的骨性界，故仅称滑膜层围成并不完整。关节腔不含空气"},{"q":"关于男性尿道弯曲的叙述，错误的是","o":["耻骨前弯在耻骨联合的前下方，凸向上","耻骨下弯位于耻骨联合的下方","耻骨前弯是阴茎体与阴茎根之间的弯曲","向上牵拉阴茎时，耻骨前弯可消失","耻骨下弯是由尿道海绵体部构成"],"a":4,"e":"耻骨下弯位于耻骨联合下方约2cm处，凸向下后方，位置恒定，由尿道前列腺部、膜部和海绵体部起始段共同构成，并非只由海绵体部构成。耻骨前弯位于耻骨联合前下方，由海绵体部形成，向上牵拉阴茎时可消失。两个弯曲共同构成尿道的走行特点"},{"q":"肝的韧带中，不属于腹膜形成的是","o":["镰状韧带","冠状韧带","左三角韧带","右三角韧带","肝圆韧带"],"a":4,"e":"肝圆韧带是胚胎时期脐静脉闭锁后形成的遗迹，位于镰状韧带游离缘内，属结缔组织索，并非腹膜襞。镰状韧带、冠状韧带及左、右三角韧带均由双层腹膜构成，属腹膜形成物。肝胃韧带与肝十二指肠韧带构成小网膜，同为腹膜结构"},{"q":"支配舌的神经不包括","o":["舌神经","面神经","舌咽神经","迷走神经","舌下神经"],"a":3,"e":"舌的感觉与运动由多对神经共同支配：舌神经传导舌前2/3黏膜一般感觉，面神经鼓索传导舌前2/3味觉，舌咽神经传导舌后1/3感觉与味觉，舌下神经支配全部舌内肌和大部分舌外肌。迷走神经分支至会厌及喉，与舌肌运动和舌黏膜感觉无关"},{"q":"在上肢带骨连结，有防止肱骨头向上脱位的结构是","o":["肩锁韧带","喙肱韧带","喙肩弓","喙锁韧带","肋锁韧带"],"a":2,"e":"喙肩韧带连于肩胛骨喙突与肩峰之间，与喙突、肩峰共同构成喙肩弓，架于肩关节上方，可防止肱骨头向上脱位。喙肱韧带自喙突根至肱骨大结节，加强关节囊上壁。喙锁韧带连于喙突与锁骨，肩锁韧带加强肩锁关节，肋锁韧带属胸锁关节的辅助结构"},{"q":"肱骨中下1/3骨折，最易发生的并发症是","o":["肱动脉损伤","正中神经损伤","尺神经损伤","桡神经损伤","肱二头肌断裂伤"],"a":3,"e":"桡神经在臂中段紧贴肱骨桡神经沟走行，肱骨中段或中、下1/3交界处骨折时最易损伤，表现为前臂伸肌群瘫痪、垂腕及第1、2掌骨间背面皮肤感觉障碍。肱动脉损伤多见于肱骨髁上骨折。正中神经损伤多见于肘部和腕部。尺神经在肱骨内上髁后方易受损"},{"q":"相邻椎骨的上、下切迹共同围成","o":["椎间孔","椎孔","横突孔","骶前孔","骶后孔"],"a":0,"e":"椎弓根上、下缘分别称椎上切迹和椎下切迹，相邻椎骨的上、下切迹共同围成椎间孔，有脊神经和血管通过。椎孔由椎体后面与椎弓围成，容纳脊髓。横突孔位于颈椎横突，有椎动脉通过。骶前孔、骶后孔为骶骨的四对孔，分别有骶神经前、后支通过"},{"q":"位于外侧沟前支和升支之间的脑区","o":["额下回眶部","额下回三角部","额下回岛盖部","缘上回","角回"],"a":1,"e":"额下回后部被外侧沟的前支和升支分为眶部、三角部和岛盖部，由前向后依次排列，故前支与升支之间为三角部，升支以后为岛盖部，三角部后部与岛盖部共同构成Broca区。眶部位于前支之前。缘上回位于外侧沟末端周围，角回位于顶下小叶后部"},{"q":"胎儿肺不同于幼儿肺，如何区分","o":["胎儿肺不含空气","胎儿肺比重较小","胎儿肺能浮出水面","胎儿肺无营养血管","胎儿肺无气道相连"],"a":0,"e":"胎儿和未曾呼吸过的新生儿肺内不含空气，质地致密，比重较大，为1.045～1.056，投入水中下沉。已呼吸者肺内含空气，比重小，为0.345～0.746，可浮于水面，此差别在法医鉴定死胎与活产中有价值。胎儿肺同样有营养血管，并经气管与外界相通"},{"q":"对迷走神经的叙述，错误的是","o":["经颈静脉孔出颅","在橄榄后沟连于延髓","内含4种纤维成分","特殊内脏纤维来自疑核","一般内脏运动纤维分布于喉肌"],"a":4,"e":"迷走神经含一般内脏感觉、一般内脏运动、特殊内脏运动和一般躯体感觉四种纤维。喉肌由疑核发出的特殊内脏运动纤维经喉返神经支配，不属一般内脏运动纤维。一般内脏运动纤维为副交感节前纤维，支配胸腹腔脏器的平滑肌、心肌和腺体。迷走神经经颈静脉孔出颅"},{"q":"经卵圆孔出颅的神经是","o":["面神经","舌下神经","上颌神经","下颌神经","舌咽神经"],"a":3,"e":"三叉神经第三支下颌神经含一般躯体感觉和特殊内脏运动两种纤维，经卵圆孔出颅，其运动纤维支配咀嚼肌、鼓膜张肌等。上颌神经经圆孔出颅，眼神经经眶上裂出颅。面神经由茎乳孔出颅，舌下神经经舌下神经管出颅，舌咽神经经颈静脉孔出颅"},{"q":"左、右主支气管不同，其区别在于","o":["右主支气管与食管第2狭窄相邻","右主支气管比左主支气管外径小","右主支气管比左主支气管短","右侧嵴下角大","右主支气管不含软骨环"],"a":2,"e":"右主支气管短、粗而陡直，嵴下角小，平均长约2cm，与气管中轴夹角小，异物易坠入右侧。左主支气管细而长，平均长4.5～4.8cm，嵴下角大，走行较倾斜，有7～8个软骨环。右主支气管外径大于左侧，软骨环完整，与食管第2狭窄无毗邻关系"},{"q":"乳房","o":["位于浅筋膜深面","乳腺叶有8～10个","每个乳腺叶有多条排泄管","输乳管以乳头为中心，呈放射状排列","乳房悬韧带对乳房无固定作用"],"a":3,"e":"乳腺叶和输乳管均以乳头为中心呈放射状排列，故乳房脓肿切开引流应作放射状切口，以免损伤输乳管。乳房位于胸肌筋膜浅面的浅筋膜内，居浅、深两层筋膜之间。乳腺叶有15～20个，每叶有一条输乳管。乳房悬韧带连于皮肤与胸肌筋膜，对乳房起固定作用"},{"q":"寰椎是","o":["第1颈椎","第2颈椎","第7颈椎","胸椎","腰椎"],"a":0,"e":"第1颈椎又名寰椎，呈环状，无椎体和棘突，由前弓、后弓和侧块组成，前弓后面有齿突凹与枢椎齿突相关节。第2颈椎称枢椎，椎体向上伸出齿突。第7颈椎棘突长而不分叉，为计数椎骨的标志。胸椎有肋凹，腰椎椎体粗大"},{"q":"关于躯干四肢痛温觉和粗触觉传导通路的叙述，错误的是","o":["第1级神经元为脊神经节细胞","脊髓丘脑侧束传导痛温觉","脊髓丘脑前束传导粗触觉","丘脑中央辐射传导痛温觉和粗触觉","在脊髓内，来自颈、胸、腰和骶部的纤维自外向内依次在脊髓丘脑束排列"],"a":4,"e":"脊髓丘脑束在脊髓内由外侧向内侧、由浅入深，依次排列着来自骶、腰、胸、颈部的纤维，故其排列顺序与题干所述恰好相反。该束传导对侧躯干四肢的痛温觉和粗触觉，第1级神经元为脊神经节细胞，交叉后经脊髓丘脑侧束和前束上行，终于丘脑腹后外侧核"},{"q":"淋巴器官包括下述哪个结构","o":["肝脏","胸腺","胰脏","孤立淋巴小结","淋巴滤泡"],"a":1,"e":"淋巴器官包括淋巴结、胸腺、脾和扁桃体，胸腺为中枢淋巴器官，培育并向周围淋巴器官输送T淋巴细胞，兼有内分泌功能。肝和胰属消化腺。孤立淋巴滤泡与淋巴小结属弥散淋巴组织，是淋巴组织而非独立器官。脾为人体最大的淋巴器官"},{"q":"不存在明显的瓣膜纤维环的是","o":["主动脉口","肺动脉口","冠状窦口","左房室口","右房室口"],"a":2,"e":"冠状窦口位于右心房下腔静脉口与右房室口之间，口缘常有半月形瓣膜，但无明显的瓣膜纤维环。主动脉口、肺动脉口、左房室口和右房室口均有致密结缔组织构成的纤维环，为心瓣膜的附着处，也属心骨骼的组成部分，心房肌与心室肌借此分隔"},{"q":"下列结构中不属于泪器","o":["泪腺","泪湖","泪小管","泪囊","鼻泪管"],"a":1,"e":"泪器由泪腺和泪道组成，泪道包括泪点、泪小管、泪囊和鼻泪管，泪液经此引流至鼻腔。泪湖是内眦处由泪液汇聚形成的凹陷，只是泪液流经的部位，不属泪器的独立结构。泪腺分泌泪液，含溶菌酶，有湿润角膜和灭菌作用"},{"q":"脊髓前角运动神经元","o":["位于Ⅹ层","包括大型的运动神经元和小型的运动神经元","α动神经元支配梭内肌","γ运动神经元支配梭外肌","反馈抑制Renshaw细胞"],"a":1,"e":"脊髓前角运动神经元位于灰质Ⅸ层，包括大型的α-运动神经元和小型的γ-运动神经元。α-运动神经元支配梭外肌，γ-运动神经元支配梭内肌，调节肌梭敏感性。Renshaw细胞接受α-运动神经元轴突侧支的兴奋，转而抑制α-运动神经元，构成负反馈环路"},{"q":"感受头部变速旋转刺激的是","o":["蜗管","螺旋器","壶腹嵴","球囊斑和椭圆囊斑","内淋巴"],"a":2,"e":"壶腹嵴位于膜壶腹壁，是位置觉感受器，能感受头部旋转变速运动的刺激，三个壶腹嵴相互垂直，可分别感受三维空间的旋转加速。球囊斑和椭圆囊斑感受直线变速运动及头部静止时的位置。螺旋器位于蜗管基底膜上，是听觉感受器。蜗管与内淋巴属结构成分"}];
